	local theirs = ns.IsCrownRank("Olympus", 1)
	GetGuildInfo = savedGuild
	eq(theirs, true, "officers of the main guild, on its members' clients")
	eq(ns.IsCrownRank("Olympus", 0), true, "its guild master everywhere")
end)

