	PanelTemplates_AnchorTabs = function() end
	eq(UI.TabStyle(atlasTab), "mainline")
	eq(UI.TabStyle(plainButton), "classic", "fallback buttons keep the old spacing")
	PanelTemplates_AnchorTabs = nil
	local f, prev = {}, {}
