		UI.SelectTab("realm")
		local row
		for _, r in ipairs(main.views.realm.rows) do
			if r:IsShown() and r.line and r.line.key == "Asmongold" and r.line.indent == 1 then row = r break end
		end
		assert(row, "the Lord's line")
