	test("channel owner: locked out (password or ban), tried again after 1, 2, 5, then every 10 minutes; told once", function()
		WithMocks(function(calls)
			local id = 0
			GetChannelName = function() return id end
			local w = OwnerComm()
			local C = w.C
			local function Joins()
				local n = 0
				for _, c in ipairs(calls) do
					if c:find("^join") then
						n = n + 1
						eq(c, "join OlympusNet", "always the same channel: no other name to flee to")
					end
				end
				return n
			end
			C.JoinChannel()
			eq(Joins(), 1)
			-- The server's answer: a wrong password, and Blizzard's password prompt for the same try.
			w.Notice(NOTICE, "WRONG_PASSWORD")
			for _, fn in ipairs(w.events.CHANNEL_PASSWORD_REQUEST) do fn("OlympusNet") end
			eq(#w.printed, 1, "told once")
			assert(w.printed[1]:find(ns.L.CHANNEL_LOCKED:format("OlympusNet"), 1, true), w.printed[1])
			eq(C.GuardStats().locked.tries, 1, "one failed join, however many notices")
			local joins = 1
			for i, gap in ipairs({ 60, 120, 300, 600, 600 }) do
				w.cns.clock = w.cns.clock + gap - 1
				C.JoinChannel() -- the housekeeping ticker, every minute
				eq(Joins(), joins, "not before " .. gap .. "s")
				w.cns.clock = w.cns.clock + 1
				C.JoinChannel()
				joins = joins + 1
				eq(Joins(), joins, "again after " .. gap .. "s")
				w.Notice(NOTICE, i % 2 == 0 and "WRONG_PASSWORD" or "BANNED")
			end
			eq(#w.printed, 1, "still told once")
			local lock = C.GuardStats().locked
			eq(lock.tries, 6); eq(lock.nextIn, 600)
			-- An honest owner opens it: in at the next try, and the census is asked for again.
			id = 5
			C.random = function() return 0 end -- (1.0.0: the ask's second is drawn in 4 to 45 s; here the first)
			w.Wait(600)
			eq(C.GuardStats().locked, nil, "open again")
			eq(C.ChannelReady(), true)
			w.Wait(4)
			eq(C.Stats().asked, 1, "census asked for once back in")
		end)
	end)
end

-- 0.9.1: privacy
-- Issues #13 and #16: where a player is goes out only with their yes, and the channel's
-- warning comes before the first line in each of its channels.

-- Runs fn(w) reading our layer from NPCs in Stormwind (map 1453), every Comm.Send kept in
-- w.sent; w.observe() reads a new layer, far enough in time to be announced at once.
local function WithLayerWatch(fn)
	local saved = { send = ns.Comm.Send, hello = ns.Comm.Hello, now = ns.Now, print = ns.Print, guid = UnitGUID,
		map = C_Map.GetBestMapForUnit, guild = GetGuildInfo, me = ns.me, share = ns.db.shareLocation, crown = ns.db.throneLocation }
	local w = { sent = {}, printed = {}, hellos = 0, clock = 3000000000, npc = 100 }
	local ok, err = pcall(function()
		ns.Comm.Send = function(dist, msg) w.sent[#w.sent + 1] = dist .. " " .. msg end
		ns.Comm.Hello = function(force) if force then w.hellos = w.hellos + 1 end end
		ns.Now = function() return w.clock end
		ns.Print = function(m) w.printed[#w.printed + 1] = m end
		C_Map.GetBestMapForUnit = function() return 1453 end
		UnitGUID = function() return ("Creature-0-4619-0-%d-68-0000AAA1"):format(w.npc) end
		w.observe = function()
			w.clock, w.npc = w.clock + 1000, w.npc + 1
			ns.Layers.Reset()
			ns.Layers.Observe("target")
		end
		w.layers = function()
			local n = 0
			for _, m in ipairs(w.sent) do if m:find("^CHANNEL L1~") then n = n + 1 end end
			return n
		end
		fn(w)
	end)
	ns.Comm.Send, ns.Comm.Hello, ns.Now, ns.Print, UnitGUID = saved.send, saved.hello, saved.now, saved.print, saved.guid
	C_Map.GetBestMapForUnit, GetGuildInfo, ns.me = saved.map, saved.guild, saved.me
	ns.db.shareLocation, ns.db.throneLocation = saved.share, saved.crown
	ns.Layers.Reset()
	if not ok then error(err, 0) end
end

test("0.9.1 privacy: a player who keeps it private still asks for hops and helps, told once what an ask says (#13)", function()
	local savedShare, savedPrint = ns.db.shareLocation, ns.Print
	local printed = {}
	local function Hints()
		local n = 0
		for _, m in ipairs(printed) do if m == ns.L.HOP_PRIVATE_HINT then n = n + 1 end end
		return n
	end
	local ok, err = pcall(function()
		ns.Print = function(m) printed[#printed + 1] = m end
		WithHop(function(w, H)
			ns.db.shareLocation = nil -- never answered: private
			GetGuildInfo = function() return "Olympus II", "Officer", 1 end
			w.see(7)
			for _, m in ipairs(w.sent) do assert(not m:find("L1~", 1, true), "no layer announced: " .. m) end
			-- A player who shares nothing does not help either (0.9.2): an offer would tell the
			-- asker, anyone on the channel, where they are.
			H.HandleAsk("CHANNEL", "Asker-Realm", "LQ~42~1453~7")
			eq(w.whispered[1], nil, "private: no offer")
			-- Asking still works: the ask names this zone and the layer wanted, and says so once.
			H.Ask(1453, 8, "Kingy's layer")
			eq(w.sent[#w.sent], "CHANNEL LQ~1~1453~8")
			eq(Hints(), 1)
			w.clock = w.clock + 30
			H.Tick() -- nobody answered: done
			H.Ask(1453, 8, "Kingy's layer")
			eq(w.sent[#w.sent], "CHANNEL LQ~1~1453~8", "asked again")
			eq(Hints(), 1, "once a session")
		end)
		WithHop(function(w, H)
			ns.db.shareLocation = true
			w.see(7)
			H.Ask(1453, 8, "Kingy's layer")
			eq(w.sent[#w.sent], "CHANNEL LQ~1~1453~8")
			eq(Hints(), 1, "sharing: nothing to tell")
		end)
	end)
	ns.db.shareLocation, ns.Print = savedShare, savedPrint
	if not ok then error(err, 0) end
end)

test("0.9.1 privacy: no layer announcement without the player's yes, officers and the sample included (#13)", function()
	WithLayerWatch(function(w)
		-- An officer, never asked yet and after Keep private: the layer is read, and stays home.
		GetGuildInfo = function() return "Olympus II", "Officer", 1 end
		for _, answer in ipairs({ "unanswered", "private" }) do
			ns.db.shareLocation = answer == "private" and false or nil
			w.observe()
			eq(ns.Layers.Mine().zoneUID, w.npc, "read, for this client alone")
			eq(w.layers(), 0, "an officer, " .. answer)
		end
		-- A member of the 1 in 8 sample: the same.
		GetGuildInfo = function() return "Olympus II", "Member", 3 end
		for i = 1, 400 do
			ns.me = "Sample" .. i .. "-Realm"
			if ns.Layers.InSample() then break end
		end
		assert(ns.Layers.InSample(), "a sampled name")
		w.observe()
		eq(w.layers(), 0, "a sampled member")
		-- Share: at once, and each new layer; the hello tells our reporter too.
		GetGuildInfo = function() return "Olympus II", "Officer", 1 end
		ns.Layers.SetSharing(true)
		eq(ns.db.shareLocation, true); eq(w.printed[#w.printed], ns.L.LOCATION_ON); eq(w.hellos, 1)
		eq(w.layers(), 1); eq(w.sent[#w.sent], ("CHANNEL L1~1453~%d~1~Olympus II"):format(w.npc))
		w.observe()
		eq(w.layers(), 2)
		-- Off again: nothing more.
		ns.Layers.SetSharing(false)
		eq(ns.db.shareLocation, false); eq(w.printed[#w.printed], ns.L.LOCATION_OFF); eq(w.hellos, 2)
		w.observe()
		eq(w.layers(), 2)
		-- The King: his crown on the map (the Throne) is his yes for his layer; without it, his
		-- own answer like anyone's.
		GetGuildInfo = function() return "Olympus", "King", 0 end
		local me = ns.me
		ns.me = "Asmongold Asmongler-Realm"
		ns.db.throneLocation = true
		w.observe()
		ns.me = me
		eq(w.layers(), 3); eq(w.sent[#w.sent], ("CHANNEL L1~1453~%d~0~Olympus"):format(w.npc))
		ns.db.throneLocation = nil
		w.observe()
		eq(w.layers(), 3)
	end)
end)

-- 1.0.0: the King's layer went out only every ten minutes, and not at all when he showed his
-- crown again within ten minutes of hiding it: players who logged in or reloaded while he
-- shared, and everyone after an off and on, clicked "Ask invite for Asmon Layer" and read
-- "try again in a minute" for up to ten.
test("1.0.0 the King's layer goes with his crown: at once when he shows it, again after hiding it, and every minute", function()
	local K = ns.King
	local savedPos = C_Map.GetPlayerMapPosition
	local ok, err = pcall(function()
		WithLayerWatch(function(w)
			C_Map.GetPlayerMapPosition = function() return { GetXY = function() return 0.42, 0.51 end } end
			K.Reset()
			GetGuildInfo = function() return "Olympus", "King", 0 end
			ns.me = "Asmongold Asmongler-Realm"
			ns.db.throneLocation = nil
			w.observe()
			eq(w.layers(), 0, "his crown hidden (the default): his layer stays home")
			local function Crowns()
				local n = 0
				for _, m in ipairs(w.sent) do if m:find("^CHANNEL T1~P~") then n = n + 1 end end
				return n
			end
			local layer = ("CHANNEL L1~1453~%d~0~Olympus"):format(w.npc)
			-- He shows it: his crown and his layer go out now.
			K.ToggleLocation()
			eq(Crowns(), 1, "his crown")
			eq(w.layers(), 1, "and his layer, at once")
			eq(w.sent[#w.sent], layer)
			-- He hides it: both withdrawn.
			w.clock = w.clock + 120
			K.ToggleLocation()
			assert(w.sent[#w.sent - 1]:find("^CHANNEL T1~Q~"), "his crown withdrawn")
			eq(w.sent[#w.sent], "CHANNEL L0~", "and his layer")
			-- He shows it again three minutes after his layer last went out: his layer too, now
			-- (before: only once ten minutes had passed since the last one).
			w.clock = w.clock + 60
			K.ToggleLocation()
			eq(w.layers(), 2, "his layer again, at once")
			eq(w.sent[#w.sent], layer)
			-- Standing still: once a minute, so a player who just logged in or reloaded learns it
			-- within a minute (his crown is repeated every 20 seconds).
			for i = 1, 5 do
				w.clock = w.clock + 60
				ns.Layers.Tick()
				eq(w.layers(), 2 + i, "minute " .. i)
			end
			-- Hidden: nothing from the ticker.
			K.ToggleLocation()
			for _ = 1, 3 do w.clock = w.clock + 60; ns.Layers.Tick() end
			eq(w.layers(), 7, "hidden: no layer")
			-- Anyone else who shares: every ten minutes, as before.
			GetGuildInfo = function() return "Olympus II", "Officer", 1 end
			ns.me = "Tester-Realm"
			ns.db.shareLocation = true
			w.observe()
			eq(w.layers(), 8, "a new layer: at once")
			for _ = 1, 9 do w.clock = w.clock + 60; ns.Layers.Tick() end
			eq(w.layers(), 8, "not every minute: only the King's")
			w.clock = w.clock + 60
			ns.Layers.Tick()
			eq(w.layers(), 9, "ten minutes on")
		end)
	end)
	C_Map.GetPlayerMapPosition = savedPos
	ns.db.throneLocation = nil
	K.Reset()
	if not ok then error(err, 0) end
end)

-- 1.0.0: with the King's layer unknown the line said "his addon announces it when he targets an
-- NPC, try again in a minute", whatever the reason. While his crown is hidden (the default: his
-- position is on stream) his layer is never announced, and a player on another realm never
-- hears it: they tried again every minute for nothing.
test("1.0.0 the King's line says why his layer is unknown: his crown is hidden, he is on another realm, or it is coming", function()
	WithHop(function(w, H)
		local savedPrint = ns.Print
		local said = {}
		local ok, err = pcall(function()
			ns.King.Reset()
			ns.rdb.guilds = SampleGuilds() -- the King online, two senders name him
			ns.Print = function(m) said[#said + 1] = m end
			local unknown = ns.L.HOP_KING_UNKNOWN:format("Asmon")
			-- His crown is not on the map: nothing will come until he shows it.
			H.AskKing()
			assert(said[1] ~= unknown, "not 'try again in a minute' while his crown is hidden")
			eq(said[1], ns.L.HOP_KING_HIDDEN:format("Asmon"))
			local tips = {}
			H.KingLine().tooltip({ AddLine = function(_, text) tips[#tips + 1] = text end })
			eq(tips[2], ns.L.HOP_KING_HIDDEN:format("Asmon"), "the line's tooltip says the same")
			eq(#w.sent, 0, "nothing asked")
			-- His crown shows: his layer is on its way (his addon repeats it every minute now).
			ns.King.HandleCommand("CHANNEL", "Asmongold Asmongler-Realm", "T1~P~3~Olympus~1453~420~510")
			H.AskKing()
			eq(said[2], unknown)
			-- It came: the ask goes out.
			ns.Layers.Receive("Asmongold-Realm", { mapID = 1453, zoneUID = 9, rank = 0, guild = "Olympus" })
			H.AskKing()
			eq(w.sent[#w.sent], "CHANNEL LQ~1~1453~9")
			-- The census places him on another realm (a guild across two realms, the next realm's
			-- reporter): a layer is a copy of a zone inside one realm, nobody here can join his.
			-- Said so, whatever the crown.
			local other = ns.L.HOP_KING_OTHER_REALM:format("Asmon", "OtherRealm")
			ns.rdb.guilds = { ["Olympus"] = Vouched({ total = 990, online = 210, zones = {}, t = os.time(),
				leader = "Asmongold-OtherRealm", leaderOnline = true }, "W1-Realm", "W2-Realm") }
			H.AskKing()
			eq(said[#said], other)
			-- Even with his layer heard here (a channel the two realms share, Comm.ElectsAcrossRealms,
			-- carries his announcements): his realm comes first, nothing is asked, and the line
			-- neither sends us to his zone nor says we are on his layer.
			ns.Layers.Receive("Asmongold-OtherRealm", { mapID = 1453, zoneUID = 7, rank = 0, guild = "Olympus" })
			eq(H.King().zoneUID, 7, "his layer is known")
			local asked = #w.sent
			H.AskKing()
			eq(said[#said], other, "his realm, not his layer")
			eq(#w.sent, asked, "nothing asked")
			w.see(7) -- (the same zone UID on our realm is another layer)
			local lines = H.KingLines()
			eq(#lines, 1, "no 'go there' line")
			eq(lines[1].text:find(ns.L.HOP_KING_HERE:format("Asmon"), 1, true), nil, "not 'on his layer'")
			tips = {}
			lines[1].tooltip({ AddLine = function(_, text) tips[#tips + 1] = text end })
			eq(tips[2], other, "the tooltip says the same")
			-- Both languages have them, and neither says the channel stays inside one realm.
			local savedLocale, pt = GetLocale, {}
			GetLocale = function() return "ptBR" end
			local loaded, lerr = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
			GetLocale = savedLocale
			if not loaded then error(lerr, 0) end
			for _, key in ipairs({ "HOP_KING_HIDDEN", "HOP_KING_OTHER_REALM" }) do
				assert(type(ns.L[key]) == "string" and ns.L[key]:find("%s", 1, true), key)
				assert(type(pt.L[key]) == "string" and pt.L[key] ~= ns.L[key] and pt.L[key]:find("%s", 1, true), "Portuguese " .. key)
			end
			eq(ns.L.HOP_KING_OTHER_REALM:find("channel", 1, true), nil)
			eq(pt.L.HOP_KING_OTHER_REALM:find("canal", 1, true), nil)
		end)
		ns.Print = savedPrint
		ns.King.Reset()
		ns.rdb.guilds = {}
		if not ok then error(err, 0) end
	end)
end)

-- Konig's review of 1.0.0: the realm Hop.King gave the King was his census row's, the realm of
-- whoever sent the last report of <Olympus>. One report from a character of another realm of our
-- group, naming him its leader, placed him there: "he plays on another realm", and his layer could
-- not be asked for, his own crown and layer coming from our realm. Now the King pinned by name is
-- where his own messages say (the server stamps their sender's realm).
test("1.0.0 one forged report can't place the King on another realm: his realm and his layer come from his own messages", function()
	WithHop(function(w, H)
		local savedPrint, savedLinks = ns.Print, ns.db.links
		local said = {}
		local ok, err = pcall(function()
			ns.King.Reset()
			ns.rdb.guilds = {}
			ns.Print = function(m) said[#said + 1] = m end
			local king = ns.KingCharacter()
			-- One report of <Olympus>, sent from another realm, naming him (by his name, as a report
			-- does) its leader online; nobody else's. The census has him online.
			local forged = { guild = "Olympus", total = 1000, online = 200, leader = king, leaderOnline = true, users = 5,
				zones = {}, officers = {}, ranks = {}, top = {}, faction = "Alliance" }
			eq(ns.Data.Receive(forged, "Forger-OtherRealm"), true, "(taken: nothing to outvote it)")
			local k = H.King()
			assert(k, "the census has him online")
			eq(H.KingOtherRealm(k), false, "a report never places him on another realm")
			eq(k.realm, nil, "nothing of his heard yet: his realm is not known")
			H.AskKing()
			eq(said[#said], ns.L.HOP_KING_HIDDEN:format("Asmon"), "not 'he plays on another realm'")
			-- His crown and his layer, from his own client on our realm: his layer can be asked for.
			ns.King.HandleCommand("CHANNEL", king .. "-Realm", "T1~P~3~Olympus~1453~420~510")
			ns.Layers.Receive(king .. "-Realm", { mapID = 1453, zoneUID = 9, rank = 0, guild = "Olympus" })
			k = H.King()
			eq(k.realm, "Realm"); eq(k.zoneUID, 9)
			eq(H.KingOtherRealm(k), false)
			H.AskKing()
			eq(w.sent[#w.sent], "CHANNEL LQ~1~1453~9", "his layer asked for")
			assert(H.KingStatusLine():find("realm Realm (ours)", 1, true), H.KingStatusLine())
			-- Someone else's layer in his guild's name changes nothing.
			ns.Layers.Receive("Forger-OtherRealm", { mapID = 1453, zoneUID = 5, rank = 0, guild = "Olympus" })
			eq(H.King().zoneUID, 9); eq(H.King().realm, "Realm")
			-- His own messages from another realm of his group (a channel shared across realms): there.
			ns.db.links = { Realm = "OtherRealm+Realm", OtherRealm = "OtherRealm+Realm" }
			ns.Layers.Receive(king .. "-OtherRealm", { mapID = 1453, zoneUID = 7, rank = 0, guild = "Olympus" })
			k = H.King()
			eq(k.realm, "OtherRealm"); eq(H.KingOtherRealm(k), true, "his own word")
			H.AskKing()
			eq(said[#said], ns.L.HOP_KING_OTHER_REALM:format("Asmon", "OtherRealm"))
		end)
		ns.Print, ns.db.links = savedPrint, savedLinks
		ns.King.Reset()
		ns.Layers.Reset()
		ns.rdb.guilds = {}
		if not ok then error(err, 0) end
	end)
end)

-- 1.0.0: a player's "the King's layer doesn't work" came with a /oly bug that said nothing of the
-- King. Now one line says what this client knows of him: whether the census has him online (and
-- how sure), the realm it places him on, his layer and his crown, and how long ago each was heard.
test("1.0.0 /oly status and /oly bug say what this client knows of the King: offline, checking, online or confirmed, realm, layer, crown", function()
	WithHop(function(w, H)
		local savedMe, savedCrown = ns.me, ns.db.throneLocation
		local ok, err = pcall(function()
			ns.King.Reset()
			local function Line() return ns.StatusText():match("\nking: ([^\n]*)") end
			ns.rdb.guilds = {}
			eq(Line(), "offline")
			assert(ns.BuildBugReport():find("\nking: offline\n", 1, true), "in /oly bug too")
			-- <Olympus> reports him online, nobody else names him yet.
			ns.rdb.guilds = { ["Olympus"] = { total = 990, online = 210, zones = {}, t = w.clock, leader = "Asmongold", leaderOnline = true } }
			eq(Line(), "checking (reported online, not confirmed yet)")
			-- One other sender names him: shown, not yet what "For Olympus!" waits for.
			ns.rdb.guilds = { ["Olympus"] = Vouched({ total = 990, online = 210, zones = {}, t = w.clock, leader = "Asmongold",
				leaderOnline = true }, "W1-Realm") }
			eq(Line(), "online (one report)  |  realm Realm (ours)  |  layer not known  |  crown not heard")
			-- Two: confirmed. His crown, then his layer, and how long ago each came.
			ns.rdb.guilds = SampleGuilds()
			eq(Line(), "confirmed  |  realm Realm (ours)  |  layer not known  |  crown not heard")
			ns.King.HandleCommand("CHANNEL", ns.KingCharacter() .. "-Realm", "T1~P~3~Olympus~1453~420~510")
			w.clock = w.clock + 30
			ns.Layers.Receive("Asmongold-Realm", { mapID = 1453, zoneUID = 9, rank = 0, guild = "Olympus" })
			w.clock = w.clock + 5
			eq(Line(), "confirmed  |  realm Realm (ours)  |  layer map 1453 zone 9, heard 5s ago  |  crown map 1453, heard 35s ago")
			-- On another realm, said so.
			ns.rdb.guilds = { ["Olympus"] = Vouched({ total = 990, online = 210, zones = {}, t = w.clock,
				leader = "Asmongold-OtherRealm", leaderOnline = true }, "W1-Realm", "W2-Realm") }
			assert(Line():find("^confirmed  |  realm OtherRealm %(another realm%)  |  layer not known"), Line())
			-- On the King's own client: his crown, and when his layer last went out.
			GetGuildInfo = function() return "Olympus", "King", 0 end
			ns.me = ns.KingCharacter() .. "-Realm"
			ns.db.throneLocation = nil
			eq(Line(), "me  |  crown hidden  |  layer not sent")
			ns.db.throneLocation = true
			w.see(12)
			w.clock = w.clock + 20
			eq(Line(), "me  |  crown shown  |  layer sent 20s ago")
		end)
		ns.me, ns.db.throneLocation = savedMe, savedCrown
		ns.King.Reset()
		ns.rdb.guilds = {}
		if not ok then error(err, 0) end
	end)
end)

test("0.9.1 privacy: a report kept private names no zone at all, and 0.9.0's decoder reads it (#13)", function()
	local r = ns.Roster.Scan()
	assert(r.leaderZone and r.officers[1].zone and r.zones.m1453, "the roster knows where everyone is")
	-- (Codec.DecodeReport is the decoder 0.9.0 ships, unchanged.)
	local d = Codec.DecodeReport(Codec.EncodeReport(Codec.Shareable(r, false, nil)))
	eq(next(d.zones), nil, "no members per zone"); eq(d.leaderZone, nil)
	eq(#d.officers, #r.officers)
	for i, o in ipairs(d.officers) do
		eq(o.zone, nil, o.name); eq(o.name, r.officers[i].name); eq(o.level, r.officers[i].level)
		eq(o.online, r.officers[i].online); eq(o.class, r.officers[i].class)
	end
	eq(d.total, 1000); eq(d.online, 300); eq(d.leader, "Member1"); eq(d.leaderLevel, r.leaderLevel)
	eq(d.classes.WA, r.classes.WA); eq(d.levels[1], r.levels[1]); eq(d.top[1].name, r.top[1].name)
	-- Our own window keeps the whole report.
	eq(r.zones.m1453, 75); assert(r.leaderZone and r.officers[1].zone, "the local report untouched")
	-- Shared: the counts, and the zones of those who share theirs (Member2), nobody else's.
	local s = Codec.DecodeReport(Codec.EncodeReport(Codec.Shareable(r, true, function(name) return name == "Member2" end)))
	eq(s.zones.m1453, 75); eq(s.leaderZone, nil, "the leader did not say yes")
	for _, o in ipairs(s.officers) do eq(o.zone ~= nil, o.name == "Member2", o.name) end
end)

test("0.9.1 privacy: what our census sends follows our answer and our guildmates' hellos (#13)", function()
	local savedChannel, savedShare = GetChannelName, ns.db.shareLocation
	local ok, err = pcall(function()
		local cns, Deliver = FreshComm()
		local C = cns.Comm
		GetChannelName = function() return 5 end
		C.JoinChannel()
		local sent = {}
		C_ChatInfo.SendAddonMessage = function(_, msg, dist) sent[#sent + 1] = { dist = dist, msg = msg } end
		-- The report that went out on the channel, put back together and decoded.
		local function Sent()
			for _ = 1, 40 do C.Pump() end
			local asm, out = Codec.NewAssembler(), nil
			for _, m in ipairs(sent) do
				if m.dist == "CHANNEL" then out = Codec.Feed(asm, "Tester-Realm", m.msg, 0) or out end
			end
			sent = {}
			return assert(out and Codec.DecodeReport(out), "a report went out")
		end
		local r = ns.Roster.Scan()
		-- Member2 shares (their hello ends in z), Member3 does not, Member1 (the leader) has no addon.
		Deliver("GUILD", "Member2", "H1~0.9.1~Realm~p~z")
		Deliver("GUILD", "Member3", "H1~0.9.1~Realm~p")
		eq(C.SharesZone("Member2"), true); eq(C.SharesZone("Member3"), false); eq(C.SharesZone("Member1"), false)
		ns.db.shareLocation = nil
		C.Broadcast(r)
		local d = Sent()
		eq(d.guild, MY_GUILD); eq(d.total, 1000); eq(d.leader, "Member1")
		eq(next(d.zones), nil, "private: no members per zone"); eq(d.leaderZone, nil)
		for _, o in ipairs(d.officers) do eq(o.zone, nil, o.name .. ": we keep ours, we name nobody's") end
		ns.db.shareLocation = true
		C.Broadcast(r)
		d = Sent()
		eq(d.zones.m1453, 75, "shared: the counts per zone")
		eq(d.leaderZone, nil)
		for _, o in ipairs(d.officers) do eq(o.zone ~= nil, o.name == "Member2", o.name) end
		-- Our hello says we share; a hello without it (0.9.0, or a no since) reads as no.
		C.Hello(true)
		for _ = 1, 5 do C.Pump() end
		eq(sent[#sent].msg, "H1~" .. ns.VERSION .. "~Realm~p~z")
		Deliver("GUILD", "Member2", "H1~0.9.0~Realm~p")
		eq(C.SharesZone("Member2"), false)
		Deliver("GUILD", "Member3", "H1~0.9.1~Realm~p~z")
		eq(C.SharesZone("Member3"), true)
		cns.clock = cns.clock + 721
		eq(C.SharesZone("Member3"), false, "not heard for 12 minutes: not counted")
	end)
	GetChannelName, C_ChatInfo, ns.db.shareLocation = savedChannel, nil, savedShare
	if not ok then error(err, 0) end
end)

-- (1.1: with the first-open page loaded this question opens the page instead, tested with it;
-- this is the question as a client without the page asks it.)
test("0.9.1 privacy: the zone and layer question is asked once, when it can be, and its answer kept (#13)", function() WithoutPage(function()
	local saved = { share = ns.db.shareLocation, combat = InCombatLockdown, instance = IsInInstance, key = ns.rdb.realmKey,
		print = ns.Print, hello = ns.Comm.Hello, send = ns.Comm.Send, guild = GetGuildInfo }
	local ok, err = pcall(function()
		local printed = {}
		ns.Print = function(m) printed[#printed + 1] = m end
		ns.Comm.Hello, ns.Comm.Send = function() end, function() end
		local d = StaticPopupDialogs.OLYMPUS_LOCATION_CHOICE
		eq(d.text, ns.L.LOCATION_ASK); eq(d.button1, ns.L.LOCATION_SHARE); eq(d.button2, ns.L.LOCATION_KEEP)
		-- It says what goes out, with whose name, to whom, and how to change it.
		for _, words in ipairs({ "your zone", "your layer", "guild rank", "your guild", "your name", "Olympus channel",
			"members per zone", "hop", "/oly location on", "/oly location off" }) do
			assert(d.text:find(words, 1, true), words)
		end
		WithGamepadUI(false, function(game)
			ns.db.shareLocation, ns.rdb.realmKey = nil, nil
			ns.Layers.Reset()
			InCombatLockdown = function() return true end
			eq(ns.Layers.AskChoice(), false, "not in combat")
			InCombatLockdown, IsInInstance = function() return false end, function() return true end
			eq(ns.Layers.AskChoice(), false, "not in an instance")
			IsInInstance = function() return false end
			GetGuildInfo = function() return "House of Guedes", "Member", 3 end
			eq(ns.Layers.AskChoice(), false, "outside Olympus the addon asks nothing")
			GetGuildInfo = saved.guild
			eq(#game.shown, 0)
			eq(ns.Layers.AskChoice(), true)
			eq(game.shown[1].which, "OLYMPUS_LOCATION_CHOICE"); eq(game.shown[1].a, ns.L.CHANNEL_PUBLIC, "no key: public, and it says so")
			eq(ns.Layers.AskChoice(), false, "once a session"); eq(#game.shown, 1)
			-- Pushed out by another window: no answer, asked again next session.
			d.OnCancel(nil, nil, "override")
			eq(ns.db.shareLocation, nil)
			ns.Layers.Reset()
			ns.rdb.realmKey = "secret"
			eq(ns.Layers.AskChoice(), true)
			eq(game.shown[2].a, ns.L.CHANNEL_SEALED, "sealed: the key's holders")
			-- Keep private (or Escape): kept, never asked again.
			d.OnCancel(nil, nil, "clicked")
			eq(ns.db.shareLocation, false); eq(printed[#printed], ns.L.LOCATION_OFF)
			ns.Layers.Reset()
			eq(ns.Layers.AskChoice(), false, "answered: never again"); eq(#game.shown, 2)
			-- Share: kept too.
			ns.db.shareLocation = nil
			d.OnAccept()
			eq(ns.db.shareLocation, true); eq(printed[#printed], ns.L.LOCATION_ON)
			ns.Layers.Reset()
			eq(ns.Layers.AskChoice(), false)
		end)
		-- The gamepad UI: our own window, its buttons answer.
		WithUI(function()
			WithGamepadUI(true, function(game)
				ns.db.shareLocation = nil
				ns.Layers.Reset()
				eq(ns.Layers.AskChoice(), true)
				eq(#game.shown, 0, "never the game's popup")
				local f = ns.Dialog.Find("OLYMPUS_LOCATION_CHOICE")
				assert(f and f:IsShown(), "our window")
				assert(f.text:GetText():find(ns.L.CHANNEL_SEALED, 1, true), f.text:GetText())
				f.buttons[2]:Click()
				eq(ns.db.shareLocation, false)
			end)
		end)
		-- /oly location on | off, alone it says which; /oly status shows it.
		SlashCmdList.OLYMPUS("location on"); eq(ns.db.shareLocation, true)
		SlashCmdList.OLYMPUS("location off"); eq(ns.db.shareLocation, false)
		SlashCmdList.OLYMPUS("location"); eq(printed[#printed], ns.L.LOCATION_OFF)
		assert(ns.StatusText():find("privacy: zone and layer off  |  channel sealed", 1, true), "in /oly status")
		ns.db.shareLocation = nil
		assert(ns.StatusText():find("privacy: zone and layer not chosen (off)", 1, true))
	end)
	ns.db.shareLocation, InCombatLockdown, IsInInstance, ns.rdb.realmKey = saved.share, saved.combat, saved.instance, saved.key
	ns.Print, ns.Comm.Hello, ns.Comm.Send, GetGuildInfo = saved.print, saved.hello, saved.send, saved.guild
	ns.Layers.Reset()
	if not ok then error(err, 0) end
end) end)

test("0.9.1 privacy: the first line in each channel waits for the player's OK (#16)", function()
	local savedWarned, savedChat, savedTime, clock = ns.db.chatWarned, ns.rdb.chat, GetTime, 20000000
	GetTime = function() return clock end
	local ok, err = pcall(function()
		ns.db.chatWarned = nil
		local d = StaticPopupDialogs.OLYMPUS_CHAT_PRIVACY
		eq(d.text, ns.L.CHAN_WARN_ASK); eq(d.button1, SEND_LABEL or "Send"); eq(d.button2, CANCEL or "Cancel")
		WithGamepadUI(false, function(game)
			WithLane(function(sent)
				AsRank(3, function()
					eq(select(2, Chan.Send("C", "hi")), "rank", "a line refused anyway never asks")
				end)
				AsRank(0, function(printed)
					-- /olc: the line is held, the warning shown, nothing sent.
					local okSend, why = Chan.Send("C", "the raid is at eight")
					eq(okSend, false); eq(why, "confirm"); eq(#sent, 0)
					eq(#game.shown, 1); eq(game.shown[1].which, "OLYMPUS_CHAT_PRIVACY"); eq(game.shown[1].a, "Captains")
					eq(game.shown[1].b, ns.L.CHANNEL_PUBLIC, "who can join the channel")
					eq(game.shown[1].data.text, "the raid is at eight")
					-- Cancel: not sent, still to be asked; an answered window answers once.
					d.OnCancel(nil, game.shown[1].data, "clicked")
					eq(#sent, 0); eq(printed[#printed], ns.L.CHAN_WARN_NOT_SENT); eq(ns.db.chatWarned.C, nil)
					d.OnAccept(nil, game.shown[1].data)
					eq(#sent, 0)
					-- Asked again; Send: the held line goes out, and [Captains] is warned for good.
					clock = clock + 10
					Chan.Send("C", "the raid is at eight")
					eq(#game.shown, 2)
					d.OnAccept(nil, game.shown[2].data)
					eq(#sent, 1); assert(sent[1]:find("^M1~C~Olympus II~%d+~PA~the raid is at eight$"), sent[1])
					eq(ns.db.chatWarned.C, true)
					clock = clock + 10
					eq((Chan.Send("C", "bring potions")), true, "not asked again")
					eq(#sent, 2); eq(#game.shown, 2)
					-- Each channel once: [Lords] and [Olympus] ask too.
					clock = clock + 10
					eq(select(2, Chan.Send("L", "lords only")), "confirm"); eq(game.shown[3].a, "Lords")
					clock = clock + 10
					eq(select(2, Chan.Send("A", "hello army")), "confirm"); eq(game.shown[4].a, "Olympus")
					eq(#sent, 2)
					for _, line in ipairs(printed) do assert(line ~= "CHAN_NOTICE", "no notice after a line any more") end
				end)
			end)
		end)
		-- The gamepad UI: our own window holds the line, and its Send sends it.
		ns.db.chatWarned = nil
		WithUI(function()
			WithGamepadUI(true, function(game)
				WithLane(function(sent)
					AsRank(3, function()
						clock = clock + 10
						eq(select(2, Chan.Send("A", "for olympus")), "confirm")
						eq(#game.shown, 0)
						local f = ns.Dialog.Find("OLYMPUS_CHAT_PRIVACY")
						assert(f and f:IsShown(), "our window")
						assert(f.text:GetText():find("[Olympus] is not private", 1, true), f.text:GetText())
						eq(f.data.text, "for olympus", "the line rides in the window")
						f.buttons[1]:Click()
						eq(#sent, 1); assert(sent[1]:find("~for olympus$"), sent[1])
						eq(ns.db.chatWarned.A, true)
					end)
				end)
			end)
		end)
	end)
	GetTime, ns.db.chatWarned, ns.rdb.chat = savedTime, savedWarned, savedChat
	if not ok then error(err, 0) end
end)

-- 0.9.1: chat
do
	-- The game's chat windows as GetChatWindowInfo tells them: 1 the main one, 2 the combat log
	-- (docked), 3 unused, 4 "Olympus" docked behind another tab (hidden, so "not shown"), 5
	-- "Officers" floating, 6-10 unused. fn(w, printed) runs with them, as a Lord of Olympus II.
	-- (1.1.1: window 4 is the Olympus tab, whose first line for a character says what it holds,
	-- ns.db.chatTabIntro: none said yet, and put back as it was.)
	local function WithWindows(fn)
		local saved = { info = GetChatWindowInfo, fcf = FCF_GetChatWindowInfo, combat = IsCombatLog, num = NUM_CHAT_WINDOWS,
			default = DEFAULT_CHAT_FRAME, lines = CHAT_LINES, windows = ns.db.chatWindows, chat = ns.rdb.chat, mute = ns.db.chatMute,
			me = ns.me, frames = {}, intro = ns.db.chatTabIntro }
		local w = {}
		for i = 1, 10 do
			saved.frames[i] = _G["ChatFrame" .. i]
			w[i] = { name = "", shown = false, lines = {} }
			w[i].AddMessage = function(self, text) self.lines[#self.lines + 1] = text end
			_G["ChatFrame" .. i] = w[i]
		end
		w[1].name, w[1].shown = "General", true
		w[2].name, w[2].isDocked = "Combat Log", true
		w[3].name = "Voice"
		w[4].name, w[4].isDocked = "Olympus", true
		w[5].name, w[5].shown = "Officers", true
		NUM_CHAT_WINDOWS = 10
		GetChatWindowInfo = function(i)
			local f = w[i]
			return f.name, 14, 0, 0, 0, 1, f.shown, false, f.isDocked and 1 or nil, false
		end
		FCF_GetChatWindowInfo = nil
		IsCombatLog = function(f) return f == w[2] end
		DEFAULT_CHAT_FRAME = w[1]
		ns.db.chatWindows, ns.rdb.chat, ns.db.chatMute, ns.me, ns.db.chatTabIntro = nil, nil, nil, "Tester-Realm", nil
		local ok, err = pcall(AsRank, 0, function(printed) fn(w, printed) end)
		GetChatWindowInfo, FCF_GetChatWindowInfo, IsCombatLog, NUM_CHAT_WINDOWS = saved.info, saved.fcf, saved.combat, saved.num
		DEFAULT_CHAT_FRAME, CHAT_LINES, ns.db.chatWindows, ns.rdb.chat, ns.db.chatMute = saved.default, saved.lines, saved.windows, saved.chat, saved.mute
		ns.me, ns.db.chatTabIntro = saved.me, saved.intro
		for i = 1, 10 do _G["ChatFrame" .. i] = saved.frames[i] end
		if not ok then error(err, 0) end
	end
	local function Count(list, what)
		local n = 0
		for _, l in ipairs(list) do if tostring(l):find(what, 1, true) then n = n + 1 end end
		return n
	end
	local id = 5000

	test("chat window: each channel's lines and our own echo go to the window chosen by its name (#14)", function()
		WithWindows(function(w, printed)
			eq(Chan.ChooseWindow("olympus"), true, "any case")
			eq(ns.db.chatWindows["Tester-Realm"].A, "Olympus", "stored as the game names it")
			eq(ns.db.chatWindows["Tester-Realm"].C, "Olympus"); eq(ns.db.chatWindows["Tester-Realm"].L, "Olympus")
			eq(printed[#printed], ns.L.CHATWIN_SET:format("[Olympus], [Captains], [Lords]", '"Olympus"'))
			-- (1.1.1: a window named Olympus is the Olympus tab: it says what it holds, the legend of
			-- the channels' colours, where another window gets CHATWIN_SET.)
			eq(Count(w[4].lines, (ns.L.CHATTAB_HERE:gsub("%%s.*$", ""))), 1, "the choice is said in that window too")
			eq(Count(w[4].lines, "[Lords]"), 1, "its legend names the channels")
			eq(Chan.ChooseWindow("5 captains"), true, "by number, one channel")
			eq(ns.db.chatWindows["Tester-Realm"].C, "Officers"); eq(ns.db.chatWindows["Tester-Realm"].A, "Olympus")
			w[1].lines, w[4].lines, w[5].lines = {}, {}, {}
			id = id + 1
			eq((Chan.Receive("CHANNEL", "Member500", Msg("A", MY_GUILD, id, "to the olympus tab"), 3000000)), true)
			eq((Chan.Receive("CHANNEL", "Member2", Msg("C", MY_GUILD, id, "to the officers window"), 3000001)), true)
			eq((Chan.Receive("CHANNEL", "Member1", Msg("L", MY_GUILD, id, "lords to the olympus tab"), 3000002)), true)
			eq(Count(w[4].lines, "to the olympus tab"), 2); eq(Count(w[5].lines, "to the officers window"), 1)
			eq(#w[1].lines, 0, "nothing in the main window")
			-- (1.1.1: in the Olympus tab without the channel's name; in "Officers" with it.)
			for _, l in ipairs(w[4].lines) do assert(l:find("^|Hplayer:"), l) end
			assert(w[5].lines[1]:find("^%[Captains%] |Hplayer:"), w[5].lines[1])
			-- Our own line, shown when sent, lands with the others.
			WithLane(function() ns.db.chatWarned = { A = true, C = true, L = true }; local ok, why = Chan.Send("A", "my own line", 1e12); eq(ok, true, tostring(why)) end)
			eq(Count(w[4].lines, "my own line"), 1); eq(#w[1].lines, 0)
			-- Through the slash command, and in /oly status.
			SlashCmdList.OLYMPUS("chatwindow Officers lords")
			eq(ns.db.chatWindows["Tester-Realm"].L, "Officers")
			eq(Chan.WindowStatus(), '[Olympus] "Olympus", [Captains] "Officers", [Lords] "Officers"')
			assert(ns.StatusText():find('chat windows: [Olympus] "Olympus"', 1, true), "in /oly status")
			-- Per character, like the game's chat windows: another character's lines stay in the main window.
			ns.me = "Other-Realm"
			w[1].lines = {}
			id = id + 1
			eq((Chan.Receive("CHANNEL", "Member501", Msg("A", MY_GUILD, id, "other character"), 3000020)), true)
			eq(Count(w[1].lines, "other character"), 1)
		end)
	end)

	test("chat window: a window closed or renamed sends its lines to the main window, with one notice", function()
		WithWindows(function(w, printed)
			Chan.ChooseWindow("Olympus")
			w[4].name = "Olympus 2" -- renamed
			local n = #printed
			for k = 1, 3 do
				id = id + 1
				eq((Chan.Receive("CHANNEL", "Member" .. (510 + k), Msg("A", MY_GUILD, id, "renamed " .. k), 3001000 + k * 2)), true)
			end
			eq(Count(w[1].lines, "renamed"), 3, "nothing lost: the main window has them")
			eq(#printed, n + 1, "one notice"); eq(printed[#printed], ns.L.CHATWIN_GONE:format('"Olympus"'))
			eq(ns.db.chatWindows["Tester-Realm"].A, "Olympus", "the choice is kept")
			assert(Chan.WindowStatus():find('[Olympus] "Olympus" ' .. ns.L.CHATWIN_GONE_TAG, 1, true), Chan.WindowStatus())
			w[4].name = "Olympus" -- back
			id = id + 1
			eq((Chan.Receive("CHANNEL", "Member520", Msg("A", MY_GUILD, id, "back again"), 3001020)), true)
			eq(Count(w[4].lines, "back again"), 1); eq(#printed, n + 1)
			w[4].isDocked, w[4].shown = nil, false -- closed
			id = id + 1
			eq((Chan.Receive("CHANNEL", "Member521", Msg("A", MY_GUILD, id, "closed now"), 3001030)), true)
			eq(Count(w[1].lines, "closed now"), 1)
			eq(#printed, n + 2, "gone again after it came back: one more notice")
			-- An open window called the same (a tab made again) takes the lines back.
			w[6].name, w[6].isDocked = "OLYMPUS", true
			id = id + 1
			eq((Chan.Receive("CHANNEL", "Member522", Msg("A", MY_GUILD, id, "new tab"), 3001040)), true)
			eq(Count(w[6].lines, "new tab"), 1)
			-- Our echo too, with the window closed.
			w[6].isDocked = nil
			w[1].lines = {}
			WithLane(function() ns.db.chatWarned = { A = true, C = true, L = true }; local ok, why = Chan.Send("A", "echo to main", 1e12 + 100); eq(ok, true, tostring(why)) end)
			eq(Count(w[1].lines, "echo to main"), 1)
		end)
	end)

	test("chat window: main puts the lines back, unknown windows and the combat log are refused", function()
		WithWindows(function(w, printed)
			eq(Chan.ChooseWindow("Nope"), false)
			eq(printed[#printed], ns.L.CHATWIN_NOT_FOUND:format('"Nope"', '1 "General", 4 "Olympus", 5 "Officers"', ns.L.CHATWIN_NEW))
			eq(ns.db.chatWindows, nil, "nothing stored")
			eq(Chan.ChooseWindow("6"), false, "a closed window"); eq(Chan.ChooseWindow("11"), false); eq(Chan.ChooseWindow("0"), false)
			eq(Chan.ChooseWindow("2"), false); eq(printed[#printed], ns.L.CHATWIN_COMBATLOG)
			eq(Chan.ChooseWindow("combat log"), false); eq(printed[#printed], ns.L.CHATWIN_COMBATLOG)
			eq(Chan.ChooseWindow("1"), true, "the main window itself"); eq(ns.db.chatWindows, nil, "nothing to remember")
			eq(Chan.ChooseWindow(""), false)
			eq(printed[#printed - 1], ns.L.CHATWIN_NOW:format("[Olympus] " .. ns.L.CHATWIN_MAIN_NAME .. ", [Captains] "
				.. ns.L.CHATWIN_MAIN_NAME .. ", [Lords] " .. ns.L.CHATWIN_MAIN_NAME))
			eq(printed[#printed], ns.L.CHATWIN_USAGE)
			-- The whole name first: a window may end with a channel's name.
			w[5].name = "Olympus Lords"
			eq(Chan.ChooseWindow("olympus lords"), true)
			eq(ns.db.chatWindows["Tester-Realm"].A, "Olympus Lords"); eq(ns.db.chatWindows["Tester-Realm"].L, "Olympus Lords")
			eq(Chan.ChooseWindow("Olympus all"), true); eq(ns.db.chatWindows["Tester-Realm"].C, "Olympus")
			eq(Chan.ChooseWindow("main captains"), true)
			eq(printed[#printed], ns.L.CHATWIN_MAIN:format("[Captains]"))
			eq(ns.db.chatWindows["Tester-Realm"].C, nil); eq(ns.db.chatWindows["Tester-Realm"].A, "Olympus")
			eq(Chan.ChooseWindow("main"), true)
			eq(ns.db.chatWindows, nil, "nothing left")
			-- The game without the chat window API, or with a broken one: the frame's own name and
			-- dock (what FCF_SetWindowName and the dock set), else the main window, never an error.
			eq(Chan.ChooseWindow("Olympus Lords"), true)
			GetChatWindowInfo = nil
			eq(select(3, Chan.FindWindow("Olympus")), "Olympus", "the frame's own name")
			GetChatWindowInfo = function() error("broken") end
			eq(select(2, Chan.FindWindow("Olympus")), 4, "docked")
			-- Window 5 floats (shown, not docked): with nothing to say it is shown, the main window.
			id = id + 1
			eq((Chan.Receive("CHANNEL", "Member530", Msg("A", MY_GUILD, id, "no api"), 3002000)), true)
			eq(Count(w[1].lines, "no api"), 1, "the main window")
		end)
	end)

	-- Chattynator 224's public API returns arrays of tab names and accepts window/tab
	-- indices followed by the AddMessage arguments. It does not expose Blizzard frames.
	-- (1.1.2: the stand-in is WithChattynatorAPI's, which also records the caller's file.)
	local function WithChattynator(fn)
		WithChattynatorAPI({ { "General", "Olympus" }, { "Captains", "Lords" } }, function(c)
			WithWindows(function(w, printed) fn(c.windows, c.calls, w, printed) end)
		end)
	end
	local function Our(text) return "|c" .. ns.COLOR .. "Olympus:|r " .. text end
	local LEGEND = "|cffe6c45c[Olympus]|r, |cff59d9d9[Captains]|r, |cffbf80ff[Lords]|r"

	-- (1.1.2, PR #47's test on 1.1.1: a tab named Olympus is the Olympus tab, whose first line says
	-- what it holds, CHATTAB_HERE, where another tab gets CHATWIN_SET, and whose lines come without
	-- the channel's name; the main window says, for each tab chosen, how to let Olympus in through its
	-- filter, which Olympus cannot read. On 1.1.1's Channels.Frame, without the adaptation, the
	-- Olympus tab's lines went to the game's hidden window named Olympus: 2 calls of 3.)
	test("chat window: Chattynator tabs receive each tier and our echo instead of hidden native frames", function()
		WithChattynator(function(tabs, calls, w, printed)
			-- A native window with the same name still exists after Chattynator hides it.
			SlashCmdList.OLYMPUS("chatwindow oLYMPus olympus")
			eq(ns.db.chatWindows["Tester-Realm"].A, "Olympus")
			eq(#calls, 1, "confirmation reaches the Chattynator tab")
			eq(calls[1][3], Our(ns.L.CHATTAB_HERE:format(LEGEND)), "the Olympus tab says what it holds")
			eq(printed[#printed - 1], ns.L.CHATWIN_SET:format("[Olympus]", '"Olympus"'))
			eq(printed[#printed], ns.L.CHATTY_FILTER:format('"Olympus"'), "and how to let Olympus in, in the main window")
			eq(Chan.ChooseWindow("Captains captains"), true, "no native window with this name")
			eq(calls[2][3], Our(ns.L.CHATWIN_SET:format("[Captains]", '"Captains"')))
			eq(printed[#printed], ns.L.CHATTY_FILTER:format('"Captains"'))
			eq(Chan.ChooseWindow("Lords lords"), true)
			eq(Chan.WindowStatus(), '[Olympus] "Olympus", [Captains] "Captains", [Lords] "Lords"')
			wipe(calls)
			for index, tier in ipairs({ "A", "C", "L" }) do
				id = id + 1
				eq((Chan.Receive("CHANNEL", "Member1", Msg(tier, MY_GUILD, id, "routed " .. tier), 3200000 + index * 10)), true)
			end
			eq(#calls, 3)
			for index, target in ipairs({ { 1, 2 }, { 2, 1 }, { 2, 2 } }) do
				eq(calls[index][1], target[1]); eq(calls[index][2], target[2])
				assert(calls[index][3]:find("routed " .. ({ "A", "C", "L" })[index], 1, true))
				local color = Chan.TIERS[({ "A", "C", "L" })[index]].color
				for c = 1, 3 do eq(calls[index][3 + c], color[c], "channel color") end
			end
			assert(calls[1][3]:find("^|Hplayer:Member1|h%["), "the Olympus tab: no channel name: " .. calls[1][3])
			assert(calls[2][3]:find("^%[Captains%] |Hplayer:"), calls[2][3])
			assert(calls[3][3]:find("^%[Lords%] |Hplayer:"), calls[3][3])
			WithLane(function()
				ns.db.chatWarned = { A = true, C = true, L = true }
				local ok, why = Chan.Send("A", "own Chattynator echo", 1e12 + 200)
				eq(ok, true, tostring(why))
			end)
			eq(#calls, 4); eq(calls[4][1], 1); eq(calls[4][2], 2)
			assert(calls[4][3]:find("own Chattynator echo", 1, true))
			assert(calls[4][3]:find("^|Hplayer:"), calls[4][3])
			eq(#w[1].lines, 0); eq(#w[4].lines, 0, "no hidden native output")
		end)
	end)

	test("chat window: Chattynator names follow moved tabs and fall back once when removed", function()
		WithChattynator(function(tabs, calls, w, printed)
			eq(Chan.ChooseWindow("Captains captains"), true)
			tabs[1], tabs[2] = { "Captains", "General", "Olympus" }, { "Lords" }
			wipe(calls)
			id = id + 1
			eq((Chan.Receive("CHANNEL", "Member2", Msg("C", MY_GUILD, id, "moved tab"), 3200100)), true)
			eq(#calls, 1); eq(calls[1][1], 1); eq(calls[1][2], 1)
			tabs[1][1] = "Renamed"
			local n = #printed
			for k = 1, 2 do
				id = id + 1
				eq((Chan.Receive("CHANNEL", "Member2", Msg("C", MY_GUILD, id, "fallback " .. k), 3200110 + k * 10)), true)
			end
			eq(#calls, 1); eq(Count(w[1].lines, "fallback"), 2)
			eq(#printed, n + 1); eq(printed[#printed], ns.L.CHATWIN_GONE:format('"Captains"'))
			tabs[2][2] = "Captains"
			id = id + 1
			eq((Chan.Receive("CHANNEL", "Member2", Msg("C", MY_GUILD, id, "restored tab"), 3200150)), true)
			eq(#calls, 2); eq(calls[2][1], 2); eq(calls[2][2], 2)
			eq(Chan.ChooseWindow("main captains"), true)
			eq(ns.db.chatWindows, nil)
		end)
	end)

	test("chat window: Chattynator routing preserves chat opt-in", function()
		WithChattynator(function(tabs, calls, w)
			local savedChatOn = ns.db.addonChat
			local ok, err = pcall(function()
				for _, state in ipairs({ "unanswered", "off" }) do
					if state == "unanswered" then ns.db.addonChat = nil else ns.db.addonChat = false end
					eq(Chan.ChooseWindow("Captains captains"), true)
					if state == "unanswered" then eq(ns.db.addonChat, nil) else eq(ns.db.addonChat, false) end
					wipe(calls)
					id = id + 1
					local shown, why = Chan.Receive("CHANNEL", "Member2", Msg("C", MY_GUILD, id, "chat is off"), 3200200)
					eq(shown, false); eq(why, "off"); eq(#calls, 0)
					eq(#Chan.History("C"), 0)
				end
				ns.db.addonChat = true
				id = id + 1
				eq((Chan.Receive("CHANNEL", "Member2", Msg("C", MY_GUILD, id, "chat is on"), 3200210)), true)
				eq(#calls, 1); eq(calls[1][1], 2); eq(calls[1][2], 1)
				eq(#Chan.History("C"), 1)
				eq(#w[1].lines, 0)
			end)
			ns.db.addonChat = savedChatOn
			if not ok then error(err, 0) end
		end)
	end)

	-- (1.1.2, PR #47's test on 1.1.1: while Chattynator answers, a name not found lists its tabs by
	-- name with how to make one there, CHATTY_NOT_FOUND, where the PR added them to the game's
	-- windows' list; "2" is a tab's name there, the game's windows being hidden behind Chattynator's,
	-- and Chattynator's own combat log tab is refused as the game's is.)
	test("chat window: unavailable Chattynator API preserves native lookup and lists available tabs", function()
		WithChattynator(function(tabs, calls, w, printed)
			eq(Chan.ChooseWindow("Missing"), false)
			eq(printed[#printed], ns.L.CHATTY_NOT_FOUND:format('"Missing"', '"General", "Olympus", "Captains", "Lords"'))
			local api = Chattynator.API
			for _, unavailable in ipairs({ {}, { GetWindowsAndTabs = api.GetWindowsAndTabs },
				{ GetWindowsAndTabs = function() error("not initialized") end, AddMessageToWindowAndTab = api.AddMessageToWindowAndTab } }) do
				Chattynator.API = unavailable
				eq(Chan.FindWindow("Olympus"), w[4], "native fallback")
				eq(Chan.ChooseWindow("Captains captains"), false)
			end
			Chattynator.API = api
			eq(Chan.ChooseWindow("2"), false, "a tab's name while Chattynator answers: the game's window 2 is hidden")
			eq(printed[#printed], ns.L.CHATTY_NOT_FOUND:format('"2"', '"General", "Olympus", "Captains", "Lords"'))
			tabs[1][3] = "COMBAT_LOG"
			eq(Chan.ChooseWindow("combat_log"), false); eq(printed[#printed], ns.L.CHATWIN_COMBATLOG, "Chattynator's combat log")
			eq(Chan.ChooseWindow("Missing"), false)
			eq(printed[#printed], ns.L.CHATTY_NOT_FOUND:format('"Missing"', '"General", "Olympus", "Captains", "Lords"'), "not listed")
			Chattynator.API = {}
			eq(Chan.ChooseWindow("2"), false, "native combat log remains refused"); eq(printed[#printed], ns.L.CHATWIN_COMBATLOG)
		end)
	end)

	-- (1.1.2, the review of PR #47: its delivery had no pcall, and a window that was not a list threw
	-- at every line, /oly status included.)
	test("chat window (1.1.2): a Chattynator that fails, or answers a window that is not a list, costs no line and raises no error", function()
		WithChattynator(function(tabs, calls, w, printed)
			eq(Chan.ChooseWindow("Captains captains"), true)
			wipe(calls)
			-- A window that is not a list of names: left out, the others still read; names not strings too.
			tabs[1] = "not a window"
			eq(Chan.WindowStatus(), '[Olympus] main window, [Captains] "Captains", [Lords] main window')
			id = id + 1
			eq((Chan.Receive("CHANNEL", "Member2", Msg("C", MY_GUILD, id, "still routed"), 3200300)), true)
			eq(#calls, 1); eq(calls[1][1], 2); eq(calls[1][2], 1)
			tabs[1] = { 42, false, "", "Olympus" }
			local f, i, name = Chan.FindWindow("olympus")
			assert(f and f ~= w[4], "Chattynator's tab"); eq(i, nil); eq(name, "Olympus")
			eq(Chan.OpenWindows()[1].name, "Olympus", "only the names")
			-- Its delivery failing: the main window has the line, whole, and nothing raises.
			local api = Chattynator.API
			Chattynator.API = { GetWindowsAndTabs = api.GetWindowsAndTabs, AddMessageToWindowAndTab = function() error("Chattynator broke") end }
			id = id + 1
			local shown, why = Chan.Receive("CHANNEL", "Member2", Msg("C", MY_GUILD, id, "delivery failed"), 3200310)
			eq(shown, true, tostring(why))
			eq(Count(w[1].lines, "delivery failed"), 1, "in the main window")
			assert(w[1].lines[#w[1].lines]:find("^%[Captains%] "), w[1].lines[#w[1].lines])
			eq(Chan.ChooseWindow("Lords lords"), true, "no error either")
			eq(Count(w[1].lines, ns.L.CHATWIN_SET:format("[Lords]", '"Lords"')), 1, "the tab's line, in the main window")
			WithLane(function()
				ns.db.chatWarned = { A = true, C = true, L = true }
				local ok, why2 = Chan.Send("L", "own line, delivery failed", 1e12 + 300)
				eq(ok, true, tostring(why2))
			end)
			eq(Count(w[1].lines, "own line, delivery failed"), 1)
			-- Answering what is not a list, or a Chattynator that throws when read: the game's windows.
			Chattynator.API = { GetWindowsAndTabs = function() return "x" end, AddMessageToWindowAndTab = api.AddMessageToWindowAndTab }
			eq(Chan.Chattynator(), false); eq(Chan.FindWindow("Officers"), w[5])
			Chattynator = setmetatable({}, { __index = function() error("not a table to read") end })
			eq(Chan.Chattynator(), false); eq(Chan.FindWindow("Officers"), w[5])
			Chattynator = "not a table"
			eq(Chan.Chattynator(), false); eq(Chan.FindWindow("Officers"), w[5])
			eq(#calls, 1, "nothing reached the tab after its failure")
		end)
	end)

	-- (1.1.2: Chattynator names the line's addon after the caller of AddMessageToWindowAndTab,
	-- debugstack(2), and a tab that lets Olympus in shows only lines named Olympus. Called through
	-- pcall(api.AddMessageToWindowAndTab, ...), or as a tail call, the caller is not our file and the
	-- line is "/loadstring": this fails on either.)
	test("chat window (1.1.2): every line reaches Chattynator from Olympus/Channels.lua, the addon its tab's filter lets in", function()
		WithChattynator(function(tabs, calls, w)
			eq(Chan.ChooseWindow("Captains captains"), true)
			eq(Chan.ChooseWindow("olympus"), true)
			id = id + 1
			eq((Chan.Receive("CHANNEL", "Member2", Msg("C", MY_GUILD, id, "a line"), 3200400)), true)
			id = id + 1
			eq((Chan.Receive("CHANNEL", "Member2", Msg("A", MY_GUILD, id, "a bare line"), 3200410)), true)
			eq(#calls, 4, "two choices said in their tabs, two lines")
			for _, call in ipairs(calls) do assert(call.source:find("Olympus/Channels%.lua$"), call.source) end
		end)
	end)

	test("chat window (1.1.2): Chattynator's tab by any case, spaces around it aside, or by the name it shows; the game's windows hidden behind its tabs are not picked", function()
		WithChattynator(function(tabs, calls, w, printed)
			local saved = rawget(_G, "GENERAL")
			local ok, err = pcall(function()
				GENERAL = "General" -- (the game's string: Chattynator shows its "GENERAL" tab so)
				tabs[1] = { "GENERAL", " olympus " }
				eq(Chan.ChooseWindow("Olympus"), true)
				eq(ns.db.chatWindows["Tester-Realm"].A, " olympus ", "as Chattynator has it")
				eq(calls[#calls][1], 1); eq(calls[#calls][2], 2); eq(calls[#calls][3], Our(ns.L.CHATTAB_HERE:format(LEGEND)))
				eq(Chan.ChooseWindow("general captains"), true)
				eq(ns.db.chatWindows["Tester-Realm"].C, "General", "the name it shows")
				eq(Chan.ChooseWindow("GENERAL lords"), true); eq(ns.db.chatWindows["Tester-Realm"].L, "General")
				wipe(calls)
				id = id + 1
				eq((Chan.Receive("CHANNEL", "Member2", Msg("A", MY_GUILD, id, "spaced tab"), 3200500)), true)
				id = id + 1
				eq((Chan.Receive("CHANNEL", "Member2", Msg("C", MY_GUILD, id, "general tab"), 3200510)), true)
				eq(#calls, 2)
				eq(calls[1][2], 2); assert(calls[1][3]:find("^|Hplayer:"), "the Olympus tab, bare: " .. calls[1][3])
				eq(calls[2][2], 1); assert(calls[2][3]:find("^%[Captains%] "), calls[2][3])
				-- A game window no tab of Chattynator's is named after: not found, by name or number.
				eq(Chan.ChooseWindow("Officers"), false)
				eq(printed[#printed], ns.L.CHATTY_NOT_FOUND:format('"Officers"', '"General", " olympus ", "Captains", "Lords"'))
				eq(Chan.ChooseWindow("5"), false)
				-- Chosen before Chattynator: hidden now, so gone: the main window, one notice.
				ns.db.chatWindows["Tester-Realm"].L = "Officers"
				local n = #printed
				for k = 1, 2 do
					id = id + 1
					eq((Chan.Receive("CHANNEL", "Member1", Msg("L", MY_GUILD, id, "officers " .. k), 3200520 + k * 10)), true)
				end
				eq(Count(w[1].lines, "officers "), 2); eq(#w[5].lines, 0, "nothing in the hidden window")
				eq(#printed, n + 1); eq(printed[#printed], ns.L.CHATWIN_GONE:format('"Officers"'))
				assert(Chan.WindowStatus():find('[Lords] "Officers" ' .. ns.L.CHATWIN_GONE_TAG, 1, true), Chan.WindowStatus())
			end)
			GENERAL = saved
			if not ok then error(err, 0) end
		end)
	end)

	test("chat window (1.1.2): ChooseTab picks Chattynator's tab by its name alone (one called main is that tab), for one channel, said as /oly chatwindow says it", function()
