			net.Hear("Faker Guy-Realm", "HS~" .. COUNCIL_TEST_NAMES4:gsub("Fourth Mod", "Faker Guy"))
			net.Hear("Faker Guy-Realm", "HT~" .. COUNCIL_TEST_TITLES:gsub("Keeper of Coin", "Boss"))
