		"PIN_DONE", "PIN_TAKEN_DOWN", "PIN_NONE", "PIN_NOW", "PIN_ONLY", "PIN_USAGE", "PIN_OUTRANKED", "PIN_WAIT", "PIN_NOT_YOURS", "HELP_PIN",
