				assert(Whispered(w, "K3~"):find("Zed-Realm", 1, true), Whispered(w, "K3~"))
				for _, x in ipairs(w.sent) do assert(not x.msg:find(rot.key, 1, true), "sent " .. x.dist .. ": " .. x.msg) end
