	end)
	local pt = { L = setmetatable({}, { __index = ns.L }) }
	local savedLocale = GetLocale
	GetLocale = function() return "ptBR" end
	local ok, err = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
	GetLocale = savedLocale
	if not ok then error(err, 0) end
	for _, key in ipairs({ "PATROLSHARE_ON", "PATROLSHARE_ON_NOT_OFFICER", "PATROLSHARE_OFF", "PATROLSHARE_BY", "PATROLSHARE_COUNT", "HELP_PATROLSHARE" }) do
		local p = rawget(pt.L, key)
		assert(type(ns.L[key]) == "string" and type(p) == "string" and p ~= ns.L[key], key)
		eq(select(2, p:gsub("%%[sd]", "")), select(2, ns.L[key]:gsub("%%[sd]", "")), key)
	end
	for _, file in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
		local f = assert(io.open(ROOT .. file))
		local doc = f:read("*a")
		f:close()
		assert(doc:find("| An officer's patrol findings (1.1)", 1, true), file .. ": the privacy table")
		assert(doc:find("`/oly patrolshare on\\|off`", 1, true), file .. ": the commands")
	end
end)

-- The 1.1 review: another officer's word reached the King's untabarded list (the King is his
-- guild's master, an officer) and a sampled officer's Royal Inspection report.
test("1.1 patrol share (#29): the King's untabarded list and the army's copy never take another officer's word, nor let it change his own", function()
	WithShare(function(w, I)
		local K = ns.King
		local saved = { guild = GetGuildInfo, me = ns.me, on = ns.db.kingUntabarded }
		local ok, err = pcall(function()
			GetGuildInfo = function(unit) if unit == nil or unit == "player" then return "Olympus", "King", 0 end return nil end
			ns.me = "Asmongold Asmongler-Realm"
			eq(K.IsKing(), true); eq(I.MayShare(), true, "the King is his guild's officer: he takes his officers' findings")
			Caught(I, "Mine")
			I.AddReported("Rep", ZEUS, "OTHER")
			-- Offi (a Captain of his guild) tells him of a player nobody else inspected, and "corrects" the King's own.
			w.clock = w.clock + 30
			I.HandleShare("GUILD", "Offi-Realm", "U1~Victim:Olympus Hera:N:0;Mine:Olympus Zeus:G:0;Rep:Olympus Zeus:G:0")
			local P = I.Players()
			eq(P["Victim"].shared, true, "on his Tabards page, as Offi's word")
			eq(P["Mine"].status, "NONE", "his own patrol's finding stands"); eq(P["Mine"].shared, nil)
			eq(P["Rep"].status, "OTHER", "the Royal Inspection's report stands"); eq(P["Rep"].shared, nil)
			local function Names()
				local names = {}
				for _, e in ipairs(I.ShameList()) do names[#names + 1] = e.name end
				table.sort(names)
				return table.concat(names, ",")
			end
			eq(Names(), "Mine,Rep", "his list: his patrol and the reports, never Offi's word")
			-- Shown to the army: the same list.
			ns.db.kingUntabarded = true
			w.sent = {}
			K.SendUntabarded(true)
			eq(#w.sent, 1); assert(w.sent[1]:find("^CHANNEL T1~U~"), w.sent[1])
			assert(not w.sent[1]:find("Victim", 1, true), w.sent[1])
			assert(w.sent[1]:find("Mine:", 1, true) and w.sent[1]:find("Rep:", 1, true), w.sent[1])
			-- The Royal Inspection reports him later: then he is the King's, Offi's name gone.
			I.AddReported("Victim", "Olympus Hera", "NONE")
			eq(P["Victim"].shared, nil); eq(P["Victim"].by, nil)
			eq(Names(), "Mine,Rep,Victim")
			-- A player he marked by hand stays on it, whoever's word the tabard is.
			I.HandleShare("GUILD", "Offi-Realm", "U1~Marked:Olympus Hera:G:0")
			P["Marked"].marked = true
			eq(Names(), "Marked,Mine,Rep,Victim")
		end)
		GetGuildInfo, ns.me, ns.db.kingUntabarded = saved.guild, saved.me, saved.on
		if not ok then error(err, 0) end
	end)
	for _, file in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
		local f = assert(io.open(ROOT .. file))
		local doc = f:read("*a")
		f:close()
		assert(doc:find("for their Tabards pages alone: never the King's untabarded list, nor a Royal Inspection's report", 1, true), file .. ": the privacy table")
	end
end)

test("1.1 patrol share (#29): a sampled officer's Royal Inspection report names only what his own patrol saw", function()
	WithShare(function(w, I)
		local K = ns.King
		local whispers, timers = {}, {}
		local saved = { after = ns.After, whisper = ns.Comm.Whisper, patrol = I.SetPatrol, pace = I.SetPace, alert = ns.PlayAlert }
		local ok, err = pcall(function()
			ns.After = function(_, _, f) timers[#timers + 1] = f end
			ns.Comm.Whisper = function(to, msg) whispers[#whispers + 1] = to .. " " .. msg end
			I.SetPatrol, I.SetPace, ns.PlayAlert = function() end, function() end, function() end
			K.RunInspection("King-Realm", 7)
			eq(#timers, 1, "a patrol of INSPECT_TIME")
			Caught(I, "Mine")
			-- A fellow officer's findings arrive during the patrol: a stranger, and a "correction" of ours.
			w.clock = w.clock + 30
			I.HandleShare("GUILD", "Offi-Realm", "U1~Victim:Olympus Hera:N:0;Mine:Olympus Zeus:G:0")
			eq(I.Players()["Victim"].shared, true, "on our page, as his word")
			eq(I.Players()["Mine"].status, "NONE", "not while our report is being made")
			timers[1]()
			eq(#whispers, 1)
			local names = whispers[1]:match("^King%-Realm T3~7~[^~]*~%d+~%d+~%d+~(.*)$")
			eq(names, "Mine:Olympus Zeus:N", "ours alone, not the finding another officer passed on")
		end)
		ns.After, ns.Comm.Whisper, I.SetPatrol, I.SetPace, ns.PlayAlert = saved.after, saved.whisper, saved.patrol, saved.pace, saved.alert
		if not ok then K.Reset() error(err, 0) end
		-- Once the report went, a later word replaces an older own inspection again (an officer's page).
		w.clock = w.clock + 100
		I.HandleShare("GUILD", "Offi-Realm", "U1~Mine:Olympus Zeus:G:0")
		eq(I.Players()["Mine"].status, "GUILD"); eq(I.Players()["Mine"].shared, true)
	end)
end)
end

---------------------------------------------------------------------------
-- 1.1: the approved guilds, named by the author's signed titles list (a throwaway key's lists here,
-- made with scripts/council-sign.py: realm group "Realm", <Sentinels of Zeus> for the Alliance and
-- <Horde Friends> for the Horde, then a newer list without them)
---------------------------------------------------------------------------

do
local APPROVED_TEST_N = ""
local APPROVED_TEST_MU = ""
local APPROVED_TEST_K = 86
local APPROVED_WITH = "HT1~1790664446~Realm~0~^^Test Councillor=Council Speaker;^guilds^Alliance^Sentinels of Zeus;^guilds^Horde^Horde Friends~"
local APPROVED_WITHOUT = "HT1~1790664448~Realm~0~^^Test Councillor=Council Speaker~"

-- The approved guilds' test council: the test key in place of the author's, our guild <Sentinels
-- of Zeus> (no Olympus by its name), every store put back after.
local function WithApproved(fn)
	local W = ns.Workshop
	local saved = { council = ns.rdb.council, titles = ns.rdb.councilTitles, me = ns.me, guild = GetGuildInfo, print = ns.Print,
		check = ns.Comm.CheckMembership, scan = ns.Roster.RequestScan, chunked = ns.Comm.SendChunked, random = W.random,
		faction = ns.faction, signed = ns.COUNCIL_SIGNED, own = ns.COUNCIL_TITLES, queue = ns.Comm.QueueSize }
	local w = { printed = {}, checked = 0, scanned = 0, guild = "Sentinels of Zeus", chunks = {} }
	local ok, err = pcall(function()
		ns.rdb.council, ns.rdb.councilTitles, ns.COUNCIL_SIGNED, ns.COUNCIL_TITLES = nil, nil, nil, nil
		ns.me, ns.faction = "Tester-Realm", "Alliance"
		GetGuildInfo = function() return w.guild, "Member", 3 end
		ns.Print = function(m) w.printed[#w.printed + 1] = m end
		ns.Comm.CheckMembership = function() w.checked = w.checked + 1 end
		ns.Roster.RequestScan = function() w.scanned = w.scanned + 1 end
		ns.Comm.SendChunked = function(payload, _, dist) w.chunks[#w.chunks + 1] = (dist or "CHANNEL") .. " " .. payload:sub(1, 3) end
		W.random = function() return 0 end
		ns.Comm.QueueSize = function() return 0 end
		W.ResetVerify()
		ns.Sign.WithKey(APPROVED_TEST_N, APPROVED_TEST_MU, APPROVED_TEST_K, function() fn(w, W) end)
	end)
	ns.rdb.council, ns.rdb.councilTitles, ns.me, GetGuildInfo, ns.Print = saved.council, saved.titles, saved.me, saved.guild, saved.print
	ns.Comm.CheckMembership, ns.Roster.RequestScan, ns.Comm.SendChunked, W.random = saved.check, saved.scan, saved.chunked, saved.random
	ns.faction, ns.COUNCIL_SIGNED, ns.COUNCIL_TITLES, ns.Comm.QueueSize = saved.faction, saved.signed, saved.own, saved.queue
	W.ResetVerify()
	if not ok then error(err, 0) end
end

test("1.1 approved guilds: the titles list's entry per faction, as the addon keeps it (letters and spaces, 24 at most, 20 a faction, each once)", function()
	local long = ("Guild "):rep(5)
	local names = {}
	for i = 1, 22 do names[i] = "Guild " .. string.char(64 + i) end
	local g = ns.ReadApprovedGuilds("^^Test Councillor=Speaker;Department^INV_X^A=B;^steward^Alliance^Some One-Realm;"
		.. "^guilds^Alliance^ Sentinels of Zeus ,Bad1 Guild,sentinels of ZEUS," .. long .. ",Ok Guild;^guilds^Horde^Horde Friends;"
		.. "^guilds^Neutral^Nobody;^guilds^Horde^" .. table.concat(names, ","))
	eq(table.concat(g.Alliance, "|"), "Sentinels of Zeus|Ok Guild", "trimmed, each once, no digits, 24 characters at most")
	eq(#g.Horde, 20, "20 a faction"); eq(g.Horde[1], "Horde Friends"); eq(g.Neutral, nil)
	eq(next(ns.ReadApprovedGuilds("^^A=B;Dept^^C=D;^steward^Alliance^X Y-Realm")), nil, "departments and Stewards are no guilds")
	-- A 1.0.0 client's reading of the same list: its departments and its Steward, the guilds left out.
	eq(#ns.ReadStewards("^guilds^Alliance^Sentinels of Zeus;^steward^Alliance^Some One-Realm").Alliance, 1)
end)

test("1.1 approved guilds: <OLYMPIAN> ships with the addon (Alliance): an Olympus guild with no signed list to paste, any case; nothing else Olympian, never the Horde's", function()
	local saved = { faction = ns.faction, titles = ns.rdb.councilTitles, inGuild = IsInGuild, guild = GetGuildInfo }
	local ok, err = pcall(function()
		ns.faction, ns.rdb.councilTitles = "Alliance", nil
		eq(ns.NamedOlympus("OLYMPIAN"), false, "not by its name")
		eq(ns.IsFederation("OLYMPIAN"), true, "no list held: shipped with the addon")
		eq(ns.IsFederation("Olympian"), true, "any case")
		eq(ns.IsFederation("Olympians"), false); eq(ns.IsFederation("Olympian Guard"), false); eq(ns.IsFederation("Olympia"), false)
		eq(table.concat(ns.ApprovedGuilds(), ","), "OLYMPIAN")
		-- Its members' addons are Olympus members at once: nothing to paste.
		IsInGuild, GetGuildInfo = function() return true end, function() return "OLYMPIAN", "Member", 3 end
		eq(ns.IsMember(), true)
		eq(ns.ApprovedOnly(), true, "by the approved list alone (its name would not make it one)")
		-- The Horde's census: not theirs.
		ns.faction = "Horde"
		eq(ns.IsFederation("OLYMPIAN"), false, "the Alliance's guild alone")
		eq(ns.IsMember(), false)
	end)
	ns.faction, ns.rdb.councilTitles, IsInGuild, GetGuildInfo = saved.faction, saved.titles, saved.inGuild, saved.guild
	if not ok then error(err, 0) end
end)

test("1.1 approved guilds: a guild the author's signed list names is an Olympus guild, on the list's realm group and faction; a newer list without it ends it", function()
	WithApproved(function(w, W)
		eq(ns.IsFederation("Sentinels of Zeus"), false, "not by its name"); eq(ns.IsMember(), false)
		eq(ns.NamedOlympus("Olympian"), false, "the name rule still leaves Olympian out")
		eq(ns.IsFederation("Olympian Guard"), false, "and any other Olympian guild (<OLYMPIAN> ships with the addon: its own test)")
		-- A changed list is refused: nothing approved.
		eq(W.TakeTitles((APPROVED_WITH:gsub("Sentinels of Zeus", "Sentinels of Hera", 1)), "Relay-Realm"), false)
		eq(ns.IsFederation("Sentinels of Hera"), false)
		eq(W.TakeTitles(APPROVED_WITH, "Relay1-Realm"), true, "the signed list")
		eq(ns.IsFederation("Sentinels of Zeus"), true); eq(ns.IsFederation("SENTINELS OF ZEUS"), true, "any case")
		eq(ns.NamedOlympus("Sentinels of Zeus"), false, "the name rule alone says no"); eq(ns.ApprovedOnly(), true)
		eq(ns.IsMember(), true, "its members are Olympus members now")
		eq(w.printed[#w.printed], ns.L.APPROVED_YOU:format("Sentinels of Zeus"))
		eq(w.checked, 1, "the channel joined, the census asked for, as when one joins a guild"); eq(w.scanned, 1)
		eq(ns.IsFederation("Horde Friends"), false, "the Horde's approved guild is not ours")
		ns.faction = "Horde"
		eq(ns.IsFederation("Horde Friends"), true); eq(ns.IsFederation("Sentinels of Zeus"), false)
		ns.faction = "Alliance"
		ns.me = "Tester-OtherRealm"
		eq(ns.IsFederation("Sentinels of Zeus"), false, "another realm group")
		ns.me = "Tester-Realm"
		-- A list taken by 1.0.0 (no guilds kept): read again from its signed text.
		ns.rdb.councilTitles.guilds = nil
		eq(table.concat(ns.ApprovedGuilds(), ","), "OLYMPIAN,Sentinels of Zeus", "(the one the addon ships with first)")
		eq(ns.IsApprovedGuild("Sentinels of Zeus"), true)
		-- The census takes its reports now.
		local savedGuilds = ns.rdb.guilds
		ns.rdb.guilds = {}
		w.guild = "Olympus II" -- (our own guild's report comes from our roster: another guild's here)
		local r = { guild = "Sentinels of Zeus", total = 50, online = 10, leader = "Sentry", users = 2, zones = {}, officers = {}, ranks = {}, top = {} }
		local taken = ns.Data.Receive(r, "Sentry-Realm")
		ns.rdb.guilds = savedGuilds
		w.guild = "Sentinels of Zeus"
		eq(taken, true, "a report of it counts")
		-- The newer list without it: no longer.
		eq(W.TakeTitles(APPROVED_WITHOUT, "Relay2-Realm"), true)
		eq(ns.IsFederation("Sentinels of Zeus"), false); eq(ns.IsMember(), false)
		eq(w.printed[#w.printed], ns.L.APPROVED_NO_LONGER:format("Sentinels of Zeus")); eq(w.checked, 2)
	end)
end)

test("1.1 approved guilds: outside any Olympus guild the addon puts together the author's titles list alone, over its own guild", function()
	local savedGuild, savedChannel = GetGuildInfo, GetChannelName
	local ok, err = pcall(function()
		GetGuildInfo = function() return "Sentinels of Zeus", "Member", 3 end
		GetChannelName = function() return 0 end
		local cns, Deliver = FreshComm()
		local got = {}
		for _, kind in ipairs({ "HT", "HS", "U1", "M1" }) do
			cns.Comm.Handle(kind, function(dist, sender, text) got[#got + 1] = dist .. " " .. sender .. " " .. text:sub(1, 12) end)
		end
		local function Pieces(dist, sender, payload, id)
			for _, c in ipairs(ns.Codec.Chunk(payload, id)) do Deliver(dist, sender, c) end
		end
		Pieces("GUILD", "Sentry-Realm", "HT~" .. APPROVED_WITH, "7")
		eq(#got, 1, "the titles list, put together"); eq(got[1], "GUILD Sentry-Realm HT~HT1~17906")
		-- Nothing else: the names list, a lone message, anything on the channel, a blocked guildmate's.
		Pieces("GUILD", "Sentry-Realm", "HS~HS1~1~Realm~A B~" .. ("0"):rep(512), "8")
		Deliver("GUILD", "Sentry-Realm", "U1~Bob:Olympus Zeus:N:0")
		Pieces("CHANNEL", "Stranger-Realm", "HT~" .. APPROVED_WITH, "9")
		ns.db.blocked["troll-realm"] = true
		Pieces("GUILD", "Troll-Realm", "HT~" .. APPROVED_WITH, "10")
		ns.db.blocked["troll-realm"] = nil
		eq(#got, 1, "only the titles list over our guild")
	end)
	GetGuildInfo, GetChannelName, C_ChatInfo = savedGuild, savedChannel, nil
	if not ok then error(err, 0) end
end)

test("1.1 approved guilds: its members holding the list pass it over their guild every 5 minutes; the first one pastes it (/oly approved paste)", function()
	WithApproved(function(w, W)
		W.ResetListAsk()
		-- Nothing held: nothing to pass on.
		eq(W.RelayGuild(), false)
		-- The paste: junk refused, the list taken (the text around it left out), the same one again held.
		eq(W.PasteTitles("hello"), false); eq(w.printed[#w.printed], ns.L.APPROVED_PASTE_BAD)
		eq(W.PasteTitles("ns.COUNCIL_TITLES = \"" .. APPROVED_WITH .. "\""), true)
		eq(w.printed[#w.printed - 1], ns.L.APPROVED_YOU:format("Sentinels of Zeus"))
		eq(w.printed[#w.printed], ns.L.APPROVED_PASTE_TAKEN)
		eq(table.concat(w.chunks, ","), "GUILD HT~,CHANNEL HT~", "to our guild at once, and our channel (the titles: no name list held)")
		eq(W.PasteTitles(APPROVED_WITH), false); eq(w.printed[#w.printed], ns.L.APPROVED_PASTE_HELD)
		-- A changed list pasted: refused (a newer time would need the author's signature).
		W.ResetVerify()
		eq(W.PasteTitles((APPROVED_WITHOUT:gsub("Council Speaker", "Council Boss", 1))), false)
		eq(w.printed[#w.printed], ns.L.APPROVED_PASTE_BAD)
		-- The relay over our guild: each APPROVED_RELAY_EVERY, whatever our guild's realms (its clock
		-- starts again here: the test's reset above cleared it).
		eq(W.RelayGuild(true), true)
		w.chunks = {}
		local savedNow = ns.Now
		local now = ns.Now()
		ns.Now = function() return now end
		eq(W.RelayGuild(), false, "just passed on")
		now = now + W.APPROVED_RELAY_EVERY
		eq(W.RelayGuild(), true)
		eq(table.concat(w.chunks, ","), "GUILD HT~")
		-- A guild Olympus by its name keeps 1.0.0's rule: only while its addon users span realms.
		w.guild = "Olympus II"
		now = now + W.APPROVED_RELAY_EVERY
		eq(W.RelayGuild(), false)
		ns.Now = savedNow
		-- /oly approved: the list, and whether ours is on it.
		w.guild = "Sentinels of Zeus"
		SlashCmdList.OLYMPUS("approved")
		eq(w.printed[#w.printed - 1], ns.L.APPROVED_LIST:format("OLYMPIAN, Sentinels of Zeus"), "the shipped ones first, then the signed list's")
		eq(w.printed[#w.printed], ns.L.APPROVED_MINE:format("Sentinels of Zeus"))
		w.guild = "Stormwind Traders"
		SlashCmdList.OLYMPUS("approved")
		eq(w.printed[#w.printed], ns.L.APPROVED_NOT_MINE:format("Stormwind Traders"))
		w.guild = "Sentinels of Zeus"
		assert(ns.StatusText():find("approved guilds: OLYMPIAN, Sentinels of Zeus  |  ours is Olympus by the list alone", 1, true))
		-- The Join screen (a guild not Olympus by its name, before the list): a click opens the paste box.
		local savedDialog = ns.ShowDialog
		local shown
		ns.ShowDialog = function(which) shown = which end
		w.guild = "Stormwind Traders"
		local join = ns.Views.RecruitLines()
		local hint = join[#join]
		eq(hint.text, "|cff9d9d9d" .. ns.L.APPROVED_JOIN_HINT:format("Stormwind Traders") .. "|r")
		hint.onClick()
		ns.ShowDialog = savedDialog
		eq(shown, "OLYMPUS_APPROVED_PASTE")
		w.guild = "Sentinels of Zeus"
		W.ResetListAsk()
	end)
end)

test("1.1 approved guilds: strings in both languages; README and CurseForge say who counts and how the list is signed", function()
	local pt = { L = setmetatable({}, { __index = ns.L }) }
	local savedLocale = GetLocale
	GetLocale = function() return "ptBR" end
	local ok, err = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
	GetLocale = savedLocale
	if not ok then error(err, 0) end
	for _, key in ipairs({ "APPROVED_YOU", "APPROVED_NO_LONGER", "APPROVED_PASTE_PROMPT", "APPROVED_PASTE_TAKEN", "APPROVED_PASTE_HELD",
		"APPROVED_PASTE_BAD", "APPROVED_LIST", "APPROVED_MINE", "APPROVED_NOT_MINE", "HELP_APPROVED", "APPROVED_JOIN_HINT" }) do
		local p = rawget(pt.L, key)
		assert(type(ns.L[key]) == "string" and type(p) == "string" and p ~= ns.L[key], key)
		eq(select(2, p:gsub("%%s", "")), select(2, ns.L[key]:gsub("%%s", "")), key)
	end
	eq(StaticPopupDialogs.OLYMPUS_APPROVED_PASTE.maxLetters, ns.Workshop.TITLES_BLOB, "room for the whole list")
	for _, file in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
		local f = assert(io.open(ROOT .. file))
		local doc = f:read("*a")
		f:close()
		assert(doc:find("/oly approved paste", 1, true), file)
		assert(doc:find("signed list", 1, true), file)
	end
	local f = assert(io.open(ROOT .. "README.md"))
	local doc = f:read("*a")
	f:close()
	assert(doc:find("council-sign.py guild", 1, true), "README: the signing command")
end)
end

---------------------------------------------------------------------------
-- 1.1 (Fern's #22): the guild's loot notes and points, officers write them by hand
---------------------------------------------------------------------------

do
-- Our guild's roster (Offi a Captain, Bob and Ann Smith members; we are an officer while w.rank is
-- 1), what goes out (w.sent: dist, message, logged; w.chunks), the server's clock (w.clock), the
-- answers' delay (w.later), the dialogs opened (w.dialogs), the group's state and the items the
-- client knows.
local LOOT_GLOBALS = { "GetGuildInfo", "GetServerTime", "GetItemInfo", "IsInGroup", "LOOT_ITEM", "LOOT_ITEM_MULTIPLE", "LOOT_ITEM_SELF",
	"LOOT_ITEM_SELF_MULTIPLE" }
local BELT = "|cffa335ee|Hitem:16830::::::::60:::::|h[Cenarion Bindings]|h|r"
local function WithLoot(fn)
	local Lt = ns.Loot
	local saved = { send = ns.Comm.Send, chunked = ns.Comm.SendChunked, byName = ns.Roster.byName, loot = ns.rdb.loot, print = ns.Print,
		fire = ns.Fire, after = Lt.after, random = Lt.random, dialog = ns.ShowDialog, ui = ns.UI, queue = ns.Comm.QueueSize, now = ns.Now,
		peers = ns.Comm.Peers }
	for _, k in ipairs(LOOT_GLOBALS) do saved[k] = _G[k] end
	local w = { sent = {}, chunks = {}, rank = 1, printed = {}, clock = 1790000000, later = {}, delays = {}, dialogs = {}, group = true, fired = {},
		queue = 0, items = { [16830] = { "Cenarion Bindings", BELT, 4 }, [2589] = { "Linen Cloth", "|cffffffff|Hitem:2589::::::::60:::::|h[Linen Cloth]|h|r", 1 } } }
	ns.rdb.loot = nil
	Lt.Reset()
	-- (1.1 review: our clock, our send queue's length and the guildmates who said hello, for the answers' pace.)
	ns.Now = function() return w.clock end
	ns.Comm.QueueSize = function() return w.queue end
	ns.Comm.Peers = function() return w.peers or {} end
	ns.Comm.Send = function(dist, msg, key, urgent, logged) w.sent[#w.sent + 1] = { dist = dist, msg = msg, logged = logged, urgent = urgent } end
	ns.Comm.SendChunked = function(payload, urgent, dist) w.chunks[#w.chunks + 1] = (dist or "CHANNEL") .. " " .. payload end
	GetGuildInfo = function(unit) if unit == nil or unit == "player" then return MY_GUILD, "Titan", w.rank end return nil end
	GetServerTime = function() return w.clock end
	GetItemInfo = function(id)
		id = tonumber(type(id) == "string" and id:match("item:(%d+)") or id)
		local it = w.items[id]
		if it then return it[1], it[2], it[3] end
	end
	IsInGroup = function() return w.group end
	LOOT_ITEM, LOOT_ITEM_MULTIPLE = "%s receives loot: %s.", "%s receives loot: %sx%d."
	LOOT_ITEM_SELF, LOOT_ITEM_SELF_MULTIPLE = "You receive loot: %s.", "You receive loot: %sx%d."
	ns.Roster.byName = { ["Offi-Realm"] = 1, ["Tester-Realm"] = 1, ["Bob-Realm"] = 3, ["Ann Smith-Realm"] = 3 }
	ns.Print = function(m) w.printed[#w.printed + 1] = m end
	ns.Fire = function(name, key) w.fired[#w.fired + 1] = name .. ":" .. tostring(key) end
	Lt.after = function(seconds, _, f) w.later[#w.later + 1] = f; w.delays[#w.delays + 1] = seconds end
	Lt.random = function() return 0 end
	ns.ShowDialog = function(which, a, b, data) w.dialogs[#w.dialogs + 1] = { which = which, a = a, data = data } end
	w.run = function() local l = w.later; w.later = {}; for _, f in ipairs(l) do f() end end
	w.last = function() return w.sent[#w.sent] end
	local ok, err = pcall(fn, w, Lt)
	ns.Comm.Send, ns.Comm.SendChunked, ns.Roster.byName, ns.rdb.loot, ns.Print = saved.send, saved.chunked, saved.byName, saved.loot, saved.print
	ns.Fire, Lt.after, Lt.random, ns.ShowDialog, ns.UI = saved.fire, saved.after, saved.random, saved.dialog, saved.ui
	ns.Comm.QueueSize, ns.Now, ns.Comm.Peers = saved.queue, saved.now, saved.peers
	for _, k in ipairs(LOOT_GLOBALS) do _G[k] = saved[k] end
	Lt.Reset()
	ns.Views.CloseChat()
	ns.Views.ClearFilters()
	if not ok then error(err, 0) end
end
local B36 = ns.Codec.Base36

test("1.1 loot notes (#22): an officer writes the decision; his guild gets it over GUILD (his words logged), never the channel", function()
	WithLoot(function(w, Lt)
		local n = Lt.Write("Ann passed on the gloves, Bob gets the next belt", 16830, "Ann Smith")
		assert(n, "written")
		eq(w.printed[#w.printed], ns.L.LOOT_WRITTEN)
		local m = w.last()
		eq(m.dist, "GUILD"); eq(m.logged, true, "his own words, through the logged API")
		eq(m.urgent, true, "never dropped from his queue: addons online hold themselves whole from their session's start")
		eq(m.msg, ("X1~N~Tester-Realm~%s~%s~%s~16830~~Ann Smith~Ann passed on the gloves, Bob gets the next belt"):format(n.id, B36(w.clock), B36(w.clock)))
		eq(#Lt.Notes(), 1); eq(Lt.Notes()[1].n.to, "Ann Smith")
		-- Escape codes, separators and runs of spaces go; the longest note fits one message.
		w.clock = w.clock + 1
		n = Lt.Write("a|cffff0000red|r ~ b^c    d", nil, nil)
		eq(n.text, "a cffff0000red r b c d")
		n = Lt.Write(("x"):rep(300), 16830, ("Longname"):rep(10))
		eq(#n.text, Lt.TEXT_MAX); assert(#w.last().msg <= 255, #w.last().msg)
		-- Nothing to write, or not an officer: nothing sent.
		local count = #w.sent
		Lt.Write(" ")
		eq(w.printed[#w.printed], ns.L.LOOT_TOO_SHORT)
		w.rank = 3
		Lt.Write("Bob gets it")
		eq(w.printed[#w.printed], ns.L.LOOT_OFFICERS_ONLY); eq(#w.sent, count)
		for _, s in ipairs(w.sent) do eq(s.dist, "GUILD", "never the channel") end
	end)
end)

test("1.1 loot notes (#22): a guildmate's addon takes an officer's changes only (his rank by its roster), newest wins; a removal holds", function()
	WithLoot(function(w, Lt)
		w.rank = 3 -- (a member's addon)
		local t = B36(w.clock)
		Lt.HandleLive("GUILD", "Offi-Realm", ("X1~N~Offi-Realm~a1~%s~%s~16830~~Ann Smith~Ann gets the belt"):format(t, t))
		eq(#Lt.Notes(), 1); eq(Lt.Notes()[1].n.writer, "Offi-Realm")
		-- A member's, the channel's, a note in someone else's name, a malformed one: nothing.
		Lt.HandleLive("GUILD", "Bob-Realm", ("X1~N~Bob-Realm~b1~%s~%s~~~~Bob wins"):format(t, t))
		Lt.HandleLive("CHANNEL", "Offi-Realm", ("X1~N~Offi-Realm~c1~%s~%s~~~~Channel note"):format(t, t))
		Lt.HandleLive("GUILD", "Offi-Realm", ("X1~N~Lord-Realm~d1~%s~%s~~~~In his name"):format(t, t))
		Lt.HandleLive("GUILD", "Offi-Realm", "X1~N~Offi-Realm~e1~zzzzzzzzz~1~~~~Bad times")
		Lt.HandleLive("GUILD", "Offi-Realm", ("X1~N~Offi-Realm~f1~%s~%s~~~~"):format(t, t))
		eq(#Lt.Notes(), 1, "only the officer's own note")
		-- Another officer removes it: its mark holds against an older copy.
		local later = B36(w.clock + 60)
		Lt.HandleLive("GUILD", "Tester-Realm", ("X1~N~Offi-Realm~a1~%s~%s~16830~1~~"):format(t, later))
		eq(#Lt.Notes(), 0, "removed")
		Lt.HandleBook("GUILD", "Offi-Realm", ("XB~S~0~0~0~0~0~0^N~Offi-Realm~a1~%s~%s~16830~~Ann Smith~Ann gets the belt"):format(t, t))
		eq(#Lt.Notes(), 0, "an older copy never brings it back")
		-- Points by hand: newest wins, a cleared one shows no more.
		Lt.HandleLive("GUILD", "Offi-Realm", "X1~P~Bob-Realm~12~" .. B36(w.clock) .. "~Offi-Realm")
		eq(Lt.Points()[1].v, 12)
		Lt.HandleLive("GUILD", "Offi-Realm", "X1~P~Bob-Realm~99~" .. B36(w.clock - 5) .. "~Offi-Realm")
		eq(Lt.Points()[1].v, 12, "an older number")
		Lt.HandleLive("GUILD", "Offi-Realm", "X1~P~Bob-Realm~~" .. B36(w.clock + 5) .. "~Offi-Realm")
		eq(#Lt.Points(), 0, "cleared")
		Lt.HandleLive("GUILD", "Offi-Realm", "X1~P~Bob-Realm~100000~" .. B36(w.clock + 9) .. "~Offi-Realm")
		eq(#Lt.Points(), 0, "past the limit")
		-- A removed note's mark is kept 30 days, then goes.
		w.clock = w.clock + Lt.REMOVED_KEEP + 120
		Lt.Prune()
		eq(next(Lt.Book().notes), nil)
	end)
end)

test("1.1 loot notes (#22): points are a notebook: an officer sets a member's number by hand, nothing adds or takes any", function()
	WithLoot(function(w, Lt)
		Lt.SetPoints("bob 12")
		eq(Lt.Points()[1].member, "Bob-Realm"); eq(Lt.Points()[1].v, 12)
		eq(w.last().msg, "X1~P~Bob-Realm~12~" .. B36(w.clock) .. "~Tester-Realm"); eq(w.last().dist, "GUILD")
		eq(w.printed[#w.printed], ns.L.LOOT_POINTS_DONE:format("Bob", 12))
		Lt.SetPoints("Bob +3")
		eq(Lt.Points()[1].v, 3, "set, not added")
		Lt.SetPoints("Ann Smith -4")
		eq(#Lt.Points(), 2); eq(Lt.Points()[2].member, "Ann Smith-Realm"); eq(Lt.Points()[2].v, -4)
		Lt.SetPoints("Bob")
		eq(#Lt.Points(), 1, "the name alone clears them"); eq(w.printed[#w.printed], ns.L.LOOT_POINTS_CLEARED:format("Bob"))
		local count = #w.sent
		Lt.SetPoints("Nobody 5")
		eq(w.printed[#w.printed], ns.L.LOOT_POINTS_NOT_MEMBER:format("Nobody"))
		Lt.SetPoints("Bob 100000")
		eq(w.printed[#w.printed], ns.L.LOOT_POINTS_BAD:format(Lt.POINTS_LIMIT, Lt.POINTS_LIMIT))
		w.rank = 2
		Lt.SetPoints("Bob 5")
		eq(w.printed[#w.printed], ns.L.LOOT_OFFICERS_ONLY); eq(#w.sent, count)
	end)
end)

-- (1.1 review: the ask carried the newest change held and was answered with the changes newer than
-- it, once each 2 minutes by every officer. It now names the ranges its book lacks, and an officer
-- answers only ranges his own book holds whole: this test says so.)
test("1.1 loot notes (#22): an ask names what its book lacks; an officer's addon holding it whole answers, in pieces over GUILD; the page asks again while something lacks", function()
	WithLoot(function(w, Lt)
		-- The officer's book: a note and points.
		local n = Lt.Write("Ann gets the belt", 16830, "Ann Smith")
		Lt.SetPoints("Bob 12")
		eq(select(2, Lt.Book()), w.clock + 1, "this session holds every change from its start on")
		local before = ("XQ~0~%s~0~%s"):format(B36(w.clock + 1), B36(w.clock + 1))
		-- Not whole yet (his session only started): an ask for what came before is not his to answer.
		w.sent = {}
		Lt.HandleAsk("GUILD", "Bob-Realm", before)
		eq(#w.later, 0, "his book is not known whole")
		-- His login's ask: everything before his session; nobody answered in ASK_WAIT: his book is the guild's.
		eq(Lt.Ask(), true)
		eq(w.last().msg, before); eq(w.last().dist, "GUILD")
		eq(#w.later, 1); eq(w.delays[1], Lt.ASK_WAIT)
		w.run()
		eq(Lt.Ask(), false, "nothing lacks now")
		w.delays = {}
		-- A member's ask for everything (a login on the Forever beta), and another's meanwhile.
		w.clock = w.clock + 100
		local all = ("XQ~0~%s~0~%s"):format(B36(w.clock), B36(w.clock))
		Lt.HandleAsk("GUILD", "Bob-Realm", all)
		Lt.HandleAsk("GUILD", "Ann Smith-Realm", all) -- (one answer covers both)
		eq(#w.later, 1); eq(w.delays[1], 2, "his turn: the first (no other officer said hello)")
		w.run()
		eq(#w.chunks, 1)
		local payload = w.chunks[1]
		eq(payload:match("^GUILD XB~([^%^]*)"), ("S~0~%s~0~0~%s~0"):format(B36(w.clock), B36(w.clock)), "every change up to the ask, whole")
		assert(payload:find(("N~Tester-Realm~%s~"):format(n.id), 1, true), "the note")
		assert(payload:find("P~Bob-Realm~12~", 1, true), "the points")
		assert(payload:find("^GUILD XB~S~[^%^]*%^N~"), "the notes before the points")
		-- An ask for nothing, a stranger's ask (not in our roster), or one heard as a member: no answer.
		Lt.HandleAsk("GUILD", "Bob-Realm", "XQ~5~5~0~0")
		Lt.HandleAsk("GUILD", "Stranger-Realm", all)
		w.rank = 3
		Lt.HandleAsk("GUILD", "Bob-Realm", all)
		eq(#w.later, 0)
		w.rank = 1
		-- The next answer comes PAGE_GAP after ours at the soonest; another officer's answer heard
		-- beginning meanwhile (its first piece) holds ours back.
		Lt.HandleAsk("GUILD", "Bob-Realm", all)
		eq(#w.later, 1); eq(w.delays[#w.delays], Lt.PAGE_GAP)
		local other = ("XB~S~0~%s~0~0~%s~0^P~Ann Smith-Realm~7~%s~Offi-Realm"):format(B36(w.clock), B36(w.clock), B36(w.clock))
		assert(ns.Comm.pieceHooks.loot, "the hook is set while our answer waits")
		ns.Comm.pieceHooks.loot("GUILD", "Offi-Realm", ns.Codec.Chunk(other, "9")[1])
		w.run()
		eq(#w.chunks, 1, "his answer covers ours"); eq(ns.Comm.pieceHooks.loot, nil, "the hook went with it")
		-- Our send queue long (the census): the answer waits, then gives up (the asker asks again).
		w.clock = w.clock + Lt.PAGE_GAP
		Lt.HandleAsk("GUILD", "Ann Smith-Realm", all)
		w.queue = 20
		for _ = 1, 4 do w.run() end
		eq(#w.chunks, 1, "not over our census"); eq(#w.later, 0)
		w.queue = 0
		-- A member's answer is not taken.
		Lt.HandleBook("GUILD", "Bob-Realm", ("XB~S~0~%s~0~0~%s~0^P~Bob-Realm~999~%s~Bob-Realm"):format(B36(w.clock + 50), B36(w.clock + 50), B36(w.clock + 50)))
		eq(Lt.Points()[1].v, 12, "Bob's own claim is nobody's word")
		-- A member's page: it asks for what its book lacks when it opens, again when it opens later
		-- while something still lacks, and after each answer until nothing lacks.
		ns.rdb.loot = nil
		Lt.Reset()
		w.rank, w.sent = 3, {}
		ns.Views.CloseChat()
		Lt.Show(true)
		local L0 = w.clock + 1
		eq(w.last().msg, ("XQ~0~%s~0~%s"):format(B36(L0), B36(L0)))
		Lt.Show(false); Lt.Show(true)
		eq(#w.sent, 1, "not again at once")
		w.clock = w.clock + Lt.ASK_AGAIN
		Lt.Show(false); Lt.Show(true)
		eq(#w.sent, 2, "unanswered: asked again")
		-- An answer that filled up with the newest notes: the points whole, the older notes asked for a moment later.
		local mid = L0 - 1000
		Lt.HandleBook("GUILD", "Offi-Realm", ("XB~S~0~%s~%s~0~%s~0^N~Offi-Realm~a1~%s~%s~~~~Newest note"):format(B36(L0), B36(mid), B36(L0), B36(mid + 10), B36(mid + 10)))
		eq(#Lt.Notes(), 1)
		eq(#w.later, 1); w.run()
		eq(w.last().msg, ("XQ~0~%s~0~0"):format(B36(mid)), "the older notes, and no points")
		-- The same asked by someone else just before ours would go: ours waits for that answer.
		Lt.HandleBook("GUILD", "Offi-Realm", ("XB~S~0~%s~%s~0~0~0^N~Offi-Realm~a2~%s~%s~~~~Older note"):format(B36(mid), B36(mid - 500), B36(mid - 400), B36(mid - 400)))
		Lt.HandleAsk("GUILD", "Ann Smith-Realm", ("XQ~0~%s~0~0"):format(B36(mid - 500)))
		local count = #w.sent
		w.run()
		eq(#w.sent, count, "Ann's ask covers ours")
		-- The rest: nothing lacks, nothing more asked.
		Lt.HandleBook("GUILD", "Offi-Realm", ("XB~S~0~%s~0~0~0~0"):format(B36(mid - 500)))
		w.run()
		eq(#w.sent, count); eq(Lt.Ask(), false, "the book whole"); eq(#Lt.Notes(), 2)
	end)
	-- The answer's pieces are put together over GUILD (Comm.lua), as the High Council's lists are.
	local savedChannel = GetChannelName
	local ok, err = pcall(function()
		GetChannelName = function() return 0 end
		local cns, Deliver = FreshComm()
		local got
		cns.Comm.Handle("XB", function(dist, sender, text) got = dist .. " " .. sender .. " " .. #text end)
		local payload = "XB~S~0~1~0~0~0~0^" .. ("N~Offi-Realm~a1~1~1~~~~" .. ("w"):rep(90) .. "^"):rep(8)
		for _, c in ipairs(ns.Codec.Chunk(payload, "5")) do Deliver("GUILD", "Offi-Realm", c) end
		eq(got, "GUILD Offi-Realm " .. #payload)
	end)
	GetChannelName, C_ChatInfo = savedChannel, nil
	if not ok then error(err, 0) end
end)

test("1.1 loot notes (#22): the group's loot shows to its officers this session, a click opens its note; nothing is handed out", function()
	WithLoot(function(w, Lt)
		Lt.OnLootMessage("Bob receives loot: " .. BELT .. ".")
		Lt.OnLootMessage("You receive loot: " .. BELT .. ".")
		Lt.OnLootMessage("Bob receives loot: " .. w.items[2589][2] .. "x5.")
		eq(#Lt.Drops(), 2, "a rare and better item, not linen cloth")
		eq(Lt.Drops()[1].to, "Tester"); eq(Lt.Drops()[2].to, "Bob"); eq(Lt.Drops()[2].id, 16830)
		-- Out of a group, or not an officer: nothing kept.
		w.group = false
		Lt.OnLootMessage("Ann Smith receives loot: " .. BELT .. ".")
		w.group, w.rank = true, 3
		Lt.OnLootMessage("Ann Smith receives loot: " .. BELT .. ".")
		eq(#Lt.Drops(), 2)
		w.rank = 1
		-- On the page: under its header, a click opens the note with the item and whom it went to.
		local lines = Lt.Lines()
		local drop
		for _, l in ipairs(lines) do if l.text and l.text:find("> Bob", 1, true) then drop = l end end
		assert(drop, "Bob's belt listed")
		drop.onClick()
		eq(w.dialogs[#w.dialogs].which, "OLYMPUS_LOOT_NOTE")
		eq(w.dialogs[#w.dialogs].data.item, 16830); eq(w.dialogs[#w.dialogs].data.to, "Bob")
		eq(w.dialogs[#w.dialogs].a, ns.L.LOOT_NOTE_FOR:format("Cenarion Bindings", "Bob"))
		-- The dialog writes it.
		local d = StaticPopupDialogs.OLYMPUS_LOOT_NOTE
		d.OnAccept({ editBox = { GetText = function() return "Bob: first epic, Ann next" end } }, { item = 16830, to = "Bob" })
		eq(Lt.Notes()[1].n.item, 16830); eq(Lt.Notes()[1].n.to, "Bob"); eq(Lt.Notes()[1].n.text, "Bob: first epic, Ann next")
		for _, s in ipairs(w.sent) do assert(s.msg:find("^X1~"), "only the note went out: " .. s.msg) end
	end)
end)

test("1.1 loot notes (#22): the Realm tab links the page; notes newest first, points only once used, the search, a copy for Discord", function()
	WithLoot(function(w, Lt)
		Lt.Write("Ann gets the belt", 16830, "Ann Smith")
		w.clock = w.clock + 60
		Lt.Write("Bob gets the next @everyone", nil, "Bob")
		-- The tree's link, for a member of an Olympus guild.
		local tree = ns.Views.RealmLines()
		local link
		for _, l in ipairs(tree) do if l.text and l.text:find(ns.L.LOOT_LINK:format(MY_GUILD), 1, true) then link = l end end
		assert(link, "linked from the Realm")
		link.onClick()
		eq(ns.Views.PageShown(), "loot")
		local lines = ns.Views.Build("realm")
		local text = {}
		for _, l in ipairs(lines) do text[#text + 1] = l.text or "" end
		text = table.concat(text, "\n")
		assert(text:find(ns.L.LOOT_TITLE:format(MY_GUILD), 1, true))
		assert(text:find(ns.L.LOOT_WRITE, 1, true), "an officer writes")
		local first, second = text:find("Bob gets the next", 1, true), text:find("Ann gets the belt", 1, true)
		assert(first and second and first < second, "newest first")
		eq(text:find(ns.L.LOOT_POINTS_TITLE, 1, true), nil, "no points column until someone has points")
		Lt.SetPoints("Bob 12")
		lines = ns.Views.Build("realm")
		text = {}
		for _, l in ipairs(lines) do text[#text + 1] = (l.text or "") .. "|" .. (l.right or "") end
		text = table.concat(text, "\n")
		assert(text:find(ns.L.LOOT_POINTS_TITLE, 1, true), "the points once used")
		-- A member sees the book, and nothing to write.
		w.rank = 3
		lines = Lt.Lines()
		for _, l in ipairs(lines) do
			assert(l.text ~= "|cff40ff40" .. ns.L.LOOT_WRITE .. "|r", "no write line for a member")
		end
		-- The search (the Realm's box): only what holds it.
		ns.Views.SetFilter("realm", "belt")
		lines = ns.Views.Build("realm")
		text = {}
		for _, l in ipairs(lines) do text[#text + 1] = l.text or "" end
		text = table.concat(text, "\n")
		assert(text:find("Ann gets the belt", 1, true) and not text:find("Bob gets the next", 1, true), text)
		-- The copy for Discord pings nobody.
		local copy = Lt.DiscordText()
		assert(copy:find("Ann gets the belt", 1, true) and copy:find("Bob: 12", 1, true), copy)
		assert(not copy:find("@everyone", 1, true), "no ping")
		ns.Views.ShowPage(nil)
		eq(ns.Views.PageShown(), nil)
	end)
end)

test("1.1 loot notes (#22): /oly loot, the strings in both languages; README and CurseForge say what it is and what it is not", function()
	local pt = { L = setmetatable({}, { __index = ns.L }) }
	local savedLocale = GetLocale
	GetLocale = function() return "ptBR" end
	local ok, err = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
	GetLocale = savedLocale
	if not ok then error(err, 0) end
	for _, key in ipairs({ "LOOT_LINK", "LOOT_LINK_TIP", "LOOT_TITLE", "LOOT_ABOUT", "LOOT_WRITE", "LOOT_WRITE_TIP", "LOOT_NOTE_PROMPT",
		"LOOT_NOTE_FOR", "LOOT_SAVE", "LOOT_WRITTEN", "LOOT_TOO_SHORT", "LOOT_OFFICERS_ONLY", "LOOT_REMOVE_PROMPT", "LOOT_REMOVE_BTN",
		"LOOT_REMOVE_TIP", "LOOT_REMOVED", "LOOT_NOTE_TIP", "LOOT_EMPTY", "LOOT_EMPTY_OFFICER", "LOOT_DROPS", "LOOT_DROP_TIP",
		"LOOT_POINTS_TITLE", "LOOT_POINTS_TIP", "LOOT_POINTS_SET", "LOOT_POINTS_SET_TIP", "LOOT_POINTS_PROMPT",
		"LOOT_POINTS_DONE", "LOOT_POINTS_CLEARED", "LOOT_POINTS_NOT_MEMBER", "LOOT_POINTS_BAD", "LOOT_POINTS_BY", "SEARCH_TIP_LOOT", "HELP_LOOT" }) do
		local p = rawget(pt.L, key)
		assert(type(ns.L[key]) == "string" and type(p) == "string" and p ~= ns.L[key], key)
		eq(select(2, p:gsub("%%[sd]", "")), select(2, ns.L[key]:gsub("%%[sd]", "")), key)
	end
	eq(rawget(pt.L, "LOOT_ITEM_N"), "item %d")
	for _, file in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
		local f = assert(io.open(ROOT .. file))
		local doc = f:read("*a")
		f:close()
		assert(doc:find("/oly loot", 1, true), file)
		assert(doc:find("| A loot note (1.1)", 1, true), file .. ": the privacy table")
		assert(doc:find("not a bid window", 1, true), file)
		-- (1.1 review: the book comes back whole, answer by answer; the ask names what it lacks.)
		assert(doc:find("asks again after each until its book is whole", 1, true), file)
		assert(doc:find("your addon's ask for the book (the spans of change times it lacks)", 1, true), file .. ": the privacy table")
	end
end)

-- The 1.1 review: Loot.lua again for each addon of our guild (its own saved book, rank and draws),
-- their messages passed as the game passes them over GUILD: a change or an ask at once, an
-- answer's first piece 1.2 s after it went (Comm.pieceHooks: an answer heard beginning) and the
-- whole answer once its last piece came (1.2 s each). g.Run(seconds) lets the time go by.
local function Letters(i) return string.char(97 + math.floor((i - 1) / 26)) .. string.char(97 + (i - 1) % 26) end
local function LootGuild(fn)
	local g = { clock = 1790000000, clients = {}, timers = {}, seq = 0, byName = {} }
	local savedDialogs, savedGlobals = {}, {}
	for k, v in pairs(StaticPopupDialogs) do savedDialogs[k] = v end
	for _, k in ipairs({ "GetGuildInfo", "GetServerTime", "IsInGuild" }) do savedGlobals[k] = _G[k] end
	GetGuildInfo = function(unit) if unit == nil or unit == "player" then return MY_GUILD, "Member", 3 end return nil end
	GetServerTime = function() return g.clock end
	IsInGuild = function() return true end
	function g.At(seconds, f)
		g.seq = g.seq + 1
		g.timers[#g.timers + 1] = { at = g.clock + seconds, seq = g.seq, f = f }
	end
	function g.Run(seconds)
		local stop = g.clock + seconds
		while true do
			table.sort(g.timers, function(a, b) if a.at ~= b.at then return a.at < b.at end return a.seq < b.seq end)
			local t = g.timers[1]
			if not t or t.at > stop then break end
			table.remove(g.timers, 1)
			g.clock = math.max(g.clock, t.at)
			t.f()
		end
		g.clock = stop
	end
	local function Others(c)
		local out = {}
		for _, o in ipairs(g.clients) do if o ~= c and not o.away then out[#out + 1] = o end end
		return out
	end
	function g.Answers()
		local n = 0
		for _, c in ipairs(g.clients) do n = n + #c.pages end
		return n
	end
	function g.Client(short, rank)
		local c = { name = short .. "-Realm", rank = rank, sent = {}, pages = {}, rand = 0 }
		g.byName[c.name] = rank
		local cns = setmetatable({}, { __index = ns })
		cns.me, cns.rdb, cns.RealmPages = c.name, {}, {}
		cns.On, cns.Log, cns.Fire, cns.Print = function() end, function() end, function() end, function() end
		cns.Now = function() return g.clock end
		cns.IsMember = function() return true end
		cns.Views = { ShowPage = function() end }
		cns.Roster = { byName = g.byName, RankOf = function(n) return g.byName[ns.FullName(n)] end,
			IsOfficer = function() return c.rank <= ns.CAPTAIN_RANK end }
		local msgId = 0
		cns.Comm = {
			Handle = function() end, pieceHooks = {}, QueueSize = function() return 0 end,
			Peers = function()
				local out = {}
				for _, o in ipairs(g.clients) do if o.hello and not o.away then out[#out + 1] = o.name end end
				return out
			end,
			Send = function(dist, msg)
				c.sent[#c.sent + 1] = msg
				for _, o in ipairs(Others(c)) do
					if msg:sub(1, 3) == "X1~" then o.Lt.HandleLive(dist, c.name, msg)
					elseif msg:sub(1, 3) == "XQ~" then o.Lt.HandleAsk(dist, c.name, msg) end
				end
			end,
			SendChunked = function(payload, urgent, dist)
				c.pages[#c.pages + 1] = payload
				msgId = msgId + 1
				local pieces = ns.Codec.Chunk(payload, tostring(msgId))
				g.At(1.2, function()
					for _, o in ipairs(Others(c)) do
						for _, hook in pairs(o.ns.Comm.pieceHooks) do hook(dist, c.name, pieces[1]) end
					end
				end)
				g.At(1.2 * #pieces, function()
					for _, o in ipairs(Others(c)) do o.Lt.HandleBook(dist, c.name, payload) end
				end)
			end,
		}
		assert(loadfile(ADDON_DIR .. "Loot.lua"))("Olympus", cns)
		c.ns, c.Lt = cns, cns.Loot
		c.Lt.after = function(seconds, _, f) g.At(seconds, f) end
		c.Lt.random = function() return c.rand end
		g.clients[#g.clients + 1] = c
		return c
	end
	-- Officers whose books are the guild's: each logs in, asks, and nobody holding it whole answers.
	function g.Officers(...)
		local list = { ... }
		for _, o in ipairs(list) do o.Lt.Ask() end
		g.Run(list[1].Lt.ASK_WAIT)
		for _, o in ipairs(list) do eq(o.Lt.Ask(), false, o.name .. " holds his book whole") end
	end
	local ok, err = pcall(fn, g)
	for k in pairs(StaticPopupDialogs) do StaticPopupDialogs[k] = savedDialogs[k] end
	for k, v in pairs(savedDialogs) do StaticPopupDialogs[k] = v end
	-- (Each put back, nil too: a clock the harness had none of must go again, or the treasury
	-- tests after it read this one.)
	for _, k in ipairs({ "GetGuildInfo", "GetServerTime", "IsInGuild" }) do _G[k] = savedGlobals[k] end
	if not ok then error(err, 0) end
end
Fern.LootGuild = LootGuild -- (for the review's tests further down)

test("1.1 loot notes (#22): a change heard as it is made never hides the older notes: a member's book comes back whole (Forever: every login)", function()
	LootGuild(function(g)
		local o = g.Client("Offi", 1)
		-- Last week the officer wrote a decision; that session ended.
		g.clock = g.clock - 7 * 86400
		o.Lt.Write("Last week: Ann passed on the gloves, Bob gets the next belt", 16830, "Bob")
		g.clock = g.clock + 7 * 86400
		o.Lt.Reset()
		g.Officers(o)
		-- Tonight a member logs in (the beta forgot his book) and an officer writes during the raid:
		-- the member hears it as it is made.
		local m = g.Client("Bob", 3)
		m.Lt.Book()
		local from = g.clock + 1
		g.Run(60)
		o.Lt.Write("Tonight: the belt went to Bob", 16830, "Bob")
		eq(#m.Lt.Notes(), 1)
		-- Later he opens the page: his ask names everything before his session, whatever he heard since.
		g.Run(600)
		m.Lt.Show(true)
		eq(m.sent[#m.sent], ("XQ~0~%s~0~%s"):format(B36(from), B36(from)), "not the newest change's time")
		g.Run(60)
		eq(#m.Lt.Notes(), 2, "last week's decision came too")
		eq(m.Lt.Ask(), false, "nothing lacks")
		-- An officer back from a week away, his book forgotten: not whole, he answers nothing; his own
		-- ask makes it whole, then he answers too.
		local o2 = g.Client("Offtwo", 1)
		o2.Lt.Book()
		g.Run(60)
		local m2 = g.Client("Ann", 3)
		o.away = true
		m2.Lt.Show(true)
		g.Run(120)
		eq(#o2.pages, 0, "not his to answer"); eq(#m2.Lt.Notes(), 0)
		o.away, m2.away = false, true
		eq(o2.Lt.Ask(), true)
		g.Run(60)
		eq(#o2.Lt.Notes(), 2); eq(o2.Lt.Ask(), false, "whole now")
		o.away, m2.away = true, false
		g.Run(m2.Lt.ASK_AGAIN)
		m2.Lt.Show(true)
		g.Run(60)
		eq(#o2.pages, 1); eq(#m2.Lt.Notes(), 2)
	end)
end)

test("1.1 loot notes (#22): a book larger than one answer comes back whole, answer by answer: the newest notes first, then the points", function()
	LootGuild(function(g)
		local o = g.Client("Offi", 1)
		g.Officers(o)
		-- 60 notes over the weeks, then a round of points for 150 members.
		for i = 1, 60 do
			g.Run(3600)
			o.Lt.Write(("Raid %d: %s"):format(i, ("the decision, and why, as the officers agreed it "):rep(2)), 16830, "Bob")
		end
		for i = 1, 150 do
			g.byName["Mem" .. Letters(i) .. "-Realm"] = 3
			o.Lt.SetPoints(("Mem%s %d"):format(Letters(i), i))
			g.Run(i % 3 == 0 and 2 or 0) -- (by hand: now and then two in the same second)
		end
		eq(#o.Lt.Notes(), 60); eq(#o.Lt.Points(), 150)
		local m = g.Client("Bob", 3)
		m.Lt.Show(true)
		g.Run(600)
		eq(#m.Lt.Notes(), 60, "every note"); eq(#m.Lt.Points(), 150, "every member's points")
		eq(m.Lt.Ask(), false, "nothing lacks")
		assert(#o.pages >= 3, #o.pages .. " answers")
		-- The first answer: the newest notes alone (it filled up with them), none of the points.
		local first = o.pages[1]
		assert(#first <= o.Lt.ANSWER_BYTES, #first)
		assert(first:find("Raid 60: ", 1, true) and not first:find("Raid 1: ", 1, true), "the newest notes first")
		assert(not first:find("^P~") and not first:find("%^P~"), "no points before the notes")
		local ncut = first:match("^XB~S~0~[0-9a-z]+~([0-9a-z]+)~0~0~0")
		assert(ncut and tonumber(ncut, 36) > 0, first:sub(1, 60))
		-- His second ask: the older notes, and all the points.
		local L0 = m.sent[1]:match("^XQ~0~([0-9a-z]+)~")
		eq(m.sent[2], ("XQ~0~%s~0~%s"):format(ncut, L0))
		eq(#m.sent, #o.pages, "one ask for each answer")
	end)
end)

test("1.1 loot notes (#22): one officer's addon answers an ask; an answer heard beginning holds the others back; one guildmate's asks are limited", function()
	LootGuild(function(g)
		local o1, o2, o3 = g.Client("Offa", 1), g.Client("Offb", 1), g.Client("Offc", 0)
		g.Officers(o1, o2, o3)
		for i = 1, 25 do
			g.Run(60)
			o1.Lt.Write(("Raid %d: %s"):format(i, ("the decision, and why, as the officers agreed it "):rep(2)), 16830, "Bob")
		end
		eq(#o3.Lt.Notes(), 25, "heard as they were written")
		-- Their hellos heard: each takes his turn, SLOT apart; the first answers, the others hear it begin.
		o1.hello, o2.hello, o3.hello = true, true, true
		local m = g.Client("Bob", 3)
		m.Lt.Show(true)
		g.Run(120)
		eq(g.Answers(), 1, "one answer"); eq(#m.Lt.Notes(), 25)
		-- No hello heard (the same turn for all): drawn a moment apart, the first answer's first piece still holds the others.
		o1.hello, o2.hello, o3.hello = false, false, false
		o1.rand, o2.rand, o3.rand = 0, 0.5, 1
		local m2 = g.Client("Ann", 3)
		m2.Lt.Show(true)
		g.Run(120)
		eq(g.Answers(), 2, "one answer again"); eq(#m2.Lt.Notes(), 25)
		-- A guildmate asking for everything every 30 seconds for 10 minutes: ASKER_ASKS answers at most
		-- (every officer answered each ask before, once each 2 minutes: 15 in all).
		local x = g.Client("Grunt", 3)
		local before = g.Answers()
		for _ = 1, 20 do
			x.ns.Comm.Send("GUILD", ("XQ~0~%s~0~%s"):format(B36(g.clock), B36(g.clock)))
			g.Run(30)
		end
		local answered = g.Answers() - before
		assert(answered >= 1 and answered <= o1.Lt.ASKER_ASKS, answered .. " answers")
	end)
end)

test("1.1 loot notes (#22): two officers' books grown apart: the one holding more sends what the other's answer lacked", function()
	LootGuild(function(g)
		local a, b = g.Client("Offa", 1), g.Client("Offb", 1)
		g.Officers(a, b)
		a.Lt.Write("Both hold this one", 16830, "Bob")
		-- B writes while A's addon hears nothing (away, or the message lost): A still takes his book as whole.
		g.Run(60)
		a.away = true
		b.Lt.Write("Only B holds this one", 16830, "Ann")
		a.away = false
		eq(#a.Lt.Notes(), 1); eq(#b.Lt.Notes(), 2)
		-- A member asks: A's turn comes first and B hears it begin; A's answer lacks B's note: B sends it.
		a.rand, b.rand = 0, 1
		g.Run(60)
		local m = g.Client("Bob", 3)
		m.Lt.Show(true)
		g.Run(120)
		eq(#a.pages, 1); eq(#b.pages, 1, "B's own note, once")
		assert(b.pages[1]:find("^XB~S~0~0~0~0~0~0%^N~Offb%-Realm~"), b.pages[1])
		eq(#m.Lt.Notes(), 2); eq(#a.Lt.Notes(), 2, "A holds it now too")
		-- Another member later: A's answer holds both; nothing more from B.
		local m2 = g.Client("Ann", 3)
		m2.Lt.Show(true)
		g.Run(120)
		eq(#b.pages, 1); eq(#m2.Lt.Notes(), 2)
	end)
end)

-- The 1.1 review: loot's J1 was the census's route ask too (Recruit.lua); Comm keeps a type's last
-- handler only. Each type is registered in one file, and in Comm.lua's list of types.
test("1.1 message types: each top-level type is registered by one file only, and each is in Comm.lua's list", function()
	local registered, where = {}, {}
	local toc = assert(io.open(ADDON_DIR .. "Olympus.toc"))
	for line in toc:lines() do
		local file = line:match("^([%w_]+)%.lua%s*$")
		if file then
			local f = io.open(ADDON_DIR .. file .. ".lua")
			local n = 0
			for code in f:lines() do
				n = n + 1
				code = code:gsub("%-%-.*$", "")
				for kind in code:gmatch("Comm%.Handle%(\"(%w%w)\"") do
					assert(not registered[kind], ("%s registered in %s and %s:%d"):format(kind, tostring(where[kind]), file, n))
					registered[kind], where[kind] = true, file .. ":" .. n
				end
			end
			f:close()
		end
	end
	toc:close()
	assert(registered.X1 and registered.XQ and registered.XB, "the loot notes' types")
	-- (Registered by Recruit.lua alone once the census part of 1.1 is in; never by the loot notes.)
	eq(registered.J1 and where.J1:match("^(%w+):"), "Recruit", "J1 is the census's route ask (Recruit.lua): " .. tostring(where.J1))
	-- Comm.lua's list: every type once, every registered type in it.
	local f = assert(io.open(ADDON_DIR .. "Comm.lua"))
	local src = f:read("*a")
	f:close()
	local block = src:match("%-%- The top%-level types.-\nlocal handlers = {}")
	assert(block, "Comm.lua's list of types")
	local listed = {}
	for kind in block:gmatch("%f[%w]([A-Z][A-Z0-9])%f[%W]") do
		assert(not listed[kind], kind .. " listed twice")
		listed[kind] = true
	end
	for kind in pairs(registered) do assert(listed[kind], kind .. " not in Comm.lua's list") end
	-- What Comm.lua reads before any handler is nobody else's.
	for _, kind in ipairs({ "K0", "K1", "H1", "R1", "R2" }) do eq(registered[kind], nil, kind); assert(listed[kind], kind) end
end)
end

---------------------------------------------------------------------------
-- 1.1 (Fern's #24): the crafters' board: a profession listed at its opening, a whisper by a click
---------------------------------------------------------------------------

do
-- WoW: Forever's professions (C_TradeSkillUI: Tailoring, three recipes known, one not) or Classic
-- Era's windows (w.era: GetTradeSkill*, GetCraft*); what goes out (w.sent: CHANNEL, w.whispers),
-- the dialogs opened, the clock, the answers' delay (w.later), the chat and whisper boxes.
local CRAFT_GLOBALS = { "C_TradeSkillUI", "C_ProfSpecs", "GetTradeSkillLine", "GetNumTradeSkills", "GetTradeSkillInfo", "GetTradeSkillItemLink",
	"GetTradeSkillRecipeLink", "GetCraftDisplaySkillLine", "GetNumCrafts", "GetCraftInfo", "GetCraftItemLink", "GetCraftRecipeLink",
	"IsTradeSkillLinked", "GetItemInfo", "GetGuildInfo", "ChatFrame_OpenChat", "ChatFrame_SendTell", "InCombatLockdown" }
local MOONCLOTH = "|cff1eff00|Hitem:14342::::::::60:::::|h[Mooncloth]|h|r"
local function WithCraft(fn)
	local Cr = ns.Crafters
	local saved = { send = ns.Comm.Send, whisper = ns.Comm.Whisper, print = ns.Print, fire = ns.Fire, dialog = ns.ShowDialog, now = ns.Now,
		after = Cr.after, random = Cr.random, ui = ns.UI, pad = ns.GamepadUI, choice = ns.db.crafterChoice, data = ns.db.crafterData, me = ns.me,
		queue = ns.Comm.QueueSize }
	for _, k in ipairs(CRAFT_GLOBALS) do saved[k] = _G[k] end
	local w = { sent = {}, whispers = {}, printed = {}, dialogs = {}, later = {}, delays = {}, clock = 5000000, calls = {}, chat = {}, tells = {}, windows = {}, tabs = {},
		prof = { id = 197, name = "Tailoring", skill = 245, max = 300 }, linked = false,
		recipes = { { id = 3915, name = "Linen Bag", item = 4238, learned = true }, { id = 18560, name = "Mooncloth", item = 14342, learned = true },
			{ id = 12088, name = "Cindercloth Boots", item = 10044, learned = false }, { id = 3914, name = "Brown Linen Pants", item = 4343, learned = true } } }
	Cr.Reset()
	ns.db.crafterChoice, ns.db.crafterData, ns.me = nil, nil, "Tester-Realm"
	ns.Now = function() return w.clock end
	ns.Comm.Send = function(dist, msg, key, urgent) w.sent[#w.sent + 1] = dist .. " " .. msg .. (urgent and " (urgent)" or "") end
	ns.Comm.Whisper = function(target, msg) w.whispers[#w.whispers + 1] = target .. " " .. msg end
	ns.Print = function(m) w.printed[#w.printed + 1] = m end
	ns.Fire = function() end
	ns.ShowDialog = function(which, a, b, data) w.dialogs[#w.dialogs + 1] = { which = which, a = a, data = data } end
	Cr.after = function(seconds, _, f) w.later[#w.later + 1] = f; w.delays[#w.delays + 1] = seconds end
	Cr.random = function() return 0 end
	-- (1.1 review: our send queue's length, for the recipe lists' pace.)
	ns.Comm.QueueSize = function() return w.queue or 0 end
	ns.UI = { WhisperWindow = function(name) w.windows[#w.windows + 1] = name end,
		SelectTab = function(tab) w.tabs[#w.tabs + 1] = tab end }
	ns.GamepadUI = function() return w.gamepad == true end
	GetGuildInfo = function(unit) if unit == nil or unit == "player" then return MY_GUILD, "Member", 3 end return nil end
	GetItemInfo = function(id) id = tonumber(type(id) == "string" and id:match("item:(%d+)") or id) if id == 14342 then return "Mooncloth", MOONCLOTH, 2 end end
	ChatFrame_OpenChat = function(text) w.chat[#w.chat + 1] = text end
	ChatFrame_SendTell = function(name) w.tells[#w.tells + 1] = name end
	InCombatLockdown = function() return false end
	-- A specialization tree is never asked for (none exists on Forever): any call fails the test.
	C_ProfSpecs = setmetatable({}, { __index = function(_, k) error("C_ProfSpecs." .. tostring(k) .. " asked for") end })
	local function Log(name, fn) return function(...) w.calls[#w.calls + 1] = name; return fn(...) end end
	C_TradeSkillUI = {
		GetBaseProfessionInfo = Log("GetBaseProfessionInfo", function()
			return { professionID = w.prof.id, professionName = w.prof.name, skillLevel = w.prof.skill, maxSkillLevel = w.prof.max }
		end),
		GetChildProfessionInfo = Log("GetChildProfessionInfo", function() return { professionID = 0, skillLevel = 0 } end),
		GetAllRecipeIDs = Log("GetAllRecipeIDs", function()
			local ids = {}
			for _, r in ipairs(w.recipes) do ids[#ids + 1] = r.id end
			return ids
		end),
		GetRecipeInfo = function(id)
			for _, r in ipairs(w.recipes) do if r.id == id then return { recipeID = id, name = r.name, learned = r.learned } end end
		end,
		GetRecipeOutputItemData = function(id)
			for _, r in ipairs(w.recipes) do if r.id == id then return { itemID = r.item } end end
			return {}
		end,
		IsTradeSkillLinked = function() return w.linked end,
		IsTradeSkillGuild = function() return false end,
		IsNPCCrafting = function() return false end,
	}
	w.era = function()
		C_TradeSkillUI = nil
		GetTradeSkillLine = function() return "Blacksmithing", 150, 300 end
		local list = { { "Blacksmithing Supplies", "header" }, { "Rough Sharpening Stone", "trivial", 2862, 2660 },
			{ "Copper Chain Belt", "optimal", 2851, 2661 } }
		GetNumTradeSkills = function() return #list end
		GetTradeSkillInfo = function(i) return list[i][1], list[i][2] end
		GetTradeSkillItemLink = function(i) return list[i][3] and ("|cffffffff|Hitem:%d::::::::60:::::|h[%s]|h|r"):format(list[i][3], list[i][1]) end
		GetTradeSkillRecipeLink = function(i) return list[i][4] and ("|cffffd000|Henchant:%d|h[%s]|h|r"):format(list[i][4], list[i][1]) end
		GetCraftDisplaySkillLine = function() return w.craftName, w.craftName and 120, w.craftName and 225 end
		GetNumCrafts = function() return 2 end
		GetCraftInfo = function(i) return ({ "Enchant Bracer - Minor Health", "Runed Copper Rod" })[i], nil, "optimal" end
		GetCraftItemLink = function(i) return i == 1 and "|cffffd000|Henchant:7418|h[Enchant Bracer - Minor Health]|h|r" or "|cffffffff|Hitem:6218::::::::60:::::|h[Runed Copper Rod]|h|r" end
		GetCraftRecipeLink = function(i) return i == 2 and "|cffffd000|Henchant:7421|h[Runed Copper Rod]|h|r" or nil end
	end
	w.run = function() local l = w.later; w.later = {}; for _, f in ipairs(l) do f() end end
	local ok, err = pcall(fn, w, Cr)
	ns.Comm.Send, ns.Comm.Whisper, ns.Print, ns.Fire, ns.ShowDialog, ns.Now = saved.send, saved.whisper, saved.print, saved.fire, saved.dialog, saved.now
	Cr.after, Cr.random, ns.UI, ns.GamepadUI = saved.after, saved.random, saved.ui, saved.pad
	ns.db.crafterChoice, ns.db.crafterData, ns.me, ns.Comm.QueueSize = saved.choice, saved.data, saved.me, saved.queue
	for _, k in ipairs(CRAFT_GLOBALS) do _G[k] = saved[k] end
	Cr.Reset()
	ns.Views.CloseChat()
	ns.Views.ClearFilters()
	if not ok then error(err, 0) end
end

test("1.1 crafters (#24): opening a profession reads its skill and the recipes known (Forever's API, no specialization tree) and asks once; nothing goes out without a yes", function()
	WithCraft(function(w, Cr)
		Cr.Opened()
		local p = Cr.Mine()["197"]
		assert(p, "Tailoring read")
		eq(p.name, "Tailoring"); eq(p.rank, 245); eq(p.max, 300); eq(#p.recipes, 3, "the three learned, not the one unlearned")
		eq(p.recipes[2].r, 18560); eq(p.recipes[2].i, 14342)
		eq(#w.dialogs, 1); eq(w.dialogs[1].which, "OLYMPUS_CRAFTER_LIST"); eq(w.dialogs[1].a, "Tailoring"); eq(w.dialogs[1].data, "197")
		eq(#w.sent, 0, "nothing listed before his yes")
		-- Someone else's profession in the window (a link): nothing read.
		ns.db.crafterData = nil
		w.linked = true
		Cr.Opened()
		eq(next(Cr.Mine()), nil)
		w.linked = false
		-- "Not now": remembered, never asked again, nothing sent.
		Cr.Opened()
		StaticPopupDialogs.OLYMPUS_CRAFTER_LIST.OnCancel(nil, "197", "clicked")
		eq(Cr.Choices()["197"], false); eq(w.printed[#w.printed], ns.L.CRAFTER_NOT_LISTED)
		Cr.Opened()
		Cr.Reset() -- (a new session: still not asked, the "no" is kept)
		Cr.Opened()
		eq(#w.dialogs, 1, "the one question, never again"); eq(#w.sent, 0)
		-- Another popup taking its place is no answer, nor is Escape (it only closes the window);
		-- asked once a session until answered, however often the game updates the list meanwhile.
		ns.db.crafterChoice = nil
		Cr.Reset()
		Cr.Opened()
		StaticPopupDialogs.OLYMPUS_CRAFTER_LIST.OnCancel(nil, "197", "override")
		eq(Cr.Choices()["197"], nil)
		eq(StaticPopupDialogs.OLYMPUS_CRAFTER_LIST.noCancelOnEscape, true)
		local asked = #w.dialogs
		Cr.Opened(); Cr.Opened()
		eq(#w.dialogs, asked, "not again this session")
		Cr.Reset() -- (a new session)
		Cr.Opened()
		eq(#w.dialogs, asked + 1, "asked again next session")
	end)
end)

-- (1.1 review: a skill up was sent CHANGED_GAP, 2 minutes, after the last listing: a crafter
-- levelling put one on the channel every 2 minutes. It now waits LIST_GAP, 10 minutes.)
test("1.1 crafters (#24): the yes lists the profession on the channel (name, guild, skill, how many recipes); repeated every 45 minutes; a skill up at most each 10 minutes", function()
	WithCraft(function(w, Cr)
		Cr.Opened()
		StaticPopupDialogs.OLYMPUS_CRAFTER_LIST.OnAccept(nil, "197")
		eq(w.sent[1], "CHANNEL W1~Olympus II~197:Tailoring:245:300:3")
		eq(w.printed[#w.printed], ns.L.CRAFTER_LISTED)
		-- Opened again, nothing changed: no question, nothing sent.
		Cr.Opened()
		eq(#w.dialogs, 1); eq(#w.sent, 1)
		-- Crafting: a skill up, then another; the listing waits LIST_GAP, then the board's tick sends the last.
		w.clock = w.clock + 10
		w.prof.skill = 246
		Cr.Opened()
		w.prof.skill = 247
		Cr.Opened()
		eq(#w.sent, 1, "not at every skill up")
