		Cr.HandleAsk("CHANNEL", "Third-Realm", "WQ~3~i~999")
		Cr.HandleAsk("WHISPER", "Fourth-Realm", "WQ~4~i~14342")
		Cr.HandleAsk("CHANNEL", "Fifth-Realm", "WQ~5~t~ab")
