		"BACKUP_WORD_NOT_KING", "BACKUP_KEY", "BACKUP_KEY_NOT_OFFICER", "BACKUP_SETTINGS", "BACKUP_BLOCKED", "BACKUP_NO_CONSENT", "BACKUP_DONE",
		"BACKUP_LINK", "BACKUP_RESTORE_LINK", "HELP_BACKUP" }) do
		assert(type(rawget(ns.L, key)) == "string", "English " .. key)
		assert(type(rawget(pt.L, key)) == "string" and pt.L[key] ~= ns.L[key], "Portuguese " .. key)
		eq(select(2, pt.L[key]:gsub("%%[ds]", "")), select(2, ns.L[key]:gsub("%%[ds]", "")), key)
	end
end)
---------------------------------------------------------------------------
-- 1.1 (batch B1, review): the first-open page first and in 1.0's words for the Treasurer (#11);
-- the log of acts names only whoever did the act, and hides the council on the King's screen (#12).
---------------------------------------------------------------------------
do
	local KING = "Asmongold Asmongler-Realm"
	local TREASURER = "Pyralis Ashandar-Realm"
	local COUNCILLOR = "Test Councillor-Realm"
	local STEWARD = "Test Steward-Realm"
	local function AsSteward() GetGuildInfo = function() return "Olympus II", "Member", 3 end; ns.me = STEWARD end
	local SWITCHES = { "shareLocation", "layerHelp", "royalInspection", "rollCall", "addonChat" }
	local function Unanswered(fn)
		local saved = {}
		for _, k in ipairs(SWITCHES) do saved[k] = ns.db[k]; ns.db[k] = nil end
		local shares, ts = ns.db.keeperShares, ns.db.treasurerShares
		ns.Consent.Reset()
		local ok, err = pcall(fn)
		for _, k in ipairs(SWITCHES) do ns.db[k] = saved[k] end
		ns.db.keeperShares, ns.db.treasurerShares = shares, ts
		ns.Consent.Reset()
		if not ok then error(err, 0) end
	end
	local function RowOf(page, key)
		for _, r in ipairs(page.rows) do if r.key == key then return r end end
		return nil
	end
	local function Terms()
		local out = {}
		for _, e in ipairs(ns.Chronicle.Entries()) do if e.kind == "terms" then out[#out + 1] = e.by .. " " .. tostring(e.words) end end
		return table.concat(out, "|")
	end
	local function Switches()
		local out = {}
		for _, e in ipairs(ns.Chronicle.Entries()) do if e.kind == "switch" then out[#out + 1] = e.by .. ": " .. e.what end end
		return table.concat(out, "|")
	end

	test("1.1 the first-open page stands on an opaque ground: the client's opaque dialog, else its dark one, else a near-black texture", function()
	local saved = TEMPLATES.DialogBorderOpaqueTemplate
	local ok, err = pcall(function()
		WithUI(function()
			local page = ns.Consent.Show()
			eq(page.border.template, "DialogBorderOpaqueTemplate", "the client's opaque dialog")
			page:Hide()
		end)
		-- A client without it: the dark one.
		TEMPLATES.DialogBorderOpaqueTemplate = nil
		WithUI(function()
			local page = ns.Consent.Show()
			eq(page.border.template, "DialogBorderDarkTemplate")
			page:Hide()
		end)
	end)
	TEMPLATES.DialogBorderOpaqueTemplate = saved
	if not ok then error(err, 0) end
end)

test("1.1 review (#11): for the Treasurer whose 0.9.3 yes stands, his line says his book goes out, and that its Yes also sends the early supporters' names, before that Yes can send them", function()
		Unanswered(function()
			WithUI(function()
				WithThrone(function(w, K)
					local T = ns.Treasury
					local saved = { split = ns.splitNames, combat = InCombatLockdown, inst = IsInInstance }
					local ok, err = pcall(function()
						ns.splitNames = true
						InCombatLockdown, IsInInstance = function() return false end, function() return false end
						local function Sent(prefix)
							local out = {}
							for _, s in ipairs(w.sent) do if s.msg:sub(1, #prefix) == prefix then out[#out + 1] = s.msg end end
							return out
						end
						-- His 0.9 book, archived on his account; his 0.9.3 yes, no answer to 1.0's question.
						ns.rdb.treasuryEpoch = nil
						ns.rdb.treasury = { { name = "Alice Early", money = 100, how = "mail", t = w.clock - 1000 } }
						AsTreasurer()
						T.Migrate()
						ns.db.keeperShares, ns.db.treasurerShares = nil, true
						eq(T.CanSend(), true, "his book goes out under his 0.9.3 yes")
						-- The page, as login opens it: his line waits for his answer, and says what is so.
						eq(ns.Consent.Ask("login"), true, "his line waits for his answer: the page asks")
						local page = ns.Consent.Frame()
						assert(page and page:IsShown(), "the page")
						eq(#w.popups, 0, "never the 1.0 popup")
						local row = RowOf(page, "treasurer")
						assert(row, "his line")
						eq(row.state:GetText():find(ns.L.CONSENT_STATE_NONE, 1, true), nil, "not 'Not answered: off': his book is going out")
						assert(row.state:GetText():find(ns.L.CONSENT_STATE_YES, 1, true), row.state:GetText())
						local text = row.text:GetText()
						assert(text:find("before 1.0", 1, true), "the early supporters, said: " .. text)
						assert(text:find(ns.L.CONSENT_TREASURER_EARLY, 1, true), "in these words")
						assert(text:find(ns.L.CONSENT_TREASURER_OLD_YES, 1, true), "his 0.9.3 yes, said")
						eq(T.YesSendsEarly(), true, "he holds the early supporters")
						assert(ns.L.CONSENT_TREASURER_EARLY:find("names of everyone who gave before 1.0", 1, true)
							and ns.L.CONSENT_TREASURER_EARLY:find("every client on the Olympus channel receives them, the names too", 1, true), "in 1.0's words")
						-- The names stay home until that Yes. (1.1's treasury part E: on the channel only while the
						-- King shows the ranking; he does here, so only the Yes is in the way.)
						ns.rdb.treasuryFlags = { balance = true, ranking = true, book = true, at = w.clock, from = "Asmongold Asmongler-Realm" }
						w.sent = {}
						eq(T.SendEarly(true), false, "no answer on the page yet: the names stay home")
						T.Share(true)
						eq(#Sent("TB~"), 1, "his book, as the line says")
						row.yes:Click()
						eq(ns.db.keeperShares[TREASURER_KEY], true)
						eq(RowOf(page, "treasurer").text:GetText():find(ns.L.CONSENT_TREASURER_OLD_YES, 1, true), nil, "answered: the note goes")
						w.sent = {}
						eq(T.SendEarly(true), true, "the Yes to words that name them")
						eq(Sent("TE~")[1], ("TE~Olympus~%d~1~1~Alice Early"):format(ns.rdb.treasuryArchive["0.9"].closed))
						page:Hide()
						-- Another keeper (the King): his line says nothing of the early supporters.
						ns.Consent.Reset()
						AsKing()
						ns.db.keeperShares = nil
						eq(T.YesSendsEarly(), false)
						page = ns.Consent.Show()
						eq(RowOf(page, "treasurer").text:GetText():find(ns.L.CONSENT_TREASURER_EARLY, 1, true), nil, "not his to send")
						eq(RowOf(page, "treasurer").state:GetText():find(ns.L.CONSENT_STATE_NONE, 1, true) ~= nil, true, "never answered: off")
						page:Hide()
					end)
					ns.splitNames, InCombatLockdown, IsInInstance = saved.split, saved.combat, saved.inst
					ns.rdb.treasuryArchive, ns.rdb.treasuryEpoch, ns.rdb.treasuryEarly, ns.rdb.treasuryFlags = nil, nil, nil, nil
					if not ok then error(err, 0) end
				end)
			end)
		end)
		-- Both languages, and both pages' privacy tables say the page's yes is the one.
		local pt = { L = setmetatable({}, { __index = function() return nil end }) }
		local savedLocale = GetLocale
		GetLocale = function() return "ptBR" end
		local ok, err = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
		GetLocale = savedLocale
		if not ok then error(err, 0) end
		for _, key in ipairs({ "CONSENT_TREASURER_EARLY", "CONSENT_TREASURER_OLD_YES", "CONSENT_OPTIONAL" }) do
			local en, br = rawget(ns.L, key), rawget(pt.L, key)
			assert(type(en) == "string" and en ~= "" and type(br) == "string" and br ~= "" and br ~= en, key)
		end
		assert(rawget(pt.L, "CONSENT_TREASURER_EARLY"):find("nomes de todos que doaram antes da 1.0", 1, true))
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path), path):gsub("%s+", " ")
			assert(doc:find("once he said yes to 1.0's question or to his line on the first-open page, both of which say their names go to everyone on the channel", 1, true), path)
		end
	end)

	test("1.1 review (#11): the page is the first question after login, before the zone and layer's and a keeper's: never their popups while it is loaded, once a session, not in combat", function()
		Unanswered(function()
			WithUI(function()
				WithGamepadUI(false, function(game)
					local saved = { after = ns.After, every = ns.Every, combat = InCombatLockdown, inst = IsInInstance, me = ns.me, send = ns.Comm.Send, hello = ns.Comm.Hello }
					local timers = {}
					local ok, err = pcall(function()
						ns.After = function(s, name, fn) timers[#timers + 1] = { s = s, name = name, fn = fn, once = true } end
						ns.Every = function(s, name, fn) timers[#timers + 1] = { s = s, name = name, fn = fn } end
						ns.Comm.Send, ns.Comm.Hello = function() end, function() end
						InCombatLockdown, IsInInstance = function() return false end, function() return false end
						GetGuildInfo = function() return "Olympus II", "Member", 3 end
						ns.me = "Fresh Install-Realm"
						ns.Layers.Reset()
						-- The 1.0 location question's own timer (Layers, 45 s after login), the window never
						-- opened: the page, not the game's popup.
						InCombatLockdown = function() return true end
						eq(ns.Layers.AskChoice(), false, "never in combat")
						InCombatLockdown = function() return false end
						eq(ns.Layers.AskChoice(), true)
						eq(#game.shown, 0, "no OLYMPUS_LOCATION_CHOICE: the game's popup never shows")
						local page = ns.Consent.Frame()
						assert(page and page:IsShown(), "the page, the window never opened")
						eq(OlympusFrame, nil, "the window was never opened")
						page:Hide()
						ns.Consent.Reset()
						-- Login: the page's own timers, for everyone.
						ns.Consent.OnLogin()
						local names = {}
						for _, t in ipairs(timers) do names[#names + 1] = t.name .. "@" .. t.s end
						eq(table.concat(names, ","), "privacy page@" .. ns.Consent.LOGIN_WAIT .. ",privacy page@60")
						eq(ns.Consent.LOGIN_WAIT, 45, "with the 1.0 location question's")
						-- In combat at that moment: nothing; the minute after, out of it: the page.
						InCombatLockdown = function() return true end
						timers[1].fn()
						eq(page:IsShown(), false, "never in combat")
						InCombatLockdown = function() return false end
						timers[2].fn()
						assert(page:IsShown(), "the minute after")
						eq(ns.Layers.AskChoice(), false, "the page is up: nothing more")
						eq(#game.shown, 0)
						-- Closed unanswered: once a session, by any of them.
						page.done:Click()
						eq(ns.Layers.AskChoice(), false); timers[2].fn(); eq(ns.Consent.Ask("window"), false)
						eq(page:IsShown(), false); eq(#game.shown, 0)
						-- A player who answered the location in 1.0 still gets the page by itself, for the rest.
						ns.Consent.Reset()
						ns.db.shareLocation = true
						eq(ns.Layers.AskChoice(), false, "answered: the location question asks nothing")
						timers[2].fn()
						assert(ns.Consent.Frame():IsShown(), "the page after login for the lines never answered")
						ns.Consent.Frame():Hide()
						-- A keeper: 1.0's question opens the page, never its popup.
						ns.Consent.Reset()
						ns.db.shareLocation = nil
						ns.db.keeperShares, ns.db.treasurerShares = nil, nil
						GetGuildInfo = function() return "OLYMPUS", "Treasurer", 2 end
						ns.me = TREASURER
						ns.Treasury.Reset()
						eq(ns.Treasury.AskConsent(), true)
						eq(#game.shown, 0, "no OLYMPUS_TREASURER_SHARE")
						assert(RowOf(ns.Consent.Frame(), "treasurer"), "his line on the page")
						ns.Consent.Frame():Hide()
						eq(ns.Treasury.AskConsent(), false, "once a session"); eq(#game.shown, 0)
					end)
					ns.After, ns.Every, InCombatLockdown, IsInInstance, ns.me = saved.after, saved.every, saved.combat, saved.inst, saved.me
					ns.Comm.Send, ns.Comm.Hello = saved.send, saved.hello
					ns.Layers.Reset(); ns.Treasury.Reset()
					if not ok then error(err, 0) end
				end)
				-- With the gamepad UI too: the page, never Olympus's dialog for the 1.0 question.
				WithGamepadUI(true, function(game)
					local saved = { combat = InCombatLockdown, inst = IsInInstance, me = ns.me }
					local ok, err = pcall(function()
						ns.Consent.Reset(); ns.Layers.Reset()
						ns.db.shareLocation = nil
						InCombatLockdown, IsInInstance = function() return false end, function() return false end
						GetGuildInfo = function() return "Olympus II", "Member", 3 end
						ns.me = "Fresh Install-Realm"
						eq(ns.Layers.AskChoice(), true)
						eq(ns.Dialog.Find("OLYMPUS_LOCATION_CHOICE"), nil, "not Olympus's dialog either")
						eq(#game.shown, 0); assert(ns.Consent.Frame():IsShown())
					end)
					InCombatLockdown, IsInInstance, ns.me = saved.combat, saved.inst, saved.me
					ns.Layers.Reset()
					if not ok then error(err, 0) end
				end)
			end)
		end)
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path), path):gsub("%s+", " ")
			assert(doc:find("About 45 seconds after login", 1, true), path .. ": the page after login")
		end
	end)

	test("1.1 review (#12): a block-term edit is logged by its editor alone: a repeat by another editor, or a name that is not the sender's, writes nothing; the editor's own repeat names him", function()
		WithThrone(function(w, K)
			local F = ns.Filter
			local saved = { shared = ns.rdb.filterShared, council = ns.rdb.council, random = F.random }
			local ok, err = pcall(function()
				ns.rdb.council = { names = { ["test councillor"] = true } }
				F.random = function() return 0 end
				ns.Chronicle.Clear()
				local lists = {}
				local function Client(name, as)
					as()
					ns.me = name
					lists[name] = lists[name] or {}
					ns.rdb.filterShared = lists[name]
					F.Reset()
				end
				local function Councillor() GetGuildInfo = function() return "Olympus II", "Member", 3 end end
				-- A High Councillor adds a word: his message names him.
				Client(COUNCILLOR, Councillor)
				local t0 = w.clock
				eq(F.EditShared("gold", true), true)
				local edit = LastSent(w)
				eq(edit:match("^BW~%x+~(.*)$"), "+gold@" .. t0 .. "@" .. COUNCILLOR)
				-- The King's client hears it from him: in its log by his name.
				Client(KING, AsKing)
				ns.Chronicle.Clear()
				F.Receive("CHANNEL", COUNCILLOR, edit)
				eq(Terms(), COUNCILLOR .. " +gold")
				-- Ten minutes later the King's client repeats its list: the word, without a name.
				w.clock = t0 + F.REPEAT + 1
				local before = #w.sent
				eq(F.Tick(), true)
				local repeatMsg = w.sent[before + 1].msg
				eq(repeatMsg:match("^BW~%x+~(.*)$"), "+gold@" .. t0, "another editor's edit: never named in a repeat")
				-- A soldier who logged in meanwhile: the word, and nothing in the log (not the King's act).
				Client("Late Login-Realm", function() AsSoldier("Late Login") end)
				ns.Chronicle.Clear()
				F.Receive("CHANNEL", KING, repeatMsg)
				eq(F.Hides("gold"), true, "the word is taken")
				eq(Terms(), "", "a repeat is not its sender's act")
				-- A sender naming someone else (a modified client): taken, never logged under either.
				F.Receive("CHANNEL", KING, "BW~00000000~+forged@" .. w.clock .. "@" .. COUNCILLOR)
				eq(F.Hides("forged"), true); eq(Terms(), "", "a name that is not the sender's")
				-- The councillor's own repeat within FRESH names him: another late login logs his edit.
				Client(COUNCILLOR, Councillor)
				before = #w.sent
				eq(F.Tick(), true)
				local own = w.sent[before + 1].msg
				eq(own:match("^BW~%x+~(.*)$"), "+gold@" .. t0 .. "@" .. COUNCILLOR)
				eq(repeatMsg:match("^BW~(%x+)~"), own:match("^BW~(%x+)~"), "the same list, the same digest, names left out")
				Client("Later Login-Realm", function() AsSoldier("Later Login") end)
				ns.Chronicle.Clear()
				F.Receive("CHANNEL", COUNCILLOR, own)
				eq(Terms(), COUNCILLOR .. " +gold", "heard from him: his")
				-- After FRESH his repeat names him no more (nobody logs a list caught up on).
				Client(COUNCILLOR, Councillor)
				w.clock = t0 + F.FRESH + 1
				before = #w.sent
				eq(F.Tick(), true)
				eq(w.sent[before + 1].msg:match("^BW~%x+~(.*)$"), "+gold@" .. t0)
			end)
			ns.rdb.filterShared, ns.rdb.council, F.random = saved.shared, saved.council, saved.random
			F.Reset()
			ns.Chronicle.Clear()
			if not ok then error(err, 0) end
		end)
	end)

	test("1.1 review (#12): the King's switches are logged by whoever gave them: never from the Treasurer's book, a repeat or a word caught up on later; another's word that new is repeated by nobody else", function()
		WithThrone(function(w, K)
			local T = ns.Treasury
			local saved = { stewardName = K.IsStewardName, steward = K.IsSteward }
			local ok, err = pcall(function()
				K.IsStewardName = function(n) return ns.FullName(n) == STEWARD end
				K.IsSteward = function() return ns.me == STEWARD end
				ns.Chronicle.Clear()
				-- The Treasurer's book carries the King's word (his switches: the balance).
				AsTreasurer()
				ns.db.keeperShares = { [TREASURER_KEY] = true }
				ns.rdb.treasuryFlags = { balance = true, ranking = false, book = false, at = w.clock, from = KING }
				local book = T.Message()
				assert(book:find("~100@" .. w.clock .. "~", 1, true), "the King's word in his book")
				-- A client that missed the King's own message: the book's copy is 1.0's addons' alone
				-- (Konig's review of 1.1), neither taken nor the Treasurer's act.
				AsSoldier("Late Login")
				ns.rdb.treasuryFlags = nil
				T.HandleReport("CHANNEL", TREASURER, book)
				eq(T.Shows("balance"), false, "not taken")
				eq(Switches(), "", "the Treasurer's book repeats the word; he never gives it")
				-- Then the King's own fresh word: his (compared with nothing shown: the book brought none).
				K.HandleCommand("CHANNEL", KING, ("T1~T~21~Olympus~010~%d"):format(w.clock + 1))
				eq(Switches(), KING .. ": " .. ns.L.ACTS_TREASURY:format(ns.L.ACTS_TREASURY_RANKING))
				-- A word given long ago (a later login, the King's repeat): taken, not logged.
				ns.Chronicle.Clear()
				ns.rdb.treasuryFlags, ns.rdb.actsState = nil, nil
				K.HandleCommand("CHANNEL", KING, ("T1~T~22~Olympus~011~%d"):format(w.clock - 3 * 86400))
				eq(T.Shows("book"), true); eq(Switches(), "", "caught up on three days later: not seen given")
				-- The Steward's client heard the King's word just given: it waits WORD_FRESH to repeat it.
				AsSteward()
				ns.rdb.treasuryFlags = nil
				K.HandleCommand("CHANNEL", KING, ("T1~T~23~Olympus~110~%d"):format(w.clock))
				local before = #w.sent
				T.SendFlags(true)
				eq(#w.sent, before, "the King's word, just given: his client alone sends it")
				local given = w.clock
				w.clock = w.clock + T.WORD_FRESH
				T.SendFlags(true)
				eq(#w.sent, before + 1)
				local steward = LastSent(w)
				assert(steward:find("~110~" .. given .. "$"), steward)
				-- A late client hearing that repeat: taken, not logged as the Steward's.
				AsSoldier("Late Login")
				ns.Chronicle.Clear()
				ns.rdb.treasuryFlags, ns.rdb.actsState = nil, nil
				K.HandleCommand("CHANNEL", STEWARD, steward)
				eq(T.Shows("ranking"), true); eq(Switches(), "", "the Steward's repeat of the King's word")
				-- The Steward's own word: his client sends it at once, and it is his in the log.
				AsSteward()
				T.SetFlag("book", true)
				local own = LastSent(w)
				AsSoldier("Late Login")
				K.HandleCommand("CHANNEL", STEWARD, own)
				eq(Switches(), STEWARD .. ": " .. ns.L.ACTS_TREASURY:format(ns.L.ACTS_TREASURY_BALANCE .. ", " .. ns.L.ACTS_TREASURY_RANKING .. ", " .. ns.L.ACTS_TREASURY_BOOK))
			end)
			K.IsStewardName, K.IsSteward = saved.stewardName, saved.steward
			ns.db.keeperShares = nil
			ns.Chronicle.Clear()
			if not ok then error(err, 0) end
		end)
	end)

	test("1.1 review (#12, #31): on the King's screen (his stream) the log shows every sender but him cut short, in /oly log, the copy, the tooltips and the search, and the shared terms' words cut short", function()
		WithThrone(function(w, K)
			local Ch, F = ns.Chronicle, ns.Filter
			local saved = { shared = ns.rdb.filterShared, print = print, UI = ns.UI, shown = ns.CouncilNamesShown() }
			local lines, copied = {}, {}
			local ok, err = pcall(function()
				Ch.Clear()
				AsKing()
				ns.SetCouncilNamesShown(false)
				eq(ns.CouncilMasked(), true, "the King's screen, names hidden")
				Ch.Add("switch", STEWARD, ns.L.ACTS_TREASURY:format(ns.L.ACTS_TREASURY_RANKING), { key = "treasury", value = "010", default = "000" })
				Ch.Add("gates", KING, ns.L.ACTS_GATES_OPEN:format("Olympus II"))
				local stewardEntry, kingEntry = Ch.Entries()[1], Ch.Entries()[2]
				local masked = ns.MaskName(STEWARD)
				eq(masked, "Test****")
				assert(Ch.Line(stewardEntry):find(masked, 1, true) and not Ch.Line(stewardEntry):find("Steward", 1, true), Ch.Line(stewardEntry))
				assert(Ch.Line(kingEntry):find(KING, 1, true), "the King's own name stays")
				-- The copy and /oly log.
				ns.UI = { ShowCopy = function(_, text) copied[#copied + 1] = text end, Refresh = function() end, RefreshSoon = function() end }
				SlashCmdList.OLYMPUS("log copy")
				assert(copied[1] and not copied[1]:find("Steward", 1, true) and copied[1]:find(masked, 1, true), "the copy")
				print = function(s) lines[#lines + 1] = tostring(s) end
				SlashCmdList.OLYMPUS("log")
				local chat = table.concat(lines, "\n")
				assert(chat:find(masked, 1, true) and not chat:find("Steward", 1, true), chat)
				-- The search finds what shows, never the hidden name.
				lines = {}
				SlashCmdList.OLYMPUS("log steward")
				eq(w.printed[#w.printed], ns.L.ACTS_CHAT_HEAD:format(0, 2), "no entry found by the hidden name")
				assert(not table.concat(lines, "\n"):find("Steward", 1, true))
				-- The Decrees tab's tooltip.
				local tip = {}
				local tt = { AddLine = function(_, s) tip[#tip + 1] = s end }
				for _, l in ipairs(Ch.AddLines({})) do if l.tooltip and l.text:find(ns.L.ACTS_KIND_SWITCH, 1, true) then l.tooltip(tt) end end
				local tipText = table.concat(tip, "\n")
				assert(tipText:find(ns.L.ACTS_BY:format(masked), 1, true) and not tipText:find("Steward", 1, true), tipText)
				-- His eye shows the names: in full.
				ns.SetCouncilNamesShown(true)
				assert(Ch.Line(stewardEntry):find(STEWARD, 1, true))
				ns.SetCouncilNamesShown(false)
				-- A term the King takes off the shared list: cut short on his Decrees tab, as in chat.
				ns.rdb.filterShared = { slur = { on = true, at = w.clock - 10, by = KING } }
				eq(F.EditShared("slur", false), true)
				local decrees = {}
				for _, l in ipairs(Ch.AddLines({})) do decrees[#decrees + 1] = tostring(l.text) end
				local all = table.concat(decrees, "\n")
				assert(all:find('"-s***"', 1, true) and not all:find("slur", 1, true), all)
				local last = Ch.Entries()[#Ch.Entries()]
				assert(not Ch.Line(last):find("slur", 1, true), Ch.Line(last))
				-- Anyone else's screen: the words and names whole.
				AsSoldier("Reader")
				eq(ns.CouncilMasked(), false)
				assert(Ch.Line(last):find('"-slur"', 1, true), Ch.Line(last))
				assert(Ch.Line(stewardEntry):find(STEWARD, 1, true))
			end)
			ns.rdb.filterShared, print, ns.UI = saved.shared, saved.print, saved.UI
			ns.SetCouncilNamesShown(saved.shown)
			Ch.Clear()
			if not ok then error(err, 0) end
		end)
	end)
end
---------------------------------------------------------------------------
-- 1.1 review of the Board and the King's week (batch C): signups, the week and the nudge kept
-- across a /reload or a login; a flag replaced shows at once; the Agenda's box; a full week.
---------------------------------------------------------------------------

do
	-- SavedVariables as a /reload leaves them: written out and read back (no table shared with
	-- what the addon held), Lua's memory of the week gone. `edit` changes what was saved first.
	local function SavedCopy(t)
		if type(t) ~= "table" then return t end
		local out = {}
		for k, v in pairs(t) do out[k] = SavedCopy(v) end
		return out
	end
	local function Reload(W, edit)
		local saved = SavedCopy({ week = ns.rdb.week, weekHeard = ns.rdb.weekHeard, signups = ns.rdb.signups, signed = ns.rdb.signed })
		if edit then edit(saved) end
		W.Reset()
		ns.rdb.week, ns.rdb.weekHeard, ns.rdb.signups, ns.rdb.signed = saved.week, saved.weekHeard, saved.signups, saved.signed
		W.Restore()
	end
	local function Sheet(w) return (LastSent(w) or ""):match("^T1~R~%d+~Olympus~(.*)$") end

	test("1.1 review: the setter's signups are kept across a /reload; the next sheet tells the army what it told before, not 0", function()
		WithWeek(function(w, W, K, B)
			AsKing()
			K.SetAgenda("Sat 20:00 Raid night")
			local id = W.Entries()[1].id
			W.Tick()
			for _, name in ipairs({ "Zed", "Zed2", "Zed3" }) do W.HandleSignup("WHISPER", name .. "-Realm", ("Y2~%d~T~Olympus Zeus"):format(id)) end
			W.HandleSignup("WHISPER", "Nomad-Realm", ("Y2~%d~A~Olympus Nowhere"):format(id))
			eq(Sheet(w), id .. ":3:0:0:0~5", "3 tanks before the /reload")
			-- The /reload (on stream): the week and its signups come back, the sheet says 3 again.
			Reload(W)
			local c = W.Counts(W.Entry(id))
			eq(c.T, 3); eq(c.others, 1, "the one the census can't place, apart as before")
			local n = #w.sent
			W.Tick()
			assert(#w.sent > n, "a sheet at the first minute")
			eq(Sheet(w), id .. ":3:0:0:0~5", "the army hears 3 tanks, as before")
			assert(Line(B.Lines(), ns.L.SIGN_WHO:format(4)), "the names behind the click, all four")
			-- A withdrawal after it counts right, and is kept for the next /reload.
			W.HandleSignup("WHISPER", "Zed2-Realm", ("Y2~%d~W~Olympus Zeus"):format(id))
			eq(W.Counts(W.Entry(id)).T, 2)
			Reload(W)
			eq(W.Counts(W.Entry(id)).T, 2); eq(W.Counts(W.Entry(id)).others, 1)
			-- What the SavedVariables hold is checked: a role that isn't one, a name that isn't one, an
			-- entry that is no longer ours (forgotten).
			Reload(W, function(saved)
				local list = saved.signups[ns.me][id]
				list["Bad-Realm"] = { role = "Q", guild = "Olympus Zeus", placed = true }
				list[42] = { role = "T", guild = "Olympus Zeus", placed = true }
				list["Odd-Realm"] = "T"
				saved.signups[ns.me][99999] = { ["Ghost-Realm"] = { role = "T", guild = "Olympus Zeus", placed = true } }
			end)
			eq(W.Counts(W.Entry(id)).T, 2); eq(W.Counts(W.Entry(id)).others, 1)
			eq(ns.rdb.signups[ns.me][99999], nil, "no such entry of ours: forgotten")
		end)
	end)

	test("1.1 review: the week heard is kept across a /reload or a login while its setter is offline; its cancel or its end takes it off", function()
		WithWeek(function(w, W, K, B)
			AsSoldier()
			local KING = ns.KingCharacter() .. "-Realm"
			K.HandleCommand("CHANNEL", KING, "T1~D~501~Olympus~" .. (4 * 86400) .. "~1~~Raid night")
			K.HandleCommand("CHANNEL", KING, "T1~D~502~Olympus~" .. (2 * 86400) .. "~1~Orgrimmar~PvP night")
			K.HandleCommand("CHANNEL", KING, "T1~D~503~Olympus~3600~1~~Court")
			local at = W.Entry(501).at
			Reload(W)
			eq(#W.Entries(), 3, "all three back")
			eq(W.Entry(501).at, at); eq(W.Entry(501).by, KING); eq(W.Entry(502).zone, "Orgrimmar")
			local text = Texts(B.Lines())
			assert(text:find("Raid night", 1, true) and text:find("Court", 1, true) and not text:find(ns.L.WEEK_EMPTY, 1, true), text)
			-- The King offline for half an hour: all of it still there.
			for _ = 1, 30 do w.clock = w.clock + 60; W.Tick() end
			eq(#W.Entries(), 3)
			-- A login on another character of this account on the realm: the same week.
			AsSoldier("Alt")
			Reload(W)
			eq(#W.Entries(), 3)
			AsSoldier()
			-- Taken off by the King: gone, and not back after the next /reload.
			K.HandleCommand("CHANNEL", KING, "T1~D~502~Olympus~0~0~~")
			Reload(W)
			eq(W.Entry(502), nil); eq(#W.Entries(), 2)
			-- An hour after it began: gone for good.
			w.clock = W.Entry(503).at + W.KEEP_AFTER + 1
			W.Tick()
			Reload(W)
			eq(W.Entry(503), nil); eq(#W.Entries(), 1)
			-- What the SavedVariables hold is checked: past, too far, no title, no setter, ours.
			Reload(W, function(saved)
				local now = w.clock
				for i, bad in ipairs({ { at = now - W.KEEP_AFTER - 5, by = KING, title = "Old" }, { at = now + 9 * 86400, by = KING, title = "Far" },
					{ at = now + 3600, by = KING, title = "" }, { at = now + 3600, title = "Nobody's" }, { at = now + 3600, by = ns.me, title = "Mine, taken off" } }) do
					bad.id = 700 + i
					saved.weekHeard[#saved.weekHeard + 1] = bad
				end
			end)
			eq(#W.Entries(), 1)
		end)
	end)

	test("1.1 review: an entry cancelled while this client was away leaves the week once its setter, back online, repeats his others without it", function()
		WithWeek(function(w, W, K)
			AsSoldier()
			local KING = ns.KingCharacter() .. "-Realm"
			K.HandleCommand("CHANNEL", KING, "T1~D~501~Olympus~" .. (4 * 86400) .. "~1~~Raid night")
			K.HandleCommand("CHANNEL", KING, "T1~D~502~Olympus~" .. (5 * 86400) .. "~1~~PvP night")
			-- Logged off for 3 hours; the King took 502 off meanwhile. Back: the week as it was kept.
			w.clock = w.clock + 3 * 3600
			Reload(W)
			eq(#W.Entries(), 2)
			-- The King online again: his client repeats 501 every 30 minutes (days away), never 502.
			local t0 = w.clock
			for m = 0, 90 do
				w.clock = t0 + m * 60
				if m % 30 == 0 then K.HandleCommand("CHANNEL", KING, ("T1~D~501~Olympus~%d~0~~Raid night"):format(W.Entry(501).at - w.clock)) end
				W.Tick()
				if m == 60 then assert(W.Entry(502), "not yet: an hour of his repeats") end
			end
			eq(W.Entry(502), nil, "his repeats go on without it: taken off")
			assert(W.Entry(501), "his own repeated one stays")
		end)
	end)

	test("1.1 review: the signed nudge comes after a /reload a few minutes before, from the signup itself when the entry isn't heard again", function()
		-- The finding: signed as Healer, a /reload 8 minutes before, the King's next repeat after the start.
		WithWeek(function(w, W, K)
			AsSoldier()
			local KING = ns.KingCharacter() .. "-Realm"
			local t0 = w.clock
			K.HandleCommand("CHANNEL", KING, "T1~D~501~Olympus~3600~1~~Raid night")
			K.HandleCommand("CHANNEL", KING, "T1~R~9~Olympus~501:0:0:0:0~5")
			eq(W.Sign(501, "H"), true)
			w.clock = t0 + 3600 - 8 * 60
			Reload(W)
			for m = 7, 1, -1 do w.clock = t0 + 3600 - m * 60; W.Tick() end
			eq(#w.alerts, 1, "nudged, once")
			assert(w.printed[#w.printed]:find(ns.L.SIGN_SOON:format(ns.L.SIGN_ROLE_H, "Raid night", 5, ""), 1, true), w.printed[#w.printed])
		end)
		-- The entry itself not kept (another client's saved week, a full week there): the signup alone.
		WithWeek(function(w, W, K)
			AsSoldier()
			local KING = ns.KingCharacter() .. "-Realm"
			local t0 = w.clock
			K.HandleCommand("CHANNEL", KING, "T1~D~501~Olympus~3600~1~Orgrimmar~Raid night")
			K.HandleCommand("CHANNEL", KING, "T1~R~9~Olympus~501:0:0:0:0~5")
			W.Sign(501, "T")
			w.clock = t0 + 3600 - 8 * 60
			Reload(W, function(saved) saved.weekHeard = nil end)
			eq(W.Entry(501), nil)
			for m = 7, 1, -1 do w.clock = t0 + 3600 - m * 60; W.Tick() end
			eq(#w.alerts, 1)
			assert(w.printed[#w.printed]:find(ns.L.SIGN_SOON:format(ns.L.SIGN_ROLE_T, "Raid night", 5, " (Orgrimmar)"), 1, true), w.printed[#w.printed])
			eq(#w.notices, 0); eq(#w.popups, 0)
		end)
		-- Taken off while it isn't held: no nudge, on any character of this account here; the
		-- Agenda's current event cancelled (X) or replaced by another: no nudge either.
		WithWeek(function(w, W, K)
			local KING = ns.KingCharacter() .. "-Realm"
			local t0 = w.clock
			K.HandleCommand("CHANNEL", KING, "T1~D~601~Olympus~3600~1~~Court")
			K.HandleCommand("CHANNEL", KING, "T1~A~77~Olympus~3000~Orgrimmar~Raid on the Crossroads")
			K.HandleCommand("CHANNEL", KING, "T1~R~9~Olympus~601:0:0:0:0,77:0:0:0:0~5")
			AsSoldier("Alt")
			W.Sign(601, "D")
			AsSoldier()
			w.clock = w.clock + W.SIGN_GAP
			W.Sign(601, "T")
			w.clock = w.clock + W.SIGN_GAP
			W.Sign(77, "A")
			local alerts = #w.alerts
			Reload(W, function(saved) saved.weekHeard = nil end)
			K.HandleCommand("CHANNEL", KING, "T1~D~601~Olympus~0~0~~")
			K.HandleCommand("CHANNEL", KING, "T1~X~77~Olympus")
			eq(W.MySignup(601), nil); eq(W.MySignup(77), nil)
			for m = 10, 1, -1 do w.clock = t0 + 3600 - m * 60; W.Tick() end
			AsSoldier("Alt")
			W.Tick()
			eq(#w.alerts, alerts, "no nudge for what was taken off")
			-- Signed for the Agenda's current event, then the King set another one: the old one's
			-- signup goes.
			AsSoldier()
			K.HandleCommand("CHANNEL", KING, "T1~A~78~Olympus~3000~Orgrimmar~Raid")
			K.HandleCommand("CHANNEL", KING, "T1~R~10~Olympus~78:0:0:0:0~5")
			w.clock = w.clock + W.SIGN_GAP
			W.Sign(78, "A")
			K.HandleCommand("CHANNEL", KING, "T1~A~79~Olympus~2400~Orgrimmar~Another raid")
			W.Tick()
			eq(W.MySignup(78), nil)
		end)
	end)

	test("1.1 review: a flag lowered and raised again 31 s later, or replaced, shows on every Board at once; the old one's G0 keeps its place in the send queue", function()
		WithBoard(function(w, B)
			local savedChannel, savedCI = GetChannelName, C_ChatInfo
			local ok, err = pcall(function()
				-- The poster's real send queue (Comm.lua), on the channel.
				GetChannelName = function() return 5 end
				local cns = FreshComm()
				cns.Comm.JoinChannel()
				local out = {}
				local function Capture(_, msg, dist) if dist == "CHANNEL" then out[#out + 1] = msg end return true end
				C_ChatInfo = { SendAddonMessage = Capture, SendAddonMessageLogged = Capture, RegisterAddonMessagePrefix = function() end }
				ns.Comm.Send = function(dist, msg, key, urgent, logged) cns.Comm.Send(dist, msg, key, urgent, logged) end
				local n = 0
				B.random = function(a) if a then n = n + 1 return a + n end return 0 end
				local function Pump() for _ = 1, 20 do cns.Comm.Pump() end end
				-- What went out, heard at once by a player of another guild (the same Board module: its
				-- cards are the viewer's, its own flag the poster's).
				local function Heard(list)
					ns.me = "Viewer-Realm"
					GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
					for _, msg in ipairs(list) do
						if msg:find("^G0~") then B.HandleLower("CHANNEL", "Soldier-Realm", msg) else B.HandlePost("CHANNEL", "Soldier-Realm", msg) end
					end
					AsSoldier()
				end
				local function Since(i) local t = {} for j = i + 1, #out do t[#t + 1] = out[j] end return t end
				AsSoldier()
				eq(B.Raise("D", "sm"), true)
				Pump()
				Heard(out)
				eq(#B.List(), 1)
				local oldId = B.List()[1].id
				-- Lowered, then raised again 31 s after the first, both still waiting to go.
				w.clock = w.clock + 10
				B.Lower()
				w.clock = w.clock + 21
				eq(B.Raise("R"), true)
				local from = #out
				Pump()
				local batch = Since(from)
				eq(#batch, 2, "its G0 and the new flag both went out")
				eq(batch[1], "G0~" .. oldId); assert(batch[2]:find("^G1~"), batch[2])
				Heard(batch)
				local list = B.List()
				eq(#list, 1); eq(list[1].flag, "R", "the new flag, at once")
				-- Replaced without lowering, 31 s later: the old one's G0 goes first; the new one shows.
				w.clock = w.clock + B.RAISE_GAP + 1
				local rId = list[1].id
				from = #out
				eq(B.Raise("P", "pvp"), true)
				Pump()
				batch = Since(from)
				eq(batch[1], "G0~" .. rId); assert(batch[2] and batch[2]:find("^G1~"), tostring(batch[2]))
				Heard(batch)
				list = B.List()
				eq(#list, 1); eq(list[1].flag, "P"); eq(list[1].note, "pvp", "not the old flag and note")
				assert(list[1].id ~= rId and list[1].id ~= oldId, "a new id, never one a Board still holds lowered")
			end)
			GetChannelName, C_ChatInfo = savedChannel, savedCI
			if not ok then error(err, 0) end
		end)
		-- The receiving side alone, as the finding's probe sent it: G1, G0 10 s later, a new G1 at
		-- 31 s; and a new one without a G0 (lost on the way) at 31 s: each shows.
		WithBoard(function(w, B)
			AsSoldier()
			local t0 = w.clock
			B.HandlePost("CHANNEL", "Aldric-Realm", Flag("a1", "Olympus Zeus", "D", 0, nil, "sm"))
			w.clock = t0 + 10
			B.HandleLower("CHANNEL", "Aldric-Realm", "G0~a1")
			w.clock = t0 + 31
			B.HandlePost("CHANNEL", "Aldric-Realm", Flag("a2", "Olympus Zeus", "R", 0))
			eq(#B.List(), 1); eq(B.List()[1].flag, "R")
			B.HandlePost("CHANNEL", "Brenna-Realm", Flag("b1", "Olympus Zeus", "D", 0, nil, "sm"))
			w.clock = t0 + 62
			B.HandlePost("CHANNEL", "Brenna-Realm", Flag("b2", "Olympus Zeus", "R", 0))
			local b
			for _, e in ipairs(B.List()) do if e.sender == "Brenna-Realm" then b = e end end
			eq(b.id, "b2", "31 s after her last: taken")
			assert(B.NEW_ID_GAP <= B.RAISE_GAP, "a raise the poster's client allows is never dropped")
			-- Her first flag held back in a long send queue, the G0 and the new one right behind it:
			-- a few seconds apart here, the new one shows all the same (her G0 took the old one down).
			w.clock = t0 + 200
			B.HandlePost("CHANNEL", "Cedric-Realm", Flag("c1", "Olympus Zeus", "D", 0))
			w.clock = t0 + 202
			B.HandleLower("CHANNEL", "Cedric-Realm", "G0~c1")
			w.clock = t0 + 204
			B.HandlePost("CHANNEL", "Cedric-Realm", Flag("c2", "Olympus Zeus", "R", 0))
			local c
			for _, e in ipairs(B.List()) do if e.sender == "Cedric-Realm" then c = e end end
			eq(c and c.id, "c2")
			-- Without a G0 that soon: still one new flag every NEW_ID_GAP at most.
			B.HandlePost("CHANNEL", "Cedric-Realm", Flag("c3", "Olympus Zeus", "P", 0))
			for _, e in ipairs(B.List()) do if e.sender == "Cedric-Realm" then c = e end end
			eq(c.id, "c2")
		end)
	end)

	test("1.1 review: the Agenda's box starts empty; a number before a day and an hour makes a week entry, never a 30-minute Agenda with its raid warning", function()
		WithWeek(function(w, W, K)
			AsKing()
			-- The box as the King gets it, then his words typed in, then OK.
			local def = StaticPopupDialogs.OLYMPUS_KING_AGENDA
			local box = { text = "?", SetText = function(self, t) self.text = t end, GetText = function(self) return self.text end, SetFocus = function() end }
			def.OnShow({ editBox = box })
			eq(box.text, "", "nothing put there first")
			box.text = box.text .. "Sat 20:00 Raid night"
			def.OnAccept({ editBox = box })
			assert(LastWeek(w) and LastWeek(w):find("~1~~Raid night$"), tostring(LastWeek(w)))
			eq(K.Agenda(), nil, "no 30-minute Agenda")
			-- Typed after a number anyway (1.0's box began with "30 "): the week's entry, quietly.
			w.clock = w.clock + W.SET_GAP
			local sent = #w.sent
			eq(K.SetAgenda("30 Sun 20:00 PvP night"), true)
			eq(K.Agenda(), nil)
			assert(LastWeek(w):find("~1~~PvP night$"), LastWeek(w))
			for i = sent + 1, #w.sent do assert(not w.sent[i].msg:find("^T1~A~"), w.sent[i].msg) end
			eq(#w.notices, 0, "no raid warning"); eq(#w.popups, 0)
			-- A day and an hour that can't be (past, 25:00): refused, nothing sent.
			w.clock = w.clock + W.SET_GAP
			sent = #w.sent
			eq(K.SetAgenda("30 today 18:00 Raid"), false)
			eq(K.SetAgenda("30 Sat 25:00 Raid"), false)
			eq(#w.sent, sent); eq(K.Agenda(), nil)
			assert(Printed(w, ns.L.THRONE_AGENDA_USAGE))
			-- Minutes, then words that are no day and hour: the Agenda's current event, as always.
			eq(K.SetAgenda("30 Sunday funday"), true)
			eq(K.Agenda().title, "Sunday funday")
		end)
	end)

	test("1.1 review: a full week keeps the King's and his Steward's entries (the Hands' furthest ahead give way); a Hand holds 5", function()
		WithWeek(function(w, W, K)
			local savedSteward = ns.IsSteward
			local ok, err = pcall(function()
				AsSoldier()
				local KING = ns.KingCharacter() .. "-Realm"
				local hands = {}
				for i = 1, 7 do hands[i] = "Help" .. string.char(96 + i) .. "-Realm" end
				K.HandleCommand("CHANNEL", KING, "T1~H~9~Olympus~" .. table.concat(hands, ","))
				-- Six Hands, 5 entries each: the week is full. A sixth of one Hand, room or not: left out.
				local id = 1000
				for i = 1, 6 do
					for j = 1, 5 do
						id = id + 1
						K.HandleCommand("CHANNEL", hands[i], ("T1~D~%d~Olympus II~%d~1~~Night %d-%d"):format(id, 3600 * (i * 5 + j), i, j))
					end
					if i == 1 then
						K.HandleCommand("CHANNEL", hands[1], "T1~D~2001~Olympus II~7200~1~~One too many")
						eq(W.Entry(2001), nil, "a Hand holds 5"); eq(#W.Entries(), 5)
					end
				end
				eq(#W.Entries(), W.MAX_KEPT)
				K.HandleCommand("CHANNEL", hands[7], "T1~D~2002~Olympus II~7200~1~~Late Hand")
				eq(W.Entry(2002), nil, "full: another Hand's waits")
				-- The King's: always kept; the Hands' entry furthest ahead gives way.
				K.HandleCommand("CHANNEL", KING, "T1~D~9001~Olympus~7200~1~~The King's raid night")
				assert(W.Entry(9001), "the King's kept")
				eq(W.Entry(1030), nil, "the Hands' furthest ahead gave way")
				eq(#W.Entries(), W.MAX_KEPT)
				-- His Steward's the same.
				ns.IsSteward = function(name) return ns.ShortName(name) == "Stew" end
				K.HandleCommand("CHANNEL", "Stew-Realm", "T1~D~9002~Olympus II~9000~1~~Court")
				assert(W.Entry(9002), "the Steward's kept"); eq(W.Entry(1029), nil)
				-- Ten of the King's, whatever the Hands hold; an eleventh: over his own cap.
				for i = 3, 12 do K.HandleCommand("CHANNEL", KING, ("T1~D~%d~Olympus~%d~1~~King %d"):format(9000 + i, 7200 + i * 60, i)) end
				local kings = 0
				for _, e in ipairs(W.Entries()) do if e.by == KING then kings = kings + 1 end end
				eq(kings, W.MAX_MINE); eq(W.Entry(9012), nil)
				eq(#W.Entries(), W.MAX_KEPT)
				-- Kept so across a /reload.
				Reload(W)
				assert(W.Entry(9001) and W.Entry(9002)); eq(#W.Entries(), W.MAX_KEPT)
				-- A Hand's own client: 5 entries, then full.
				AsKing(); K.AddHand("Helper")
				AsSoldier("Helper")
				K.HandleCommand("CHANNEL", KING, "T1~H~10~Olympus~Helper-Realm")
				W.Reset()
				for i = 1, 5 do w.clock = w.clock + W.SET_GAP; eq(K.SetAgenda(("Sun %02d:00 Night %d"):format(10 + i, i)), true) end
				w.clock = w.clock + W.SET_GAP
				eq(K.SetAgenda("Mon 20:00 One too many"), false)
				assert(Printed(w, ns.L.WEEK_FULL:format(5)))
			end)
			ns.IsSteward = savedSteward
			if not ok then error(err, 0) end
		end)
	end)

	test("1.1 review: the channel's budget: entries days away repeat every 30 minutes; the sheet every 15 while nobody signed anything within 2 days, Sign up as long", function()
		WithWeek(function(w, W, K, B)
			AsKing(); K.AddHand("Helper")
			AsSoldier("Helper")
			local KING = ns.KingCharacter() .. "-Realm"
			K.HandleCommand("CHANNEL", KING, "T1~H~10~Olympus~Helper-Realm")
			for i = 1, W.MAX_HAND do w.clock = w.clock + W.SET_GAP; K.SetAgenda(("Sun %02d:00 Night %d"):format(10 + i, i)) end
			-- A Hand's client, minute by minute: when each entry went out again, and its sheets.
			local times, sheets = {}, {}
			local function Run(minutes)
				for _ = 1, minutes do
					local from = #w.sent
					w.clock = w.clock + 60
					K.HandleCommand("CHANNEL", KING, "T1~H~10~Olympus~Helper-Realm") -- (the King online, his list repeated)
					W.Tick()
					for i = from + 1, #w.sent do
						local msg = w.sent[i].msg
						local id = msg:match("^T1~D~(%d+)~")
						if id then times[id] = times[id] or {}; table.insert(times[id], w.clock) end
						if msg:find("^T1~R~") then sheets[#sheets + 1] = msg end
					end
				end
			end
			-- Three hours of 5 entries days away that nobody signed: each again every 30 minutes, the
			-- sheet every 15.
			Run(180)
			local farId, n = next(times), 0
			for id, list in pairs(times) do
				n = n + 1
				for i = 2, #list do assert(list[i] - list[i - 1] >= W.RESEND_FAR, id .. " again after " .. (list[i] - list[i - 1])) end
				assert(#list >= 5, id .. " repeated " .. #list)
			end
			eq(n, W.MAX_HAND)
			assert(#sheets >= 11, #sheets .. " sheets")
			for _, msg in ipairs(sheets) do assert(msg:find("~15$"), msg) end
			local idle = sheets[#sheets]
			-- An hour of it: 5 entries twice each and 4 sheets (before the review: 10 entries every 10
			-- minutes and a sheet every 5, 72 an hour).
			local before = #w.sent
			Run(60)
			assert(#w.sent - before <= 2 * W.MAX_HAND + 4, "an hour: " .. (#w.sent - before))
			-- An entry within a day in place of one of them: again every 10 minutes, and the sheet
			-- every 5 at once.
			local other = next(times, farId)
			eq(W.Cancel(tonumber(other)), true)
			times, sheets = {}, {}
			eq(K.SetAgenda("tomorrow 12:00 Court"), true)
			local court = LastWeek(w):match("^T1~D~(%d+)~")
			Run(60)
			eq(sheets[1]:match("~(%d+)$"), "5")
			assert(#sheets >= 11, #sheets .. " sheets")
			local list = times[court]
			assert(list and #list >= 5, "Court repeated " .. (list and #list or 0))
			for i = 2, #list do assert(list[i] - list[i - 1] >= W.RESEND, "Court again after " .. (list[i] - list[i - 1])) end
			-- A soldier hears a 15-minute sheet: Sign up stays for its 15 minutes, not after.
			local far = W.Entry(tonumber(farId))
			local at, title = far.at, far.title
			AsSoldier()
			W.Reset()
			K.HandleCommand("CHANNEL", "Helper-Realm", ("T1~D~%s~Olympus II~%d~0~~%s"):format(farId, at - w.clock, title))
			K.HandleCommand("CHANNEL", "Helper-Realm", "T1~R~5~Olympus II~" .. idle:match("^T1~R~%d+~[^~]*~(.*)$"))
			local heard = w.clock
			w.clock = heard + 15 * 60
			assert(Line(B.Lines(), ns.L.SIGN_UP), "Sign up after 15 minutes still")
			w.clock = heard + 15 * 60 + W.SHEET_LATE + 1
			eq(Line(B.Lines(), ns.L.SIGN_UP), nil)
		end)
	end)
end

---------------------------------------------------------------------------
-- 1.1 (batch E, the review's findings): a keeper who stops sharing his location, the keeper's
-- message budget, what a 1.0 insider reads from the channel copy, and what left the bank.
---------------------------------------------------------------------------

test("1.1 taking donations: once the keeper stops sharing his location, no repeat carries his zone (his answer, the King's crown)", function()
	WithThrone(function(w, K)
		local T = ns.Treasury
		local saved = { best = C_Map.GetBestMapForUnit, share = ns.db.shareLocation, crown = ns.db.throneLocation, hello = ns.Comm.Hello,
			split = ns.splitNames }
		local ok, err = pcall(function()
			ns.splitNames = true
			ns.Comm.Hello = function() end
			C_Map.GetBestMapForUnit = function() return 1453 end
			local TREASURER = "Pyralis Ashandar-Realm"
			local function Donations()
				local out = {}
				for _, s in ipairs(w.sent) do if s.msg:find("^TD~") then out[#out + 1] = s.msg end end
				return out
			end
			-- He turns it on while sharing: his zone goes with it.
			AsTreasurer()
			ns.db.shareLocation = true
			local since = w.clock
			T.SetDonations(true)
			eq(LastSent(w), ("TD~Olympus~1~%d~1453"):format(since), "his zone, shared")
			-- He stops sharing (the setting alone, as a saved answer changed any other way): the next
			-- repeat has no zone, nor any after it.
			ns.db.shareLocation = false
			w.clock = w.clock + T.DONATIONS_EVERY
			eq(T.SendDonations(), true)
			eq(LastSent(w), ("TD~Olympus~1~%d~"):format(since), "the repeat: no zone")
			w.clock = w.clock + T.DONATIONS_EVERY
			eq(T.SendDonations(), true)
			eq(LastSent(w), ("TD~Olympus~1~%d~"):format(since), "nor the one after")
			-- A soldier's client given that repeat: the line without a zone.
			local repeat_ = LastSent(w)
			AsSoldier()
			T.HandleDonations("CHANNEL", TREASURER, repeat_)
			local lines = Texts(T.DonationLines())
			assert(lines:find(ns.L.DONATIONS_LINE:format("Pyralis Ashandar"), 1, true), lines)
			assert(not lines:find("Elwynn", 1, true), lines)
			-- /oly location on and off (Layers.SetSharing): said at once, each way.
			AsTreasurer()
			ns.Layers.SetSharing(true)
			eq(LastSent(w), ("TD~Olympus~1~%d~1453"):format(since), "sharing again: his zone at once")
			local n = #Donations()
			ns.Layers.SetSharing(false)
			eq(#Donations(), n + 1, "off: said at once, not at the next repeat")
			eq(Donations()[#Donations()], ("TD~Olympus~1~%d~"):format(since), "without his zone")
			w.clock = w.clock + T.DONATIONS_EVERY
			T.SendDonations()
			eq(LastSent(w), ("TD~Olympus~1~%d~"):format(since), "and the repeat")
			assert(Texts(T.DonationLines()):find(ns.L.DONATIONS_LINE:format("Pyralis Ashandar"), 1, true), "his own line: no zone either")
			T.SetDonations(false)
			-- The King: his crown is his sharing. On with it shown, then he hides it.
			AsKing()
			ns.db.throneLocation = true
			local kingSince = w.clock
			T.SetDonations(true)
			eq(LastSent(w), ("TD~Olympus~1~%d~1453"):format(kingSince), "his crown shown: his zone")
			n = #Donations()
			K.ToggleLocation()
			eq(K.SharingLocation(), false)
			eq(#Donations(), n + 1, "his crown hidden: said at once")
			eq(Donations()[#Donations()], ("TD~Olympus~1~%d~"):format(kingSince), "without his zone")
			w.clock = w.clock + T.DONATIONS_EVERY
			T.SendDonations()
			eq(LastSent(w), ("TD~Olympus~1~%d~"):format(kingSince), "nor at the next repeat")
			T.SetDonations(false)
		end)
		C_Map.GetBestMapForUnit, ns.db.shareLocation, ns.db.throneLocation, ns.Comm.Hello = saved.best, saved.share, saved.crown, saved.hello
		ns.splitNames = saved.split
		if not ok then error(err, 0) end
	end)
end)

-- The keeper's client on a simulated clock: the real Comm queue (Comm.lua in a namespace of its
-- own, FreshComm: a message each 1.2 s, 60 waiting at most, the oldest dropped when full), the
-- real Treasury code, a donation a minute during a stream, the King and keepers online.
local function TreasurySim(opts)
	local result
	WithThrone(function(w, K)
		local T = ns.Treasury
		local saved = { split = ns.splitNames, after = ns.After, time = GetTime, cci = C_ChatInfo, chan = GetChannelName, now = ns.Now,
			chunked = ns.Comm.SendChunked, size = ns.Comm.QueueSize }
		local ok, err = pcall(function()
			ns.splitNames = true
			GetChannelName = function() return 5 end
			local cns = FreshComm()
			local t, base = 0, w.clock
			local timers, log = {}, {}
			ns.Now = function() return base + math.floor(t) end
			cns.Now = ns.Now
			GetTime = function() return t end
			ns.After = function(sec, _, fn) timers[#timers + 1] = { at = t + sec, fn = fn } end
			C_ChatInfo.SendAddonMessage = function(_, msg, dist, target) log[#log + 1] = { msg = msg, dist = dist, to = target, t = t } return true end
			cns.Comm.JoinChannel()
			-- Everything the treasury sends goes through that queue; its size after each send.
			local maxQ = 0
			local function Measured(fn) return function(...) fn(...); maxQ = math.max(maxQ, cns.Comm.QueueSize()) end end
			ns.Comm.Send, ns.Comm.Whisper, ns.Comm.SendChunked = Measured(cns.Comm.Send), Measured(cns.Comm.Whisper), Measured(cns.Comm.SendChunked)
			ns.Comm.QueueSize = cns.Comm.QueueSize
			local KING = "Asmongold Asmongler-Realm"
			AsTreasurer()
			ns.db.keeperShares = { [TREASURER_KEY] = true }
			ns.rdb.treasuryFlags = opts.flags
			local keepers = {}
			for i = 1, opts.keepers do keepers[i] = "Keeper Number" .. string.char(64 + i) .. "-Realm" end
			local names = { unpack(keepers) }
			names[#names + 1] = "Old Keeper-Realm" -- his addon is 1.0: heard by his book, never asking
			ns.rdb.treasuryKeepers = { at = 1, names = names }
			T.SetOpening("1000")
			for i = 1, 150 do T.Record(("Generous Donor Named%03d"):format(i), 10000 + i * 7, "trade", nil, { quiet = true }) end
			local readers = { KING, unpack(keepers) }
			-- Their clients ask after their login (TA), and are heard now and then (the King's
			-- switches, the keepers' books), the King asking again every ASK_EVERY.
			for _, n in ipairs(readers) do T.HandleAsk("CHANNEL", n, "TA~Olympus~0") end
			local nextPump, nextTick, nextHear, nextAsk, nextGift, gifts = 0, 60, 0, T.ASK_EVERY, 0, 0
			while t < opts.minutes * 60 do
				t = t + 0.1
				local due = {}
				for i = #timers, 1, -1 do if timers[i].at <= t then due[#due + 1] = table.remove(timers, i) end end
				table.sort(due, function(a, b) return a.at < b.at end)
				for _, x in ipairs(due) do x.fn() end
				if t >= nextPump then nextPump = nextPump + 1.2; cns.Comm.Pump() end
				if t >= nextTick then nextTick = nextTick + 60; T.Tick() end
				if t >= nextHear then
					nextHear = nextHear + 300
					for _, n in ipairs(readers) do T.Heard(n) end
					T.Heard("Old Keeper-Realm")
				end
				if t >= nextAsk then nextAsk = nextAsk + T.ASK_EVERY; T.HandleAsk("CHANNEL", KING, "TA~Olympus~1") end
				if t >= nextGift and t < opts.stream * 60 then
					nextGift, gifts = nextGift + 60, gifts + 1
					T.Record(("Stream Donor%03d"):format(gifts), 5000 + gifts, "trade", nil, { quiet = true })
				end
			end
			-- Every set of pieces sent, on the channel and by whisper, and the whole books each got.
			local sets, books, asm = {}, {}, ns.Codec.NewAssembler()
			for _, e in ipairs(log) do
				local kind, body = "channel", e.msg
				if e.dist == "WHISPER" then
					local k, rest = e.msg:match("^TW~(%w%w)~(.*)$")
					kind, body = "whisper " .. tostring(k) .. " to " .. tostring(e.to), rest or ""
					local whole = ns.Codec.Feed(asm, e.to, body, ns.Now())
					if whole and k == "TB" then books[e.to] = books[e.to] or {}; table.insert(books[e.to], { msg = whole, t = e.t }) end
				end
				local id, i, n = body:match("^C(%w+):(%d+):(%d+):")
				if id then
					local key = kind .. " #" .. id
					sets[key] = sets[key] or { n = tonumber(n), got = {}, c = 0 }
					if not sets[key].got[i] then sets[key].got[i], sets[key].c = true, sets[key].c + 1 end
				end
			end
			local broken, channelSets, whispers = {}, 0, {}
			for key, x in pairs(sets) do
				if x.c ~= x.n then broken[#broken + 1] = key .. (" %d/%d"):format(x.c, x.n) end
				if key:find("^channel") then channelSets = channelSets + 1 end
			end
			for _, e in ipairs(log) do if e.dist == "WHISPER" then whispers[e.to] = (whispers[e.to] or 0) + 1 end end
			table.sort(broken)
			result = { maxQ = maxQ, broken = broken, channelSets = channelSets, whispers = whispers, books = books, final = T.Message(),
				readers = readers, gifts = gifts }
		end)
		ns.splitNames, ns.After, GetTime, C_ChatInfo, GetChannelName, ns.Now = saved.split, saved.after, saved.time, saved.cci, saved.chan, saved.now
		ns.Comm.SendChunked, ns.Comm.QueueSize = saved.chunked, saved.size
		ns.rdb.treasuryKeepers, ns.db.keeperShares = nil, nil
		if not ok then error(err, 0) end
	end)
	return result
end

test("1.1 Zeal's promise, the keeper's message budget: a donation a minute with 2 or 3 of them online drops nothing from his queue, and each gets the latest book whole", function()
	for _, case in ipairs({
		{ what = "the ranking shown, the King and a keeper", flags = { ranking = true, at = 1 }, keepers = 1 },
		{ what = "the ranking shown, the King and two keepers", flags = { ranking = true, at = 1 }, keepers = 2 },
		{ what = "the ranking and the book shown, the King and two keepers", flags = { ranking = true, book = true, at = 1 }, keepers = 2 },
	}) do
		local r = TreasurySim({ flags = case.flags, keepers = case.keepers, minutes = 30, stream = 20 })
		eq(r.gifts, 20, case.what .. ": a donation a minute for 20 minutes")
		-- Nothing dropped: the queue never reached its 60 (then its oldest message goes), and every
		-- message in pieces arrived whole, his own on the channel and his whispers.
		assert(r.maxQ < 60, case.what .. ": his queue reached " .. r.maxQ)
		assert(#r.broken == 0, case.what .. ": broken " .. table.concat(r.broken, ", "))
		assert(r.channelSets >= 20, case.what .. ": his book on the channel, each time it changed: " .. r.channelSets)
		for _, name in ipairs(r.readers) do
			local got = r.books[ns.TellName(name)] or {} -- (a whisper goes to the name the server finds)
			assert(#got >= 2, case.what .. ": whole books to " .. name .. ": " .. #got)
			-- A changed one PRIVATE_GAP after the last at the soonest, and the latest in the end.
			for i = 2, #got do
				assert(got[i].t - got[i - 1].t >= ns.Treasury.PRIVATE_GAP - 60, case.what .. ": two books to " .. name .. " " .. (got[i].t - got[i - 1].t) .. " s apart")
			end
			eq(got[#got].msg, r.final, case.what .. ": " .. name .. " holds the latest book")
		end
		-- A 1.0 keeper's addon reads no whisper: none goes to him.
		eq(r.whispers[ns.TellName("Old Keeper-Realm")], nil, case.what .. ": nothing whispered to a 1.0 keeper")
	end
end)

test("1.1 Zeal's promise and 1.0: a King, Steward or keeper still on 1.0 is named on a 1.1 insider's Treasury tab while the King hides a part", function()
	WithThrone(function(w, K)
		local T = ns.Treasury
		local saved = { split = ns.splitNames }
		local ok, err = pcall(function()
			ns.splitNames = true
			local KING, TREASURER = "Asmongold Asmongler-Realm", "Pyralis Ashandar-Realm"
			AsTreasurer()
			ns.db.keeperShares = { [TREASURER_KEY] = true }
			T.Record("Secret Donor", 250000, "trade", nil, { quiet = true })
			-- The tab's text, its paragraphs' rows put back together, colors off.
			local function Page()
				local out = {}
				for _, l in ipairs(T.Build()) do out[#out + 1] = (tostring(l.text or ""):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")) end
				return table.concat(out, " ")
			end
			local want = ns.L.TREASURY_NOT_UPDATED:format("Asmon")
			local function Shown() return Page():find(want, 1, true) ~= nil end
			-- The King's switches heard (his addon, whatever its version): not named at once (a 1.1
			-- addon asks ASK_AFTER after its login).
			T.Heard(KING)
			eq(#T.NotUpdated(), 0, "just heard"); eq(Shown(), false)
			-- Heard again later, never asking: a 1.0 addon, named in red on the keeper's tab.
			w.clock = w.clock + T.ASK_AFTER + 61
			T.Heard(KING)
			eq(T.NotUpdated()[1], KING); eq(#T.NotUpdated(), 1)
			assert(Shown(), Page())
			-- What that 1.0 addon shows (1.0.0's Treasury.lua, as a 1.0 King's client runs it): it
			-- held the Treasurer's whole book from 1.0; the channel's copy with every switch off
			-- (the King's starting state) takes its place, the King's switches with it, and his
			-- balance reads zero. (Taken, so no 1.0 client keeps a whole book of 1.0 the King now
			-- hides; the note is how he learns to update.)
			local Old, old = OldTreasury()
			old.me = KING
			Old.HandleReport("CHANNEL", TREASURER, T.Message())
			eq(old.rdb.treasuryReports[TREASURER].balance, T.Balance(), "the whole book of 1.0")
			ns.rdb.treasuryFlags = { balance = false, ranking = false, book = false, at = w.clock }
			Old.HandleReport("CHANNEL", TREASURER, T.Message(nil, (T.PublicParts())))
			eq(old.rdb.treasuryReports[TREASURER].balance, 0, "a 1.0 King reads zero")
			eq(#old.rdb.treasuryReports[TREASURER].rank, 0, "and no ranking")
			-- His addon updated: it asks, and he is named no more.
			T.HandleAsk("CHANNEL", KING, "TA~Olympus~0")
			eq(#T.NotUpdated(), 0); eq(Shown(), false)
			-- A keeper still on 1.0, while the King shows every part: the channel carries the whole
			-- book, nothing to tell.
			ns.rdb.treasuryKeepers = { at = 1, names = { "Test Keeper-Realm" } }
			T.Heard("Test Keeper-Realm")
			w.clock = w.clock + T.ASK_AFTER + 61
			T.Heard("Test Keeper-Realm")
			eq(T.NotUpdated()[1], "Test Keeper-Realm")
			ns.rdb.treasuryFlags = { balance = true, ranking = true, book = true, at = w.clock }
			assert(not Page():find(ns.L.TREASURY_NOT_UPDATED:format("Test Keeper"), 1, true), "every part shown: no note")
			ns.rdb.treasuryFlags = { balance = true, at = w.clock }
			assert(Page():find(ns.L.TREASURY_NOT_UPDATED:format("Test Keeper"), 1, true), "a part hidden: named: " .. Page())
			-- A soldier's tab never names anyone.
			AsSoldier()
			assert(not Page():find("Olympus 1.0", 1, true), "not on a soldier's tab")
		end)
		ns.splitNames = saved.split
		ns.rdb.treasuryKeepers, ns.db.keeperShares = nil, nil
		if not ok then error(err, 0) end
	end)
end)

test("1.1 the treasury's review lines are in both languages, with the same format arguments", function()
	local savedLocale, pt = GetLocale, {}
	GetLocale = function() return "ptBR" end
	local ok, err = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
	GetLocale = savedLocale
	if not ok then error(err, 0) end
	for _, key in ipairs({ "TREASURY_NOT_UPDATED" }) do
		assert(type(rawget(ns.L, key)) == "string", "English " .. key)
		assert(type(rawget(pt.L, key)) == "string" and pt.L[key] ~= ns.L[key], "Portuguese " .. key)
		eq(select(2, pt.L[key]:gsub("%%[ds]", "")), select(2, ns.L[key]:gsub("%%[ds]", "")), key)
	end
end)

-- The guild bank as the game shows it to a test: tabs Mats and Potions, `slots[tab][slot] = { count, item }`,
-- `loaded[tab]` false for a tab whose slots never arrive (it reads empty), the tab on screen.
local function WithBankWorld(fn)
	local saved = { item = C_Item, after = ns.After, time = GetTime, tabs = GetNumGuildBankTabs, info = GetGuildBankTabInfo, slot = GetGuildBankItemInfo,
		link = GetGuildBankItemLink, money = GetGuildBankMoney, query = QueryGuildBankTab, current = GetCurrentGuildBankTab }
	local ok, err = pcall(function()
		local bank = { slots = {}, loaded = {}, shown = 1, gt = 100 }
		C_Item = { GetItemNameByID = function(id) return ({ [2589] = "Linen Cloth", [929] = "Healing Potion", [118] = "Minor Healing Potion" })[id] end }
		local After, Run = Queued()
		ns.After = After
		GetTime = function() return bank.gt end
		GetNumGuildBankTabs = function() return 2 end
		GetGuildBankTabInfo = function(tab) return ({ "Mats", "Potions" })[tab], "icon" .. tab, true end
		local function Slot(tab, slot) return bank.loaded[tab] ~= false and bank.slots[tab] and bank.slots[tab][slot] end
		GetGuildBankItemInfo = function(tab, slot) local s = Slot(tab, slot); if s then return "tex", s[1] end end
		GetGuildBankItemLink = function(tab, slot) local s = Slot(tab, slot); return s and ("|Hitem:" .. s[2] .. ":0|h[x]|h") end
		GetGuildBankMoney = function() return 5000 end
		QueryGuildBankTab, GetCurrentGuildBankTab = function() end, function() return bank.shown end
		-- A visit: the bank opened, read once its slots settle, closed.
		function bank.Visit()
			ns.Bank.Opened(); bank.gt = bank.gt + ns.Bank.SETTLE; Run(); ns.Bank.Closed(); bank.gt = bank.gt + ns.Bank.SETTLE; Run()
		end
		fn(bank)
	end)
	C_Item, ns.After, GetTime, GetNumGuildBankTabs, GetGuildBankTabInfo = saved.item, saved.after, saved.time, saved.tabs, saved.info
	GetGuildBankItemInfo, GetGuildBankItemLink, GetGuildBankMoney, QueryGuildBankTab, GetCurrentGuildBankTab = saved.slot, saved.link, saved.money, saved.query, saved.current
	if not ok then error(err, 0) end
end

-- "Gone since the last snapshot" as the Treasury tab lists it: "<item> -<n> (<tabs>)", sorted.
local function GoneList(cur)
	local out = {}
	for _, g in ipairs(ns.Bank.Gone(cur, ns.Bank.Previous(cur))) do out[#out + 1] = ("%d -%d (%s)"):format(g.id, g.n, table.concat(g.tabs, ", ")) end
	table.sort(out)
	return table.concat(out, "; ")
end

test("1.1 the bank's gone since the last snapshot: a tab emptied between visits shows, a visit later when it was not on screen", function()
	WithThrone(function(w, K)
		local B = ns.Bank
		WithBankWorld(function(bank)
			AsTreasurer()
			ns.rdb.bank, ns.rdb.bankPrev = nil, nil
			-- The first visit: Potions holds 5 Healing Potions and 20 Minor ones; the bank opens on Mats.
			bank.slots = { [1] = { [1] = { 200, 2589 } }, [2] = { [1] = { 5, 929 }, [2] = { 20, 118 } } }
			bank.Visit()
			eq(GoneList(ns.rdb.bank), "")
			-- Someone empties Potions. The next visit opens on Mats again: its empty read is kept
			-- (0.9.1: a tab whose slots never arrived reads empty too), nothing listed yet.
			w.clock = w.clock + 3600
			bank.slots[2] = {}
			bank.Visit()
			eq(ns.rdb.bank.tabs[2].kept ~= nil, true, "kept from the visit before")
			eq(GoneList(ns.rdb.bank), "", "not known yet")
			-- Read empty again a visit later: gone, listed (before: never, the tab kept before was skipped).
			w.clock = w.clock + 3600
			bank.Visit()
			eq(#ns.rdb.bank.tabs[2].items, 0)
			eq(GoneList(ns.rdb.bank), "118 -20 (Potions); 929 -5 (Potions)")
			-- Once: the visit after compares two empty reads.
			w.clock = w.clock + 3600
			bank.Visit()
			eq(GoneList(ns.rdb.bank), "")
			-- On screen, the emptied tab shows at once (the game loaded it).
			bank.slots[2] = { [1] = { 5, 929 } }
			w.clock = w.clock + 3600
			bank.Visit()
			w.clock = w.clock + 3600
			bank.slots[2], bank.shown = {}, 2
			bank.Visit()
			eq(GoneList(ns.rdb.bank), "929 -5 (Potions)")
		end)
	end)
end)

test("1.1 the bank's gone since the last snapshot: a tab that never loaded, with nothing earlier to keep it from, is not sent empty", function()
	WithThrone(function(w, K)
		local B = ns.Bank
		local savedRank = ns.Roster.RankOf
		local ok, err = pcall(function()
			ns.Roster.RankOf = function(n) if ns.FullName(n) == "Pyralis Ashandar-Realm" then return 1 end return savedRank(n) end
			WithBankWorld(function(bank)
				-- The Treasurer after a wipe of his saved variables (or a keeper just named): no
				-- snapshot of his own. He opens the bank on Mats; Potions' slots never arrive.
				AsTreasurer()
				ns.rdb.bank, ns.rdb.bankPrev, ns.rdb.bankReport, ns.rdb.bankReportPrev = nil, nil, nil, nil
				bank.slots = { [1] = { [1] = { 200, 2589 } }, [2] = { [1] = { 5, 929 }, [2] = { 20, 118 } } }
				bank.loaded[2] = false
				bank.Visit()
				local msg = B.Message(ns.rdb.bank)
				eq(msg, ("T9~Olympus~%d~5000~Mats;2589x200"):format(w.clock), "Potions left out, not sent empty")
				eq(#ns.rdb.bank.tabs, 2, "his own screen still draws it (empty)")
				-- The King's client held the Treasurer's snapshot of an hour before: nothing listed gone.
				AsKing()
				local saved = { bank = ns.rdb.bank }
				ns.rdb.bank = nil
				B.HandleReport("CHANNEL", "Pyralis Ashandar-Realm", ("T9~Olympus~%d~5000~Mats;2589x200~Potions;929x5,118x20"):format(w.clock - 3600))
				B.HandleReport("CHANNEL", "Pyralis Ashandar-Realm", msg)
				eq(B.Current().t, w.clock, "his new snapshot")
				eq(GoneList(B.Current()), "", "a tab he did not see is no theft")
				-- His own screen, with that older report too: nothing listed either.
				AsTreasurer()
				ns.rdb.bank = saved.bank
				eq(GoneList(ns.rdb.bank), "")
				-- His next visit, the tab loaded: sent with its items.
				bank.loaded[2] = nil
				w.clock = w.clock + 3600
				bank.Visit()
				eq(B.Message(ns.rdb.bank), ("T9~Olympus~%d~5000~Mats;2589x200~Potions;929x5,118x20"):format(w.clock))
			end)
		end)
		ns.Roster.RankOf = savedRank
		if not ok then error(err, 0) end
	end)
end)

---------------------------------------------------------------------------
-- 1.1 (Konig's review of #45, item 1): the pinned line. The army's line only from the King, his
-- Stewards and Hands; a guild master pins for his own guild over GUILD, his rank read in his
-- guildmates' own rosters; takedowns stick; net-off, the chats' opt-in and block terms apply.
---------------------------------------------------------------------------

do
-- Runs fn(w, K, sent, C) on the Throne's bench (WithThrone), as the pinned line's own tests do:
-- sends recorded with their logged flag, the channel ready, the pin (and what it saved) forgotten
-- before and after, our roster put back.
local function PinBench(fn)
	WithThrone(function(w, K)
		local C = ns.Channels
		local saved = { ready = ns.Comm.ChannelReady, send = ns.Comm.Send, info = C_ChatInfo, delivered = ns.Comm.DeliveredLogged,
			byName = ns.Roster.byName, filter = ns.db.filterWords, shared = ns.rdb.filterShared, netoff = ns.rdb.netoff, chat = ns.db.addonChat }
		local sent = {}
		local ok, err = pcall(function()
			C.ResetPin()
			ns.Comm.ChannelReady = function() return true end
			ns.Comm.Send = function(dist, msg, key, urgent, logged) sent[#sent + 1] = { dist = dist, msg = msg, key = key, logged = logged } end
			fn(w, K, sent, C)
		end)
		ns.Comm.ChannelReady, ns.Comm.Send, C_ChatInfo, ns.Comm.DeliveredLogged = saved.ready, saved.send, saved.info, saved.delivered
		ns.Roster.byName, ns.db.filterWords, ns.rdb.filterShared, ns.rdb.netoff, ns.db.addonChat = saved.byName, saved.filter, saved.shared, saved.netoff, saved.chat
		if ns.Moderation.Reset then ns.Moderation.Reset(); ns.Moderation.Load() end
		C.ResetPin()
		if not ok then error(err, 0) end
	end)
end
local function FindLine(lines, text)
	for i, l in ipairs(lines) do if type(l.text) == "string" and l.text:find(text, 1, true) then return l, i end end
	return nil
end

test("1.1 pinned line (Konig's review): two characters reporting a made-up guild that names one of them its leader pin for nobody", function()
	PinBench(function(w, K, sent, C)
		local G = "Olympus Fakers"
		-- The census as two alts can write it: each reports the made-up guild, naming the first its leader.
		ns.rdb.guilds[G] = Vouched({ total = 12, online = 2, zones = {}, t = w.clock, leader = "Alt1", realm = "Realm" }, "Alt1-Realm", "Alt2-Realm")
		AsSoldier()
		local level, verified, rankIndex = C.VerifiedLevel("Alt1-Realm", G)
		eq(level, 3, "the census makes him one of its Lords"); eq(verified, true); eq(rankIndex, 0)
		-- His pin for the army: dropped on every client outside that guild, whatever the census says.
		eq(select(2, C.HandlePin("CHANNEL", "Alt1-Realm", ("N1~7~%s~7200~0~Free gold at the bank, whisper me"):format(G))), "rank")
		eq(C.Pin(), nil)
		-- Over GUILD it reaches his own guild alone: nobody else's client takes it.
		eq(select(2, C.HandlePin("GUILD", "Alt1-Realm", ("N1~8~%s~7200~0~Free gold"):format(G))), "rank")
		eq(C.Pin(), nil)
		eq(FindLine(ns.Views.Build("realm"), "Free gold"), nil, "nothing on the Realm")
	end)
end)

test("1.1 pinned line (Konig's review): a guild master's pin is his guild's, read in its members' own rosters: demoted there, he pins for nobody", function()
	PinBench(function(w, K, sent, C)
		-- The census still names Zed the leader of <Olympus Zeus> (two reports vouch for it).
		GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
		ns.me = "Mate-Realm"
		ns.Roster.byName = { ["Zed-Realm"] = 0, ["Mate-Realm"] = 3 }
		eq(C.HandlePin("GUILD", "Zed-Realm", "N1~5~Olympus Zeus~7200~0~Raid at nine"), true)
		eq(C.Pin().rank, C.PIN_LORD)
		eq(C.Pin().dist, "GUILD")
		-- The server's roster moves the guild to another master: Zed's next pin is dropped here.
		C.ResetPin()
		ns.Roster.byName = { ["Zed-Realm"] = 2, ["Nova-Realm"] = 0, ["Mate-Realm"] = 3 }
		eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~6~Olympus Zeus~7200~0~Raid at ten")), "rank")
		eq(C.HandlePin("GUILD", "Nova-Realm", "N1~9~Olympus Zeus~7200~0~Raid at ten"), true)
		-- Never the channel's: the guild master's line on the channel is nobody's (not even his own guild's).
		C.ResetPin()
		eq(select(2, C.HandlePin("CHANNEL", "Nova-Realm", "N1~9~Olympus Zeus~7200~0~Raid at ten")), "rank")
		-- His own client: the pin goes over GUILD, its takedown too; the King's and his Crown's on the channel.
		GetGuildInfo = function() return "Olympus Zeus", "Guild Master", 0 end
		ns.me = "Nova-Realm"
		eq(C.PinScope(), "guild")
		eq(C.SetPin("Raid at ten"), true)
		eq(sent[#sent].dist, "GUILD")
		eq(C.TakeDownPin(), true)
		eq(sent[#sent].dist, "GUILD"); assert(sent[#sent].msg:find("^N1~%d+~Olympus Zeus~0~0~$"), sent[#sent].msg)
		AsKing()
		eq(C.PinScope(), "army")
		w.clock = w.clock + C.PIN_GAP
		eq(C.SetPin("Muster at the gates"), true)
		eq(sent[#sent].dist, "CHANNEL"); assert(sent[#sent].msg:find("^N1~%d+~Olympus~7200~0~Muster at the gates$"), sent[#sent].msg)
	end)
end)

test("1.1 pinned line (Konig's review): a client without N1 (1.0, 0.9.8) drops a guild master's pin over GUILD unread", function()
	local savedChannel = GetChannelName
	local ok, err = pcall(function()
		GetChannelName = function() return 5 end
		for _, old in ipairs({ false, true }) do
			local cns, Deliver = FreshComm(old)
			cns.Comm.JoinChannel()
			local captured
			local savedCapture = ns.CaptureError
			ns.CaptureError = function(where, e) captured = where .. ": " .. tostring(e) end
			Deliver("GUILD", "Zed-Realm", "N1~5~Olympus Zeus~7200~0~Raid moves to Stranglethorn")
			Deliver("GUILD", "Zed-Realm", "N1~5~Olympus Zeus~0~0~")
			ns.CaptureError = savedCapture
			eq(captured, nil, "no error")
		end
	end)
	GetChannelName, C_ChatInfo = savedChannel, nil
	if not ok then error(err, 0) end
end)

test("1.1 pinned line (Konig's review): the guild master's lines in both languages", function()
	local pt = { L = setmetatable({}, { __index = ns.L }) }
	local savedLocale = GetLocale
	GetLocale = function() return "ptBR" end
	local ok, err = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
	GetLocale = savedLocale
	if not ok then error(err, 0) end
	for _, k in ipairs({ "PIN_ADD_GUILD", "PIN_ADD_GUILD_TIP", "PIN_DONE_GUILD", "PIN_ONLY", "PIN_USAGE", "HELP_PIN", "PIN_ASK" }) do
		assert(rawget(ns.L, k) and rawget(ns.L, k) ~= k, "English: " .. k)
		assert(rawget(pt.L, k) and rawget(pt.L, k) ~= rawget(ns.L, k), "pt-BR: " .. k)
	end
	eq(select(2, ns.L.PIN_DONE_GUILD:gsub("%%s", "")), 1)
	eq(select(2, pt.L.PIN_DONE_GUILD:gsub("%%s", "")), 1)
	assert(ns.L.PIN_ONLY:find("guild", 1, true), "who pins for a guild")
end)

test("1.1 pinned line (Konig's review): a takedown sticks: a late repeat, or a setter's client that missed it, never brings the pin back, a /reload later too", function()
	PinBench(function(w, K, sent, C)
		K.HandleCommand("CHANNEL", "Asmongold Asmongler-Realm", "T1~H~5~Olympus~Helper-Realm")
		-- Zed, guild master of <Olympus Zeus>, pins for his guild.
		AsLord()
		eq(C.SetPin("Raid at nine in Ashenvale"), true)
		local first = sent[#sent].msg
		local id = first:match("^N1~(%d+)~")
		-- A guildmate's client shows it; a Hand of that guild takes it down.
		GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
		ns.me = "Mate-Realm"
		ns.Roster.byName = { ["Zed-Realm"] = 0, ["Mate-Realm"] = 3, ["Helper-Realm"] = 3 }
		C.ResetPin()
		eq(C.HandlePin("GUILD", "Zed-Realm", first), true)
		w.clock = w.clock + 60
		eq(select(2, C.HandlePin("CHANNEL", "Helper-Realm", ("N1~%s~Olympus~0~0~"):format(id))), "down")
		eq(C.Pin(), nil)
		-- Zed's client missed it and repeats his pin five minutes on: not taken again.
		w.clock = w.clock + C.PIN_RESEND
		local again = ("N1~%s~Olympus Zeus~%d~%d~Raid at nine in Ashenvale"):format(id, 7200 - C.PIN_RESEND - 60, C.PIN_RESEND + 60)
		eq(select(2, C.HandlePin("GUILD", "Zed-Realm", again)), "downed")
		eq(C.Pin(), nil)
		eq(FindLine(ns.Views.Build("realm"), "Raid at nine"), nil, "not back on the Realm")
		-- After a /reload of the guildmate's client: still remembered.
		C.ResetPin(true)
		C.RestorePin()
		eq(select(2, C.HandlePin("GUILD", "Zed-Realm", again)), "downed")
		eq(C.Pin(), nil)
		-- A new pin of his (another id) is taken.
		eq(C.HandlePin("GUILD", "Zed-Realm", "N1~777~Olympus Zeus~7200~0~Raid at ten instead"), true)
		-- His own takedown, then a repeat of it that comes late: not taken again either.
		w.clock = w.clock + 5
		eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~777~Olympus Zeus~0~0~")), "down")
		eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~777~Olympus Zeus~7195~5~Raid at ten instead")), "downed")
		eq(C.Pin(), nil)
		-- A takedown of a pin this client never held (it logged in between) is remembered too.
		eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~778~Olympus Zeus~0~0~")), "nothing")
		eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~778~Olympus Zeus~7000~200~An older line")), "downed")
		-- Remembered for PIN_TIME: then a pin of that id is anyone's again.
		w.clock = w.clock + C.PIN_TIME + 1
		eq(C.HandlePin("GUILD", "Zed-Realm", "N1~778~Olympus Zeus~7200~0~A new line"), true)
	end)
end)

test("1.1 pinned line (Konig's review): the client that took a pin down says so again when its setter's client repeats it, so the setter lets it go", function()
	PinBench(function(w, K, sent, C)
		K.HandleCommand("CHANNEL", "Asmongold Asmongler-Realm", "T1~H~5~Olympus~Helper-Realm")
		-- The Hand's client (a member of <Olympus Zeus>) takes Zed's pin down.
		GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
		ns.me = "Helper-Realm"
		ns.Roster.byName = { ["Zed-Realm"] = 0, ["Helper-Realm"] = 3 }
		eq(C.HandlePin("GUILD", "Zed-Realm", "N1~42~Olympus Zeus~7200~0~Raid at nine"), true)
		eq(C.TakeDownPin(), true)
		eq(#sent, 1); eq(sent[1].msg, "N1~42~Olympus~0~0~"); eq(sent[1].dist, "GUILD", "where his pin went")
		-- Zed's repeat, within the minute: not shown, and not answered yet (a takedown a minute at most).
		w.clock = w.clock + 30
		eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~42~Olympus Zeus~7170~30~Raid at nine")), "downed")
		eq(#sent, 1)
		-- Later: answered once, named by its id, over GUILD (where the repeat came from); not again within the minute.
		w.clock = w.clock + C.PIN_RESEND
		eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~42~Olympus Zeus~6870~330~Raid at nine")), "downed")
		eq(#sent, 2); eq(sent[2].msg, "N1~42~Olympus~0~0~"); eq(sent[2].dist, "GUILD"); eq(sent[2].logged, true)
		eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~42~Olympus Zeus~6869~331~Raid at nine")), "downed")
		eq(#sent, 2)
		eq(C.Pin(), nil)
		-- Zed's own client, which had missed the first: the takedown said again reaches it, and it stops.
		local down = sent[2].msg
		AsLord()
		C.ResetPin()
		eq(C.SetPin("Raid at nine"), true)
		local mine = C.Pin()
		local id = sent[#sent].msg:match("^N1~(%d+)~")
		down = down:gsub("^N1~%d+~", "N1~" .. id .. "~")
		w.clock = w.clock + 60
		eq(select(2, C.HandlePin("GUILD", "Helper-Realm", down)), "down")
		eq(C.Pin(), nil)
		eq(ns.rdb.pinMine, nil, "no longer kept for a /reload")
		local before = #sent
		w.clock = w.clock + C.PIN_RESEND
		eq(C.RepeatPin(), false)
		eq(#sent, before, "never repeated again")
		eq(mine.text, "Raid at nine")
	end)
end)

test("1.1 pinned line (Konig's review): the setter's pin survives his /reload, still his to repeat and take down", function()
	PinBench(function(w, K, sent, C)
		AsKing()
		eq(C.SetPin("Muster at the gates at nine"), true)
		local id = sent[1].msg:match("^N1~(%d+)~Olympus~")
		assert(id, sent[1].msg)
		-- A /reload: what Lua held is gone, what the SavedVariables hold stays.
		w.clock = w.clock + 100
		C.ResetPin(true)
		eq(C.Pin(), nil)
		eq(C.RestorePin(), true)
		local p = C.Pin()
		assert(p and p.mine, "ours again")
		eq(tostring(p.id), id); eq(p.text, "Muster at the gates at nine"); eq(p.dist, "CHANNEL"); eq(p.rank, C.PIN_KING)
		-- Repeated for late logins, as before the /reload: its time left and its age.
		w.clock = w.clock + C.PIN_RESEND
		eq(C.RepeatPin(), true)
		eq(sent[#sent].msg, ("N1~%s~Olympus~%d~%d~Muster at the gates at nine"):format(id, 7200 - 100 - C.PIN_RESEND, 100 + C.PIN_RESEND))
		-- And taken down by its setter: the same pin, for everyone.
		eq(C.TakeDownPin(), true)
		eq(sent[#sent].msg, ("N1~%s~Olympus~0~0~"):format(id))
		eq(ns.rdb.pinMine, nil)
		C.ResetPin(true)
		eq(C.RestorePin(), false, "nothing left to restore")
		-- Another character of the account (ns.rdb is the realm group's) never takes it as his.
		eq(C.SetPin("Muster again"), true)
		C.ResetPin(true)
		AsLord()
		eq(C.RestorePin(), false)
		eq(C.Pin(), nil)
		-- Saved variables edited, or its time over: not restored.
		AsKing()
		C.ResetPin(true)
		ns.rdb.pinMine["Asmongold Asmongler-Realm"].text = "|~|"
		eq(C.RestorePin(), false, "no words left once cleaned")
		ns.rdb.pinMine = { ["Asmongold Asmongler-Realm"] = { id = 5, guild = "Olympus", text = "Old line", rank = 3, dist = "CHANNEL", setAt = w.clock - 7300, expires = w.clock - 100 } }
		eq(C.RestorePin(), false, "over")
		ns.rdb.pinMine = { ["Asmongold Asmongler-Realm"] = { id = 5, guild = "Olympus", text = "Old line", rank = 3, dist = "WHISPER", setAt = w.clock, expires = w.clock + 100 } }
		eq(C.RestorePin(), false, "nowhere a pin goes")
		ns.rdb.pinMine = { ["Asmongold Asmongler-Realm"] = { id = 5, guild = "Olympus", text = "Old line", rank = 3, dist = "CHANNEL", setAt = w.clock, expires = w.clock + 99999 } }
		eq(C.RestorePin(), false, "longer than a pin lasts")
		eq(C.Pin(), nil)
		-- Whoever may no longer pin as he did repeats nothing (a Hand the King took off his list).
		K.HandleCommand("CHANNEL", "Asmongold Asmongler-Realm", "T1~H~5~Olympus~Helper-Realm")
		GetGuildInfo = function() return "Olympus II", "Member", 3 end
		ns.me = "Helper-Realm"
		w.clock = w.clock + C.PIN_GAP
		eq(C.SetPin("A Hand's line"), true)
		local n = #sent
		K.HandleCommand("CHANNEL", "Asmongold Asmongler-Realm", "T1~H~6~Olympus~")
		w.clock = w.clock + C.PIN_RESEND
		eq(C.RepeatPin(), false)
		eq(#sent, n)
	end)
end)

test("1.1 pinned line (Konig's review): the pins taken down a client remembers are bounded, the lapsed ones dropped at login", function()
	PinBench(function(w, K, sent, C)
		local keep = C.PIN_DOWN_KEEP
		local ok, err = pcall(function()
			C.PIN_DOWN_KEEP = 3
			GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
			ns.me = "Mate-Realm"
			ns.Roster.byName = { ["Zed-Realm"] = 0, ["Mate-Realm"] = 3 }
			-- (A minute apart: a takedown of a pin never held here is remembered once a minute at most
			-- from each sender, Konig's review of the fixes.)
			for i = 1, 6 do
				w.clock = w.clock + C.PIN_GAP
				C.HandlePin("GUILD", "Zed-Realm", ("N1~%d~Olympus Zeus~0~0~"):format(i))
			end
			local n = 0
			for _ in pairs(ns.rdb.pinsDown) do n = n + 1 end
			eq(n, 3)
			eq(ns.rdb.pinsDown["zed-realm#6"] ~= nil, true, "the newest kept")
			eq(ns.rdb.pinsDown["zed-realm#1"], nil, "the oldest gone")
			-- Saved, then edited or lapsed: gone at login.
			ns.rdb.pinsDown["x#1"] = "junk"
			ns.rdb.pinsDown["x#2"] = { t = w.clock + 10 * C.PIN_TIME }
			C.ResetPin(true)
			w.clock = w.clock + C.PIN_TIME - 1
			C.RestorePin()
			eq(ns.rdb.pinsDown["x#1"], nil); eq(ns.rdb.pinsDown["x#2"], nil)
			eq(ns.rdb.pinsDown["zed-realm#4"], nil, "lapsed"); eq(ns.rdb.pinsDown["zed-realm#5"], nil, "lapsed")
			eq(ns.rdb.pinsDown["zed-realm#6"] ~= nil, true)
		end)
		C.PIN_DOWN_KEEP = keep
		if not ok then error(err, 0) end
	end)
end)

test("1.1 pinned line (Konig's review): net-off hides a pin and stops its setter: none shown from a name or guild the moderators took off, none sent by one", function()
	PinBench(function(w, K, sent, C)
		local M, L = ns.Moderation, ns.L
		local KING = "Asmongold Asmongler-Realm"
		local function Word(kind, off, name)
			w.clock = w.clock + 10
			M.Handle("CHANNEL", KING, ("O1~%s~%s~%d~%s~%s~%s"):format(kind, off and "1" or "0", w.clock, name, KING, off and "spam" or ""))
		end
		C_ChatInfo = nil
		ns.rdb.netoff = nil
		M.Reset()
		K.HandleCommand("CHANNEL", KING, "T1~H~5~Olympus~Helper-Realm")
		-- A Hand pins for the army.
		GetGuildInfo = function() return "Olympus II", "Member", 3 end
		ns.me = "Helper-Realm"
		eq(C.SetPin("Gold for sale, whisper me"), true)
		local msg = sent[#sent].msg
		-- A soldier's client shows it; then the King takes the Hand off: the line leaves at once.
		AsSoldier()
		C.ResetPin()
		eq(C.HandlePin("CHANNEL", "Helper-Realm", msg), true)
		assert(FindLine(ns.Views.Build("realm"), "Gold for sale"), "shown")
		Word("c", true, "Helper-Realm")
		assert(M.Hidden("Helper-Realm"), "hidden")
		eq(C.Pin(), nil)
		eq(FindLine(ns.Views.Build("realm"), "Gold for sale"), nil, "gone from the Realm (and from the Chat tab, whose strip is Channels.Pin)")
		w.printed = {}
		SlashCmdList.OLYMPUS("pin")
		eq(Printed(w, "Gold for sale"), false, "/oly pin shows nothing of it")
		assert(C.PinStatus():find("not shown here", 1, true), C.PinStatus())
		-- Nothing new of his is taken.
		w.clock = w.clock + 60
		eq(select(2, C.HandlePin("CHANNEL", "Helper-Realm", "N1~12~Olympus~7200~0~More gold")), "netoff")
		eq(C.Pin(), nil)
		-- On a guild's client that held it: its guild master's pin (a lower rank) takes the hidden
		-- line's place; the hidden Hand takes nobody's pin down.
		GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
		ns.me = "Mate-Realm"
		ns.Roster.byName = { ["Zed-Realm"] = 0, ["Mate-Realm"] = 3 }
		eq(C.HandlePin("GUILD", "Zed-Realm", "N1~21~Olympus Zeus~7200~0~Raid at nine"), true)
		eq(C.Pin().text, "Raid at nine")
		eq(select(2, C.HandlePin("CHANNEL", "Helper-Realm", "N1~21~Olympus~0~0~")), "netoff", "no takedown from him")
		eq(C.Pin().text, "Raid at nine")
		-- The Hand's own client: back on, he pins; off again, no pin leaves, his own is not
		-- repeated, and he can still take it down.
		GetGuildInfo = function() return "Olympus II", "Member", 3 end
		ns.me = "Helper-Realm"
		C.ResetPin()
		Word("c", false, "Helper-Realm")
		eq(M.SelfOff(), nil)
		eq(C.SetPin("Muster at the gates"), true)
		Word("c", true, "Helper-Realm")
		local off = M.SelfOff()
		assert(off, "he is off")
		local before = #sent
		w.clock = w.clock + C.PIN_GAP
		w.printed = {}
		eq(select(2, C.SetPin("Muster again")), "netoff")
		assert(Printed(w, M.YouText(off)), "told why")
		w.clock = w.clock + C.PIN_RESEND
		eq(C.RepeatPin(), false)
		eq(#sent, before, "nothing sent")
		eq(C.TakeDownPin(), true, "his own, taken down all the same")
		eq(#sent, before + 1); assert(sent[#sent].msg:find("^N1~%d+~Olympus~0~0~$"), sent[#sent].msg)
		-- A guild the moderators took off: its master's pin hidden on his guildmates' clients, and none
		-- leaves his own.
		GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
		ns.me = "Mate-Realm"
		C.ResetPin()
		eq(C.HandlePin("GUILD", "Zed-Realm", "N1~22~Olympus Zeus~7200~0~Raid at ten"), true)
		Word("g", true, "Olympus Zeus")
		eq(C.Pin(), nil, "hidden with his guild")
		w.clock = w.clock + 60
		eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~23~Olympus Zeus~7200~0~Raid at eleven")), "netoff")
		AsLord()
		C.ResetPin()
		assert(M.SelfOff(), "his guild is off")
		eq(select(2, C.SetPin("Raid at eleven")), "netoff")
		-- Back on: his pins show again.
		Word("g", false, "Olympus Zeus")
		GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
		ns.me = "Mate-Realm"
		w.clock = w.clock + 60
		eq(C.HandlePin("GUILD", "Zed-Realm", "N1~24~Olympus Zeus~7200~0~Raid at midnight"), true)
		eq(C.Pin().text, "Raid at midnight")
	end)
end)

test("1.1 pinned line (Konig's review): a client whose Olympus chats are off shows no pin and sends none; its setter's takedown still goes", function()
	PinBench(function(w, K, sent, C)
		local L = ns.L
		local asked
		local savedAsk = ns.Consent.Ask
		local ok, err = pcall(function()
			ns.Consent.Ask = function(what) asked = what end
			-- A soldier who said no: the King's pin is not taken, not shown, not said in chat.
			AsSoldier()
			ns.db.addonChat = false
			w.printed = {}
			eq(select(2, C.HandlePin("CHANNEL", "Asmongold Asmongler-Realm", "N1~5~Olympus~7200~0~Muster at the gates")), "off")
			eq(C.Pin(), nil)
			eq(FindLine(ns.Views.Build("realm"), "Muster at the gates"), nil)
			eq(Printed(w, "Muster at the gates"), false, "no chat line")
			-- Said yes: shown. Turned off later: gone from the screen; on again: back while it lasts.
			ns.db.addonChat = true
			eq(C.HandlePin("CHANNEL", "Asmongold Asmongler-Realm", "N1~5~Olympus~7200~0~Muster at the gates"), true)
			assert(FindLine(ns.Views.Build("realm"), "Muster at the gates"))
			ns.db.addonChat = false
			eq(C.Pin(), nil)
			eq(FindLine(ns.Views.Build("realm"), "Muster at the gates"), nil)
			ns.db.addonChat = true
			assert(C.Pin(), "back")
			-- A takedown while the chats are off: taken (a takedown only removes), without a line in chat.
			ns.db.addonChat = false
			w.printed = {}
			eq(select(2, C.HandlePin("CHANNEL", "Asmongold Asmongler-Realm", "N1~5~Olympus~0~0~")), "down")
			eq(#w.printed, 0)
			ns.db.addonChat = true
			eq(C.Pin(), nil)
			-- The King with his chats off: no pin leaves; never answered, the first-open page asks.
			AsKing()
			C.ResetPin()
			ns.db.addonChat = false
			w.printed = {}
			eq(select(2, C.SetPin("Muster at the gates")), "off")
			assert(Printed(w, L.CHAT_OFF), "told")
			ns.db.addonChat = nil
			eq(select(2, C.SetPin("Muster at the gates")), "off")
			assert(Printed(w, L.CHAT_OFF_UNANSWERED), "told"); eq(asked, "chat")
			eq(#sent, 0, "nothing sent")
			-- Pinned while on, then the chats turned off: not repeated, but its setter still takes it down.
			ns.db.addonChat = true
			eq(C.SetPin("Muster at the gates"), true)
			ns.db.addonChat = false
			w.clock = w.clock + C.PIN_RESEND
			eq(C.RepeatPin(), false)
			eq(#sent, 1)
			eq(C.CanTakeDown(), true)
			eq(C.TakeDownPin(), true)
			eq(#sent, 2); assert(sent[2].msg:find("^N1~%d+~Olympus~0~0~$"), sent[2].msg)
		end)
		ns.Consent.Ask = savedAsk
		if not ok then error(err, 0) end
	end)
end)

test("1.1 pinned line (Konig's review): the player's block terms hide a pin's words like other addon text, until a click shows them", function()
	PinBench(function(w, K, sent, C)
		local L = ns.L
		ns.db.filterWords, ns.rdb.filterShared = { gold = true }, nil
		K.HandleCommand("CHANNEL", "Asmongold Asmongler-Realm", "T1~H~5~Olympus~Helper-Realm")
		AsSoldier()
		w.printed = {}
		eq(C.HandlePin("CHANNEL", "Helper-Realm", "N1~5~Olympus~7200~0~Cheap gold, whisper me"), true)
		-- Its chat line: who pinned it, not the words.
		assert(Printed(w, L.PIN_NEW:format("Helper", "Olympus", L.FILTER_WORDS_HIDDEN_SHORT)), "the chat line, veiled")
		eq(Printed(w, "Cheap gold"), false)
		-- On the Realm: veiled, and its tooltip too; a click shows the words.
		local line = FindLine(ns.Views.Build("realm"), L.PIN_LABEL)
		assert(line, "the line is there")
		eq(line.text:find("Cheap gold", 1, true), nil)
		assert(line.text:find(L.FILTER_WORDS_HIDDEN, 1, true), line.text)
		local tips = {}
		line.tooltip({ AddLine = function(_, t) tips[#tips + 1] = t end })
		eq(table.concat(tips, "\n"):find("Cheap gold", 1, true), nil, "the tooltip keeps them hidden")
		-- /oly pin: veiled too.
		w.printed = {}
		SlashCmdList.OLYMPUS("pin")
		eq(Printed(w, "Cheap gold"), false)
		assert(Printed(w, L.FILTER_WORDS_HIDDEN_SHORT))
		assert(line.onClick, "a click shows them")
		line.onClick()
		line = FindLine(ns.Views.Build("realm"), "Cheap gold, whisper me")
		assert(line, "shown after the click")
		-- A pin without the word shows as ever; the setter's own is never veiled on his screen.
		ns.db.filterWords = { raid = true }
		AsKing()
		C.ResetPin()
		eq(C.SetPin("Raid at nine at the gates"), true)
		assert(FindLine(ns.Views.Build("realm"), "Raid at nine at the gates"), "his own words")
	end)
end)

-- 1.1 (Konig's review of #45, the pinned line, second pass): a higher rank's takedown of a guild
-- master's pin goes where that pin went (over GUILD), so his guildmates on another realm or the
-- other channel take it too; a setter whose /reload kept nothing (the Forever beta) still takes
-- his own line down.
do
test("1.1 pinned line (Konig's review, 2): a Hand's takedown of a guild master's pin goes over GUILD, and his guildmates on another realm take it", function()
	PinBench(function(w, K, sent, C)
		local L = ns.L
		K.HandleCommand("CHANNEL", "Asmongold Asmongler-Realm", "T1~H~5~Olympus~Helper-Realm")
		GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
		ns.Roster.byName = { ["Zed-Realmtwo"] = 0, ["Helper-Realm"] = 3, ["Mate-Realmtwo"] = 3 }
		-- The Hand's client (a member of <Olympus Zeus>) takes Zed's pin down: over GUILD, where it came from.
		ns.me = "Helper-Realm"
		eq(C.HandlePin("GUILD", "Zed-Realmtwo", "N1~42~Olympus Zeus~7200~0~Raid at nine"), true)
		eq(C.TakeDownPin(), true)
		eq(#sent, 1); eq(sent[1].dist, "GUILD", "where his pin went"); eq(sent[1].msg, "N1~42~Olympus~0~0~"); eq(sent[1].logged, true)
		local down = sent[1].msg
		-- Zed's client missed it and repeats his pin: the Hand's answers where the repeat came from.
		w.clock = w.clock + C.PIN_RESEND
		eq(select(2, C.HandlePin("GUILD", "Zed-Realmtwo", "N1~42~Olympus Zeus~6900~300~Raid at nine")), "downed")
		eq(#sent, 2); eq(sent[2].dist, "GUILD"); eq(sent[2].msg, down)
		-- A guildmate on the other realm (another OlympusNet: he hears it over GUILD alone) takes it, and is told who.
		ns.me = "Mate-Realmtwo"
		C.ResetPin()
		eq(C.HandlePin("GUILD", "Zed-Realmtwo", "N1~42~Olympus Zeus~7200~0~Raid at nine"), true)
		w.clock = w.clock + 60
		w.printed = {}
		eq(select(2, C.HandlePin("GUILD", "Helper-Realm", down)), "down")
		eq(C.Pin(), nil)
		eq(FindLine(ns.Views.Build("realm"), "Raid at nine"), nil, "gone from the Realm")
		assert(Printed(w, L.PIN_DOWN_BY:format("Helper", "Olympus", ns.DisplayName("Zed-Realmtwo"))), table.concat(w.printed, "\n"))
		-- It sticks there: Zed's repeat is not taken again.
		w.clock = w.clock + C.PIN_RESEND
		eq(select(2, C.HandlePin("GUILD", "Zed-Realmtwo", "N1~42~Olympus Zeus~6840~360~Raid at nine")), "downed")
		eq(C.Pin(), nil)
		-- Zed's own client, on that other realm: it lets his line go, and repeats it no more.
		GetGuildInfo = function() return "Olympus Zeus", "Guild Master", 0 end
		ns.me = "Zed-Realmtwo"
		C.ResetPin()
		eq(C.SetPin("Raid at nine"), true)
		eq(sent[#sent].dist, "GUILD")
		local id = sent[#sent].msg:match("^N1~(%d+)~")
		w.clock = w.clock + 60
		eq(select(2, C.HandlePin("GUILD", "Helper-Realm", ("N1~%s~Olympus~0~0~"):format(id))), "down")
		eq(C.Pin(), nil); eq(ns.rdb.pinMine, nil, "no longer his to repeat")
		local n = #sent
		w.clock = w.clock + C.PIN_RESEND
		eq(C.RepeatPin(), false); eq(#sent, n, "never repeated again")
	end)
end)

test("1.1 pinned line (Konig's review, 2): over GUILD the channel's rule counts for a takedown alone; the channel's pins are still taken down on the channel", function()
	PinBench(function(w, K, sent, C)
		local KING = "Asmongold Asmongler-Realm"
		K.HandleCommand("CHANNEL", KING, "T1~H~5~Olympus~Helper-Realm")
		GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
		ns.me = "Mate-Realmtwo"
		ns.Roster.byName = { ["Zed-Realmtwo"] = 0, ["Helper-Realm"] = 3, ["Mate-Realmtwo"] = 3, ["Cap3-Realmtwo"] = 1 }
		eq(C.HandlePin("GUILD", "Zed-Realmtwo", "N1~42~Olympus Zeus~7200~0~Raid at nine"), true)
		w.clock = w.clock + 60
		-- An officer of the guild, no Hand, names it, with the King's guild or his own: refused.
		eq(select(2, C.HandlePin("GUILD", "Cap3-Realmtwo", "N1~42~Olympus~0~0~")), "rank")
		eq(select(2, C.HandlePin("GUILD", "Cap3-Realmtwo", "N1~42~Olympus Zeus~0~0~")), "rank")
		eq(C.Pin().text, "Raid at nine")
		-- A Hand's pin over GUILD is nobody's: the army's line goes on the channel.
		eq(select(2, C.HandlePin("GUILD", "Helper-Realm", "N1~50~Olympus~7200~0~A Hand's line over guild chat")), "rank")
		eq(C.Pin().text, "Raid at nine")
		-- The King's client: a Hand's pin (on the channel) taken down on the channel, its repeat answered there.
		AsKing()
		K.AddHand("Helper")
		C.ResetPin()
		eq(C.HandlePin("CHANNEL", "Helper-Realm", "N1~60~Olympus~7200~0~A Hand's line"), true)
		eq(C.TakeDownPin(), true)
		eq(sent[#sent].dist, "CHANNEL"); eq(sent[#sent].msg, "N1~60~Olympus~0~0~")
		local n = #sent
		w.clock = w.clock + C.PIN_RESEND
		eq(select(2, C.HandlePin("CHANNEL", "Helper-Realm", "N1~60~Olympus~6900~300~A Hand's line")), "downed")
		eq(#sent, n + 1); eq(sent[#sent].dist, "CHANNEL"); eq(sent[#sent].msg, "N1~60~Olympus~0~0~")
	end)
end)
test("1.1 pinned line (Konig's review, 2): after a /reload that kept nothing (the Forever beta), /oly pin off still takes the setter's line down everywhere", function()
	PinBench(function(w, K, sent, C)
		local L = ns.L
		local KING = "Asmongold Asmongler-Realm"
		-- The King pins.
		AsKing()
		eq(C.SetPin("Muster at the gates at nine"), true)
		local pinned = sent[#sent].msg
		-- A /reload on the beta: what Lua held is gone, and the saved variables never load back.
		w.clock = w.clock + 100
		C.ResetPin()
		eq(C.RestorePin(), false)
		eq(C.Pin(), nil)
		-- /oly pin off: his takedown goes all the same, where his pin went, and he is told.
		local n = #sent
		w.printed = {}
		SlashCmdList.OLYMPUS("pin off")
		eq(#sent, n + 1, "a takedown went out")
		eq(sent[#sent].dist, "CHANNEL"); eq(sent[#sent].msg, "N1~0~Olympus~0~0~"); eq(sent[#sent].logged, true)
		assert(Printed(w, L.PIN_DOWN_ANY), table.concat(w.printed, "\n"))
		eq(Printed(w, L.PIN_NONE), false)
		local blind = sent[#sent].msg
		-- Once a minute at most.
		w.clock = w.clock + 30
		eq(select(2, C.TakeDownPin()), "fast"); eq(#sent, n + 1)
		-- A soldier's client that shows his line takes it down, and his repeat, late, never brings it back.
		AsSoldier()
		C.ResetPin()
		eq(C.HandlePin("CHANNEL", KING, pinned), true)
		w.printed = {}
		eq(select(2, C.HandlePin("CHANNEL", KING, blind)), "down")
		eq(C.Pin(), nil)
		assert(Printed(w, L.PIN_DOWN_OWN:format(ns.DisplayName(KING), "Olympus")), "said who")
		eq(select(2, C.HandlePin("CHANNEL", KING, pinned)), "downed")
		eq(C.Pin(), nil)
		-- Someone else's line stays.
		K.HandleCommand("CHANNEL", KING, "T1~H~5~Olympus~Helper-Realm")
		w.clock = w.clock + 60
		eq(C.HandlePin("CHANNEL", "Helper-Realm", "N1~9~Olympus~7200~0~A Hand's line"), true)
		eq(select(2, C.HandlePin("CHANNEL", KING, blind)), "nothing")
		eq(C.Pin().text, "A Hand's line")
		-- A guild master's goes over his guild.
		AsLord()
		C.ResetPin()
		eq(C.TakeDownPin(), true)
		eq(sent[#sent].dist, "GUILD"); eq(sent[#sent].msg, "N1~0~Olympus Zeus~0~0~")
		-- Whoever may not pin sends nothing: nothing is pinned.
		AsSoldier()
		C.ResetPin()
		n = #sent
		w.printed = {}
		eq(select(2, C.TakeDownPin()), "none"); eq(#sent, n)
		assert(Printed(w, L.PIN_NONE), "told")
		-- Its line in both languages.
		local pt = { L = setmetatable({}, { __index = ns.L }) }
		local savedLocale = GetLocale
		GetLocale = function() return "ptBR" end
		local ok, err = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
		GetLocale = savedLocale
		if not ok then error(err, 0) end
		assert(rawget(ns.L, "PIN_DOWN_ANY"), "English")
		assert(rawget(pt.L, "PIN_DOWN_ANY") and rawget(pt.L, "PIN_DOWN_ANY") ~= ns.L.PIN_DOWN_ANY, "pt-BR")
	end)
end)
end -- (the pinned line's review, second pass)

end -- (the pinned line's review)
---------------------------------------------------------------------------
-- 1.1 (Konig's review of 1.1, moderation: items 2 and 5): the net-off's ranks and repeats, the
-- shared block terms, and the net-off on the 1.1 surfaces. Each test fails on the code before its
-- fix. One function (the file's top level is near Lua's 200 locals).
---------------------------------------------------------------------------
;(function()
	local M = ns.Moderation
	local KING = "Asmongold Asmongler-Realm"
	local HC = "Test Councillor-Realm" -- a made-up councillor of the test council
	local ROGUE = "Rogue Hand-Realm"   -- a made-up Hand
	-- A net-off word as an issuer's client sends it.
	local function O1(kind, off, at, name, by, reason)
		return ("O1~%s~%s~%d~%s~%s~%s"):format(kind, off and "1" or "0", at, name, by, reason or "")
	end
	-- fn with no net-off word yet and a council of one (Test Councillor); all put back after.
	local function NoWords(fn)
		local saved = { council = ns.rdb.council, netoff = ns.rdb.netoff, info = C_ChatInfo }
		local ok, err = pcall(function()
			M.Reset()
			ns.rdb.netoff = nil
			ns.rdb.council = { at = 1, names = { ["test councillor"] = "Test Councillor" } }
			fn()
		end)
		ns.rdb.council, ns.rdb.netoff, C_ChatInfo = saved.council, saved.netoff, saved.info
		M.Reset()
		if not ok then error(err, 0) end
	end
	-- The Throne's scene (WithThrone) with no word yet, the plain API, Comm.Send's logged flag kept.
	local function WithModeration(fn)
		WithThrone(function(w, K)
			NoWords(function()
				C_ChatInfo = nil
				ns.Comm.Send = function(dist, msg, key, urgent, logged)
					w.sent[#w.sent + 1] = { dist = dist, msg = msg, key = key, urgent = urgent, logged = logged }
				end
				fn(w, K)
			end)
		end)
	end
	local function Sent(w)
		local out = {}
		for _, s in ipairs(w.sent) do out[#out + 1] = s.msg end
		return table.concat(out, "\n")
	end

	test("1.1 Konig's review (item 2): no net-off word replaces one from higher up: the King's undo holds against a rogue Hand's newer word, on every client whatever came first", function()
		WithModeration(function(w, K)
			AsSoldier("Watcher")
			K.HandleCommand("CHANNEL", KING, "T1~H~1~Olympus~Rogue Hand-Realm")
			local t = w.clock
			-- The rogue Hand hides a player; the King shows him again; the rogue hides him again.
			M.Handle("CHANNEL", ROGUE, O1("c", true, t, "Victim Guy-Realm", ROGUE, "rogue"))
			assert(M.Hidden("Victim Guy-Realm"), "a Hand's word")
			M.Handle("CHANNEL", KING, O1("c", false, t + 1, "Victim Guy-Realm", KING, ""))
			eq(M.Hidden("Victim Guy-Realm"), nil, "the King's undo")
			M.Handle("CHANNEL", ROGUE, O1("c", true, t + 2, "Victim Guy-Realm", ROGUE, "edit war"))
			eq(M.Hidden("Victim Guy-Realm"), nil, "the King's word holds against a newer one")
			-- A client that heard them the other way round keeps the same word.
			M.Reset(); ns.rdb.netoff = nil
			M.Handle("CHANNEL", ROGUE, O1("c", true, t + 2, "Victim Guy-Realm", ROGUE, "edit war"))
			assert(M.Hidden("Victim Guy-Realm"))
			M.Handle("CHANNEL", KING, O1("c", false, t + 1, "Victim Guy-Realm", KING, ""))
			eq(M.Hidden("Victim Guy-Realm"), nil, "the King's word replaces a lower one whatever its date")
			-- The same the other way: the King hid him; no Hand shows him again.
			M.Handle("CHANNEL", KING, O1("c", true, t + 3, "Victim Guy-Realm", KING, "the King's word"))
			M.Handle("CHANNEL", ROGUE, O1("c", false, t + 4, "Victim Guy-Realm", ROGUE, ""))
			assert(M.Hidden("Victim Guy-Realm"), "a Hand doesn't show again one the King hid")
			-- Between words of the same rank the newest still wins.
			M.Handle("CHANNEL", ROGUE, O1("c", true, t + 5, "Other Guy-Realm", ROGUE, "spam"))
			M.Handle("CHANNEL", HC, O1("c", false, t + 6, "Other Guy-Realm", HC, ""))
			eq(M.Hidden("Other Guy-Realm"), nil, "a councillor's newer word over a Hand's")
			-- The rogue's own client: refused and said, nothing sent.
			AsSoldier("Rogue Hand")
			local sent = #w.sent
			eq(M.Set("c", "Victim Guy", false, ""), false)
			assert(Printed(w, ns.L.NETOFF_HELD_HIGHER:format("Victim Guy")), "said why")
			eq(#w.sent, sent, "nothing sent")
			-- The King's own client: his word replaces his own.
			AsKing()
			eq(M.Set("c", "Victim Guy", false, ""), true)
			eq(M.Hidden("Victim Guy-Realm"), nil)
		end)
	end)

	test("1.1 Konig's review (item 2): an issuer's client repeats only the words its own player gave: a word passed on in the King's name never goes out from his client as his own", function()
		WithModeration(function(w, K)
			AsKing()
			local t = w.clock
			-- A councillor writes a word in the King's name: the King's client takes it, passed on.
			M.Handle("CHANNEL", HC, O1("c", true, t, "Victim Guy-Realm", KING, "written in the King's name"))
			local e = M.Hidden("Victim Guy-Realm")
			assert(e, "taken"); eq(e.via, HC)
			-- And the King's own word, given on his client.
			eq(M.Set("c", "Real Spammer", true, "spam"), true)
			M.random = function() return 0 end
			local ok, err = pcall(function()
				w.sent = {}
				w.clock = w.clock + M.REPEAT + 1
				eq(M.Tick(), 1, "his own word alone")
				local all = Sent(w)
				assert(all:find("Real Spammer", 1, true), all)
				assert(not all:find("Victim Guy", 1, true), "never the word passed on in his name: " .. all)
				for _ = 1, 5 do w.clock = w.clock + M.REPEAT + 1; M.Tick() end
				assert(not Sent(w):find("Victim Guy", 1, true), "nor later")
				-- A councillor's client: his own words, never the King's he heard.
				AsSoldier("Test Councillor")
				M.Handle("CHANNEL", KING, O1("c", true, w.clock, "King Target-Realm", KING, "the King's own"))
				eq(M.Set("c", "Hc Target", true, "spam"), true)
				w.sent = {}
				w.clock = w.clock + M.REPEAT + 1
				M.Tick()
				all = Sent(w)
				assert(all:find("Hc Target", 1, true), all)
				assert(not all:find("King Target", 1, true) and not all:find("Real Spammer", 1, true) and not all:find("Victim Guy", 1, true), all)
			end)
			M.random = math.random
			if not ok then error(err, 0) end
		end)
	end)

	test("1.1 Konig's review (item 2): a Hand is known whatever the case his name is written in, so one Hand can't hide another", function()
		WithModeration(function(w, K)
			AsSoldier("Watcher")
			local t = w.clock
			-- The King typed the second Hand's name in lower case; the server spells it its own way.
			K.HandleCommand("CHANNEL", KING, "T1~H~1~Olympus~Rogue Hand-Realm,other hand-Realm")
			eq(K.IsHandName("Other Hand-Realm"), true, "his name as the server writes it")
			eq(M.IsIssuer("Other Hand-Realm"), true)
			-- The rogue aims at him, spelled any way: no word is taken on him.
			for _, spelled in ipairs({ "Other Hand-Realm", "OTHER HAND-Realm", "other hand-realm" }) do
				M.Handle("CHANNEL", ROGUE, O1("c", true, t, spelled, ROGUE, "rogue"))
			end
			eq(M.Character("Other Hand-Realm"), nil, "no word on him")
			eq(M.Hidden("Other Hand-Realm"), nil); eq(M.IsIssuer("Other Hand-Realm"), true)
			-- His own client knows he is a Hand.
			AsSoldier("Other Hand")
			eq(K.IsHand(), true)
			-- The King's own client, his list as he typed it.
			AsKing()
			K.AddHand("third hand")
			eq(K.IsHandName("Third Hand-Realm"), true)
			eq(M.Rank("THIRD HAND-Realm"), 1)
		end)
	end)

	-- fn with empty block terms (the player's own and the shared list), the shared list used, the
	-- server's clock the scene's; all put back after.
	local function NoTerms(w, fn)
		local F = ns.Filter
		local saved = { mine = ns.db.filterWords, shared = ns.rdb.filterShared, off = ns.db.filterSharedOff, st = GetServerTime,
			show = ns.Acts.ShowWrit, ui = ns.UI }
		local ok, err = pcall(function()
			ns.db.filterWords, ns.rdb.filterShared, ns.db.filterSharedOff = nil, nil, nil
			ns.Chronicle.Clear()
			F.Reset()
			GetServerTime = function() return w.clock end
			fn(F)
		end)
		ns.db.filterWords, ns.rdb.filterShared, ns.db.filterSharedOff, GetServerTime = saved.mine, saved.shared, saved.off, saved.st
		ns.Acts.ShowWrit, ns.UI = saved.show, saved.ui
		ns.Chronicle.Clear()
		F.Reset()
		if not ok then error(err, 0) end
	end

	test("1.1 Konig's review (item 2): a shared block term is 4 letters at least, and the shared list never hides the King's writs (a player's own filter still may)", function()
		WithModeration(function(w, K)
			NoTerms(w, function(F)
				local now = w.clock
				AsSoldier("Watcher")
				-- An editor's list with short common words: only the long enough one is taken.
				F.Receive("CHANNEL", HC, "BW~00000000~+the@" .. now .. ",+de@" .. now .. ",+que@" .. now .. ",+treason@" .. now)
				eq(F.Hides("the King speaks"), false, "\"the\"")
				eq(F.Hides("de nada"), false, "\"de\""); eq(F.Hides("o que foi"), false, "\"que\"")
				eq(F.Hides("treason again"), true, "a word of 4 letters or more")
				eq(#F.SharedTerms(), 1)
				-- A short word kept from an earlier session goes at login.
				ns.rdb.filterShared.the = { on = true, at = now, by = HC }
				F.OnLogin()
				eq(ns.rdb.filterShared.the, nil, "dropped at login")
				-- The editor's own client refuses it, says why and sends nothing.
				AsSoldier("Test Councillor")
				local sent = #w.sent
				eq(F.EditShared("the", true), nil)
				assert(Printed(w, ns.L.FILTER_SHARED_SHORT:format(F.SHARED_TERM_MIN)), "said why")
				eq(#w.sent, sent, "nothing sent")
				eq(F.EditShared("vendo", true), true, "a longer word")
				-- A player's own filter still takes short words: it hides lines on his screen alone.
				AsSoldier("Watcher")
				eq(F.Add("de"), true); eq(F.Hides("de nada"), true)
				ns.db.filterWords = nil
				-- The King's writ: the shared list never hides it.
				local opened = {}
				ns.Acts.ShowWrit = function(wr) opened[#opened + 1] = wr end
				ns.UI = { Refresh = function() end, RefreshSoon = function() end, ShowCopy = function() end }
				K.HandleCommand("CHANNEL", KING, "T1~W~77~Olympus~E~Treason is afoot in the south")
				local writ = ns.rdb.writs[#ns.rdb.writs]
				eq(writ.text, "Treason is afoot in the south"); eq(writ.hidden, nil, "not folded by the shared list")
				assert(Printed(w, ns.L.WRIT_ARRIVED:format(ns.KingName(KING))), "its alert")
				-- The player's own filter still folds one.
				F.Add("treason")
				w.clock = w.clock + 3600
				K.HandleCommand("CHANNEL", KING, "T1~W~78~Olympus~E~Treason once more")
				writ = ns.rdb.writs[#ns.rdb.writs]
				eq(writ.text, "Treason once more"); eq(writ.hidden, true, "folded by the player's own filter")
			end)
		end)
	end)

	-- A made-up word of lower-case letters only: "goneqab".
	local function Word(i)
		local s = ""
		repeat
			s = string.char(97 + i % 26) .. s
			i = math.floor(i / 26)
		until i == 0
		return "goneq" .. s
	end

	test("1.1 Konig's review (item 2): the shared block terms keep SHARED_KEEP entries at most, however many removals of words they never held an editor sends", function()
		WithModeration(function(w, K)
			NoTerms(w, function(F)
				AsSoldier("Watcher")
				local now = w.clock
				F.Receive("CHANNEL", HC, "BW~00000000~+treason@" .. now)
				-- Twenty-four messages of ten removals each, of words never on the list.
				for page = 1, 24 do
					local entries = {}
					for i = 1, 10 do entries[#entries + 1] = "-" .. Word(page * 100 + i) .. "@" .. now end
					local msg = "BW~00000000~" .. table.concat(entries, ",")
					assert(#msg <= 255, "one message: " .. #msg)
					F.Receive("CHANNEL", HC, msg)
				end
				local n = 0
				for _ in pairs(ns.rdb.filterShared) do n = n + 1 end
				assert(n <= F.SHARED_KEEP, "entries kept: " .. n)
				eq(F.Hides("treason again"), true, "the words it hides stay")
				-- The newest removal is kept (the oldest go first) and still stands against an older add.
				F.Receive("CHANNEL", HC, "BW~00000000~-" .. Word(9999) .. "@" .. (now + 1))
				F.Receive("CHANNEL", HC, "BW~00000000~+" .. Word(9999) .. "@" .. now)
				eq(F.Hides(Word(9999)), false, "the newest removal still stands")
				n = 0
				for _ in pairs(ns.rdb.filterShared) do n = n + 1 end
				assert(n <= F.SHARED_KEEP, "entries kept: " .. n)
			end)
		end)
	end)

	-- The King's word on a character or a guild, dated by the server's clock (the scene's own, else ns.Now).
	local function Clock() return ns.Data.ServerTime() or ns.Now() end
	local function Off(name, reason) M.Handle("CHANNEL", KING, O1("c", true, Clock(), name, KING, reason or "spam")) end
	local function Back(name) M.Handle("CHANNEL", KING, O1("c", false, Clock() + 1, name, KING, "")) end
	local function GuildOff(guild) M.Handle("CHANNEL", KING, O1("g", true, Clock(), guild, KING, "spam guild")) end

	test("1.1 Konig's review (item 5): the King's week: a Hand the moderators took off sets, cancels and signs nothing any client shows, nor does a signer; their own client sends none of it", function()
		WithWeek(function(w, W, K)
			NoWords(function()
				AsSoldier("Watcher")
				K.HandleCommand("CHANNEL", KING, "T1~H~1~Olympus~Rogue Hand-Realm,Watcher-Realm")
				-- An entry of his heard before the word, and the King's own.
				K.HandleCommand("CHANNEL", ROGUE, "T1~D~601~Olympus II~" .. (2 * 86400) .. "~1~~Before the word")
				K.HandleCommand("CHANNEL", KING, "T1~D~602~Olympus~" .. (3 * 86400) .. "~1~~Raid night")
				eq(#W.Entries(), 2)
				-- Our own entry, and a signup heard for it before any word.
				eq(W.SetEntry("Sat 20:00 Our raid"), true)
				local ours
				for _, e in ipairs(W.Entries()) do if e.mine then ours = e end end
				W.HandleSignup("WHISPER", "Spammer Guy-Realm", ("Y2~%d~T~Olympus II"):format(ours.id))
				eq(W.Counts(ours).others, 1, "counted")
				-- The King takes the rogue Hand and the spammer off.
				Off(ROGUE, "abuse of the week"); Off("Spammer Guy-Realm")
				assert(M.Hidden(ROGUE) and M.Hidden("Spammer Guy-Realm"))
				local function Titles()
					local out = {}
					for _, e in ipairs(W.Entries()) do out[#out + 1] = e.title end
					return table.concat(out, ",")
				end
				eq(Titles(), "Raid night,Our raid", "his entry heard before the word: gone")
				-- A new entry of his: dropped, no chat line.
				local printed = #w.printed
				K.HandleCommand("CHANNEL", ROGUE, "T1~D~603~Olympus II~" .. 86400 .. "~1~~After the word")
				eq(W.Entry(603), nil); eq(#w.printed, printed, "no chat line")
				-- His cancel of the King's entry: dropped.
				K.HandleCommand("CHANNEL", ROGUE, "T1~D~602~Olympus II~0~0~~")
				assert(W.Entry(602), "the King's entry stays")
				-- His sheet: dropped.
				K.HandleCommand("CHANNEL", ROGUE, "T1~R~1~Olympus II~601:5:5:5:5~5")
				eq(W.Sheets()[601], nil)
				-- The spammer's signup: gone from the counts, a new one not taken.
				eq(W.Counts(ours).others, 0, "not counted since the word")
				W.HandleSignup("WHISPER", "Spammer Guy-Realm", ("Y2~%d~H~Olympus II"):format(ours.id))
				eq(W.Counts(ours).others, 0)
				W.HandleSignup("WHISPER", "Honest Guy-Realm", ("Y2~%d~H~Olympus II"):format(ours.id))
				eq(W.Counts(ours).others, 1, "anyone else's still counts")
				-- Put back on: his entries show again as he repeats them.
				Back(ROGUE)
				K.HandleCommand("CHANNEL", ROGUE, "T1~D~603~Olympus II~" .. 86400 .. "~0~~After the word")
				assert(W.Entry(603), "back on")
				M.Handle("CHANNEL", KING, O1("c", true, Clock() + 2, ROGUE, KING, "abuse again"))
				assert(M.Hidden(ROGUE), "off again")
				-- The rogue's own client: says why, sends nothing.
				AsSoldier("Rogue Hand")
				w.clock = w.clock + W.SET_GAP + 1
				local sent = #w.sent
				eq(W.SetEntry("Sat 21:00 Rogue raid"), false)
				assert(Printed(w, M.YouText(M.SelfOff())), "said why")
				eq(W.Sign(602, "T"), false)
				eq(#w.sent, sent, "nothing sent"); eq(#w.whispered, 0, "no signup whispered")
				eq(M.Blocks("T1~D~9~Olympus II~3600~1~~Raid"), true, "an entry held back")
				eq(M.Blocks("T1~R~9~Olympus II~9:1:0:0:0~5"), true, "a sheet held back")
				eq(M.Blocks("Y2~602~T~Olympus II"), true, "a signup held back")
				eq(M.Blocks("T1~N~9~Olympus II~Someone-Realm"), false, "a list still goes")
			end)
		end)
	end)

	test("1.1 Konig's review (item 5): the Board: a poster the moderators took off (or his guild) has no flag or camp on any Board; his own client raises none and sends no G1", function()
		WithBoard(function(w, B, K)
			NoWords(function()
				AsSoldier("Watcher")
				local function Posters(slot)
					local out = {}
					for _, e in ipairs(B.List(slot)) do out[#out + 1] = e.sender end
					table.sort(out)
					return table.concat(out, ",")
				end
				-- A spammer's flag and camp, a guild's member's flag, an honest player's flag.
				B.HandlePost("CHANNEL", "Spammer Guy-Realm", Flag("a1", "Olympus Zeus", "D", 0, 1453, "buy gold"))
				B.HandlePost("CHANNEL", "Spammer Guy-Realm", Flag("c1", "Olympus Zeus", "C", 0, 1453, "gold here"))
				B.HandlePost("CHANNEL", "Gale Member-Realm", Flag("g1", "Olympus Gale", "R", 0, 1429))
				B.HandlePost("CHANNEL", "Honest Guy-Realm", Flag("h1", "Olympus Zeus", "P", 0, 1429))
				eq(Posters("flag"), "Gale Member-Realm,Honest Guy-Realm,Spammer Guy-Realm"); eq(Posters("camp"), "Spammer Guy-Realm")
				-- The King takes the spammer and the guild off: what they had leaves the Board (map badges come from it).
				Off("Spammer Guy-Realm"); GuildOff("Olympus Gale")
				eq(Posters("flag"), "Honest Guy-Realm", "their flags gone"); eq(Posters("camp"), "", "his camp gone")
				eq(B.Count("flag"), 1); eq(B.Count("camp"), 0)
				-- New ones, or their refreshes: not taken.
				w.clock = w.clock + B.NEW_ID_GAP + 1
				B.HandlePost("CHANNEL", "Spammer Guy-Realm", Flag("a2", "Olympus Zeus", "D", 0, 1453, "buy gold"))
				B.HandlePost("CHANNEL", "Spammer Guy-Realm", Flag("c1", "Olympus Zeus", "C", 1, 1453, "gold here"))
				B.HandlePost("CHANNEL", "Other Gale-Realm", Flag("g2", "Olympus Gale", "D", 0, 1429))
				eq(Posters("flag"), "Honest Guy-Realm"); eq(Posters("camp"), "")
				-- His own client: says why, raises nothing, sends no G1 (a refresh or an answer to an ask).
				AsSoldier("Spammer Guy")
				local sent = #w.sent
				local ok, why = B.Raise("D", "buy gold")
				eq(ok, false); eq(why, "netoff")
				assert(Printed(w, M.YouText(M.SelfOff())), "said why")
				w.share = true
				ok, why = B.DropCamp("gold")
				eq(ok, false); eq(why, "netoff")
				eq(#w.sent, sent, "nothing sent")
				eq(M.Blocks(Flag("a2", "Olympus Zeus", "D", 0, 1453, "buy gold")), true, "a G1 held back")
				eq(M.Blocks("G0~a2"), false, "taking his own down still goes")
				-- Put back on: his next flag shows.
				AsSoldier("Watcher")
				Back("Spammer Guy-Realm")
				B.HandlePost("CHANNEL", "Spammer Guy-Realm", Flag("a3", "Olympus Zeus", "D", 0, 1453, "sorry"))
				eq(Posters("flag"), "Honest Guy-Realm,Spammer Guy-Realm")
			end)
		end)
	end)

	-- The crafters' board as this client holds it: what goes out (w.sent: CHANNEL, w.whispers), the
	-- answers' delay (w.later, w.run), the clock; no word yet.
	local function WithCrafters(fn)
		local Cr = ns.Crafters
		local saved = { send = ns.Comm.Send, whisper = ns.Comm.Whisper, print = ns.Print, dialog = ns.ShowDialog, now = ns.Now,
			after = Cr.after, random = Cr.random, choice = ns.db.crafterChoice, data = ns.db.crafterData, me = ns.me, guild = GetGuildInfo,
			queue = ns.Comm.QueueSize, show = ns.Views.ShowPage, ui = ns.UI }
		local w = { sent = {}, whispers = {}, printed = {}, later = {}, clock = 5000000 }
		local ok, err = pcall(function()
			Cr.Reset()
			ns.db.crafterChoice, ns.db.crafterData, ns.me = nil, nil, "Tester-Realm"
			ns.Now = function() return w.clock end
			ns.Comm.Send = function(dist, msg) w.sent[#w.sent + 1] = dist .. " " .. msg end
			ns.Comm.Whisper = function(target, msg) w.whispers[#w.whispers + 1] = target .. " " .. msg end
			ns.Comm.QueueSize = function() return 0 end
			ns.Print = function(m) w.printed[#w.printed + 1] = tostring(m) end
			ns.ShowDialog = function() end
			ns.Views.ShowPage = function() end
			ns.UI = { SelectTab = function(tab) w.tab = tab end }
			Cr.after = function(_, _, f) w.later[#w.later + 1] = f end
			Cr.random = function() return 0 end
			GetGuildInfo = function(unit) if unit == nil or unit == "player" then return "Olympus II", "Member", 3 end return nil end
			w.run = function() local l = w.later; w.later = {}; for _, f in ipairs(l) do f() end end
			NoWords(function()
				C_ChatInfo = nil
				fn(w, Cr)
			end)
		end)
		ns.Comm.Send, ns.Comm.Whisper, ns.Print, ns.ShowDialog, ns.Now = saved.send, saved.whisper, saved.print, saved.dialog, saved.now
		Cr.after, Cr.random, ns.db.crafterChoice, ns.db.crafterData, ns.me = saved.after, saved.random, saved.choice, saved.data, saved.me
		GetGuildInfo, ns.Comm.QueueSize, ns.Views.ShowPage, ns.UI = saved.guild, saved.queue, saved.show, saved.ui
		Cr.Reset()
		if not ok then error(err, 0) end
	end

	test("1.1 Konig's review (item 5): the crafters: a crafter the moderators took off (or his guild) is not listed, his answers and recipe lists are not taken, and his own client sends none", function()
		WithCrafters(function(w, Cr)
			do
				local function Names()
					local out = {}
					for _, c in ipairs(Cr.Board()) do out[#out + 1] = c.name end
					return table.concat(out, ",")
				end
				Cr.HandleListing("CHANNEL", "Spammer Guy-Realm", "W1~Olympus Zeus~197:Tailoring:250:300:12")
				Cr.HandleListing("CHANNEL", "Gale Crafter-Realm", "W1~Olympus Gale~164:Blacksmithing:200:300:40")
				Cr.HandleListing("CHANNEL", "Honest Crafter-Realm", "W1~Olympus Zeus~197:Tailoring:300:300:90")
				eq(Names(), "Gale Crafter-Realm,Honest Crafter-Realm,Spammer Guy-Realm")
				-- Our ask, answered by the spammer and an honest crafter before any word.
				local ask = Cr.Ask("item:14342")
				Cr.HandleAnswer("WHISPER", "Spammer Guy-Realm", ("WA~%s~Olympus Zeus~Tailoring~250~18560:14342"):format(ask.id))
				Cr.HandleAnswer("WHISPER", "Honest Crafter-Realm", ("WA~%s~Olympus Zeus~Tailoring~300~18560:14342"):format(ask.id))
				-- The King takes the spammer and a guild off.
				Off("Spammer Guy-Realm"); GuildOff("Olympus Gale")
				eq(Names(), "Honest Crafter-Realm", "off the board")
				local page = {}
				for _, l in ipairs(Cr.Lines()) do page[#page + 1] = tostring(l.text) end
				page = table.concat(page, "\n")
				assert(page:find("Honest Crafter", 1, true) and not page:find("Spammer Guy", 1, true) and not page:find("Gale Crafter", 1, true), page)
				-- A new listing, answer or recipe list of his: not taken.
				Cr.HandleListing("CHANNEL", "Spammer Guy-Realm", "W1~Olympus Zeus~197:Tailoring:251:300:12")
				Cr.HandleListing("CHANNEL", "Other Gale-Realm", "W1~Olympus Gale~164:Blacksmithing:100:300:5")
				eq(Names(), "Honest Crafter-Realm")
				w.clock = w.clock + Cr.ASK_GAP + 1
				ask = Cr.Ask("item:14342")
				Cr.HandleAnswer("WHISPER", "Spammer Guy-Realm", ("WA~%s~Olympus Zeus~Tailoring~250~18560:14342"):format(ask.id))
				eq(ask.answers["Spammer Guy-Realm"], nil, "his answer")
				Cr.AskList("Spammer Guy-Realm", "197")
				Cr.HandleList("WHISPER", "Spammer Guy-Realm", "WL~197~1/1~18560:14342")
				eq(#(Cr.ListOf("Spammer Guy-Realm", "197") or {}), 0, "his recipe list")
				-- His own client: nothing goes out, not his listing, an answer or a recipe list.
				ns.me = "Spammer Guy-Realm"
				Cr.Mine()["197"] = { key = "197", name = "Tailoring", rank = 245, max = 300, recipes = { { r = 18560, i = 14342, n = "Mooncloth" } } }
				w.sent, w.whispers, w.later = {}, {}, {}
				Cr.Choose("197", true)
				eq(#w.sent, 0, "no listing"); assert(Printed(w, M.YouText(M.SelfOff())), "said why")
				Cr.HandleAsk("CHANNEL", "Asker-Realm", "WQ~a1~i~14342")
				Cr.HandleListAsk("WHISPER", "Asker-Realm", "WR~197")
				w.run()
				eq(#w.whispers, 0, "no answer, no recipe list")
				eq(M.Blocks("W1~Olympus II~197:Tailoring:245:300:3"), true); eq(M.Blocks("WA~a1~Olympus II~Tailoring~245~18560:14342"), true)
				eq(M.Blocks("WL~197~1/1~18560:14342"), true); eq(M.Blocks("W0~"), false, "unlisting still goes")
				-- Put back on: his listing goes at the next tick.
				Back("Spammer Guy-Realm")
				Cr.Tick()
				assert(table.concat(w.sent, "\n"):find("W1~Olympus II~197:Tailoring", 1, true), "listed again: " .. table.concat(w.sent, "\n"))
			end
		end)
	end)

	test("1.1 Konig's review (item 5): the elite borders and nameplate marks: a character or a guild the moderators took off shows as no Olympus player; back on, as before; never the King", function()
		WithNameplates(function(w)
			NoWords(function()
				C_ChatInfo = nil
				w.internal("LOGIN")
				local capt = BorderUnit("Capt", "Olympus Zeus", "Titan", 1)
				local axe = BorderUnit("Axe", "Olympus Gale", "Raider", 4)
				w.add("nameplate1", capt); w.add("nameplate2", axe); w.add("nameplate3", BORDER_KING)
				eq(w.mark("nameplate1"), "silver"); eq(w.mark("nameplate2"), "bronze"); eq(w.mark("nameplate3"), "gold")
				w.target(capt)
