			assert(type(br) == "string" and br ~= "" and br ~= en, "pt-BR " .. key)
			local function Args(s) local out = {} for a in s:gmatch("%%%a") do out[#out + 1] = a end return table.concat(out) end
			eq(Args(br), Args(en), key .. ": format arguments")
		end
	end)
end)()

---------------------------------------------------------------------------
-- 1.1 (Konig's review of the moderation fixes): no net-off word pushes one from higher up out of
-- a full list; a word on another name of a player (a linked alt, or the same name on another
-- realm of the group) doesn't hide a name whose own word stands above it; the shared block
-- terms keep the same entries on every client, whatever order it heard them in. Each test fails
-- on the code before its fix. One function (the file's top level is near Lua's 200 locals).
---------------------------------------------------------------------------
;(function()
	local M = ns.Moderation
	local KING = "Asmongold Asmongler-Realm"
	local HC = "Test Councillor-Realm" -- a made-up councillor of the test council
	local ROGUE = "Rogue Hand-Realm"   -- a made-up Hand
	-- A net-off word as an issuer's client sends it.
	local function O1(kind, off, at, name, by, reason)
		return ("O1~%s~%s~%d~%s~%s~%s"):format(kind, off and "1" or "0", at, name, by, reason or "")
	end
	-- The Throne's scene with no net-off word yet, a council of one (Test Councillor) and the plain
	-- API; the alt links, the realm names and the repeats' draw all put back after.
	local function WithModeration(fn)
		WithThrone(function(w, K)
			local saved = { council = ns.rdb.council, netoff = ns.rdb.netoff, info = C_ChatInfo, alts = ns.Alts,
				split = ns.splitNames, random = M.random }
			local ok, err = pcall(function()
				M.Reset()
				ns.rdb.netoff = nil
				ns.rdb.council = { at = 1, names = { ["test councillor"] = "Test Councillor" } }
				C_ChatInfo = nil
				fn(w, K)
			end)
			ns.rdb.council, ns.rdb.netoff, C_ChatInfo, ns.Alts = saved.council, saved.netoff, saved.info, saved.alts
			ns.splitNames, M.random = saved.split, saved.random
			M.Reset()
			if not ok then error(err, 0) end
		end)
	end
	-- A made-up name of lower-case letters: 1 "b", 26 "ba".
	local function Letters(i)
		local s = ""
		repeat
			s = string.char(97 + i % 26) .. s
			i = math.floor(i / 26)
		until i == 0
		return s
	end
	-- The rogue Hand fills the list: MAX.c words hiding made-up names (one message each, at t),
	-- then one of them shown again (at t + 1), so that his next word finds room.
	local function Flood(t)
		for i = 1, M.MAX.c do M.Handle("CHANNEL", ROGUE, O1("c", true, t, "Filler " .. Letters(i) .. "-Realm", ROGUE, "x")) end
		M.Handle("CHANNEL", ROGUE, O1("c", false, t + 1, "Filler " .. Letters(1) .. "-Realm", ROGUE, ""))
	end

	test("1.1 Konig's review (net-off, a full list): a rogue Hand who fills the list never pushes out the King's word showing a name again, so he can't hide that name again", function()
		WithModeration(function(w, K)
			AsSoldier("Watcher")
			K.HandleCommand("CHANNEL", KING, "T1~H~1~Olympus~Rogue Hand-Realm")
			local t = w.clock
			M.Handle("CHANNEL", ROGUE, O1("c", true, t, "Victim Guy-Realm", ROGUE, "rogue"))
			M.Handle("CHANNEL", KING, O1("c", false, t + 1, "Victim Guy-Realm", KING, ""))
			eq(M.Hidden("Victim Guy-Realm"), nil, "the King's undo")
			Flood(t + 2)
			local kept = ns.rdb.netoff.c["victim guy-realm"]
			assert(type(kept) == "table" and kept.off == false and kept.by == KING, "the King's word stays in the full list")
			M.Handle("CHANNEL", ROGUE, O1("c", true, t + 4, "Victim Guy-Realm", ROGUE, "edit war won"))
			eq(M.Hidden("Victim Guy-Realm"), nil, "the King's word still holds")
			-- A word as high as the one it pushes out still finds room: the rogue's own "on" word goes.
			M.Handle("CHANNEL", ROGUE, O1("c", true, t + 5, "Late Spammer-Realm", ROGUE, "spam"))
			assert(M.Hidden("Late Spammer-Realm"), "a Hand's word takes the room of a Hand's older 'on' word")
			eq(ns.rdb.netoff.c["filler b-realm"], nil, "the rogue's 'on' word went")
			assert(ns.rdb.netoff.c["victim guy-realm"].by == KING, "the King's did not")
		end)
	end)

	test("1.1 Konig's review (net-off, a full list): on the King's own client the flood never pushes out his word showing a name again, and he goes on repeating it", function()
		WithModeration(function(w, K)
			AsKing()
			K.AddHand("Rogue Hand")
			local t = w.clock
			M.Handle("CHANNEL", ROGUE, O1("c", true, t, "Victim Guy-Realm", ROGUE, "rogue"))
			eq(M.Set("c", "Victim Guy", false, ""), true, "the King shows him again")
			Flood(t + 2)
			M.Handle("CHANNEL", ROGUE, O1("c", true, t + 4, "Victim Guy-Realm", ROGUE, "edit war won"))
			local kept = ns.rdb.netoff.c["victim guy-realm"]
			assert(type(kept) == "table" and kept.off == false and kept.by == KING, "his own word stays")
			w.sent = {}
			M.random = function() return 0 end
			for _ = 1, 40 do w.clock = w.clock + 60; M.Tick() end
			local repeated = false
			for _, s in ipairs(w.sent) do if s.msg:find("~Victim Guy-Realm~" .. KING .. "~", 1, true) then repeated = true end end
			assert(repeated, "his client repeats his word on Victim Guy")
		end)
	end)

	test("1.1 Konig's review (net-off, other names of a player): a Hand's word on the victim's linked alt, or on his name on another realm of the group, doesn't hide one the King showed again; the King's newer word there still does", function()
		WithModeration(function(w, K)
			AsSoldier("Watcher")
			K.HandleCommand("CHANNEL", KING, "T1~H~1~Olympus~Rogue Hand-Realm")
			local t = w.clock
			-- A linked alt (Alts.lua: both characters confirmed it).
			ns.Alts = { Linked = function(name)
				local key = tostring(name):lower()
				if key == "victim guy-realm" then return { "Victim Alt-Realm" } end
				if key == "victim alt-realm" then return { "Victim Guy-Realm" } end
				return {}
			end }
			M.Handle("CHANNEL", ROGUE, O1("c", true, t, "Victim Guy-Realm", ROGUE, "rogue"))
			M.Handle("CHANNEL", KING, O1("c", false, t + 1, "Victim Guy-Realm", KING, ""))
			eq(M.Hidden("Victim Guy-Realm"), nil, "the King's undo")
			M.Handle("CHANNEL", ROGUE, O1("c", true, t + 2, "Victim Alt-Realm", ROGUE, "edit war via the alt"))
			eq(M.Hidden("Victim Guy-Realm"), nil, "the King's word on his own name holds against a Hand's word on his alt")
			eq(M.Hides("Victim Guy-Realm"), nil, "his lines show")
			-- The King's own newer word on the alt still reaches him.
			M.Handle("CHANNEL", KING, O1("c", true, t + 3, "Victim Alt-Realm", KING, "the King's word"))
			local e, on = M.Hidden("Victim Guy-Realm")
			assert(e and e.by == KING, "the King's newer word on his alt hides him"); eq(on, "Victim Alt-Realm")
			-- Forever: the same name on another realm of the group is the same player.
			M.Reset(); ns.rdb.netoff = nil
			ns.Alts = { Linked = function() return {} end }
			ns.splitNames = true
			M.Handle("CHANNEL", ROGUE, O1("c", true, t, "Victim Guy-ClassicBetaPvP", ROGUE, "rogue"))
			assert(M.Hidden("Victim Guy-ClassicBetaPvP"), "a Hand's word")
			M.Handle("CHANNEL", KING, O1("c", false, t + 1, "Victim Guy-ClassicBetaPvP", KING, ""))
			eq(M.Hidden("Victim Guy-ClassicBetaPvP"), nil, "the King's undo")
			M.Handle("CHANNEL", ROGUE, O1("c", true, t + 2, "Victim Guy-ClassicBetaPvP2", ROGUE, "edit war, the group's other realm"))
			eq(M.Hidden("Victim Guy-ClassicBetaPvP"), nil, "the King's word holds whatever realm of the group the rogue names")
			eq(M.Character("Victim Guy-ClassicBetaPvP"), nil)
			-- The King's own newer word there still reaches him.
			M.Handle("CHANNEL", KING, O1("c", true, t + 3, "Victim Guy-ClassicBetaPvP2", KING, "the King's word"))
			e = M.Hidden("Victim Guy-ClassicBetaPvP")
			assert(e and e.by == KING, "the King's newer word on the group's other realm hides him")
		end)
	end)

	test("1.1 Konig's review (block terms): removals of the same second are pruned by the term, so two clients that heard them in another order keep the same list and digest, and an editor who hears his list repeated sends no more", function()
		WithThrone(function(w, K)
			local F = ns.Filter
			local saved = { mine = ns.db.filterWords, shared = ns.rdb.filterShared, off = ns.db.filterSharedOff, st = GetServerTime,
				council = ns.rdb.council, random = F.random }
			local ok, err = pcall(function()
				ns.rdb.council = { at = 1, names = { ["test councillor"] = "Test Councillor" } }
				ns.db.filterWords, ns.db.filterSharedOff = nil, nil
				GetServerTime = function() return w.clock end
				F.random = function() return 0 end
				local now = w.clock
				-- Twenty-four messages of ten removals each, all of the same second, of words never on the list.
				local pages, all = {}, {}
				for page = 1, 24 do
					local entries = {}
					for i = 1, 10 do
						local term = "goneq" .. Letters(page * 100 + i)
						all[#all + 1] = term
						entries[#entries + 1] = "-" .. term .. "@" .. now
					end
					pages[#pages + 1] = "BW~00000000~" .. table.concat(entries, ",")
				end
				local function Heard(order)
					ns.rdb.filterShared = nil; F.Reset()
					for _, i in ipairs(order) do F.Receive("CHANNEL", HC, pages[i]) end
					local keys = {}
					for term in pairs(ns.rdb.filterShared) do keys[#keys + 1] = term end
					table.sort(keys)
					return ns.rdb.filterShared, F.Digest(), table.concat(keys, ",")
				end
				local forward, backward = {}, {}
				for i = 1, #pages do forward[i] = i; backward[i] = #pages + 1 - i end
				AsSoldier("Watcher")
				local A, digestA, keysA = Heard(forward)
				local B, digestB, keysB = Heard(backward)
				assert(keysB == keysA, "the same entries, whatever order they came in")
				eq(digestB, digestA, "the same digest")
				-- Which ones: the SHARED_KEEP last by the term (the same second throughout).
				table.sort(all)
				local expected = {}
				for i = #all - F.SHARED_KEEP + 1, #all do expected[#expected + 1] = all[i] end
				assert(keysA == table.concat(expected, ","), "the removals last in alphabetical order stay")
				-- The King's client (it heard them in order) repeats its list; an editor's client that
				-- heard them the other way round takes it as its own, and sends none of its ten pages.
				AsKing()
				ns.rdb.filterShared = A
				local fromA = F.Pages()
				AsSoldier("Test Councillor")
				ns.rdb.filterShared = B; F.Reset()
				for _, pg in ipairs(fromA) do F.Receive("CHANNEL", KING, pg) end
				eq(F.Digest(), digestA, "still the same list")
				local sent = #w.sent
				eq(F.Tick(), false, "no repeat due")
				eq(#w.sent, sent, "nothing sent")
			end)
			ns.db.filterWords, ns.rdb.filterShared, ns.db.filterSharedOff, GetServerTime = saved.mine, saved.shared, saved.off, saved.st
			ns.rdb.council, F.random = saved.council, saved.random
			F.Reset()
			if not ok then error(err, 0) end
		end)
	end)

	test("1.1 Konig's review (moderation fixes): the README and the CurseForge page say a full list never loses a word from higher up, a player's other names don't undo his own name's word, and which removals the block terms keep", function()
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
			for _, must in ipairs({ "a new word waits for room, except the King's own, which always finds it, and no word ever makes room by pushing out one from higher up",
				"a word on a name he linked as an alt, or (Forever) on the same name on another realm of the group, doesn't hide him when his own name's word comes from higher up, or from as high and is newer",
				"the oldest removals going first, those of the same second in alphabetical order" }) do
				assert(doc:find(must, 1, true), path .. ": " .. must)
			end
		end
	end)
end)()
---------------------------------------------------------------------------
-- Konig's review of 1.1 (#45), guild tools: items 3 and 4 and their follow-ups.
---------------------------------------------------------------------------
do
	-- Item 3: "A pasted backup can swap an officer's channel key ... Suggest: never restore a
	-- different key, refuse retired ones, show the blocked names."
	test("1.1 Konig's review (#3): a pasted backup never sets a channel key: not a different one, not with none held, and one a newer key replaced is refused", function()
		WithThrone(function(w)
			local Bk = ns.Backup
			local saved = { key = ns.rdb.realmKey, epoch = ns.rdb.keyEpoch, retired = ns.rdb.keyRetired, join = ns.Comm.JoinChannel, sound = ns.db.sound }
			local ok, err = pcall(function()
				local joined = 0
				ns.Comm.JoinChannel = function() joined = joined + 1 end
				AsCaptain() -- (an officer: his restore took the text's key, and his client hands it to his guild)
				ns.rdb.realmKey, ns.rdb.keyEpoch, ns.rdb.keyRetired = "ourrealkey1", nil, nil
				-- "Paste this to fix your settings": a text carrying the sender's key.
				local forged = ForgedBackup({ v = 1, char = ns.me, faction = ns.faction, key = "attackerkey", settings = { sound = false } })
				local d = assert(Bk.Read(forged))
				local summary = table.concat(Bk.Summary(d), "\n")
				assert(summary:find(ns.L.BACKUP_KEY, 1, true), summary)
				Bk.Apply(d)
				eq(ns.rdb.realmKey, "ourrealkey1", "a different key: never set"); eq(joined, 0)
				eq(ns.db.sound, false, "the rest is restored")
				-- None held (the saved variables wiped): none from a text either (his officers hand it over, K0).
				ns.rdb.realmKey = nil
				Bk.Apply(Bk.Read(forged))
				eq(ns.rdb.realmKey, nil, "none held: none from a text"); eq(joined, 0)
				-- A key a newer one replaced (the leaked one): refused, and the confirm warns.
				ns.rdb.realmKey = "leakedkey1"
				ns.Keys.Take("newerkey22", w.clock, true)
				eq(ns.Keys.IsRetired("leakedkey1"), true)
				joined = 0
				d = assert(Bk.Read(ForgedBackup({ v = 1, char = ns.me, faction = ns.faction, key = "leakedkey1" })))
				summary = table.concat(Bk.Summary(d), "\n")
				assert(summary:find(ns.L.BACKUP_KEY_RETIRED, 1, true), summary)
				Bk.Apply(d)
				eq(ns.rdb.realmKey, "newerkey22", "never back to the replaced key"); eq(joined, 0)
				-- His own backup carries no key at all.
				local own = Bk.Export()
				eq(own:find("newerkey22", 1, true), nil, "not in the text"); eq(Bk.Read(own).key, nil)
			end)
			ns.rdb.realmKey, ns.rdb.keyEpoch, ns.rdb.keyRetired, ns.Comm.JoinChannel, ns.db.sound = saved.key, saved.epoch, saved.retired, saved.join, saved.sound
			if not ok then error(err, 0) end
		end)
	end)

	test("1.1 Konig's review (#3): a pasted backup's confirm names each player it would block, adds them only on its yes, 30 at most", function()
		WithThrone(function(w)
			local Bk = ns.Backup
			local saved = ns.db.blocked
			local ok, err = pcall(function()
				AsSoldier("Victim")
				ns.db.blocked = { ["pest-realm"] = true }
				local text = ForgedBackup({ v = 1, char = ns.me, faction = ns.faction,
					blocked = { ["pest-realm"] = true, ["officer one-realm"] = true, ["officer two-realm"] = true } })
				eq(Bk.Take(text), true)
				local p = w.popups[#w.popups]
				eq(p.name, "OLYMPUS_BACKUP_RESTORE")
				-- The names it would add (not the one blocked already), before anything changes.
				assert(p.a:find(ns.L.BACKUP_BLOCKED:format(2, "officer one-realm, officer two-realm"), 1, true), p.a)
				eq(ns.db.blocked["officer one-realm"], nil, "nothing added before the yes")
				StaticPopupDialogs.OLYMPUS_BACKUP_RESTORE.OnAccept(nil, p.data)
				eq(ns.db.blocked["officer one-realm"], true); eq(ns.db.blocked["officer two-realm"], true)
				-- 2000 names: the first BLOCKED_MAX by name, each named; the rest left out, and said so.
				local many = {}
				for i = 1, 2000 do many[("name%04d-realm"):format(i)] = true end
				local d = assert(Bk.Read(ForgedBackup({ v = 1, char = ns.me, faction = ns.faction, blocked = many })))
				local summary = table.concat(Bk.Summary(d), "\n")
				local names = {}
				for i = 1, Bk.BLOCKED_MAX do names[i] = ("name%04d-realm"):format(i) end
				assert(summary:find(ns.L.BACKUP_BLOCKED:format(Bk.BLOCKED_MAX, table.concat(names, ", ")), 1, true), summary)
				assert(summary:find(ns.L.BACKUP_BLOCKED_MORE:format(2000 - Bk.BLOCKED_MAX, Bk.BLOCKED_MAX), 1, true), summary)
				Bk.Apply(d)
				eq(ns.db.blocked[names[Bk.BLOCKED_MAX]], true)
				eq(ns.db.blocked[("name%04d-realm"):format(Bk.BLOCKED_MAX + 1)], nil, "not in the confirm: not added")
			end)
			ns.db.blocked = saved
			if not ok then error(err, 0) end
		end)
	end)

	-- Item 4: "Decline whispers can advertise a forged guild ... Name only the gates or our own guild."
	test("1.1 Konig's review (#4): an officer's decline whisper names only the King's gates or his own guild, never a 'most room' guild two characters made up", function()
		local R, D, L = ns.Recruit, ns.Data, ns.L
		local saved = { can = CanGuildInvite, byName = ns.Roster.byName }
		Fern.Census(function(w)
			local ok, err = pcall(function()
				R.ResetForTests()
				local now = os.time()
				ns.Acts.Gates = function() return nil end
				CanGuildInvite = function() return true end
				ns.Roster.byName = {}
				-- Two made-up characters report a made-up guild with 999 free slots, and agree.
				local fake = "R2~Olympus Fake~1~1~Fakelord~1~1~~~0,0,0,0,0,0,0~~"
				eq(D.Receive(Codec.DecodeReport(fake), "Forgera-Realm"), true)
				eq(D.Receive(Codec.DecodeReport(fake), "Forgerb-Realm"), true)
				eq(D.Dispute(ns.rdb.guilds["Olympus Fake"]), nil, "two senders agree: the census does not mark it")
				eq(R.OpenGuilds()[1].name, "Olympus Fake", "the most room")
				-- A recruit asks; the officer's Decline, sent from his own chat, names only his guild.
				eq(R.OnJoinRequest("WHISPER", "Newbie-Realm", "J3~Olympus II~12~MAGE"), true)
				eq(R.Decline(R.requests[1]), true)
				eq(#w.said, 1); eq(w.said[1].kind, "WHISPER"); eq(w.said[1].to, "Newbie")
				eq(w.said[1].text, L.JOIN_DECLINE_TEXT_PLAIN:format("Olympus II"))
				eq(w.said[1].text:find("Fake", 1, true), nil, w.said[1].text)
				-- The King's gates open on another guild: that one, named.
				ns.Acts.Gates = function() return { guild = "Olympus Zeus", at = now + 600 } end
				eq(R.DeclineText({}), L.JOIN_DECLINE_TEXT:format("Olympus II", "Olympus Zeus"))
				-- ...on ours: ours alone.
				ns.Acts.Gates = function() return { guild = "Olympus II", at = now + 600 } end
				eq(R.DeclineText({}), L.JOIN_DECLINE_TEXT_PLAIN:format("Olympus II"))
			end)
			CanGuildInvite, ns.Roster.byName = saved.can, saved.byName
			R.ResetForTests()
			if not ok then error(err, 0) end
		end)
	end)

	-- Follow-up: "patrol share default-on and not on the privacy page".
	test("1.1 Konig's review: an officer's patrol share is off until he answers, and his line on the first-open page asks him (officers only)", function()
		local I = ns.Inspect
		local saved = { share = ns.db.patrolShare, send = ns.Comm.Send, guild = GetGuildInfo, byName = ns.Roster.byName, store = ns.rdb.inspect,
			print = ns.Print, fire = ns.Fire }
		local sent, printed = {}, {}
		local ok, err = pcall(function()
			ns.rdb.inspect = nil
			I.ResetShare()
			ns.Consent.Reset()
			ns.db.patrolShare = nil
			ns.Comm.Send = function(dist, msg) sent[#sent + 1] = dist .. " " .. msg end
			ns.Print = function(m) printed[#printed + 1] = m end
			ns.Fire = function() end
			GetGuildInfo = function(unit) if unit == nil or unit == "player" then return "Olympus II", "Officer", 1 end return nil end
			ns.Roster.byName = { ["Offi-Realm"] = 1 }
			-- Never answered: his findings stay his, another officer's are not taken, nothing is asked.
			eq(I.Sharing(), false, "off until answered")
			I.Record("Bob", "Olympus Zeus", "WARRIOR", 30, nil, true)
			eq(I.FlushShare(), 0); eq(I.AskShared(), false)
			I.HandleShare("GUILD", "Offi-Realm", "U1~Eve:Olympus Hera:N:0")
			eq(I.Players()["Eve"], nil, "not taken")
			eq(#sent, 0, "nothing sent")
			-- The first-open page has his line, waiting for his answer; his Yes turns it on, his No off.
			local pending = {}
			for _, item in ipairs(ns.Consent.Pending()) do pending[item.key] = true end
			eq(pending.patrolshare, true, "asked on the first-open page")
			eq(ns.Consent.Choose("patrolshare", true), true)
			eq(ns.db.patrolShare, true); eq(I.Sharing(), true); eq(printed[#printed], ns.L.PATROLSHARE_ON)
			I.Record("Cid", "Olympus Zeus", "WARRIOR", 30, nil, true)
			eq(I.FlushShare(), 1); eq(sent[#sent], "GUILD U1~Cid:Olympus Zeus:N:0")
			ns.Consent.Choose("patrolshare", false)
			eq(I.Sharing(), false); eq(printed[#printed], ns.L.PATROLSHARE_OFF)
			-- A member (he neither sends nor keeps them) is not asked.
			GetGuildInfo = function(unit) if unit == nil or unit == "player" then return "Olympus II", "Member", 3 end return nil end
			for _, item in ipairs(ns.Consent.Items()) do eq(item.key ~= "patrolshare", true, "a member's page") end
		end)
		ns.db.patrolShare, ns.Comm.Send, GetGuildInfo, ns.Roster.byName, ns.rdb.inspect = saved.share, saved.send, saved.guild, saved.byName, saved.store
		ns.Print, ns.Fire = saved.print, saved.fire
		I.ResetShare()
		ns.Consent.Reset()
		if not ok then error(err, 0) end
		-- Both pages say so, in the privacy table and the first-open page's list.
		for _, file in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local f = assert(io.open(ROOT .. file))
			local doc = f:read("*a")
			f:close()
			assert(doc:find("and said yes (1.1: off until you answer, on the first-open page or with `/oly patrolshare on`)", 1, true), file .. ": the privacy table")
			assert(doc:find("the Olympus chats and your patrols' findings to your\nguild's officers (officers only)", 1, true), file .. ": the first-open page")
		end
	end)

	-- Follow-up: "loot notes rewritable": the writer's own note and the "by" of a points change hold
	-- for answers and pushes (XB) too, not only live (X1).
	test("1.1 Konig's review: a loot note stays its writer's and a points change its officer's, in officers' answers too", function()
		local Lt, B36 = ns.Loot, ns.Codec.Base36
		local saved = { guild = GetGuildInfo, time = GetServerTime, byName = ns.Roster.byName, loot = ns.rdb.loot, fire = ns.Fire }
		local base = 1790000000
		local function Answer(entries) return "XB~S~0~0~0~0~0~0^" .. table.concat(entries, "^") end
		local ok, err = pcall(function()
			ns.rdb.loot = nil
			Lt.Reset()
			GetGuildInfo = function(unit) if unit == nil or unit == "player" then return "Olympus II", "Member", 3 end return nil end
			GetServerTime = function() return base end
			ns.Fire = function() end
			ns.Roster.byName = { ["Offi-Realm"] = 1, ["Rival-Realm"] = 1, ["Bob-Realm"] = 3, ["Ann Smith-Realm"] = 3 }
			Lt.Book() -- (a member's session starts: from here on it hears each change as it is made)
			local old1, old2, later = B36(base - 1000), B36(base - 500), B36(base + 60)
			local function Note(key) return Lt.Book().notes[key] end
			-- Offi's note of last week, from his own answer.
			Lt.HandleBook("GUILD", "Offi-Realm", Answer({ ("N~Offi-Realm~a1~%s~%s~16830~~Ann Smith~Ann gets the belt"):format(old1, old1) }))
			eq(Note("Offi-Realm#a1").text, "Ann gets the belt")
			-- Another officer's answer puts other words in it (a newer change time): a note is written once.
			Lt.HandleBook("GUILD", "Rival-Realm", Answer({ ("N~Offi-Realm~a1~%s~%s~16830~~Bob Rival~Bob gets the belt"):format(old1, old2) }))
			eq(Note("Offi-Realm#a1").text, "Ann gets the belt", "his words stay"); eq(Note("Offi-Realm#a1").to, "Ann Smith")
			-- A new note in Offi's name made this session, in Rival's answer: it would have come from Offi, live.
			Lt.HandleBook("GUILD", "Rival-Realm", Answer({ ("N~Offi-Realm~b1~%s~%s~~~~Offi says Bob"):format(later, later) }))
			eq(Note("Offi-Realm#b1"), nil, "not in his name")
			-- A points change in Offi's name from Rival, live or in an answer made this session: refused.
			Lt.HandleLive("GUILD", "Rival-Realm", "X1~P~Bob-Realm~50~" .. later .. "~Offi-Realm")
			Lt.HandleBook("GUILD", "Rival-Realm", Answer({ "P~Bob-Realm~50~" .. later .. "~Offi-Realm" }))
			eq(Lt.Book().points["Bob-Realm"], nil, "never claimed in his name")
			-- Rival's own, in his own name: taken.
			Lt.HandleBook("GUILD", "Rival-Realm", Answer({ "P~Bob-Realm~7~" .. later .. "~Rival-Realm" }))
			eq(Lt.Book().points["Bob-Realm"].v, 7); eq(Lt.Book().points["Bob-Realm"].by, "Rival-Realm")
			-- Changes from before this session (it could have missed them) still come back in any officer's answer.
			Lt.HandleBook("GUILD", "Rival-Realm", Answer({ ("N~Offi-Realm~c1~%s~%s~~~~Last week's decision"):format(old1, old1),
				"P~Ann Smith-Realm~3~" .. old1 .. "~Offi-Realm" }))
			eq(Note("Offi-Realm#c1").text, "Last week's decision"); eq(Lt.Book().points["Ann Smith-Realm"].by, "Offi-Realm")
			-- A relay's copy that differs from its writer's (nothing tells them apart): his own copy replaces it, and holds.
			Lt.HandleBook("GUILD", "Rival-Realm", Answer({ ("N~Offi-Realm~d1~%s~%s~~~~Forged words"):format(old1, old2) }))
			Lt.HandleBook("GUILD", "Offi-Realm", Answer({ ("N~Offi-Realm~d1~%s~%s~~~~His words"):format(old1, old1) }))
			eq(Note("Offi-Realm#d1").text, "His words")
			Lt.HandleBook("GUILD", "Rival-Realm", Answer({ ("N~Offi-Realm~d1~%s~%s~~~~Forged again"):format(old1, B36(base - 10)) }))
			eq(Note("Offi-Realm#d1").text, "His words")
			-- Any officer still removes a note, and Offi's own change this session comes live, his name on it.
			Lt.HandleBook("GUILD", "Rival-Realm", Answer({ ("N~Offi-Realm~a1~%s~%s~16830~1~~"):format(old1, later) }))
			eq(Note("Offi-Realm#a1").del, true)
			Lt.HandleLive("GUILD", "Offi-Realm", "X1~P~Bob-Realm~12~" .. B36(base + 90) .. "~Offi-Realm")
			eq(Lt.Book().points["Bob-Realm"].v, 12); eq(Lt.Book().points["Bob-Realm"].by, "Offi-Realm")
		end)
		GetGuildInfo, GetServerTime, ns.Roster.byName, ns.rdb.loot, ns.Fire = saved.guild, saved.time, saved.byName, saved.loot, saved.fire
		Lt.Reset()
		if not ok then error(err, 0) end
		for _, file in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local f = assert(io.open(ROOT .. file))
			local doc = f:read("*a"):gsub("%s+", " ")
			f:close()
			-- (Konig's second round: "nobody changes its words afterwards" claimed more than the code
			-- does; the page now says what holds, and the limit: see the relayer's test below.)
			assert(doc:find("Once your addon holds a note, no other officer changes its words", 1, true), file .. ": the loot notes")
		end
	end)

	-- Follow-up: "/oly photo H-1 still there": GetChildren listed every child before the cap applied.
	test("1.1 Konig's review: /oly photo on a screen of more than PHOTO_MAX children never lists them, changes nothing, and says why", function()
		local UI = LoadUI()
		local saved = { UIParent = UIParent, combat = InCombatLockdown, print = ns.Print, me = ns.me, devThrone = ns.devThrone, UI = ns.UI }
		local printed = {}
		local ok, err = pcall(function()
			ns.UI = UI
			ns.Print = function(m) printed[#printed + 1] = m end
			InCombatLockdown = function() return false end
			local children, listed = {}, 0
			for i = 1, UI.PHOTO_MAX + 5 do children[i] = PhotoFrame("Frame" .. i, 1) end
			UIParent = { GetNumChildren = function() return #children end,
				GetChildren = function() listed = listed + 1 return unpack(children) end }
			ns.me, ns.devThrone = "Tester-Realm", { Tester = true } -- (the author's test build)
			SlashCmdList.OLYMPUS("photo")
			eq(UI.PhotoMode(), false); eq(listed, 0, "never listed")
			eq(printed[#printed], ns.L.PHOTO_TOO_MANY:format(UI.PHOTO_MAX))
			for i, f in ipairs(children) do eq(f.sets, 0, "left as it is: " .. i) end
			-- No count to go by: not listed either.
			UIParent = { GetChildren = function() listed = listed + 1 return unpack(children) end }
			SlashCmdList.OLYMPUS("photo")
			eq(UI.PhotoMode(), false); eq(listed, 0)
		end)
		UIParent, InCombatLockdown, ns.Print, ns.me, ns.devThrone, ns.UI = saved.UIParent, saved.combat, saved.print, saved.me, saved.devThrone, saved.UI
		if not ok then error(err, 0) end
	end)

	test("1.1 Konig's review (guild tools): the new lines in English and pt-BR, with the same format arguments", function()
		local savedLocale, pt = GetLocale, {}
		GetLocale = function() return "ptBR" end
		local ok, err = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
		GetLocale = savedLocale
		if not ok then error(err, 0) end
		for _, key in ipairs({ "BACKUP_KEY", "BACKUP_KEY_RETIRED", "BACKUP_BLOCKED", "BACKUP_BLOCKED_MORE", "HELP_BACKUP", "JOIN_REQUESTS_TIP",
			"CONSENT_PATROLSHARE", "CONSENT_PATROLSHARE_TEXT", "PATROLSHARE_OFF", "PHOTO_TOO_MANY" }) do
			assert(type(rawget(ns.L, key)) == "string", "English " .. key)
			assert(type(rawget(pt.L, key)) == "string" and pt.L[key] ~= ns.L[key], "Portuguese " .. key)
			eq(select(2, pt.L[key]:gsub("%%[ds]", "")), select(2, ns.L[key]:gsub("%%[ds]", "")), key)
		end
	end)
end

---------------------------------------------------------------------------
-- Konig's review of 1.1 (#45), guild tools, second round: the patrol share's ask and the loot
-- notes' relays.
---------------------------------------------------------------------------
do
	-- "Patrol share follow-up: off until answered": the login's ask (40 to 70 s in) went while he had
	-- not answered, and his yes on the first-open page (45 s in) asked nothing: no findings of the day.
	test("1.1 Konig's review: an officer who says yes after the login's ask asks for the day's findings then, once a session", function()
		local I = ns.Inspect
		local saved = { share = ns.db.patrolShare, send = ns.Comm.Send, guild = GetGuildInfo, byName = ns.Roster.byName, store = ns.rdb.inspect,
			print = ns.Print, fire = ns.Fire }
		local sent = {}
		local function Asks()
			local n = 0
			for _, m in ipairs(sent) do if m == "GUILD U0~" then n = n + 1 end end
			return n
		end
		local function Rank(rank)
			GetGuildInfo = function(unit) if unit == nil or unit == "player" then return "Olympus II", "Titan", rank end return nil end
		end
		local ok, err = pcall(function()
			ns.rdb.inspect = nil
			I.ResetShare()
			ns.Consent.Reset()
			ns.db.patrolShare = nil -- (a login on the Forever beta: never answered)
			ns.Comm.Send = function(dist, msg) sent[#sent + 1] = dist .. " " .. msg end
			ns.Print = function() end
			ns.Fire = function() end
			Rank(1)
			ns.Roster.byName = { ["Offi-Realm"] = 1 }
			-- The login's timer first, before his answer: nothing asked.
			eq(I.AskShared(), false); eq(Asks(), 0)
			-- His yes on the first-open page: the day's findings asked for then.
			eq(ns.Consent.Choose("patrolshare", true), true)
			eq(Asks(), 1, "asked once he said yes")
			-- A second yes, /oly patrolshare on, off and on again, a later timer: none more this session.
			ns.Consent.Choose("patrolshare", true)
			SlashCmdList.OLYMPUS("patrolshare on")
			ns.Consent.Choose("patrolshare", false)
			ns.Consent.Choose("patrolshare", true)
			eq(I.AskShared(), false)
			eq(Asks(), 1, "one a session")
			-- The next session: the timer asks (he said yes before), and a yes after it asks nothing more.
			I.ResetShare()
			eq(I.AskShared(), true); eq(Asks(), 2)
			SlashCmdList.OLYMPUS("patrolshare on")
			eq(Asks(), 2)
			-- Another session: /oly patrolshare alone (it only says which) and a member's yes ask nothing.
			I.ResetShare()
			SlashCmdList.OLYMPUS("patrolshare")
			eq(Asks(), 2, "not turned on")
			Rank(3)
			SlashCmdList.OLYMPUS("patrolshare on")
			eq(Asks(), 2, "not an officer")
		end)
		ns.db.patrolShare, ns.Comm.Send, GetGuildInfo, ns.Roster.byName, ns.rdb.inspect = saved.share, saved.send, saved.guild, saved.byName, saved.store
		ns.Print, ns.Fire = saved.print, saved.fire
		I.ResetShare()
		ns.Consent.Reset()
		if not ok then error(err, 0) end
		for _, file in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local f = assert(io.open(ROOT .. file))
			local doc = f:read("*a")
			f:close()
			assert(doc:find("for the day's findings once a session: after its login, or at his yes if that came later.", 1, true), file .. ": the patrol share")
			assert(doc:find("when another officer's addon asks (once a session: after its login, or at its officer's yes if later)", 1, true), file .. ": the privacy table")
		end
	end)

	-- "Loot notes follow-up: 'nobody rewrites another officer's note' in answers/replays": a note's
	-- writer's own copy replaces a relayed one, so his wiped addon (the Forever beta, every login),
	-- holding a rogue officer's copy of his note, sent it to the guild as his own, over a reader's
	-- honest copy, in a push and in its answers.
	test("1.1 Konig's review: an officer's addon never sends, as its own, a copy of its note another officer gave it; a reader's honest copy stays", function()
		local B36 = ns.Codec.Base36
		Fern.LootGuild(function(g)
			local o, h, r = g.Client("Offi", 1), g.Client("Honest", 1), g.Client("Rival", 1)
			r.away = true -- (Rival's addon is his own: what it sends is written here by hand)
			g.Officers(o, h)
			local a1 = o.Lt.Write("Ann gets the belt", 16830, "Ann Smith")
			local key = "Offi-Realm#" .. a1.id
			local function Note(c) return c.Lt.Book().notes[key] end
			eq(Note(h).text, "Ann gets the belt")
			-- The next day a member logs in while Offi is away: Honest's answer gives him Offi's note.
			o.away = true
			g.Run(86400)
			local m = g.Client("Bob", 3)
			m.Lt.Show(true)
			g.Run(60)
			eq(Note(m).text, "Ann gets the belt"); eq(Note(m).by, "Honest-Realm")
			-- Offi logs in, his book wiped; Rival's push, other words in his note, reaches his addon first.
			o.away = false
			o.ns.rdb = {}
			o.Lt.Reset()
			o.Lt.Book()
			g.Run(5)
			r.ns.Comm.SendChunked(("XB~S~0~0~0~0~0~0^N~Offi-Realm~%s~%s~%s~16830~~Bob Rival~Bob gets the belt"):format(a1.id, B36(a1.t), B36(a1.rev)),
				nil, "GUILD")
			g.Run(10)
			eq(Note(o).text, "Bob gets the belt", "(his wiped addon cannot tell)"); eq(Note(o).by, "Rival-Realm")
			eq(Note(m).text, "Ann gets the belt"); eq(Note(h).text, "Ann gets the belt")
			-- His login ask: Honest answers; Offi's addon hears an answer without its copy and pushes none of it.
			eq(o.Lt.Ask(), true)
			g.Run(60)
			eq(Note(m).text, "Ann gets the belt", "the honest copy stays"); eq(Note(m).by, "Honest-Realm")
			-- Another member asks and Offi's addon answers first: without that note, which Honest's then sends.
			o.rand, h.rand = 0, 1
			local m2 = g.Client("Ann", 3)
			m2.Lt.Show(true)
			g.Run(120)
			assert(#o.pages >= 1, "Offi's addon answered")
			eq(Note(m2).text, "Ann gets the belt"); eq(Note(m2).by, "Honest-Realm")
			for _, page in ipairs(o.pages) do eq(page:find("Bob gets the belt", 1, true), nil, "never from Offi's addon: " .. page) end
			-- A note he writes himself goes out in his answers as his.
			o.Lt.Write("Cid gets the ring", nil, "Cid")
			local page = o.Lt.Page(o.Lt.Book(), { n = { 0, g.clock + 1 } })
			assert(page:find("~Cid~Cid gets the ring", 1, true), page)
			eq(page:find("Bob gets the belt", 1, true), nil, page)
		end)
	end)

	-- "Loot notes follow-up: backdated relays": a change another officer passes on, dated before the
	-- reader's session, is taken on his word (nothing signs it). He is named with it now, and the pages
	-- say the limit.
	test("1.1 Konig's review: a change another officer passes on, dated before the reader's session, keeps who passed it on, and the page names him", function()
		local Lt, B36, L = ns.Loot, ns.Codec.Base36, ns.L
		local saved = { guild = GetGuildInfo, time = GetServerTime, byName = ns.Roster.byName, loot = ns.rdb.loot, fire = ns.Fire }
		local base = 1790000000
		local function Answer(entries) return "XB~S~0~0~0~0~0~0^" .. table.concat(entries, "^") end
		local ok, err = pcall(function()
			ns.rdb.loot = nil
			Lt.Reset()
			GetGuildInfo = function(unit) if unit == nil or unit == "player" then return "Olympus II", "Member", 3 end return nil end
			GetServerTime = function() return base end
			ns.Fire = function() end
			ns.Roster.byName = { ["Offi-Realm"] = 1, ["Rival-Realm"] = 1, ["Bob-Realm"] = 3, ["Cid-Realm"] = 3 }
			Lt.Book() -- (a member's session starts)
			local week, day, minute = B36(base - 7 * 86400), B36(base - 86400), B36(base - 60)
			local notes, points = Lt.Book().notes, Lt.Book().points
			-- Offi's own answer: his note and his points change, nobody else's word.
			Lt.HandleBook("GUILD", "Offi-Realm", Answer({ ("N~Offi-Realm~a1~%s~%s~~~Ann Smith~Ann gets the belt"):format(week, week),
				"P~Bob-Realm~5~" .. week .. "~Offi-Realm" }))
			eq(notes["Offi-Realm#a1"].via, nil); eq(points["Bob-Realm"].via, nil)
			-- Rival's push: a note in Offi's name dated yesterday, a points change "by Offi" a minute before
			-- this session. Nothing tells them from real ones: taken, with Rival kept as who passed them on.
			Lt.HandleBook("GUILD", "Rival-Realm", Answer({ ("N~Offi-Realm~zz~%s~%s~~~Bob Rival~Correction: Bob gets the belt"):format(day, day),
				"P~Bob-Realm~99999~" .. minute .. "~Offi-Realm", "P~Cid-Realm~4~" .. minute .. "~Rival-Realm" }))
			eq(notes["Offi-Realm#zz"].text, "Correction: Bob gets the belt"); eq(notes["Offi-Realm#zz"].via, "Rival-Realm")
			eq(points["Bob-Realm"].v, 99999); eq(points["Bob-Realm"].by, "Offi-Realm"); eq(points["Bob-Realm"].via, "Rival-Realm")
			eq(points["Cid-Realm"].by, "Rival-Realm"); eq(points["Cid-Realm"].via, nil, "his own: nobody else named")
			-- The page: the relayed note's line names both, its tooltip and the points' say who passed them on.
			local lines = Lt.Lines()
			local forged, real = Fern.Find(lines, "Correction: Bob gets the belt"), Fern.Find(lines, "Ann gets the belt")
			eq(Fern.Bare(forged.right), L.LOOT_VIA:format("Offi", "Rival") .. "  " .. date("%Y-%m-%d", base - 86400))
			eq(Fern.Bare(real.right), "Offi  " .. date("%Y-%m-%d", base - 7 * 86400))
			assert(Fern.Tip(forged):find(L.LOOT_VIA_TIP:format("Rival"), 1, true), Fern.Tip(forged))
			eq(Fern.Tip(real):find("Passed on by", 1, true), nil, Fern.Tip(real))
			local function Row(name) for _, l in ipairs(lines) do if Fern.Bare(l.text) == name then return l end end end
			local tip = Fern.Tip(Row("Bob"))
			assert(tip:find(L.LOOT_POINTS_BY:format("Offi", date("%Y-%m-%d %H:%M", base - 60)), 1, true), tip)
			assert(tip:find(L.LOOT_VIA_TIP:format("Rival"), 1, true), tip)
			eq(Fern.Tip(Row("Cid")):find("Passed on by", 1, true), nil, "Rival's own")
			-- The copy for Discord names him too.
			local text = Lt.DiscordText()
			assert(text:find("Correction: Bob gets the belt (" .. L.LOOT_VIA:format("Offi", "Rival") .. ")", 1, true), text)
			assert(text:find("Ann gets the belt (Offi)", 1, true), text)
			-- Offi's own change later, live: his, and the relayer goes.
			GetServerTime = function() return base + 60 end
			Lt.HandleLive("GUILD", "Offi-Realm", "X1~P~Bob-Realm~6~" .. B36(base + 30) .. "~Offi-Realm")
			eq(points["Bob-Realm"].v, 6); eq(points["Bob-Realm"].via, nil)
		end)
		GetGuildInfo, GetServerTime, ns.Roster.byName, ns.rdb.loot, ns.Fire = saved.guild, saved.time, saved.byName, saved.loot, saved.fire
		Lt.Reset()
		if not ok then error(err, 0) end
		-- In English and pt-BR (the list's "%s via %s" is the same words in both), and both pages say the limit.
		local pt = Fern.BothLanguages({ "LOOT_VIA", "LOOT_VIA_TIP" }, { LOOT_VIA = true })
		for _, key in ipairs({ "LOOT_VIA", "LOOT_VIA_TIP" }) do eq(select(2, pt[key]:gsub("%%s", "")), select(2, L[key]:gsub("%%s", "")), key) end
		for _, file in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local f = assert(io.open(ROOT .. file))
			local doc = f:read("*a"):gsub("%s+", " ")
			f:close()
			assert(doc:find("changes from before your session began, and those come on the passing officer's word: nothing proves who made them", 1, true), file)
			assert(doc:find("the page names the officer who passed each one on (\"Offi via Rival\" on a note and in the copy for Discord, and in the tooltips of notes and points)", 1, true), file)
			assert(doc:find("an officer's addon sends a change in his name only as he made it", 1, true), file)
			eq(doc:find("nobody changes its words afterwards", 1, true), nil, file .. ": more than the code holds")
		end
	end)

	-- The points' half of the first item: a points change "by Offi" his wiped addon took from Rival's
	-- push, sent by it, read as his own (past the check of a reader whose session began before it).
	test("1.1 Konig's review: an officer's addon never sends, as its own, a points change in its name another officer passed on to it", function()
		local B36 = ns.Codec.Base36
		Fern.LootGuild(function(g)
			local o, h, r = g.Client("Offi", 1), g.Client("Honest", 1), g.Client("Rival", 1)
			r.away = true -- (Rival's addon is his own: what it sends is written here by hand)
			g.byName["Cid-Realm"] = 3
			g.Officers(o, h)
			o.away = true
			g.Run(3600)
			-- A member logs in; ten minutes later Offi does, his book wiped.
			local m = g.Client("Bob", 3)
			m.Lt.Book()
			local memberFrom = g.clock + 1
			g.Run(600)
			o.away = false
			o.ns.rdb = {}
			o.Lt.Reset()
			o.Lt.Book()
			-- Rival pushes a points change "by Offi" dated between the two logins.
			r.ns.Comm.SendChunked("XB~S~0~0~0~0~0~0^P~Cid-Realm~99999~" .. B36(memberFrom + 300) .. "~Offi-Realm", nil, "GUILD")
			g.Run(10)
			local function Points(c) return c.Lt.Book().points["Cid-Realm"] end
			eq(Points(m), nil, "dated in the member's session: not from Rival"); eq(Points(h), nil)
			eq(Points(o).v, 99999, "(Offi's addon, its session younger, cannot tell)"); eq(Points(o).via, "Rival-Realm")
			-- Offi's login ask: Honest answers without it; Offi's addon pushes none of it.
			eq(o.Lt.Ask(), true)
			g.Run(60)
			eq(Points(m), nil, "never from Offi's addon as his")
			for _, page in ipairs(o.pages) do eq(page:find("P~Cid-Realm~99999", 1, true), nil, page) end
			eq(o.Lt.Page(o.Lt.Book(), { p = { 0, g.clock + 1 } }):find("P~Cid-Realm~99999", 1, true), nil, "nor in his answers")
			-- His own change goes out as his, and the member takes it.
			o.Lt.SetPoints("Cid 7")
			eq(Points(m).v, 7); eq(Points(m).by, "Offi-Realm"); eq(Points(m).via, nil)
			assert(o.Lt.Page(o.Lt.Book(), { p = { 0, g.clock + 1 } }):find("P~Cid-Realm~7~", 1, true))
		end)
	end)
end
---------------------------------------------------------------------------
-- 1.1, Konig's review of #45 (the treasury): the King's word from the King and his Stewards alone,
-- a sister bank's no to every viewer holding it, requests to the treasury paced, "gone since" from
-- one source's own snapshots, and no dues in the ranking that leaves the Treasurer's client.
---------------------------------------------------------------------------
do
	local KING, TREASURER, STEWARD = "Asmongold Asmongler-Realm", "Pyralis Ashandar-Realm", "Test Steward-Realm"
	local function AsSteward() GetGuildInfo = function() return "Olympus II", "Member", 3 end; ns.me = STEWARD end
	-- The Throne's world with a Steward the signed list names (STEWARD), put back after.
	local function WithStewards(fn)
		WithThrone(function(w, K)
			local saved = { steward = ns.IsSteward, split = ns.splitNames, shares = ns.db.keeperShares }
			local ok, err = pcall(function()
				ns.IsSteward = function(n) return type(n) == "string" and ns.FullName(n) == STEWARD end
				ns.splitNames = true
				fn(w, K)
			end)
			ns.IsSteward, ns.splitNames, ns.db.keeperShares = saved.steward, saved.split, saved.shares
			ns.rdb.duesAmount, ns.rdb.treasuryKeepers = nil, nil
			if not ok then error(err, 0) end
		end)
	end
	-- Dues.lua loaded again, on its own: the types it registers (handles), what it runs at login
	-- and on its timers (on, timers); its dialogs put back as they were.
	local function DuesAlone()
		local got = { handles = {}, on = {}, timers = {} }
		local fresh = setmetatable({
			On = function(name, f) got.on[name] = f end,
			RegisterEvent = function() end,
			After = function(_, _, f) got.timers[#got.timers + 1] = f end,
			Every = function(_, _, f) got.timers[#got.timers + 1] = f end,
			Comm = setmetatable({ Handle = function(kind) got.handles[kind] = true end }, { __index = ns.Comm }),
			King = setmetatable({ Register = function(kind) got.handles["T1 " .. kind] = true end }, { __index = ns.King }),
		}, { __index = ns })
		local dialogs = {}
		for k, v in pairs(StaticPopupDialogs) do if k:find("^OLYMPUS_DUES") then dialogs[k] = v end end
		assert(loadfile(ADDON_DIR .. "Dues.lua"))("Olympus", fresh)
		for k in pairs(StaticPopupDialogs) do if k:find("^OLYMPUS_DUES") then StaticPopupDialogs[k] = dialogs[k] end end
		return fresh.Dues, got
	end

	test("1.1 Konig's review: the Treasurer's book sets none of the King's switches, a word newer than any the King gave neither; 1.0's addons still read its copy", function()
		WithStewards(function(w, K)
			local T = ns.Treasury
			-- The King shows the army the balance.
			AsKing(); T.SetFlag("balance", true)
			local given, word = w.clock, LastSent(w)
			-- A Treasurer's client that makes a word up: every switch on, dated after the King's (inside
			-- the minute a word may run ahead of the server's clock), in his book.
			AsTreasurer()
			ns.db.keeperShares = { [TREASURER_KEY] = true }
			ns.rdb.treasuryFlags = { balance = true, ranking = true, book = true, at = given + 30, from = TREASURER }
			local forged = T.Message()
			assert(forged:find("~111@" .. (given + 30) .. "~", 1, true), forged)
			-- A soldier who heard the King keeps his word; one who never did takes none from the book.
			AsSoldier("Late Login"); ns.rdb.treasuryFlags = nil
			K.HandleCommand("CHANNEL", KING, word)
			T.HandleReport("CHANNEL", TREASURER, forged)
			eq(T.Shows("balance"), true); eq(T.Shows("ranking"), false, "the Treasurer set no switch"); eq(T.Shows("book"), false)
			ns.rdb.treasuryFlags = nil
			T.HandleReport("CHANNEL", TREASURER, forged)
			eq(T.AnyShown(), false, "never heard the King: nothing shown on the Treasurer's word")
			eq(T.Visible(), false, "no tab for the army")
			-- By whisper (the whole book, on a keeper's client): the same.
			ns.rdb.treasuryKeepers = { at = 1, names = { "Late Login-Realm" } }
			GetGuildInfo = function() return "Olympus", "Member", 3 end
			T.HandleReport("WHISPER", TREASURER, forged)
			eq(T.AnyShown(), false, "whispered: nothing either")
			ns.rdb.treasuryKeepers = nil
			-- The King's client: his word stays his, and it is his that he repeats (it never becomes
			-- the Treasurer's, taken and repeated in the King's name).
			AsKing(); ns.rdb.treasuryFlags = { balance = true, ranking = false, book = false, at = given, from = KING, t = given }
			T.HandleReport("CHANNEL", TREASURER, forged)
			eq(ns.rdb.treasuryFlags.at, given); eq(T.Shows("book"), false)
			w.clock = w.clock + T.FLAGS_EVERY
			T.SendFlags(true)
			assert(LastSent(w):find("^T1~T~%d+~Olympus~100~" .. given .. "$"), LastSent(w))
			-- A Steward's client neither.
			AsSteward(); ns.rdb.treasuryFlags = { balance = true, ranking = false, book = false, at = given, from = KING, t = given }
			T.HandleReport("CHANNEL", TREASURER, forged)
			eq(ns.rdb.treasuryFlags.at, given); eq(T.Shows("ranking"), false)
			-- The Treasurer's copy older than the King's word: the King's client answers with his, so the
			-- Treasurer's client (and the 1.0 addons reading his book) catch up.
			AsTreasurer(); ns.rdb.treasuryFlags = { balance = false, ranking = false, book = false, at = given - 600, from = KING }
			local stale = T.Message()
			AsKing(); ns.rdb.treasuryFlags = { balance = true, ranking = false, book = false, at = given, from = KING, t = given }
			local before = #w.sent
			T.HandleReport("CHANNEL", TREASURER, stale)
			eq(#w.sent, before + 1, "answered"); assert(w.sent[#w.sent].msg:find("~100~" .. given .. "$"), w.sent[#w.sent].msg)
			AsTreasurer(); ns.rdb.treasuryFlags = nil
			K.HandleCommand("CHANNEL", KING, w.sent[#w.sent].msg)
			eq(T.Shows("balance"), true, "the Treasurer's client takes the King's own word")
			-- A 1.0 addon (1.0.0's Treasury.lua) still reads the switches from the Treasurer's book: his
			-- 1.1 client repeats there the King's word it took from him.
			local copy = T.Message()
			assert(copy:find("~100@" .. given .. "~", 1, true), copy)
			local Old, old = OldTreasury()
			old.rdb.treasuryFlags = nil
			Old.HandleReport("CHANNEL", TREASURER, copy)
			eq(old.rdb.treasuryFlags and old.rdb.treasuryFlags.balance, true, "1.0 reads it there, as before")
		end)
	end)

	test("1.1 Konig's review: the dues' amount comes from the King and his Stewards alone; the Treasurer's client repeats none (FK), and none is read", function()
		WithStewards(function(w, K)
			local D = ns.Dues
			D.Reset()
			local week = D.Week()
			-- The King's amount, 2 gold from next week.
			AsKing(); D.SetAmount("2g")
			local word = LastSent(w)
			eq(D.AmountOf(week + 1), 20000); eq(D.Amount(), 10000)
			-- The Treasurer's client, logged in with the King's word: nothing of it goes out from him,
			-- at login or on its timers.
			AsTreasurer()
			local Alone, got = DuesAlone()
			eq(got.handles.FK, nil, "no copy of the amount is read")
			eq(got.handles["T1 Y"], true, "the King's and his Stewards' word is")
			w.sent = {}
			got.on.LOGIN()
			for _, f in ipairs(got.timers) do f() end
			for _, x in ipairs(w.sent) do assert(not x.msg:find("^FK~"), "the Treasurer's copy of the amount: " .. x.msg) end
			-- A word of the Treasurer's own (a newer amount, and this week's in its <before>), sent as
			-- the King's is: not his to give.
			AsSoldier(); ns.rdb.duesAmount = nil
			K.HandleCommand("CHANNEL", KING, word)
			K.HandleCommand("CHANNEL", TREASURER, ("T1~Y~5~Olympus~9990000~%d~9990000"):format(w.clock + 30))
			eq(D.Amount(), 10000, "this week's stays"); eq(D.AmountOf(week + 1), 20000, "the King's")
			-- His Steward's, in the King's name: taken.
			K.HandleCommand("CHANNEL", STEWARD, ("T1~Y~6~Olympus II~30000~%d~10000"):format(w.clock + 1))
			eq(D.AmountOf(week + 1), 30000)
			-- Both pages say so, and no longer that the Treasurer's addon repeats the King's word.
			for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
				local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
				assert(not doc:find("The Treasurer's addon repeats the King's latest word", 1, true), path)
				assert(not doc:find("repeated by the Treasurer's", 1, true) and not doc:find("and so does the Treasurer's", 1, true), path)
				assert(doc:find("so 1.1 takes none from it; 1.0's addons still read it there", 1, true), path)
				assert(doc:find("the Treasurer, who receives the dues, sets none of it", 1, true), path)
			end
		end)
	end)

	test("1.1 Konig's review: a sister guild's no reaches every viewer holding its bank, one heard too long ago at his next ask, once, after a /reload of its sender too", function()
		WithStewards(function(w, K)
			local T, B = ns.Treasury, ns.Bank
			local saved = { after = ns.After, shares = ns.db.sisterBankShares, sent = ns.db.sisterBankSent, zeus = ns.rdb.guilds["Olympus Zeus"] }
			local ok, err = pcall(function()
				local After, Run = Queued()
				ns.After = After
				ns.db.sisterBankShares, ns.db.sisterBankSent = nil, nil
				-- The Lord of Olympus Zeus (the census confirms him) says yes; the King's addon asks after its login.
				AsLord()
				ns.rdb.bank = { t = w.clock, guild = "Olympus Zeus", by = ns.me, money = 424242,
					tabs = { { i = 1, name = "Stash", items = { { id = 2589, n = 60, s = 1 } } } } }
				B.SetSisterConsent(true)
				w.whispered = {}
				T.HandleAsk("CHANNEL", KING, "TA~Olympus~0"); Run()
				local pieces = {}
				for _, x in ipairs(w.whispered) do eq(x.to, KING); pieces[#pieces + 1] = x.msg end
				assert(#pieces > 0, "whispered to the King")
				local function Holds()
					-- (The census as its reporters say it now: reports count 30 minutes.)
					ns.rdb.guilds["Olympus Zeus"] = Vouched({ total = 100, online = 9, zones = {}, t = w.clock, leader = "Zed", realm = "Realm" }, "W3-Realm", "W4-Realm")
					AsKing()
					for _, m in ipairs(pieces) do T.HandlePrivate("WHISPER", "Zed-Realm", m) end
					eq(#B.Sisters(), 1, "the King holds it")
				end
				Holds()
				-- Longer than NO_WITHIN later (his addon asks every 15 minutes; the Lord's heard none of
				-- them, offline meanwhile), the Lord says no: the King was heard too long ago for it to go
				-- at once. (Konig's review of 1.1, again: 12 minutes later it went at his next ask alone;
				-- within NO_WITHIN it now goes at once, tested with the review's second pass below.)
				AsLord()
				w.clock = w.clock + B.NoWithin() + 60
				w.whispered = {}
				B.SetSisterConsent(false)
				eq(#w.whispered, 0, "not heard lately: nothing at once")
				-- His next ask: the no, and the bank leaves his screen.
				w.clock = w.clock + 60
				T.HandleAsk("CHANNEL", KING, "TA~Olympus~1"); Run()
				eq(#w.whispered, 1, "the no"); eq(w.whispered[1].to, KING); eq(w.whispered[1].msg, "TS~Olympus Zeus~0~0~")
				AsKing(); B.HandleSister("WHISPER", "Zed-Realm", w.whispered[1].msg)
				eq(#B.Sisters(), 0, "withdrawn")
				-- Once a session: his asks after that cost nothing; a Hand's addon asking afresh (after its
				-- login: it holds nothing) is not told either.
				AsLord(); w.clock = w.clock + T.ASK_EVERY
				T.HandleAsk("CHANNEL", KING, "TA~Olympus~1"); Run()
				eq(#w.whispered, 1, "told once")
				AsKing(); K.AddHand("Helper"); K.SendHands(true); local hands = LastSent(w)
				AsLord(); K.HandleCommand("CHANNEL", KING, hands)
				T.HandleAsk("CHANNEL", "Helper-Realm", "TA~Olympus II~0"); Run()
				eq(#w.whispered, 1, "a fresh ask holds nothing")
				-- The Lord's addon reloads (its session's memory gone) while the King still holds his bank
				-- (sent before the no): remembered, the King's next ask gets the no.
				B.Reset(); Holds()
				AsLord(); w.whispered = {}
				T.HandleAsk("CHANNEL", KING, "TA~Olympus~1"); Run()
				eq(#w.whispered, 1, "told after the reload"); eq(w.whispered[1].msg, "TS~Olympus Zeus~0~0~")
				-- The census no longer names him Lord (his guild's reports stopped): his no still counts, from
				-- the one whose snapshot the King holds; nobody else's does.
				ns.rdb.guilds["Olympus Zeus"] = nil
				AsKing()
				B.HandleSister("WHISPER", "Faker Guy-Realm", w.whispered[1].msg)
				eq(#B.Sisters(), 1, "not from anyone")
				B.HandleSister("WHISPER", "Zed-Realm", w.whispered[1].msg)
				eq(#B.Sisters(), 0, "his own no")
				-- An officer who said no and never shared: nothing whispered, ever.
				B.Reset()
				AsCaptain(); ns.db.sisterBankShares = { ["cap-realm"] = false }
				w.whispered = {}
				T.HandleAsk("CHANNEL", KING, "TA~Olympus~1"); Run()
				eq(#w.whispered, 0, "never shared: nothing to take back")
				-- Both pages say how the no travels.
				for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
					local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
					assert(doc:find("from the others at their next ask", 1, true), path)
				end
			end)
			ns.After, ns.db.sisterBankShares, ns.db.sisterBankSent, ns.rdb.guilds["Olympus Zeus"] = saved.after, saved.shares, saved.sent, saved.zeus
			ns.Bank.Reset()
			if not ok then error(err, 0) end
		end)
	end)

	test("1.1 Konig's review: requests to the treasury are paced, each requester's new ones, each keeper's answers and his list on the channel", function()
		WithStewards(function(w, K)
			local T, B = ns.Treasury, ns.Bank
			local saved = { after = ns.After, zeus = ns.rdb.guilds["Olympus Zeus"], two = ns.rdb.guilds["Olympus II"] }
			local ok, err = pcall(function()
				local After, Run = Queued()
				ns.After = After
				-- The census as its reporters say it now (reports count 30 minutes): Zed the Lord of
				-- Olympus Zeus, Cap a Captain of Olympus II.
				local function Census()
					ns.rdb.guilds["Olympus Zeus"] = Vouched({ total = 100, online = 9, zones = {}, t = w.clock, leader = "Zed", realm = "Realm" }, "W3-Realm", "W4-Realm")
					ns.rdb.guilds["Olympus II"] = Vouched({ total = 300, online = 3, zones = {}, t = w.clock, leader = "Ceo", realm = "Realm",
						officers = { { name = "Cap", online = true, days = 0 } } }, "W5-Realm", "W6-Realm")
				end
				local function Count(prefix, to)
					local n = 0
					for _, x in ipairs(w.whispered) do if x.msg:sub(1, #prefix) == prefix and (not to or x.to == to) then n = n + 1 end end
					return n
				end
				local function NewLines()
					local n = 0
					for _, p in ipairs(w.printed) do if p:find(" <Olympus Zeus>", 1, true) and p:find("Zed", 1, true) then n = n + 1 end end
					return n
				end
				Census()
				-- The Lord's own client: a request taken back and made again, six in the hour; the
				-- seventh waits, and he is told when it may go. No whisper for it.
				AsLord()
				T.Heard(TREASURER); T.MarkReader(TREASURER)
				w.whispered = {}
				for i = 1, B.REQUEST_NEW do
					local e = B.Request(2589, i)
					assert(e, "request " .. i)
					B.Cancel(e.id)
					w.clock = w.clock + 60
				end
				local sent = Count("TN~", TREASURER)
				eq(sent, 2 * B.REQUEST_NEW, "each one and its taking back, to the keeper heard")
				eq(B.Request(2589, 1), nil, "paced")
				assert(Printed(w, ns.L.BANK_REQUEST_PACED:format(B.REQUEST_NEW, (B.REQUEST_WINDOW - B.REQUEST_NEW * 60) / 60)), "told when")
				eq(Count("TN~", TREASURER), sent, "nothing sent for it")
				-- An hour after the first: one more may go.
				w.clock = w.clock - B.REQUEST_NEW * 60 + B.REQUEST_WINDOW
				assert(B.Request(2589, 1), "the window moved on")
				-- A keeper's client, a modified client's flood of new ids (each taken back at once): six
				-- an hour taken, told in chat, answered; the rest nothing at all, and never on the channel.
				B.Reset(); Census()
				AsTreasurer()
				ns.db.keeperShares = { [TREASURER_KEY] = true }
				ns.rdb.treasuryFlags = { book = true, at = w.clock, from = KING }
				w.whispered, w.printed, w.sent = {}, {}, {}
				for id = 1, 40 do
					B.HandleRequest("WHISPER", "Zed-Realm", ("TN~%d~2589~10~Olympus Zeus"):format(id))
					B.HandleRequest("WHISPER", "Zed-Realm", ("TN~%d~2589~0~Olympus Zeus"):format(id))
				end
				eq(NewLines(), B.REQUEST_NEW, "six lines in his chat")
				eq(Count("TO~", "Zed-Realm"), 2 * B.REQUEST_NEW, "each taken one answered, and its taking back")
				local lists = 0
				for _, s in ipairs(w.sent) do if s.msg:find("^TL~") then lists = lists + 1 end end
				assert(lists <= 1, "his list on the channel once in the minute: " .. lists)
				-- Hours of it: he keeps ten of that player's at most, and another player's request stays.
				B.HandleRequest("WHISPER", "Cap-Realm", "TN~7~929~2~Olympus II")
				B.Answer("Cap-Realm#7", "declined")
				for hour = 1, 12 do
					w.clock = w.clock + B.REQUEST_WINDOW
					Census()
					for id = 100 * hour, 100 * hour + 10 do
						B.HandleRequest("WHISPER", "Zed-Realm", ("TN~%d~2589~10~Olympus Zeus"):format(id))
						B.HandleRequest("WHISPER", "Zed-Realm", ("TN~%d~2589~0~Olympus Zeus"):format(id))
					end
				end
				local his, other = 0, false
				for key in pairs(ns.rdb.bankRequests) do
					if key:find("^Zed%-Realm#") then his = his + 1 end
					if key == "Cap-Realm#7" then other = true end
				end
				assert(his <= B.REQUESTS_EACH, "his, kept: " .. his)
				eq(other, true, "another player's request is not pushed out by his")
				-- One request asked about again and again: answered once an ANSWER_GAP while unchanged (7.5
				-- minutes since the review's second pass), at once when it changes. (An hour later: his last
				-- six are out of the window.)
				w.clock = w.clock + B.REQUEST_WINDOW
				Census()
				B.HandleRequest("WHISPER", "Zed-Realm", "TN~5000~118~1~Olympus Zeus")
				w.whispered = {}
				for _ = 1, 10 do B.HandleRequest("WHISPER", "Zed-Realm", "TN~5000~118~1~Olympus Zeus") end
				eq(Count("TO~", "Zed-Realm"), 0, "answered a moment ago")
				w.clock = w.clock + B.ANSWER_GAP
				for _ = 1, 10 do B.HandleRequest("WHISPER", "Zed-Realm", "TN~5000~118~1~Olympus Zeus") end
				eq(Count("TO~", "Zed-Realm"), 1, "once an ANSWER_GAP")
				B.Answer("Zed-Realm#5000", "done")
				eq(Count("TO~5000~d", "Zed-Realm"), 1, "a change: at once")
				B.Answer("Zed-Realm#5000", "done")
				eq(Count("TO~5000~d", "Zed-Realm"), 1, "the same click again: nothing")
				-- His list on the channel: once a minute, a change inside it once the minute is over.
				w.clock = w.clock + B.PUBLIC_GAP
				Run() -- (what waited goes)
				w.clock = w.clock + B.PUBLIC_GAP
				B.HandleRequest("WHISPER", "Cap-Realm", "TN~8~2770~3~Olympus II")
				w.sent = {}
				B.HandleRequest("WHISPER", "Cap-Realm", "TN~9~2771~3~Olympus II")
				B.HandleRequest("WHISPER", "Cap-Realm", "TN~10~2772~3~Olympus II")
				eq(#w.sent, 0, "inside the minute: held")
				w.clock = w.clock + B.PUBLIC_GAP
				Run()
				eq(#w.sent, 1, "then once, as it is then")
				assert(w.sent[1].msg:find("10:2772:3:Cap%-Realm", 1) and w.sent[1].msg:find("9:2771:3:Cap%-Realm", 1), w.sent[1].msg)
				-- Both languages, the same format arguments; both pages say so.
				local savedLocale, pt = GetLocale, {}
				GetLocale = function() return "ptBR" end
				local okL, errL = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
				GetLocale = savedLocale
				if not okL then error(errL, 0) end
				local key = "BANK_REQUEST_PACED"
				assert(type(rawget(ns.L, key)) == "string", "English " .. key)
				assert(type(rawget(pt.L, key)) == "string" and pt.L[key] ~= ns.L[key], "Portuguese " .. key)
				eq(select(2, pt.L[key]:gsub("%%[ds]", "")), select(2, ns.L[key]:gsub("%%[ds]", "")), key)
				for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
					local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
					assert(doc:find("6 new requests an hour per character", 1, true), path)
				end
			end)
			ns.After, ns.rdb.guilds["Olympus Zeus"], ns.rdb.guilds["Olympus II"] = saved.after, saved.zeus, saved.two
			ns.rdb.treasuryFlags = nil
			ns.Bank.Reset()
			if not ok then error(err, 0) end
		end)
	end)

	test("1.1 Konig's review: the bank's gone since the last snapshot compares one source's own snapshots; another keeper's never marks anything gone", function()
		WithStewards(function(w, K)
			local B = ns.Bank
			local KEEPER = "Test Keeper-Realm"
			local t = w.clock
			-- (A snapshot taken at `when`, heard then: never dated after its arrival.)
			local function T9(when, tabs)
				w.clock = math.max(w.clock, when)
				return ("T9~Olympus~%d~5000~%s"):format(when, tabs)
			end
			-- The King's client holds none of its own; the King named a keeper besides the Treasurer.
			AsKing()
			B.Reset()
			ns.rdb.treasuryKeepers = { at = 1, names = { KEEPER } }
			-- The other keeper's snapshot (his word: more than the bank holds, or tabs the Treasurer can't
			-- see), then the Treasurer's, newer: nothing gone, they are two sources.
			B.HandleReport("CHANNEL", KEEPER, T9(t - 100, "Mats;2589x200,2770x20"))
			B.HandleReport("CHANNEL", TREASURER, T9(t, "Mats;2589x190"))
			eq(B.Current().by, TREASURER)
			eq(GoneList(B.Current()), "", "another keeper's snapshot marks nothing gone")
			-- The Treasurer's next one: compared with his own before it.
			B.HandleReport("CHANNEL", TREASURER, T9(t + 100, "Mats;2589x150"))
			eq(GoneList(B.Current()), "2589 -40 (Mats)")
			-- The other keeper's again (inflated), and the Treasurer's after it: each only with his own.
			B.HandleReport("CHANNEL", KEEPER, T9(t + 150, "Mats;2589x999,2770x999"))
			eq(B.Current().by, KEEPER)
			eq(GoneList(B.Current()), "", "the Treasurer's snapshots are not his to compare with")
			B.HandleReport("CHANNEL", TREASURER, T9(t + 200, "Mats;2589x140"))
			local gone = GoneList(B.Current())
			assert(not gone:find("999", 1, true) and not gone:find("2770", 1, true), "nothing of the other keeper's: " .. gone)
			-- Our own snapshot (the King opens the bank), newer than the reports: compared with ours alone,
			-- none before it; a keeper's newer one after it is never compared with ours.
			ns.rdb.bank = { t = t + 250, guild = "Olympus", by = KING, money = 5000, tabs = { { i = 1, name = "Mats", items = { { id = 2589, n = 100, s = 1 } } } } }
			eq(B.Current(), ns.rdb.bank)
			eq(GoneList(B.Current()), "", "no snapshot of ours before it")
			B.HandleReport("CHANNEL", KEEPER, T9(t + 300, "Mats;2589x10"))
			eq(B.Current().by, KEEPER)
			-- (His own earlier one went when the Treasurer's replaced it: nothing listed, rather than a
			-- list made from ours or the Treasurer's.)
			eq(GoneList(B.Current()), "", "never ours, never the Treasurer's")
			-- The Treasurer's after it: his own earlier one, still kept.
			B.HandleReport("CHANNEL", TREASURER, T9(t + 400, "Mats;2589x130"))
			eq(GoneList(B.Current()), "2589 -60 (Mats)", "with his own of " .. (t))
			-- Both pages say so.
			for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
				local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
				assert(doc:find("never another keeper's", 1, true), path)
			end
			ns.rdb.treasuryKeepers = nil
			B.Reset()
		end)
	end)

	test("1.1 Konig's review: the ranking that leaves the Treasurer's client never tells who paid the dues; a total grows only by what a week's gold went over the amount", function()
		WithStewards(function(w, K)
			local T, D = ns.Treasury, ns.Dues
			local saved = { chars = ns.db.myCharacters, gst = GetServerTime }
			local ok, err = pcall(function()
				D.Reset()
				GetServerTime = nil -- (the server's clock is the test's)
				AsTreasurer()
				ns.db.keeperShares = { [TREASURER_KEY] = true }
				ns.rdb.treasuryFlags = { balance = true, ranking = true, book = true, at = w.clock, from = KING }
				-- The King's amount: 5 gold a week, for weeks already.
				ns.rdb.duesAmount = { copper = 50000, at = w.clock - 60 * 86400, before = 50000, from = KING }
				T.SetOpening("100")
				local function Give(name, copper, book) T.Record(name, copper, "mail", nil, { quiet = true, book = book }) end
				local function Field(msg, i)
					local f = {}
					for x in (msg .. "~"):gmatch("([^~]*)~") do f[#f + 1] = x end
					return f[i]
				end
				local function Ranked(list)
					local out = {}
					for e in (list or ""):gmatch("[^,]+") do
						local n, c = e:match("^(.-):(%d+)$")
						out[n] = tonumber(c)
					end
					return out
				end
				-- The ranking on the channel (the army's part with the ranking shown).
				local function Channel() return Ranked(Field(T.Message(nil, { ranking = true }), 13)) end
				-- A patron's gift; then week after week Payer pays the amount, Tipper too and one week
				-- 20 gold more; Skipper pays nothing.
				Give("Patron", 5000000)
				eq(Channel().Patron, 5000000 - 50000, "a donation ranks, less what may be his dues")
				for week = 1, 7 do
					Give("Payer", 50000)
					Give("Tipper", 50000 + (week == 3 and 200000 or 0))
					local now = Channel()
					eq(now.Payer, nil, "week " .. week .. ": a payer, not told from Skipper")
					eq(now.Skipper, nil)
					eq(now.Tipper, week >= 3 and 200000 or nil, "week " .. week .. ": only what went over the amount")
					eq(now.Patron, 4950000, "week " .. week .. ": no total grows back, weeks dropped too")
					w.clock = w.clock + 7 * 86400
				end
				-- His own screen: all of it.
				local mine = {}
				for _, g in ipairs(T.Totals().ranking) do mine[g.name] = g.money end
				eq(mine.Payer, 7 * 50000); eq(mine.Patron, 5000000)
				-- The whole book (whispered to the King, a Steward, the keepers) and 0.9's copy: the same.
				eq(Ranked(Field(T.Message(), 13)).Payer, nil, "whispered: nor there")
				eq(Ranked(Field(T.Message(), 13)).Tipper, 200000)
				eq(Ranked(Field(T.LegacyMessage(), 9)).Payer, nil, "0.9's copy: nor there")
				-- His mail character's book, passed on by his client: the same.
				ns.db.myCharacters = { [TREASURER_KEY] = true, [ANDARAI_KEY] = true }
				ns.db.keeperShares = { [TREASURER_KEY] = true, [ANDARAI_KEY] = true }
				local mailBook = T.BookOf(ANDARAI, true)
				mailBook.opening = 0
				Give("Mail Payer", 50000, mailBook)
				Give("Mail Patron", 800000, mailBook)
				w.sent = {}
				T.Relay(true)
				local tr
				for _, x in ipairs(w.sent) do if x.msg:find("^TR~") then tr = x.msg end end
				assert(tr, "relayed")
				local relayed = Ranked(Field(tr:match("~(TB~.*)$"), 13))
				eq(relayed["Mail Payer"], nil); eq(relayed["Mail Patron"], 750000)
				-- Another keeper's book (the King's): no dues there, his donors as they gave.
				AsKing()
				Give("Payer", 50000)
				eq(Ranked(Field(T.Message(), 13)).Payer, 50000, "gold to the King is no dues")
				-- A backup of the Treasurer's book, restored after a wipe: the ranking as before (the weeks
				-- dropped still left out).
				AsTreasurer()
				ns.db.myCharacters = { [TREASURER_KEY] = true }
				local before = Field(T.Message(nil, { ranking = true }), 13)
				local text = ns.Backup.Export()
				ns.rdb.treasuryBooks = nil
				local d = assert(ns.Backup.Read(text))
				ns.Backup.Apply(d)
				eq(Field(T.Message(nil, { ranking = true }), 13), before, "restored: the same ranking")
				-- Both pages say so.
				for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
					local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
					assert(doc:find("each week's gold up to that week's amount", 1, true), path)
					assert(not doc:find("a ranked donor's total still grows on the channel when he gives", 1, true), path)
				end
			end)
			ns.db.myCharacters, GetServerTime = saved.chars, saved.gst
			D.Reset()
			if not ok then error(err, 0) end
		end)
	end)
end


---------------------------------------------------------------------------
-- 1.1, Konig's review of #45, second pass (the treasury): each week's dues amount kept in the
-- Treasurer's book as his client knew it, gold sent with the dues' note dues in full, a sister
-- guild's no at once to each viewer whose addon asked within ASK_EVERY (before a /reload of its
-- sender too), and a keeper's answers to one requester's requests paced.
---------------------------------------------------------------------------
do
	local KING, STEWARD = "Asmongold Asmongler-Realm", "Test Steward-Realm"
	local WEEK = 7 * 86400
	-- The Throne's world with a Steward the signed list names (STEWARD), the server's clock the
	-- test's, the dues as new; all put back after.
	local function WithStewards(fn)
		WithThrone(function(w, K)
			local saved = { steward = ns.IsSteward, split = ns.splitNames, shares = ns.db.keeperShares, gst = GetServerTime, chars = ns.db.myCharacters }
			local ok, err = pcall(function()
				ns.IsSteward = function(n) return type(n) == "string" and ns.FullName(n) == STEWARD end
				ns.splitNames = true
				GetServerTime = nil
				ns.Dues.Reset()
				fn(w, K)
			end)
			ns.IsSteward, ns.splitNames, ns.db.keeperShares, GetServerTime = saved.steward, saved.split, saved.shares, saved.gst
			ns.db.myCharacters = saved.chars
			ns.rdb.duesAmount, ns.rdb.treasuryKeepers, ns.rdb.treasuryFlags = nil, nil, nil
			ns.Dues.Reset()
			if not ok then error(err, 0) end
		end)
	end
	-- The Treasurer, sharing his book, while the King shows the army the ranking.
	local function SharingTreasurer(w)
		AsTreasurer()
		ns.db.keeperShares = { [TREASURER_KEY] = true }
		ns.rdb.treasuryFlags = { balance = true, ranking = true, book = true, at = w.clock, from = KING }
		ns.Treasury.SetOpening("100")
	end
	-- The ranking his client puts on the channel: { [name] = copper }.
	local function Channel()
		local f = {}
		for x in (ns.Treasury.Message(nil, { ranking = true }) .. "~"):gmatch("([^~]*)~") do f[#f + 1] = x end
		local out = {}
		for e in (f[13] or ""):gmatch("[^,]+") do
			local n, c = e:match("^(.-):(%d+)$")
			out[n] = tonumber(c)
		end
		return out
	end
	local function Give(name, copper, note) return ns.Treasury.Record(name, copper, "mail", nil, { quiet = true, note = note }) end
	local function Pages(fn)
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do fn(path, (assert(ReadFile(ROOT .. path)):gsub("%s+", " "))) end
	end

	test("1.1 Konig's review, second pass: each week's dues amount stays as the Treasurer's book kept it; a later word never re-judges a week kept, so its payers stay out of the ranking", function()
		WithStewards(function(w)
			local T, D = ns.Treasury, ns.Dues
			SharingTreasurer(w)
			-- The King's amount: 5 gold from next week. That week Payer pays it; Skipper pays nothing.
			eq(D.TakeAmount(50000, w.clock, KING, 10000), true)
			w.clock = w.clock + WEEK
			local paid = D.Week()
			Give("Payer", 50000)
			eq(Channel().Payer, nil, "the week of 5 gold")
			-- He lowers it to 2 gold from the week after; a week later he sets 3 gold. That word carries
			-- 2 gold as the amount of its own week and of every week before it.
			eq(D.TakeAmount(20000, w.clock, KING, 50000), true)
			eq(Channel().Payer, nil, "after the lower amount")
			w.clock = w.clock + WEEK
			eq(D.TakeAmount(30000, w.clock, KING, 20000), true)
			eq(D.AmountOf(paid), 20000, "(the latest word alone would judge Payer's week by 2 gold)")
			eq(Channel().Payer, nil, "a payer of a week kept never shows on the channel")
			local mine = {}
			for _, g in ipairs(T.Totals().ranking) do mine[g.name] = g.money end
			eq(mine.Payer, 50000, "his own screen: all of it")
			-- Two words are enough when the first lowers the amount under the 1 gold it had: Early paid
			-- 1 gold, then the King says 50 silver from next week, and next week 2 gold.
			D.Reset(); ns.rdb.treasuryBooks = nil
			SharingTreasurer(w)
			Give("Early", 10000)
			eq(D.TakeAmount(5000, w.clock, KING, 10000), true)
			w.clock = w.clock + WEEK
			eq(D.TakeAmount(20000, w.clock, KING, 5000), true)
			eq(Channel().Early, nil, "a 1 gold payer of the week before both words")
			-- Its week dropped from the weeks kept, folded with the amount it kept: still not there.
			for _ = 1, D.WEEKS_KEPT do
				w.clock = w.clock + WEEK
				Give("Other", 30000)
			end
			eq(Channel().Early, nil, "nor once its week is folded")
			-- This week's payer of 2 gold; three more words (3 gold, 1 gold, 4 gold: the last carries 1
			-- gold for its own week and every week before it), then a backup restored after a wipe: each
			-- week's amount comes back with the book, never worked out again from the latest word.
			Give("Late", 20000)
			eq(D.TakeAmount(30000, w.clock, KING, 20000), true)
			w.clock = w.clock + WEEK
			eq(D.TakeAmount(10000, w.clock, KING, 30000), true)
			w.clock = w.clock + WEEK
			eq(D.TakeAmount(40000, w.clock, KING, 10000), true)
			eq(Channel().Late, nil, "three words later: his week keeps its 2 gold")
			ns.db.myCharacters = { [TREASURER_KEY] = true }
			local text = ns.Backup.Export()
			ns.rdb.treasuryBooks = nil
			ns.Backup.Apply(assert(ns.Backup.Read(text)))
			local now = Channel()
			eq(now.Late, nil, "restored: the same"); eq(now.Early, nil, "restored: the weeks folded too")
			eq(now.Other, 5 * 10000, "(a gift over the amount still shows its excess: 1 gold a week)")
			-- A payer's week while the Treasurer's book was not shared (nothing built the ranking then):
			-- the week's amount is kept with the gift all the same, so a Steward's word the week after
			-- (his client had not heard the King's: 1 gold for its own week and every week before)
			-- changes nothing once the book is shared.
			D.Reset(); ns.rdb.treasuryBooks = nil
			eq(D.TakeAmount(50000, w.clock - WEEK, KING, 10000), true)
			SharingTreasurer(w)
			ns.db.keeperShares = nil
			Give("Quiet Payer", 50000)
			w.clock = w.clock + WEEK
			eq(D.TakeAmount(20000, w.clock, STEWARD, 10000), true)
			ns.db.keeperShares = { [TREASURER_KEY] = true }
			eq(Channel()["Quiet Payer"], nil, "the amount kept with his gift")
		end)
	end)

	test("1.1 Konig's review, second pass: gold sent with the dues' note is dues in full, an amount the Treasurer's client never heard too; a week's amount only rises while it runs", function()
		WithStewards(function(w)
			local T, D = ns.Treasury, ns.Dues
			SharingTreasurer(w)
			-- The King set 5 gold from this week while the Treasurer was offline, and no King's or
			-- Steward's addon met his since: his client still holds 1 gold. Members who heard the King
			-- pay 5 gold, by the button (its mail's note) or by hand.
			eq(D.Amount(), 10000)
			local line = Give("Noted Payer", 50000, D.Note(D.Week(), "Olympus II"))
			Give("Plain Payer", 50000)
			local now = Channel()
			eq(now["Noted Payer"], nil, "sent with the note: dues, all of it")
			eq(now["Plain Payer"], 40000, "by hand, while his client knows 1 gold: the limit both pages state")
			-- A tip on top of the note shows as any gift over the amount does; a line taken out of the
			-- count and put back leaves it as it was.
			Give("Noted Payer", 30000)
			eq(Channel()["Noted Payer"], 30000, "the tip alone")
			T.Toggle(line)
			eq(Channel()["Noted Payer"], 20000, "the paid line not counted: his tip less the amount")
			T.Toggle(line)
			eq(Channel()["Noted Payer"], 30000, "counted again")
			-- A backup restored after a wipe keeps what went with the note.
			ns.db.myCharacters = { [TREASURER_KEY] = true }
			local function Restore()
				local text = ns.Backup.Export()
				ns.rdb.treasuryBooks = nil
				ns.Backup.Apply(assert(ns.Backup.Read(text)))
			end
			Restore()
			now = Channel()
			eq(now["Noted Payer"], 30000, "restored: the tip alone"); eq(now["Plain Payer"], 40000)
			-- The King's word reaches the Treasurer's client in that week: the week's amount rises as it
			-- is heard. A Steward's later word says 1 gold for this week (his client had not heard the
			-- King's): the week's amount kept never goes down, so nobody who paid shows because of it.
			eq(D.TakeAmount(50000, w.clock - WEEK, KING, 10000), true)
			eq(D.TakeAmount(20000, w.clock, STEWARD, 10000), true)
			eq(D.Amount(), 10000, "(the word says 1 gold for this week)")
			now = Channel()
			eq(now["Plain Payer"], nil, "the amount heard while the week ran, never lowered"); eq(now["Noted Payer"], 30000)
			-- The week gone by (a new word carries 2 gold for every week before its own), then a backup
			-- restored: the week keeps the 5 gold its book kept.
			w.clock = w.clock + WEEK
			eq(D.TakeAmount(30000, w.clock, KING, 20000), true)
			eq(Channel()["Plain Payer"], nil, "the week gone by")
			Restore()
			now = Channel()
			eq(now["Plain Payer"], nil, "restored"); eq(now["Noted Payer"], 30000, "restored: the tip alone")
			-- Both pages say how it holds, and where it does not.
			Pages(function(path, doc)
				assert(doc:find("all he sent with the dues' note", 1, true), path)
				assert(doc:find("never changed by a later word of the King's", 1, true), path)
				assert(doc:find("grows by the difference, which can tell that he paid", 1, true), path)
				assert(not doc:find("the ranking never shows who did not pay", 1, true), path)
				assert(doc:find("less all you sent with the dues' note", 1, true), path)
			end)
		end)
	end)

	test("1.1 Konig's review, second pass: a sister guild's no goes at once to each viewer whose addon asked within ASK_EVERY, one heard before a /reload of its sender too", function()
		WithStewards(function(w, K)
			local T, B = ns.Treasury, ns.Bank
			local saved = { after = ns.After, shares = ns.db.sisterBankShares, sent = ns.db.sisterBankSent, heard = ns.db.sisterHeard,
				zeus = ns.rdb.guilds["Olympus Zeus"] }
			local ok, err = pcall(function()
				local After, Run = Queued()
				ns.After = After
				ns.db.sisterBankShares, ns.db.sisterBankSent, ns.db.sisterHeard = nil, nil, nil
				-- The census as its reporters say it now (reports count 30 minutes): Zed the Lord of Olympus Zeus.
				local function Census()
					ns.rdb.guilds["Olympus Zeus"] = Vouched({ total = 100, online = 9, zones = {}, t = w.clock, leader = "Zed", realm = "Realm" }, "W3-Realm", "W4-Realm")
				end
				local pieces
				local function Hold()
					Census()
					AsKing()
					for _, m in ipairs(pieces) do T.HandlePrivate("WHISPER", "Zed-Realm", m) end
					eq(#B.Sisters(), 1, "the King holds it")
				end
				-- The Lord says yes; the King's addon asks and holds his bank.
				local function Share()
					Census()
					AsLord()
					ns.rdb.bank = { t = w.clock, guild = "Olympus Zeus", by = ns.me, money = 424242,
						tabs = { { i = 1, name = "Stash", items = { { id = 2589, n = 60, s = 1 } } } } }
					w.whispered = {} -- (what it sends at once, to a viewer heard lately, and what the ask gets)
					B.SetSisterConsent(true)
					T.HandleAsk("CHANNEL", KING, "TA~Olympus~0"); Run()
					pieces = {}
					for _, x in ipairs(w.whispered) do pieces[#pieces + 1] = x.msg end
					assert(#pieces > 0, "whispered to the King")
					Hold()
				end
				-- A /reload of the Lord's addon: its session's memory gone, its saved variables kept (the
				-- King's client, in the same test, holds the bank again as before).
				local function Reload()
					local kept = ns.db.sisterHeard
					B.Reset()
					ns.db.sisterHeard = kept
					Hold()
				end
				-- The Lord says no: what reaches the King's screen at once.
				local function No()
					AsLord()
					w.whispered = {}
					B.SetSisterConsent(false)
					local told = 0
					AsKing()
					for _, x in ipairs(w.whispered) do
						if x.to == KING then
							eq(x.msg, "TS~Olympus Zeus~0~0~")
							told = told + 1
							B.HandleSister("WHISPER", "Zed-Realm", x.msg)
						end
					end
					return told
				end
				-- 12 minutes after the King's ask (his addon asks every 15), the Lord says no, and may log
				-- off before the next: the no goes at once.
				Share()
				w.clock = w.clock + T.AUDIENCE_FRESH + 60
				eq(No(), 1, "told at once")
				eq(#B.Sisters(), 0, "withdrawn from the King's screen")
				-- His next ask: nothing more (told once).
				AsLord(); w.whispered = {}
				w.clock = w.clock + (T.ASK_EVERY - T.AUDIENCE_FRESH)
				T.HandleAsk("CHANNEL", KING, "TA~Olympus~1"); Run()
				eq(#w.whispered, 0, "told once")
				-- Heard before a /reload of the Lord's addon, 17 minutes before the no: at once too.
				w.clock = w.clock + T.RESET_GAP
				Share()
				w.clock = w.clock + 5 * 60
				Reload()
				w.clock = w.clock + 12 * 60
				eq(No(), 1, "told at once after the reload")
				eq(#B.Sisters(), 0, "withdrawn")
				-- Heard longer ago than that (the Lord's addon was offline meanwhile and heard none of his
				-- asks): not at once (he may be offline), at his next ask while the Lord plays.
				w.clock = w.clock + T.RESET_GAP
				Share()
				w.clock = w.clock + B.NoWithin() + 60
				Reload()
				eq(No(), 0, "heard too long ago: not at once")
				eq(#B.Sisters(), 1, "the limit both pages state: until his next ask")
				AsLord(); w.whispered = {}
				T.HandleAsk("CHANNEL", KING, "TA~Olympus~1"); Run()
				eq(#w.whispered, 1, "his next ask: the no")
				AsKing(); B.HandleSister("WHISPER", "Zed-Realm", w.whispered[1].msg)
				eq(#B.Sisters(), 0, "withdrawn")
				-- The server says the King is offline: he is no longer one to tell at once.
				AsLord()
				ns.db.sisterHeard = { [KING] = w.clock }
				local savedErr = ERR_CHAT_PLAYER_NOT_FOUND_S
				ERR_CHAT_PLAYER_NOT_FOUND_S = "No player named '%s' is currently playing."
				T.NotFound(ERR_CHAT_PLAYER_NOT_FOUND_S:format(ns.TellName(KING)))
				ERR_CHAT_PLAYER_NOT_FOUND_S = savedErr
				eq(ns.db.sisterHeard[KING], nil, "offline: forgotten")
				eq(B.NoWithin(), 18 * 60, "(the pages' 18 minutes)")
				Pages(function(path, doc)
					assert(doc:find("from each one whose addon asked in the last 18 minutes", 1, true), path)
					assert(doc:find("from the others at their next ask", 1, true), path)
					assert(doc:find("keeps it on his screen until that player logs out", 1, true), path)
					assert(doc:find("your no takes it back from their screens: at once from those whose addon asked in the last 18 minutes", 1, true), path)
				end)
			end)
			ns.After, ns.db.sisterBankShares, ns.db.sisterBankSent, ns.db.sisterHeard = saved.after, saved.shares, saved.sent, saved.heard
			ns.rdb.guilds["Olympus Zeus"] = saved.zeus
			B.Reset()
			if not ok then error(err, 0) end
		end)
	end)

	test("1.1 Konig's review, second pass: a keeper answers one requester paced: a closed request he was told of never again, an open one unchanged once an ANSWER_GAP, a change at once", function()
		WithStewards(function(w)
			local B = ns.Bank
			local saved = { after = ns.After, zeus = ns.rdb.guilds["Olympus Zeus"] }
			local ok, err = pcall(function()
				ns.After = (Queued())
				local function Census()
					ns.rdb.guilds["Olympus Zeus"] = Vouched({ total = 100, online = 9, zones = {}, t = w.clock, leader = "Zed", realm = "Realm" }, "W3-Realm", "W4-Realm")
				end
				local function Ask(id, count) B.HandleRequest("WHISPER", "Zed-Realm", ("TN~%d~2589~%d~Olympus Zeus"):format(id, count)) end
				local function Answers()
					local n = 0
					for _, x in ipairs(w.whispered) do if x.to == "Zed-Realm" and x.msg:find("^TO~") then n = n + 1 end end
					return n
				end
				Census()
				AsTreasurer()
				ns.db.keeperShares = { [TREASURER_KEY] = true }
				-- A modified client: six new ids in an hour and four in the next, each taken back at once
				-- (a change each time, answered), ten held on the keeper's client.
				w.whispered = {}
				for id = 1, 6 do Ask(id, 10); Ask(id, 0) end
				w.clock = w.clock + B.REQUEST_WINDOW; Census()
				for id = 7, 10 do Ask(id, 10); Ask(id, 0) end
				eq(Answers(), 20, "each new one and its taking back")
				-- Then it asks about each of them every minute for an hour: closed, and he was told.
				w.whispered = {}
				for _ = 1, 60 do
					w.clock = w.clock + 60; Census()
					for id = 1, 10 do Ask(id, 10) end
				end
				eq(Answers(), 0, "closed and told: never again (600 whispers an hour before)")
				-- Three open ones (his most), asked about every minute for an hour: each answered once an
				-- ANSWER_GAP at most, twice what an honest client draws at the most (it asks about each every
				-- REQUEST_AGAIN).
				w.clock = w.clock + B.REQUEST_WINDOW; Census()
				for id = 21, 23 do Ask(id, 10) end
				w.whispered = {}
				for _ = 1, 60 do
					w.clock = w.clock + 60; Census()
					for id = 21, 23 do Ask(id, 10) end
				end
				local n = Answers()
				assert(n > 0 and n <= 2 * 3 * 3600 / B.REQUEST_AGAIN, "open ones, unchanged, an hour: " .. n)
				-- An honest client asks every REQUEST_AGAIN: each ask answered.
				w.whispered = {}
				for _ = 1, 4 do
					w.clock = w.clock + B.REQUEST_AGAIN; Census()
					Ask(21, 10)
				end
				eq(Answers(), 4, "each honest ask answered")
				-- A change goes at once; the keeper's click does not count as telling him (he may have
				-- logged off since he was heard), so his next ask gets it once more; then that request,
				-- closed and told, is never answered again.
				w.whispered = {}
				B.Answer("Zed-Realm#21", "done")
				eq(Answers(), 1, "done: at once")
				for _ = 1, 30 do
					w.clock = w.clock + 60; Census()
					Ask(21, 10)
				end
				eq(Answers(), 2, "once more at his next ask, then never again")
				-- One who logged off just after his ask: the click's whisper never reaches him, and his
				-- next ask, a day later, is answered (once).
				Ask(23, 10)
				w.clock = w.clock + 5 * 60
				w.whispered = {}
				B.Answer("Zed-Realm#23", "declined")
				eq(Answers(), 1, "heard lately: whispered at the click")
				w.clock = w.clock + 86400; Census()
				w.whispered = {}
				Ask(23, 10); Ask(23, 10)
				eq(Answers(), 1, "his next ask: declined, once")
				assert(w.whispered[#w.whispered].msg == "TO~23~x", w.whispered[#w.whispered].msg)
				eq(B.ANSWER_GAP, 7.5 * 60, "(the pages' 7.5 minutes: half a requester's REQUEST_AGAIN)")
				Pages(function(path, doc)
					assert(doc:find("answers an open request once every 7.5 minutes at most while nothing changed, a closed one never again once its asker was told", 1, true), path)
				end)
			end)
			ns.After, ns.rdb.guilds["Olympus Zeus"] = saved.after, saved.zeus
			ns.Bank.Reset()
			if not ok then error(err, 0) end
		end)
	end)
end
---------------------------------------------------------------------------
-- 1.1 (Konig's review of the key rotation, #45): the King's new key is whispered only to the
-- Lords and Captains his own /who saw in their guild (the server's word), never to names the
-- census alone gives (two characters on the leaked channel can report themselves a real guild's
-- Lord and Captain).
---------------------------------------------------------------------------
do
	local KY = ns.Keys
	local function Page(lines)
		local out = {}
		for _, l in ipairs(lines) do out[#out + 1] = tostring(l.text) end
		return table.concat(out, "\n")
	end
	local function LineWith(lines, text)
		for _, l in ipairs(lines) do if tostring(l.text):find(text, 1, true) then return l end end
		return nil
	end
	local function Whispered(w)
		local out = {}
		for _, x in ipairs(w.whispered) do if x.msg:sub(1, 3) == "K3~" then out[#out + 1] = x.to end end
		table.sort(out)
		return table.concat(out, ",")
	end
	-- The King's client with a stand-in of the game's /who (WithWho: GetTime is its clock) and the
	-- Throne (WithThrone). The census: <Olympus Zeus>, its Lord Zed and Captain Zeus Cap online;
	-- <Olympus II>, a real guild (his /who saw it), reported by two characters of the leaked
	-- channel alone, each naming the other its Lord or Captain (two senders: the census believes
	-- them). A whisper leaves at once (Comm's queue says so: done(true)).
	local function WithRotation(fn)
		WithWho(function(server)
			WithThrone(function(w, K)
				local saved = { key = ns.rdb.realmKey, epoch = ns.rdb.keyEpoch, rot = ns.rdb.keyRotation, retired = ns.rdb.keyRetired,
					join = ns.Comm.JoinChannel, log = ns.db.log }
				local ok, err = pcall(function()
					ns.rdb.realmKey, ns.rdb.keyEpoch, ns.rdb.keyRotation, ns.rdb.keyRetired = nil, nil, nil, nil
					ns.db.log = {}
					KY.Reset()
					ns.Comm.JoinChannel = function() end
					local record = ns.Comm.Whisper
					ns.Comm.Whisper = function(to, msg, key, urgent, logged, done)
						record(to, msg, key, urgent)
						if done then done(true) end
					end
					ns.rdb.seen = { ["Olympus Zeus"] = { online = 9, t = w.clock }, ["Olympus II"] = { online = 40, t = w.clock } }
					local G = ns.rdb.guilds
					G["Olympus Zeus"] = Vouched({ total = 100, online = 9, zones = {}, t = w.clock, leader = "Zed", leaderOnline = true, realm = "Realm",
						officers = { { name = "Zeus Cap", online = true, days = 0 } } }, "W3-Realm", "W4-Realm")
					G["Olympus II"] = Vouched({ total = 300, online = 40, zones = {}, t = w.clock, leader = "Leaker One", leaderOnline = true, realm = "Realm",
						officers = { { name = "Leaker Two", online = true, days = 0 } } }, "Leaker One-Realm", "Leaker Two-Realm")
					fn(w, K, server)
				end)
				ns.rdb.realmKey, ns.rdb.keyEpoch, ns.rdb.keyRotation, ns.rdb.keyRetired = saved.key, saved.epoch, saved.rot, saved.retired
				ns.Comm.JoinChannel, ns.db.log = saved.join, saved.log
				KY.Reset()
				if not ok then error(err, 0) end
			end)
		end)
	end

	test("1.1 key rotation, Konig's review: two characters who call themselves a real guild's Lord and Captain in the census get no key; those the King's own /who saw in their guild do", function()
		WithRotation(function(w, K, server)
			AsKing()
			eq(ns.Data.KnownRank("Leaker One-Realm", "Olympus II"), 0, "the census believes them")
			eq(ns.Data.KnownRank("Leaker Two-Realm", "Olympus II"), 1)
			-- His /who lists Olympus Zeus's two in it, and the two leakers where they really are.
			eq(ns.Who.Search(true), true)
			server.Answer({ { "Zed", "Olympus Zeus", 60, "WARRIOR" }, { "Zeus Cap", "Olympus Zeus", 60, "MAGE" },
				{ "Leaker One", "Leakers Club", 60, "ROGUE" }, { "Leaker Two", "", 60, "ROGUE" } })
			server.Run(ns.Who.SETTLE)
			eq(KY.Rotate(), true)
			-- Both guilds checked (his /who saw a guild of each name): the census's two show, not counted.
			K.Show("home")
			local page = Page((K.Build()))
			assert(page:find("<Olympus II>  0 · " .. ns.L.KEY_GUILD_SEEN .. " · " .. ns.L.KEY_GUILD_WAITING:format(2), 1, true), page)
			assert(page:find("<Olympus Zeus>  2 · " .. ns.L.KEY_GUILD_SEEN, 1, true), page)
			eq(KY.Start(), true)
			eq(Whispered(w), "Zed-Realm,Zeus Cap-Realm", "never a name the census alone gives")
			-- His /who of that guild (a click on its row, twice: unchecked, then checked again) lists
			-- its players, not them: still nothing for them, now or on a later round.
			local row = LineWith(K.Build(), "<Olympus II>")
			row.onClick()
			server.clock = server.clock + ns.Who.COOLDOWN + 1
			LineWith(K.Build(), "<Olympus II>").onClick()
			eq(server.sent[#server.sent], 'g-"Olympus II"', "his /who of the guild clicked")
			server.Answer({ { "Real Member", "Olympus II", 40, "PRIEST" }, { "Other Member", "Olympus II", 30, "MAGE" } })
			server.Run(ns.Who.SETTLE)
			-- The /who line then asks for each by name (he may have logged in since): the server
			-- shows him in his own guild.
			server.clock = server.clock + ns.Who.COOLDOWN + 1
			LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:format(2)).onClick()
			eq(server.sent[#server.sent], 'n-"Leaker One"')
			server.Answer({ { "Leaker One", "Leakers Club", 60, "ROGUE" } })
			server.Run(ns.Who.SETTLE)
			w.clock = w.clock + 60
			KY.Tick()
			eq(Whispered(w), "Zed-Realm,Zeus Cap-Realm")
			eq(#KY.Targets(), 2)
			-- Nor when /who saw one of them in another guild long ago, or in that guild too long ago.
			assert(not KY.WhoSaw("Leaker One-Realm", "Olympus II"))
			-- (Both clocks move in the game: the /who's and the server's, by which the rotation keeps
			-- what his /who saw. The census stays fresh: only his /who is old.)
			server.clock, w.clock = server.clock + KY.WHO_FRESH + 1, w.clock + KY.WHO_FRESH + 1
			for _, g in pairs(ns.rdb.guilds) do
				g.t = w.clock
				for _, v in pairs(g.vouch or {}) do v.t = w.clock end
			end
			for _, s in pairs(ns.rdb.seen) do s.t = w.clock end
			assert(Page((K.Build())):find("<Olympus Zeus>  0 · " .. ns.L.KEY_GUILD_SEEN .. " · " .. ns.L.KEY_GUILD_WAITING:format(2), 1, true), Page((K.Build())))
			eq(#KY.Targets(), 0, "his /who of Zed and Zeus Cap is too old now")
		end)
	end)

	test("1.1 key rotation, Konig's review: the Throne's /who line asks the server about the Lords and Captains picked it has not seen, one search a click: their guild, then by name whom its answer did not list", function()
		WithRotation(function(w, K, server)
			AsKing()
			ns.rdb.seen["Olympus II"] = nil -- (the census alone names it: unchecked)
			eq(KY.Rotate(), true)
			K.Show("home")
			local page = Page((K.Build()))
			assert(page:find("<Olympus Zeus>  0 · " .. ns.L.KEY_GUILD_SEEN .. " · " .. ns.L.KEY_GUILD_WAITING:format(2), 1, true), page)
			local line = LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:format(2))
			assert(line and line.onClick, "the /who line: " .. page)
			-- Nothing is whispered to names his /who has not seen.
			eq(#KY.Targets(), 0)
			line.onClick()
			eq(server.sent[#server.sent], 'g-"Olympus Zeus"')
			-- 50 of its players online: Zed among them, not Zeus Cap (the answer is full).
			local rows = { { "Zed", "Olympus Zeus", 60, "WARRIOR" } }
			for i = 2, 50 do rows[i] = { "Zeus Soldier" .. string.char(96 + i % 26) .. string.char(97 + math.floor(i / 26)), "Olympus Zeus", 20, "MAGE" } end
			server.Answer(rows, 50)
			server.Run(ns.Who.SETTLE)
			assert(Page((K.Build())):find(ns.L.KEY_WHO_CONFIRM:format(1), 1, true), Page((K.Build())))
			-- A click within the cooldown searches nothing; the next one asks for him by name.
			local sent = #server.sent
			LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:format(1)).onClick()
			eq(#server.sent, sent, "one search each 10 seconds")
			server.clock = server.clock + ns.Who.COOLDOWN + 1
			LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:format(1)).onClick()
			eq(server.sent[#server.sent], 'n-"Zeus Cap"')
			server.Answer({ { "Zeus Cap", "Olympus Zeus", 60, "MAGE" } })
			server.Run(ns.Who.SETTLE)
			eq(LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:sub(1, 12)), nil, "nobody left to look for")
			eq(KY.Start(), true)
			eq(Whispered(w), "Zed-Realm,Zeus Cap-Realm")
		end)
	end)

	test("1.1 key rotation, Konig's review, with the gamepad UI: the /who line sends no quiet search (a plain one of a guild picked, 1.1 review); what the census's Refresh lists counts; no popup", function()
		WithUI(function()
			LoadUI()
			WithGamepadUI(true, function(game)
				WithRotation(function(w, K, server)
					AsKing()
					eq(KY.Rotate(), true)
					K.Show("home")
					LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:format(4)).onClick()
					-- (1.1 review: it searched nothing there, and the King could confirm almost nobody;
					-- now a plain /who of a guild picked, as Refresh: see the review's tests at the end.)
					eq(table.concat(server.sent, "|"), 'g-"Olympus II"', "no quiet /who with the gamepad UI: a plain one")
					eq(#game.shown, 0); eq(#w.popups, 0)
					-- The census's Refresh: a plain /who of his, its answer in the game's list.
					server.clock = server.clock + ns.Who.COOLDOWN + 1
					eq(ns.Who.Search(), true)
					server.Answer({ { "Zed", "Olympus Zeus", 60, "WARRIOR" }, { "Zeus Cap", "Olympus Zeus", 60, "MAGE" } })
					server.Run(ns.Who.SETTLE)
					eq(KY.Start(), true)
					eq(Whispered(w), "Zed-Realm,Zeus Cap-Realm")
				end)
			end)
		end)
	end)

	test("1.1 key rotation: a guild the King's /who saw (checked for him) that he unchecks gets nothing, and is checked again with his next click", function()
		WithRotation(function(w, K, server)
			AsKing()
			eq(ns.Who.Search(true), true)
			server.Answer({ { "Zed", "Olympus Zeus", 60, "WARRIOR" }, { "Zeus Cap", "Olympus Zeus", 60, "MAGE" } })
			server.Run(ns.Who.SETTLE)
			eq(KY.Rotate(), true)
			K.Show("home")
			LineWith(K.Build(), "<Olympus Zeus>").onClick()
			local row = LineWith(K.Build(), "<Olympus Zeus>")
			assert(tostring(row.text):find("ReadyCheck-NotReady", 1, true), tostring(row.text))
			eq(#KY.Targets(), 0, "unchecked: nobody of it")
			eq(KY.Start(), true)
			eq(Whispered(w), "", "nothing for the guild he unchecked")
			-- His next click checks it again: from the next round.
			LineWith(K.Build(), "<Olympus Zeus>").onClick()
			w.clock = w.clock + 60
			KY.Tick()
			eq(Whispered(w), "Zed-Realm,Zeus Cap-Realm")
		end)
	end)

	test("1.1 key rotation, Konig's review: the King's Throne counts an acknowledgement (K4) only from a name his client whispered the key to", function()
		WithRotation(function(w, K, server)
			AsKing()
			eq(ns.Who.Search(true), true)
			server.Answer({ { "Zed", "Olympus Zeus", 60, "WARRIOR" }, { "Zeus Cap", "Olympus Zeus", 60, "MAGE" } })
			server.Run(ns.Who.SETTLE)
			eq(KY.Rotate(), true)
			local rot = KY.Rotation()
			local ack = ("K4~%d~%s"):format(rot.at, "Olympus II")
			-- Before anything left: nobody's answer counts.
			KY.HandleAck("WHISPER", "Zed-Realm", ("K4~%d~Olympus Zeus"):format(rot.at))
			eq(KY.Stats().acks, 0, "not whispered yet")
			eq(KY.Start(), true)
			eq(Whispered(w), "Zed-Realm,Zeus Cap-Realm")
			K.Show("home")
			assert(Page((K.Build())):find(ns.L.KEY_ROTATING:format(2, 0, 0), 1, true), Page((K.Build())))
			-- The census's two "Lords" of Olympus II and anyone else, with the right epoch: not counted.
			KY.HandleAck("WHISPER", "Leaker One-Realm", ack)
			KY.HandleAck("WHISPER", "Leaker Two-Realm", ack)
			KY.HandleAck("WHISPER", "Some Soldier-Realm", ("K4~%d~Olympus Made Up"):format(rot.at))
			eq(KY.Stats().acks, 0)
			assert(Page((K.Build())):find(ns.L.KEY_ROTATING:format(2, 0, 0), 1, true), Page((K.Build())))
			-- Zed, whom it whispered: counted, once.
			KY.HandleAck("WHISPER", "Zed-Realm", ("K4~%d~Olympus Zeus"):format(rot.at))
			KY.HandleAck("WHISPER", "Zed-Realm", ("K4~%d~Olympus Zeus"):format(rot.at))
			eq(KY.Stats().acks, 1)
			assert(Page((K.Build())):find(ns.L.KEY_ROTATING:format(2, 1, 1), 1, true), Page((K.Build())))
			-- After he moves, the same count.
			eq(KY.Move(), true)
			assert(Page((K.Build())):find(ns.L.KEY_ROTATED_AGO:format(ns.Ago(rot.movedAt), 1, 1), 1, true), Page((K.Build())))
		end)
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
			assert(doc:find("the Throne says how many of those he whispered have it (an answer from anyone else is not counted)", 1, true), path)
		end
	end)

	test("1.1 key rotation, Konig's review: the Throne's new words in English and pt-BR; the README and the CurseForge page say only whom the King's /who saw in their guild get the key", function()
		local pt = { L = setmetatable({}, { __index = ns.L }) }
		local savedLocale = GetLocale
		GetLocale = function() return "ptBR" end
		local ok, err = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
		GetLocale = savedLocale
		if not ok then error(err, 0) end
		for _, k in ipairs({ "KEY_GUILD_WAIT_TIP", "KEY_GUILD_WAITING", "KEY_WHO_CONFIRM", "KEY_WHO_GAMEPAD", "KEY_GUILD_TIP", "KEY_PICK_HINT",
			"KEY_HAND_OUT_CONFIRM", "KEY_ROTATED", "KEY_ROTATE_TIP", "KEY_ROTATE_CONFIRM", "HELP_KEY_ROTATE" }) do
			local en, br = rawget(ns.L, k), rawget(pt.L, k)
			assert(type(en) == "string" and en:find("/who", 1, true), "English: " .. k)
			assert(type(br) == "string" and br ~= en and br:find("/who", 1, true), "pt-BR: " .. k)
			eq(select(2, br:gsub("%%[sd]", "")), select(2, en:gsub("%%[sd]", "")), "the same placeholders: " .. k)
		end
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
			eq(KY.WHO_FRESH, 30 * 60, "the docs say 30 minutes")
			for _, must in ipairs({ "confirms online and his own /who saw in that guild in the last 30 minutes", "a name the census alone gives gets nothing",
				"on the Throne's /who line", "the census's Refresh searches", "whom his own /who saw in that guild (a whisper from the King each)",
				"whispers the key only to the Lords and Captains his own /who saw in that very guild" }) do
				assert(doc:find(must, 1, true), path .. ": " .. must)
			end
			assert(not doc:find("The King alone: not his Steward or a Hand", 1, true), path .. ": his Steward rotates too")
		end
	end)
end

---------------------------------------------------------------------------
-- 1.1 (Konig's review of the key rotation's /who, #45): what the King's /who saw of the Lords and
-- Captains is kept with the rotation (a /reload, a relog or Who.lua's forgetting past SEEN_MAX
-- names no longer undoes it), and the Throne's /who line searches every guild picked before
-- any name, each name at most once in WHO_FRESH.
---------------------------------------------------------------------------
do
	local KY = ns.Keys
	local function LineWith(lines, text)
		for _, l in ipairs(lines) do if tostring(l.text):find(text, 1, true) then return l end end
		return nil
	end
	local function Whispered(w)
		local out = {}
		for _, x in ipairs(w.whispered) do if x.msg:sub(1, 3) == "K3~" then out[#out + 1] = x.to end end
		table.sort(out)
		return table.concat(out, ",")
	end
	local function Targets()
		local out = {}
		for _, t in ipairs(KY.Targets()) do out[#out + 1] = t.name end
		table.sort(out)
		return table.concat(out, ",")
	end
	-- The census's reports as just made: in these tests only what the King's /who saw ages.
	local function Fresh(w)
		for _, g in pairs(ns.rdb.guilds) do
			g.t = w.clock
			for _, v in pairs(g.vouch or {}) do v.t = w.clock end
		end
		for _, s in pairs(ns.rdb.seen) do s.t = w.clock end
	end
	-- The King's client with a stand-in of the game's /who (WithWho: GetTime is its clock) and the
	-- Throne (WithThrone; ns.Now, the server's clock here, is w.clock). The census: <Olympus Zeus>,
	-- its Lord Zed and Captain Zeus Cap online (two senders: the census believes them), checked
	-- (his /who saw a guild of that name). A whisper leaves at once (done(true)).
	local function WithKing(fn)
		WithWho(function(server)
			WithThrone(function(w, K)
				local saved = { key = ns.rdb.realmKey, epoch = ns.rdb.keyEpoch, rot = ns.rdb.keyRotation, retired = ns.rdb.keyRetired,
					join = ns.Comm.JoinChannel, log = ns.db.log }
				local ok, err = pcall(function()
					ns.rdb.realmKey, ns.rdb.keyEpoch, ns.rdb.keyRotation, ns.rdb.keyRetired = nil, nil, nil, nil
					ns.db.log = {}
					KY.Reset()
					ns.Comm.JoinChannel = function() end
					local record = ns.Comm.Whisper
					ns.Comm.Whisper = function(to, msg, key, urgent, logged, done)
						record(to, msg, key, urgent)
						if done then done(true) end
					end
					ns.rdb.guilds["Olympus II"] = nil
					ns.rdb.seen = { ["Olympus Zeus"] = { online = 9, t = w.clock } }
					ns.rdb.guilds["Olympus Zeus"] = Vouched({ total = 100, online = 9, zones = {}, t = w.clock, leader = "Zed", leaderOnline = true, realm = "Realm",
						officers = { { name = "Zeus Cap", online = true, days = 0 } } }, "W3-Realm", "W4-Realm")
					AsKing()
					fn(w, K, server)
				end)
				ns.rdb.realmKey, ns.rdb.keyEpoch, ns.rdb.keyRotation, ns.rdb.keyRetired = saved.key, saved.epoch, saved.rot, saved.retired
				ns.Comm.JoinChannel, ns.db.log = saved.join, saved.log
				KY.Reset()
				if not ok then error(err, 0) end
			end)
		end)
	end
	-- A /reload (or a relog): Who.lua starts empty, and Keys' LOGIN handler forgets the old send queue.
	local function Reload()
		ns.Who.Reset()
		KY.Rotation().queued = {}
	end

	test("1.1 key rotation, Konig's review: after a /reload during the hand-out, the Lords and Captains the King's /who saw (before he rotated, or since) whose whisper never left are whispered again, and he does not move while they wait", function()
		WithKing(function(w, K, server)
			-- His /who before he rotates lists Zed in Olympus Zeus (a full answer: not Zeus Cap).
			eq(ns.Who.Search(true), true)
			server.Answer({ { "Zed", "Olympus Zeus", 60, "WARRIOR" } })
			server.Run(ns.Who.SETTLE)
			eq(KY.Rotate(), true)
			-- Then the Throne's /who line searches Olympus Zeus: a full answer, Zeus Cap in it, not Zed.
			K.Show("home")
			server.clock = server.clock + ns.Who.COOLDOWN + 1
			LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:format(1)).onClick()
			eq(server.sent[#server.sent], 'g-"Olympus Zeus"')
			local rows = { { "Zeus Cap", "Olympus Zeus", 60, "MAGE" } }
			for i = 2, 50 do rows[i] = { "Zeus Soldier" .. i, "Olympus Zeus", 20, "MAGE" } end
			server.Answer(rows, 60)
			server.Run(ns.Who.SETTLE)
			-- A long send queue: the whispers wait there, none leaves before the /reload.
			ns.Comm.Whisper = function(to, msg) w.whispered[#w.whispered + 1] = { to = to, msg = msg } end
			eq(KY.Start(), true)
			eq(Whispered(w), "Zed-Realm,Zeus Cap-Realm", "queued")
			Reload()
			w.whispered = {}
			w.clock = w.clock + 60
			Fresh(w)
			KY.Tick()
			eq(Whispered(w), "Zed-Realm,Zeus Cap-Realm", "handed again after the /reload")
			eq(KY.Waiting(), 2)
			-- The grace is over, their whisper still waits: he does not move yet...
			Reload()
			w.clock = KY.Rotation().till + 1
			Fresh(w)
			KY.Tick()
			eq(KY.Rotation().moved, nil, "two picked still wait for their whisper")
			-- ...until GRACE_MORE is over; what his /who saw goes with the hand-out.
			w.clock = KY.Rotation().till + KY.GRACE_MORE
			Fresh(w)
			KY.Tick()
			eq(KY.Rotation().moved, true)
			eq(KY.Rotation().saw, nil)
		end)
	end)

	test("1.1 key rotation, Konig's review: the rotation's record of the King's /who follows its newest answer: a Lord it later lists in another guild is no longer whispered, after a /reload too", function()
		WithKing(function(w, K, server)
			eq(KY.Rotate(), true)
			eq(ns.Who.Search(true), true)
			server.Answer({ { "Zed", "Olympus Zeus", 60, "WARRIOR" }, { "Zeus Cap", "Olympus Zeus", 60, "MAGE" } })
			server.Run(ns.Who.SETTLE)
			Reload()
			eq(Targets(), "Zed-Realm,Zeus Cap-Realm", "kept through the /reload")
			-- He left it since: a /who by name lists him in another guild (the census still names him).
			server.clock = server.clock + ns.Who.COOLDOWN + 1
			eq(ns.Who.Search(true, nil, "Zed"), true)
			server.Answer({ { "Zed", "Leakers Club", 60, "WARRIOR" } })
			server.Run(ns.Who.SETTLE)
			eq(Targets(), "Zeus Cap-Realm")
			Reload()
			eq(Targets(), "Zeus Cap-Realm", "after a /reload too")
			eq(KY.Start(), true)
			eq(Whispered(w), "Zeus Cap-Realm")
		end)
	end)

	test("1.1 key rotation, Konig's review: made-up Captains in a real guild's census don't keep the Throne's /who line from the next guild; each name is asked once", function()
		WithKing(function(w, K, server)
			-- <Olympus II>: a real guild (his /who saw it), its census the two leakers' alone: they name
			-- 8 made-up Captains online, and a big total so it sorts first.
			local offs = { { name = "Leaker Two", online = true, days = 0 } }
			for i = 1, 8 do offs[#offs + 1] = { name = "Ghost" .. string.char(96 + i), online = true, days = 0 } end
			ns.rdb.guilds["Olympus II"] = Vouched({ total = 900, online = 40, zones = {}, t = w.clock, leader = "Leaker One", leaderOnline = true, realm = "Realm",
				officers = offs }, "Leaker One-Realm", "Leaker Two-Realm")
			ns.rdb.seen["Olympus II"] = { online = 40, t = w.clock }
			eq(KY.Rotate(), true)
			eq(KY.Candidates()[1].guild, "Olympus II", "sorted first")
			K.Show("home")
			-- His click on the /who line each 11 seconds, each search answered as the server would.
			local function Click()
				server.clock, w.clock = server.clock + ns.Who.COOLDOWN + 1, w.clock + ns.Who.COOLDOWN + 1
				Fresh(w)
				local line = LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:sub(1, 12))
				local before = #server.sent
				if line then line.onClick() end
				if #server.sent == before then return nil end
				local q = server.sent[#server.sent]
				if q == 'g-"Olympus Zeus"' then
					server.Answer({ { "Zed", "Olympus Zeus", 60, "WARRIOR" }, { "Zeus Cap", "Olympus Zeus", 60, "MAGE" } })
				elseif q == 'g-"Olympus II"' then
					server.Answer({ { "Real Member", "Olympus II", 40, "PRIEST" } })
				else
					server.Answer({}) -- a made-up name: nobody
				end
				server.Run(ns.Who.SETTLE)
				return q
			end
			eq(Click(), 'g-"Olympus II"')
			eq(Click(), 'g-"Olympus Zeus"', "the next guild's search before any name")
			eq(Targets(), "Zed-Realm,Zeus Cap-Realm")
			-- Then Olympus II's ten by name, each once in 11 minutes of clicks.
			local byName = {}
			for _ = 1, 60 do
				local q = Click()
				if q then byName[#byName + 1] = q end
			end
			eq(table.concat(byName, " "), 'n-"Leaker One" n-"Leaker Two" n-"Ghosta" n-"Ghostb" n-"Ghostc" n-"Ghostd" n-"Ghoste" n-"Ghostf" n-"Ghostg" n-"Ghosth"')
			-- His clicks on the guild row (unchecked, checked again) ask no name a second time either.
			local sent = #server.sent
			LineWith(K.Build(), "<Olympus II>").onClick()
			server.clock = server.clock + ns.Who.COOLDOWN + 1
			LineWith(K.Build(), "<Olympus II>").onClick()
			eq(#server.sent, sent)
			eq(KY.Start(), true)
			eq(Whispered(w), "Zed-Realm,Zeus Cap-Realm")
		end)
	end)

	test("1.1 key rotation, Konig's review, at the army's scale: his /who of 46 guilds of 50 players (more than Who.lua keeps) confirms every Lord and Captain with one search a guild, and the census's later searches don't undo it", function()
		WithKing(function(w, K, server)
			local function Tag(i) return string.char(65 + math.floor(i / 26)) .. string.char(97 + i % 26) end
			local lords = { ["Olympus Zeus"] = { "Zed", "Zeus Cap" } }
			for i = 1, 45 do
				local guild = "Olympus " .. Tag(i)
				ns.rdb.guilds[guild] = Vouched({ total = 100, online = 60, zones = {}, t = w.clock, leader = "Lord" .. Tag(i), leaderOnline = true, realm = "Realm",
					officers = { { name = "Cap" .. Tag(i), online = true, days = 0 } } }, "Wa" .. i .. "-Realm", "Wb" .. i .. "-Realm")
				ns.rdb.seen[guild] = { online = 60, t = w.clock }
				lords[guild] = { "Lord" .. Tag(i), "Cap" .. Tag(i) }
			end
			eq(KY.Rotate(), true)
			K.Show("home")
			local listed, first, last = 0, nil, nil
			for click = 1, 46 do
				server.clock = server.clock + ns.Who.COOLDOWN + 1
				local before = #server.sent
				LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:sub(1, 12)).onClick()
				eq(#server.sent, before + 1, "one search a click")
				local guild = server.sent[#server.sent]:match('^g%-"(.*)"$')
				assert(guild and lords[guild], "click " .. click .. ", a guild's search: " .. server.sent[#server.sent])
				first, last = first or guild, guild
				-- The server lists 50 at most: its Lord and Captain, and 48 more.
				local rows = { { lords[guild][1], guild, 60, "WARRIOR" }, { lords[guild][2], guild, 60, "MAGE" } }
				for j = 3, 50 do rows[j] = { "S" .. click .. "x" .. j, guild, 30, "MAGE" } end
				server.Answer(rows, 60)
				server.Run(ns.Who.SETTLE)
				listed = listed + #rows
			end
			assert(listed > ns.Who.SEEN_MAX, "more players than Who.lua keeps")
			eq(ns.Who.SeenGuild(lords[first][1]), nil, "Who.lua forgot the first guild's")
			-- Right after the last guild's answer, the census's own searches (his other clicks in the
			-- window) list 2050 more: Who.lua forgets the last guild's too, the rotation does not.
			for i = 1, 41 do
				server.clock = server.clock + ns.Who.COOLDOWN + 1
				eq(ns.Who.Search(true), true)
				local rows = {}
				for j = 1, 50 do rows[j] = { "T" .. i .. "x" .. j, "Horde Pals", 30, "MAGE" } end
				server.Answer(rows, 50)
				server.Run(ns.Who.SETTLE)
			end
			eq(ns.Who.SeenGuild(lords[last][1]), nil, "Who.lua forgot the last guild's")
			eq(#KY.Targets(), 92, "every Lord and Captain his /who listed in his guild")
			eq(LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:sub(1, 12)), nil, "nobody left to look for")
		end)
	end)

	test("1.1 key rotation, Konig's review: the README and the CurseForge page say the /who line searches every guild first, each name once in 30 minutes, and that what his /who saw survives a /reload", function()
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
			for _, must in ipairs({ "every guild picked first, then each of them by name, at most once in 30 minutes",
				"What his /who saw is kept with the rotation, through a /reload or relog too" }) do
				assert(doc:find(must, 1, true), path .. ": " .. must)
			end
		end
	end)
end

---------------------------------------------------------------------------
-- 1.1 (the internal review of Konig's fixes to the pinned line): the pins taken down are no
-- longer anyone's to push out of a client's memory, a Hand the moderators took off takes no one
-- else's line down, and the Spanish, French and German lines say who pins for whom. Each test
-- fails on the code before its fix.
---------------------------------------------------------------------------
do
	local KING = "Asmongold Asmongler-Realm"
	-- The pinned line's bench, as its own tests run it (WithThrone): sends recorded with their
	-- logged flag, the channel ready, no net-off word yet; the pin, what it saved, the net-off
	-- words, our roster and the memory's bounds put back after.
	local function PinBench(fn)
		WithThrone(function(w, K)
			local C, M = ns.Channels, ns.Moderation
			local saved = { ready = ns.Comm.ChannelReady, send = ns.Comm.Send, info = C_ChatInfo, byName = ns.Roster.byName,
				netoff = ns.rdb.netoff, chat = ns.db.addonChat, keep = C.PIN_DOWN_KEEP, each = C.PIN_DOWN_EACH }
			local sent = {}
			local ok, err = pcall(function()
				C.ResetPin()
				C_ChatInfo = nil
				ns.rdb.netoff = nil
				M.Reset()
				ns.db.addonChat = true
				ns.Comm.ChannelReady = function() return true end
				ns.Comm.Send = function(dist, msg, key, urgent, logged) sent[#sent + 1] = { dist = dist, msg = msg, key = key, logged = logged } end
				fn(w, K, sent, C, M)
			end)
			ns.Comm.ChannelReady, ns.Comm.Send, C_ChatInfo, ns.Roster.byName = saved.ready, saved.send, saved.info, saved.byName
			ns.rdb.netoff, ns.db.addonChat, C.PIN_DOWN_KEEP, C.PIN_DOWN_EACH = saved.netoff, saved.chat, saved.keep, saved.each
			M.Reset(); M.Load()
			C.ResetPin()
			if not ok then error(err, 0) end
		end)
	end
	-- How many pins of this setter ("name-realm#") the client remembers taken down.
	local function Remembered(prefix)
		local n = 0
		for k in pairs(ns.rdb.pinsDown or {}) do if k:sub(1, #prefix) == prefix then n = n + 1 end end
		return n
	end
	-- A member of <Olympus Zeus> (Zed its master) who reads the channel too; Helper and Aide the King's Hands.
	local function AsMate(K)
		K.HandleCommand("CHANNEL", KING, "T1~H~5~Olympus~Helper-Realm,Aide-Realm")
		GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
		ns.me = "Mate-Realm"
		ns.Roster.byName = { ["Zed-Realm"] = 0, ["Mate-Realm"] = 3, ["Helper-Realm"] = 3 }
	end
	local function PinLineWith(text)
		for _, l in ipairs(ns.Views.Build("realm")) do if type(l.text) == "string" and l.text:find(text, 1, true) then return l end end
		return nil
	end

	-- "A takedown naming a pin this client does not hold runs Remember with no rate limit ... any
	-- sender PinRank accepts can evict every remembered takedown with 200 takedowns of fresh ids,
	-- and a pin the King took down comes back at its setter's next repeat."
	test("1.1 pinned line (review of Konig's fixes): a burst of takedowns naming pins nobody holds, from a guild master or a Hand, never brings back a line the King took down", function()
		PinBench(function(w, K, sent, C)
			AsMate(K)
			eq(C.HandlePin("CHANNEL", "Helper-Realm", "N1~9~Olympus~7200~0~A Hand's line"), true)
			w.clock = w.clock + 60
			eq(select(2, C.HandlePin("CHANNEL", KING, "N1~9~Olympus~0~0~")), "down")
			eq(C.Pin(), nil)
			-- Zed over guild chat and Aide on the channel: 250 takedowns each, of made-up ids, at once.
			for i = 1, 250 do
				eq(select(2, C.HandlePin("GUILD", "Zed-Realm", ("N1~%d~Olympus Zeus~0~0~"):format(1000 + i))), "nothing")
				eq(select(2, C.HandlePin("CHANNEL", "Aide-Realm", ("N1~%d~Olympus~0~0~"):format(2000 + i))), "nothing")
			end
			-- Helper's addon missed the King's takedown and repeats his line: it stays down.
			w.clock = w.clock + C.PIN_RESEND
			eq(select(2, C.HandlePin("CHANNEL", "Helper-Realm", "N1~9~Olympus~6840~360~A Hand's line")), "downed")
			eq(C.Pin(), nil)
			eq(PinLineWith("A Hand's line"), nil, "not back on the Realm")
			eq(Remembered("zed-realm#"), 1, "one a minute at most from each")
			eq(Remembered("aide-realm#"), 1)
		end)
	end)

	test("1.1 pinned line (review of Konig's fixes): paced a minute apart, a sender's takedowns push out only his own: never the King's, nor a Hand's of a guild master's line", function()
		PinBench(function(w, K, sent, C)
			C.PIN_DOWN_KEEP = 12
			AsMate(K)
			-- The King takes a Hand's line down; a Hand takes Zed's down (over guild chat, where it went).
			eq(C.HandlePin("CHANNEL", "Helper-Realm", "N1~9~Olympus~7200~0~A Hand's line"), true)
			w.clock = w.clock + 60
			eq(select(2, C.HandlePin("CHANNEL", KING, "N1~9~Olympus~0~0~")), "down")
			eq(C.HandlePin("GUILD", "Zed-Realm", "N1~42~Olympus Zeus~7200~0~Raid at nine"), true)
			w.clock = w.clock + 60
			eq(select(2, C.HandlePin("GUILD", "Helper-Realm", "N1~42~Olympus~0~0~")), "down")
			-- Aide (a Hand, as Helper) and Zed take down made-up pins of theirs, a minute apart, for half
			-- an hour (the King's addon repeating his list of Hands meanwhile).
			for i = 1, 30 do
				w.clock = w.clock + C.PIN_GAP
				if i % 10 == 0 then K.HandleCommand("CHANNEL", KING, "T1~H~5~Olympus~Helper-Realm,Aide-Realm") end
				eq(select(2, C.HandlePin("CHANNEL", "Aide-Realm", ("N1~%d~Olympus~0~0~"):format(2000 + i))), "nothing")
				eq(select(2, C.HandlePin("GUILD", "Zed-Realm", ("N1~%d~Olympus Zeus~0~0~"):format(1000 + i))), "nothing")
			end
			-- Both setters' addons missed the takedowns and repeat their lines: both stay down.
			w.clock = w.clock + C.PIN_RESEND
			eq(select(2, C.HandlePin("CHANNEL", "Helper-Realm", "N1~9~Olympus~5000~2200~A Hand's line")), "downed")
			eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~42~Olympus Zeus~5000~2200~Raid at nine")), "downed")
			eq(C.Pin(), nil)
			-- Aide's own: PIN_DOWN_EACH at most, his newest; the oldest he pushed out is his to pin again.
			eq(Remembered("aide-realm#"), C.PIN_DOWN_EACH)
			assert(ns.rdb.pinsDown["aide-realm#2030"], "his newest remembered")
			eq(C.HandlePin("CHANNEL", "Aide-Realm", "N1~2001~Olympus~7200~0~Aide's line"), true)
		end)
	end)

	test("1.1 pinned line (review of Konig's fixes): a sender's takedowns of pins this addon does not hold are remembered once a minute at most, and id 0 (it names no pin) never", function()
		PinBench(function(w, K, sent, C)
			AsMate(K)
			eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~501~Olympus Zeus~0~0~")), "nothing")
			w.clock = w.clock + 10
			eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~502~Olympus Zeus~0~0~")), "nothing")
			eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~0~Olympus Zeus~0~0~")), "nothing")
			assert(ns.rdb.pinsDown["zed-realm#501"], "the first remembered")
			eq(ns.rdb.pinsDown["zed-realm#502"], nil, "not a second within the minute")
			eq(ns.rdb.pinsDown["zed-realm#0"], nil, "id 0 names no pin")
			eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~501~Olympus Zeus~7000~200~Raid at nine")), "downed")
			w.clock = w.clock + C.PIN_GAP
			eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~503~Olympus Zeus~0~0~")), "nothing")
			assert(ns.rdb.pinsDown["zed-realm#503"], "a minute later: remembered")
			eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~503~Olympus Zeus~7000~200~Raid at ten")), "downed")
			eq(C.Pin(), nil)
		end)
	end)

	-- "A Hand the moderators took off can 'take down' a guild master's line, his client removes it
	-- and says it is down for everyone while every other client drops his takedown as netoff, and
	-- every later repeat makes his client send another dropped takedown (ResendDown)."
	test("1.1 pinned line (review of Konig's fixes): a Hand the moderators took off takes no one else's line down, sends nothing, and says no takedown again", function()
		PinBench(function(w, K, sent, C, M)
			local L = ns.L
			local function Word(off)
				w.clock = w.clock + 10
				M.Handle("CHANNEL", KING, ("O1~c~%s~%d~Helper-Realm~%s~%s"):format(off and "1" or "0", w.clock, KING, off and "spam" or ""))
			end
			K.HandleCommand("CHANNEL", KING, "T1~H~5~Olympus~Helper-Realm")
			-- Helper, a Hand and a member of <Olympus Zeus>, takes Zed's line down while he is on.
			GetGuildInfo = function() return "Olympus Zeus", "Member", 3 end
			ns.me = "Helper-Realm"
			ns.Roster.byName = { ["Zed-Realm"] = 0, ["Helper-Realm"] = 3 }
			eq(C.HandlePin("GUILD", "Zed-Realm", "N1~42~Olympus Zeus~7200~0~Raid at nine"), true)
			eq(C.TakeDownPin(), true)
			eq(#sent, 1)
			-- The moderators take him off.
			Word(true)
			local off = M.SelfOff()
			assert(off, "he is off")
			-- Zed's addon missed the takedown and repeats his line: not shown, and not answered (nobody would take it).
			w.clock = w.clock + C.PIN_RESEND
			eq(select(2, C.HandlePin("GUILD", "Zed-Realm", "N1~42~Olympus Zeus~6900~300~Raid at nine")), "downed")
			eq(#sent, 1, "no takedown said again")
			-- Zed's next line shows on Helper's screen: no click takes it down, and /oly pin off says why and sends nothing.
			eq(C.HandlePin("GUILD", "Zed-Realm", "N1~43~Olympus Zeus~7200~0~Raid at ten"), true)
			eq(C.CanTakeDown(), false)
			local line = PinLineWith("Raid at ten")
			assert(line, "shown")
			eq(line.onClick, nil, "no click takes it down")
			w.printed = {}
			eq(select(2, C.TakeDownPin()), "netoff")
			assert(Printed(w, M.YouText(off)), table.concat(w.printed, "\n"))
			eq(Printed(w, L.PIN_TAKEN_DOWN), false)
			eq(#sent, 1, "nothing sent")
			eq(C.Pin().text, "Raid at ten", "still shown here")
			w.printed = {}
			SlashCmdList.OLYMPUS("pin off")
			assert(Printed(w, M.YouText(off)), table.concat(w.printed, "\n"))
			eq(#sent, 1)
			-- Back on: he takes it down.
			Word(false)
			eq(C.CanTakeDown(), true)
			eq(C.TakeDownPin(), true)
			eq(#sent, 2); eq(sent[2].msg, "N1~43~Olympus~0~0~"); eq(sent[2].dist, "GUILD")
		end)
	end)

	-- "es/fr/de: HELP_PIN still carries the old rule (the guild masters pin a line for the army), and
	-- PIN_ADD_TIP there still speaks of Lords' pins being outranked."
	test("1.1 pinned line (review of Konig's fixes): the Spanish, French and German help and army pin tooltip say who pins for whom (or are left out, and the English shows)", function()
		local want = {
			deDE = { help = { "der König, seine Seneschalle und Hände für die Armee", "ein Gildenmeister für seine Gilde" }, tip = "über der eines Gildenmeisters", old = "Lords" },
			esES = { help = { "el Rey, sus Senescales y Manos para el ejército", "un maestro de hermandad para su hermandad" }, tip = "por delante de la de un maestro de hermandad", old = "Señores" },
			frFR = { help = { "le Roi, ses Sénéchaux et ses Mains pour l'armée", "un maître de guilde pour sa guilde" }, tip = "devant celle d'un maître de guilde", old = "Seigneurs" },
		}
		for file, lines in pairs(want) do
			-- The file's lines, as a game in that language loads them after Locales.lua.
			local lns, s = {}, nil
			local savedLocale = GetLocale
			GetLocale = function() return file end
			local ok, err = pcall(function()
				assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", lns)
				local real = lns.Locale
				lns.Locale = function(codes, strings) s = strings; return real(codes, strings) end
				assert(loadfile(ADDON_DIR .. "Locales/" .. file .. ".lua"))("Olympus", lns)
			end)
			GetLocale = savedLocale
			if not ok then error(err, 0) end
			assert(type(s) == "table", file .. " calls ns.Locale")
			if s.HELP_PIN then
				for _, must in ipairs(lines.help) do assert(s.HELP_PIN:find(must, 1, true), file .. " HELP_PIN: " .. s.HELP_PIN) end
			end
			if s.PIN_ADD_TIP then
				assert(s.PIN_ADD_TIP:find(lines.tip, 1, true), file .. " PIN_ADD_TIP: " .. s.PIN_ADD_TIP)
				assert(not s.PIN_ADD_TIP:find(lines.old, 1, true), file .. " PIN_ADD_TIP still speaks of Lords: " .. s.PIN_ADD_TIP)
			end
		end
	end)

	test("1.1 pinned line (review of Konig's fixes): the README and the CurseForge page say how the memory of the pins taken down is bounded, and that a net-off addon takes no one else's line down", function()
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
			for _, must in ipairs({ ("It remembers %d at most, and nobody's takedowns push a higher rank's out"):format(ns.Channels.PIN_DOWN_KEEP),
				"a takedown naming a pin it does not hold is remembered once a minute at most from each sender",
				("a sender's takedowns of his own pins %d at most"):format(ns.Channels.PIN_DOWN_EACH),
				"whose own addon pins nothing and takes no one else's line down",
				"when you take it down and again when its setter's addon repeats it, once a minute at most, never while the moderators have you off" }) do
				assert(doc:find(must, 1, true), path .. ": " .. must)
			end
		end
	end)
end
---------------------------------------------------------------------------
-- 1.1 review of Konig's fixes (net-off): a hidden setter's cancel of his own entry on the King's
-- week, the nudge for an entry whose setter is hidden, a hidden guild's entries after a /reload,
-- and the texts that say what the net-off drops. Each test fails on the code before its fix. One
-- function (the file's top level is near Lua's 200 locals).
---------------------------------------------------------------------------
;(function()
	local M = ns.Moderation
	local KING = "Asmongold Asmongler-Realm"
	local ROGUE = "Rogue Hand-Realm" -- a made-up Hand
	-- A net-off word as an issuer's client sends it.
	local function O1(kind, off, at, name, by, reason)
		return ("O1~%s~%s~%d~%s~%s~%s"):format(kind, off and "1" or "0", at, name, by, reason or "")
	end
	-- fn with no net-off word yet and a council of one (Test Councillor); all put back after.
	local function NoWords(fn)
		local saved = { council = ns.rdb.council, netoff = ns.rdb.netoff, info = C_ChatInfo }
		local ok, err = pcall(function()
			M.Reset()
			ns.rdb.netoff = nil
			ns.rdb.council = { at = 1, names = { ["test councillor"] = "Test Councillor" } }
			fn()
		end)
		ns.rdb.council, ns.rdb.netoff, C_ChatInfo = saved.council, saved.netoff, saved.info
		M.Reset()
		if not ok then error(err, 0) end
	end
	-- The King's word on a character or a guild, dated by the server's clock (the scene's own, else ns.Now).
	local function Clock() return ns.Data.ServerTime() or ns.Now() end
	local function Off(name, reason) M.Handle("CHANNEL", KING, O1("c", true, Clock(), name, KING, reason or "spam")) end
	local function Back(name) M.Handle("CHANNEL", KING, O1("c", false, Clock() + 1, name, KING, "")) end
	local function GuildOff(guild) M.Handle("CHANNEL", KING, O1("g", true, Clock(), guild, KING, "spam guild")) end
	local function GuildBack(guild) M.Handle("CHANNEL", KING, O1("g", false, Clock() + 1, guild, KING, "")) end
	local function Titles(W)
		local out = {}
		for _, e in ipairs(W.Entries()) do out[#out + 1] = e.title end
		return table.concat(out, ",")
	end

	test("1.1 review (net-off, item 1): a Hand the moderators took off still takes his own entry off the King's week: his client sends the cancel past Comm's backstop; anyone else's entry stays, the reason said", function()
		WithWeek(function(w, W, K)
			NoWords(function()
				AsSoldier("Watcher")
				K.HandleCommand("CHANNEL", KING, "T1~H~1~Olympus~Rogue Hand-Realm")
				K.HandleCommand("CHANNEL", KING, "T1~D~602~Olympus~" .. (3 * 86400) .. "~1~~Raid night")
				-- The rogue Hand's own client: his entry, set before the word.
				AsSoldier("Rogue Hand")
				eq(W.SetEntry("Sat 20:00 Rogue raid"), true)
				local mine
				for _, e in ipairs(W.Entries()) do if e.mine then mine = e end end
				Off(ROGUE, "abuse of the week")
				assert(M.SelfOff(), "his client knows he is off")
				local sent = #w.sent
				-- He takes it down: the cancel goes out, and Comm.Send's backstop lets it through.
				eq(W.Cancel(mine.id), true)
				local cancel = LastWeek(w)
				eq(cancel, ("T1~D~%d~Olympus II~0~0~~"):format(mine.id), "his cancel")
				eq(#w.sent, sent + 1)
				eq(M.Blocks(cancel), false, "not held")
				assert(Printed(w, ns.L.WEEK_CANCELLED:format("Rogue raid")))
				-- The King's entry: no client would take his cancel of it; it stays, and he is told why.
				w.printed = {}
				eq(W.Cancel(602), false)
				assert(W.Entry(602), "still on his week")
				assert(Printed(w, M.YouText(M.SelfOff())), "said why")
				assert(not Printed(w, ns.L.WEEK_CANCELLED:format("Raid night")), "not said cancelled")
				eq(#w.sent, sent + 1, "nothing more sent")
				-- Anything else of the week is still held: an entry, a repeat, a sheet.
				eq(M.Blocks("T1~D~9~Olympus II~3600~1~~Raid"), true, "an entry")
				eq(M.Blocks("T1~D~9~Olympus II~3600~0~~Raid"), true, "a repeat")
				eq(M.Blocks("T1~R~9~Olympus II~9:1:0:0:0~5"), true, "a sheet")
				-- Shown again: his cancels of anyone's go as before.
				Back(ROGUE)
				eq(M.SelfOff(), nil)
				eq(W.Cancel(602), true)
				eq(LastWeek(w), "T1~D~602~Olympus II~0~0~~")
			end)
		end)
	end)

	test("1.1 review (net-off, item 1): every client takes a hidden setter's cancel of his own entry, so it doesn't come back once he is shown again; never his cancel of another's entry, nor a new entry", function()
		WithWeek(function(w, W, K)
			NoWords(function()
				AsSoldier("Watcher")
				K.HandleCommand("CHANNEL", KING, "T1~H~1~Olympus~Rogue Hand-Realm")
				-- Two entries of his heard before the word, and the King's own.
				K.HandleCommand("CHANNEL", ROGUE, "T1~D~601~Olympus II~" .. (2 * 86400) .. "~1~~Taken down")
				K.HandleCommand("CHANNEL", ROGUE, "T1~D~604~Olympus II~" .. (3 * 86400) .. "~1~~Kept")
				K.HandleCommand("CHANNEL", KING, "T1~D~602~Olympus~" .. (3 * 86400) .. "~1~~Raid night")
				-- Our signup for the one he takes down.
				ns.rdb.signed = { [ns.me] = { [601] = { role = "T", at = w.clock + 2 * 86400, title = "Taken down", zone = "" } } }
				Off(ROGUE, "abuse of the week")
				eq(Titles(W), "Raid night", "his entries hidden")
				-- He takes his own down (his client lets it out): taken, our signup for it gone.
				K.HandleCommand("CHANNEL", ROGUE, "T1~D~601~Olympus II~0~0~~")
				eq(W.MySignup(601), nil, "our signup for it goes")
				-- His cancel of the King's entry, and a new entry of his: dropped as ever.
				K.HandleCommand("CHANNEL", ROGUE, "T1~D~602~Olympus II~0~0~~")
				K.HandleCommand("CHANNEL", ROGUE, "T1~D~605~Olympus II~" .. 86400 .. "~1~~After the word")
				eq(Titles(W), "Raid night", "the King's entry stays")
				-- His cancels (of nothing we hold) over more than an hour don't count as hearing him:
				-- his other entry, which his client can't repeat while he is off, isn't taken for stale.
				for i = 1, 3 do
					w.clock = w.clock + 3000
					K.HandleCommand("CHANNEL", KING, "T1~H~1~Olympus~Rogue Hand-Realm") -- (the King repeats his list)
					K.HandleCommand("CHANNEL", ROGUE, ("T1~D~%d~Olympus II~0~0~~"):format(700 + i))
					W.Tick()
				end
				-- Shown again: the entry he took down stays down; the other shows again.
				Back(ROGUE)
				eq(Titles(W), "Raid night,Kept", "not the entry he took down")
				eq(W.Entry(601), nil)
				-- A /reload after: still down (it left the week this client keeps).
				eq(#ns.rdb.weekHeard, 2)
				for _, e in ipairs(ns.rdb.weekHeard) do assert(e.id ~= 601, "not saved") end
			end)
		end)
	end)

	-- SavedVariables as a /reload leaves them: written out and read back, Lua's memory of the week
	-- and of the guilds senders named (Moderation's, for this session) gone; the words kept.
	-- `edit` changes what was saved first.
	local function SavedCopy(t)
		if type(t) ~= "table" then return t end
		local out = {}
		for k, v in pairs(t) do out[k] = SavedCopy(v) end
		return out
	end
	local function Reload(W, edit)
		local saved = SavedCopy({ week = ns.rdb.week, weekHeard = ns.rdb.weekHeard, signups = ns.rdb.signups, signed = ns.rdb.signed })
		if edit then edit(saved) end
		W.Reset()
		M.Reset()
		ns.rdb.week, ns.rdb.weekHeard, ns.rdb.signups, ns.rdb.signed = saved.week, saved.weekHeard, saved.signups, saved.signed
		W.Restore()
	end
	local GALE = "Gale Hand-Realm" -- a made-up Hand of another guild
	-- Watcher's client: two Hands' entries 2 days ahead (the rogue's, the other guild's a minute
	-- later), their sheets heard, and his signup for each. The clock of the first, the second.
	local function SignedBoth(w, W, K)
		AsSoldier("Watcher")
		K.HandleCommand("CHANNEL", KING, "T1~H~1~Olympus~Rogue Hand-Realm,Gale Hand-Realm")
		local t0 = w.clock
		K.HandleCommand("CHANNEL", ROGUE, "T1~D~601~Olympus II~" .. (2 * 86400) .. "~1~~Rogue raid")
		K.HandleCommand("CHANNEL", GALE, "T1~D~611~Olympus Gale~" .. (2 * 86400 + 60) .. "~1~~Gale raid")
		K.HandleCommand("CHANNEL", ROGUE, "T1~R~1~Olympus II~601:0:0:0:0~5")
		K.HandleCommand("CHANNEL", GALE, "T1~R~2~Olympus Gale~611:0:0:0:0~5")
		eq(W.Sign(601, "T"), true)
		w.clock = w.clock + W.SIGN_GAP
		eq(W.Sign(611, "H"), true)
		return t0 + 2 * 86400, t0 + 2 * 86400 + 60
	end
	local function Nudged(w, title) return Printed(w, title .. " in ") end

	test("1.1 review (net-off, item 2): no nudge for an entry we signed once its setter, or his guild, is off; shown again before it begins, it comes", function()
		WithWeek(function(w, W, K)
			NoWords(function()
				local at = SignedBoth(w, W, K)
				-- The King takes the rogue Hand, and the other Hand's guild, off.
				Off(ROGUE, "abuse of the week"); GuildOff("Olympus Gale")
				eq(Titles(W), "", "both entries hidden")
				-- Four minutes before: no line, no sound.
				w.printed, w.alerts = {}, {}
				w.clock = at - 240
				W.Remind()
				assert(not Nudged(w, "Rogue raid") and not Nudged(w, "Gale raid"), "no nudge: " .. table.concat(w.printed, " / "))
				eq(#w.alerts, 0, "no sound")
				-- The rogue shown again before it begins: his nudge comes (it wasn't spent), the other's not yet.
				Back(ROGUE)
				W.Remind()
				assert(Printed(w, ns.L.SIGN_SOON:format(W.RoleLabel("T"), "Rogue raid", 4, "")), "the rogue's entry")
				assert(not Nudged(w, "Gale raid"), "the guild still off")
				eq(#w.alerts, 1)
				GuildBack("Olympus Gale")
				W.Remind()
				assert(Nudged(w, "Gale raid"), "the guild back on")
				eq(#w.alerts, 2)
			end)
		end)
	end)

	test("1.1 review (net-off, item 2): after a /reload, the nudge from the signup alone (its entry not heard again) stays quiet too while its setter or his guild is off", function()
		WithWeek(function(w, W, K)
			NoWords(function()
				local at = SignedBoth(w, W, K)
				Off(ROGUE, "abuse of the week"); GuildOff("Olympus Gale")
				-- The /reload: the entries not kept (their setters' next repeats after the pull).
				Reload(W, function(saved) saved.weekHeard = nil end)
				eq(W.Entry(601), nil); eq(W.Entry(611), nil)
				w.printed, w.alerts = {}, {}
				w.clock = at - 240
				W.Remind()
				assert(not Nudged(w, "Rogue raid") and not Nudged(w, "Gale raid"), "no nudge: " .. table.concat(w.printed, " / "))
				eq(#w.alerts, 0, "no sound")
				Back(ROGUE); GuildBack("Olympus Gale")
				W.Remind()
				assert(Nudged(w, "Rogue raid") and Nudged(w, "Gale raid"), "both shown again")
				eq(#w.alerts, 2)
			end)
		end)
	end)

	test("1.1 review (net-off, item 3): after a /reload, the entries of a Hand whose guild is off stay hidden until it is back on: the guild his messages named is kept with them", function()
		WithWeek(function(w, W, K)
			NoWords(function()
				AsSoldier("Watcher")
				K.HandleCommand("CHANNEL", KING, "T1~H~1~Olympus~Gale Hand-Realm")
				K.HandleCommand("CHANNEL", GALE, "T1~D~611~Olympus Gale~" .. (2 * 86400) .. "~1~~Gale raid")
				K.HandleCommand("CHANNEL", KING, "T1~D~602~Olympus~" .. (3 * 86400) .. "~1~~Raid night")
				GuildOff("Olympus Gale")
				eq(Titles(W), "Raid night", "hidden")
				-- The /reload: this session's memory of the guild his messages named is gone.
				Reload(W)
				eq(Titles(W), "Raid night", "still hidden after the /reload")
				Reload(W)
				eq(Titles(W), "Raid night", "and after the next")
				GuildBack("Olympus Gale")
				eq(Titles(W), "Gale raid,Raid night", "back on: it shows again")
				-- Kept without it (an earlier build, or an edited file: never trusted): his next repeat names it again.
				Reload(W, function(saved)
					for _, e in ipairs(saved.weekHeard) do if e.id == 611 then e.guild = { "not a name" } end end
				end)
				eq(Titles(W), "Gale raid,Raid night", "kept, the bad guild left out")
				K.HandleCommand("CHANNEL", GALE, "T1~D~611~Olympus Gale~" .. (2 * 86400 - 600) .. "~0~~Gale raid")
				M.Handle("CHANNEL", KING, O1("g", true, Clock() + 2, "Olympus Gale", KING, "spam guild again"))
				Reload(W)
				eq(Titles(W), "Raid night", "hidden again after the /reload")
			end)
		end)
	end)

	test("1.1 review (net-off, item 4): what a hidden player or guild reads names every surface the net-off drops (the week, the Board, the crafter board, the pinned line, the elite border and nameplate mark), in English and pt-BR; es/fr/de say nothing of it; so do the README and the CurseForge page", function()
		local pt = { L = setmetatable({}, { __index = function() return nil end }) }
		local savedLocale = GetLocale
		GetLocale = function() return "ptBR" end
		local ok, err = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
		GetLocale = savedLocale
		if not ok then error(err, 0) end
		local keys = { "NETOFF_YOU", "NETOFF_YOU_BACK", "NETOFF_YOUR_GUILD", "NETOFF_GUILD_TIP", "NETOFF_GUILD_OFF" }
		local en = { "week", "Board", "crafter", "pinned line", "elite border", "nameplate mark", "decrees", "hop", "Vox", "chat" }
		local br = { "semana", "Mural", "artes", "linha fixada", "borda", "placa", "decretos", "saltos", "Vox", "chats" }
		for _, key in ipairs(keys) do
			for _, word in ipairs(en) do assert(ns.L[key]:find(word, 1, true), key .. " (English): " .. word) end
			for _, word in ipairs(br) do assert(rawget(pt.L, key):find(word, 1, true), key .. " (pt-BR): " .. word) end
		end
		-- (es/fr/de have none of them: the English shows there.)
		for _, lang in ipairs({ "esES", "frFR", "deDE" }) do
			local src = assert(ReadFile(ADDON_DIR .. "Locales/" .. lang .. ".lua"))
			for _, key in ipairs(keys) do assert(not src:find("L." .. key .. " ", 1, true), lang .. ": " .. key) end
		end
		-- Where the addon says it: a hidden Hand's own client refusing an entry on the week names the
		-- week, the Board and the crafter board (the reason Week.Sign, Board.Ready and Crafters.Choose print too).
		WithWeek(function(w, W, K)
			NoWords(function()
				AsSoldier("Watcher")
				K.HandleCommand("CHANNEL", KING, "T1~H~1~Olympus~Rogue Hand-Realm")
				AsSoldier("Rogue Hand")
				Off(ROGUE, "abuse of the week")
				w.printed = {}
				eq(W.SetEntry("Sat 20:00 Rogue raid"), false)
				local said = w.printed[#w.printed] or ""
				for _, word in ipairs({ "entries and signups on the King's week", "flags and camps on the Board", "listing on the crafter board" }) do
					assert(said:find(word, 1, true), "the reason printed: " .. word .. " in " .. said)
				end
			end)
		end)
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
			for _, must in ipairs({ "its Vox Populi votes, its Olympus chats and pinned lines, and (1.1, Konig's review) its members' entries and signups on the King's week, their flags and camps on the Board, and their listings, answers and recipe lists on the crafters' board",
				"Every addon also drops its members' requests at court, and shows them with no elite border or nameplate mark" }) do
				assert(doc:find(must, 1, true), path .. ": " .. must)
			end
			assert(not doc:find("its Vox Populi votes and its Olympus chats: its own members' addons", 1, true), path .. ": the old list")
		end
	end)
end)()
---------------------------------------------------------------------------
-- 1.1, the review of Konig's fixes (the dues): a Captain's and the King's dues pages go by the
-- King's amount for the week as their own client holds it, never by the one the Treasurer's list
-- came with (a list counted by another amount removes nobody, and the King's table shows its
-- counts of who paid as not known); the Treasurer's copy for Discord ranks the donors as his
-- client sends them, without what may be each giver's dues.
---------------------------------------------------------------------------
do
	local D, T = ns.Dues, ns.Treasury
	local WEEK = 7 * 86400
	local rosterSize = 12
	-- <Olympus II>'s roster as the server gives it (Cap's guild): Nm(1) its Lord, Nm(2) to Nm(6) its
	-- officers, the others soldiers (names of letters alone, as the game's are).
	local function Nm(i) return "Squire" .. string.char(96 + math.floor((i - 1) / 26) + 1) .. string.char(96 + (i - 1) % 26 + 1) end
	-- Runs fn(w, K, removed) on the Throne's world with the dues fresh, that roster, a rank that may
	-- remove members, and `removed` the names the game was asked to remove; all put back after.
	local function WithLows(fn)
		WithThrone(function(w, K)
			local saved = { split = ns.splitNames, byName = ns.Roster.byName, members = GetNumGuildMembers, st = GetServerTime,
				roster = GetGuildRosterInfo, can = CanGuildRemove, info = C_GuildInfo, uninvite = GuildUninvite, scan = ns.Roster.RequestScan,
				shares = ns.db.keeperShares }
			local removed = {}
			local ok, err = pcall(function()
				ns.splitNames = true
				GetServerTime = nil -- (the server's clock is the test's: ns.Now)
				D.Reset()
				ns.Roster.byName = {}
				GetNumGuildMembers = function() return rosterSize, 1 end
				GetGuildRosterInfo = function(i)
					if i > rosterSize then return nil end
					local rank = i == 1 and 0 or (i <= 6 and 1 or 3)
					return Nm(i) .. "-Realm", ({ [0] = "Lord", [1] = "Officer", [3] = "Soldier" })[rank], rank, 20
				end
				CanGuildRemove = function() return true end
				C_GuildInfo = { Uninvite = function(name) removed[#removed + 1] = name end }
				GuildUninvite = nil
				ns.Roster.RequestScan = function() end
				fn(w, K, removed)
			end)
			ns.splitNames, ns.Roster.byName, GetNumGuildMembers, GetServerTime = saved.split, saved.byName, saved.members, saved.st
			GetGuildRosterInfo, CanGuildRemove, C_GuildInfo, GuildUninvite = saved.roster, saved.can, saved.info, saved.uninvite
			ns.Roster.RequestScan, ns.db.keeperShares, ns.db.myCharacters = saved.scan, saved.shares, nil
			D.Reset()
			if not ok then error(err, 0) end
		end)
	end
	-- The King's and the Treasurer's names, as the addon pins them (the Treasurer's client after).
	local function Names()
		AsKing()
		local king = ns.me
		AsTreasurer()
		return king, ns.me
	end
	-- The King's word as this client last heard it (every client of the test shares one saved
	-- variables): `copper` from the weekly reset after `at`, `before` until then.
	local function Word(king, copper, at, before)
		ns.rdb.duesAmount = nil
		eq(D.TakeAmount(copper, at, king, before), true)
	end
	-- A dues mail the Treasurer took, with the note for <Olympus II>.
	local function Paid(i, copper) T.Record(Nm(i), copper, "mail", nil, { quiet = true, note = D.Note(D.Week(), "Olympus II") }) end
	-- The dues page's text as one (colours taken out), and its lines.
	local function Page()
		local lines = D.Build()
		local out = {}
		for _, l in ipairs(lines) do out[#out + 1] = tostring(l.text or "") .. " " .. tostring(l.right or "") end
		return (table.concat(out, " "):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""):gsub("%s+", " ")), lines
	end
	local function Row(lines, text)
		for _, l in ipairs(lines) do if tostring(l.text):find(text, 1, true) then return l end end
	end
	local function RemoveLines(lines)
		local out = {}
		for _, l in ipairs(lines) do if tostring(l.key):find("^dues remove ") then out[#out + 1] = l end end
		return out
	end
	-- The asks for a list whispered to `to` since `from`.
	local function Asks(w, from, to)
		local n = 0
		for i = from + 1, #w.whispered do if w.whispered[i].msg:find("^FQ~") and w.whispered[i].to == to then n = n + 1 end end
		return n
	end

	test("1.1 dues, the review of Konig's fixes: the King lowers the dues and the Treasurer's addon still counts the old amount: a Captain's page goes by the King's, and that list removes nobody", function()
		WithLows(function(w, K, removed)
			local KING, TREASURER = Names()
			-- The King lowered the dues from 10 gold to 5 from this week. The Treasurer's addon has met
			-- neither him nor a Steward since the 10 gold: it counts this week by 10.
			Word(KING, 100000, w.clock - 2 * WEEK, 10000)
			eq(D.Amount(), 100000)
			Paid(7, 50000)
			Paid(8, 100000)
			local stale = D.GuildMessages(D.Ledger(), "Olympus II")
			-- The Captain's addon heard the King: 5 gold this week (10 the week before).
			AsCaptain()
			Word(KING, 50000, w.clock - WEEK, 100000)
			eq(D.Amount(), 50000)
			for _, m in ipairs(stale) do D.HandleGuild("WHISPER", TREASURER, m) end
			D.Open()
			local text, lines = Page()
			local m7 = Row(lines, Nm(7) .. " ")
			assert(m7 and m7.right:find(ns.L.DUES_ABOVE, 1, true), "paid the King's 5 gold: above, never below by the list's 10: " .. text)
			assert(Row(lines, Nm(8) .. " ").right:find(ns.L.DUES_ABOVE, 1, true))
			assert(text:find(ns.L.DUES_OWN_COUNT:format(2, rosterSize, T.Coins(50000)), 1, true), "counted by the King's amount: " .. text)
			assert(text:find(ns.L.DUES_AMOUNT_DIFFERS:format(T.Coins(100000), T.Coins(50000)), 1, true), "the page says so: " .. text)
			-- Nobody is removed by that list, a list of now: not Nm(7), who paid the King's amount, nor
			-- Nm(9), who paid nothing; a removal confirmed anyway does nothing and asks again.
			m7.onClick()
			eq(#RemoveLines(select(2, Page())), 0, "paid: never removable")
			eq(D.Remove({ key = Nm(7):lower(), name = Nm(7) }), false)
			Row(select(2, Page()), Nm(9) .. " ").onClick()
			text, lines = Page()
			assert(Row(lines, Nm(9) .. " ").right:find(ns.L.DUES_NOT_IN_BOOK, 1, true), "nothing of his this week: " .. text)
			eq(#RemoveLines(lines), 0, "a list counted by another amount removes nobody")
			assert(Row(lines, ns.L.DUES_REMOVE_AMOUNT_WAIT), "said why, under him: " .. text)
			local before = #w.whispered
			eq(D.Remove({ key = Nm(9):lower(), name = Nm(9) }), false)
			eq(#removed, 0, "nothing done")
			assert(Printed(w, ns.L.DUES_REMOVE_AMOUNT:format(T.Coins(100000), T.Coins(50000), Nm(9))), "said why")
			eq(Asks(w, before, TREASURER), 1, "asked again")
			-- The Treasurer's addon hears the King: its list, counted by 5 gold, agrees, and the one
			-- click removes Nm(9).
			AsTreasurer()
			Word(KING, 50000, w.clock - WEEK, 100000)
			local agreed = D.GuildMessages(D.Ledger(), "Olympus II")
			AsCaptain()
			for _, m in ipairs(agreed) do D.HandleGuild("WHISPER", TREASURER, m) end
			text, lines = Page()
			assert(not text:find(ns.L.DUES_AMOUNT_DIFFERS:sub(1, 30), 1, true), "nothing to say now: " .. text)
			eq(#RemoveLines(lines), 1, "Nm(9), picked, on a list counted by the King's amount")
			eq(D.Remove({ key = Nm(9):lower(), name = Nm(9) }), true)
			eq(#removed, 1); eq(removed[1], Nm(9) .. "-Realm")
			-- The other way round (the Captain's addon has not heard the King's 5 gold yet): his page
			-- goes by the 10 gold it holds, and the list counted by 5 removes nobody meanwhile.
			Word(KING, 100000, w.clock - 2 * WEEK, 10000)
			text, lines = Page()
			assert(Row(lines, Nm(7) .. " ").right:find(ns.L.DUES_BELOW, 1, true), "by the 10 gold it holds: " .. text)
			assert(text:find(ns.L.DUES_AMOUNT_DIFFERS:format(T.Coins(50000), T.Coins(100000)), 1, true), text)
			Row(lines, Nm(7) .. " ").onClick()
			eq(#RemoveLines(select(2, Page())), 0, "not removable by a list counted by another amount")
			eq(D.Remove({ key = Nm(7):lower(), name = Nm(7) }), false)
			eq(#removed, 1, "nobody more")
		end)
	end)

	test("1.1 dues, the review of Konig's fixes: a Treasurer's addon that says another amount (a modified one, 1000 gold) puts nobody who paid the King's under it, and removes nobody", function()
		WithLows(function(w, K, removed)
			local KING, TREASURER = Names()
			-- 10 gold this week, on every client.
			Word(KING, 100000, w.clock - WEEK, 10000)
			Paid(8, 100000)
			local forged = {}
			for i, m in ipairs((D.GuildMessages(D.Ledger(), "Olympus II"))) do
				local head, rest = m:match("^(FA~%d+~%d+~)[0-9a-z]+(~.*)$")
				assert(head, m)
				forged[i] = head .. ns.Codec.Base36(D.MAX_AMOUNT) .. rest
			end
			AsCaptain()
			for _, m in ipairs(forged) do D.HandleGuild("WHISPER", TREASURER, m) end
			D.Open()
			local text, lines = Page()
			local m8 = Row(lines, Nm(8) .. " ")
			assert(m8 and m8.right:find(ns.L.DUES_ABOVE, 1, true), "paid the King's 10 gold: above, whatever the list says: " .. text)
			assert(text:find(ns.L.DUES_AMOUNT_DIFFERS:format(T.Coins(D.MAX_AMOUNT), T.Coins(100000)), 1, true), text)
			m8.onClick()
			eq(#RemoveLines(select(2, Page())), 0)
			eq(D.Remove({ key = Nm(8):lower(), name = Nm(8) }), false)
			-- Nm(10) paid nothing: under the King's amount, and still not removable by that list.
			Row(select(2, Page()), Nm(10) .. " ").onClick()
			eq(#RemoveLines(select(2, Page())), 0)
			eq(D.Remove({ key = Nm(10):lower(), name = Nm(10) }), false)
			eq(#removed, 0, "nobody removed by the list of an addon that set its own amount")
			-- The King's own table the same: its counts of who paid, made by 1000 gold, are not known.
			local fs = {}
			AsTreasurer()
			for i, m in ipairs((D.SummaryMessages(D.Ledger()))) do
				local head, rest = m:match("^(FS~%d+~%d+~)[0-9a-z]+(~.*)$")
				assert(head, m)
				fs[i] = head .. ns.Codec.Base36(D.MAX_AMOUNT) .. rest
			end
			AsKing()
			for _, m in ipairs(fs) do D.HandleSummary("WHISPER", TREASURER, m) end
			D.Open()
			eq(Row(select(2, Page()), "<Olympus II>").right, ns.L.DUES_GUILD_ROW:format("300", "?", T.GoldText(100000), "?"))
		end)
	end)

	test("1.1 dues, the review of Konig's fixes: the King's table of every guild goes by his amount; the Treasurer's counts of who paid, made by another amount, show as not known until his addon counts by the King's", function()
		WithLows(function(w)
			local KING, TREASURER = Names()
			Word(KING, 100000, w.clock - 2 * WEEK, 10000) -- (the Treasurer's addon: 10 gold this week)
			Paid(7, 50000)
			Paid(8, 100000)
			local fs = D.SummaryMessages(D.Ledger())
			AsKing()
			Word(KING, 50000, w.clock - WEEK, 100000) -- (his own: 5 gold)
			for _, m in ipairs(fs) do D.HandleSummary("WHISPER", TREASURER, m) end
			D.Open()
			local text, lines = Page()
			local row = Row(lines, "<Olympus II>")
			assert(row, text)
			eq(row.right, ns.L.DUES_GUILD_ROW:format("300", "?", T.GoldText(150000), "?"), "paid and the percentage not known")
			assert(text:find(ns.L.DUES_TABLE_DIFFERS:format(T.Coins(100000), T.Coins(50000)), 1, true), "the page says why: " .. text)
			local tip = {}
			row.tooltip({ AddLine = function(_, s) tip[#tip + 1] = s end })
			eq(tip[2], ns.L.DUES_GUILD_TIP:format("300", "?", T.Coins(50000), T.Coins(150000), 2), "the King's amount in its tip")
			-- (1.1.2's review: its members are the census's, and the tip says why they can differ.)
			assert(table.concat(tip, "\n"):find(ns.Answers.Find("count-other-guild-report").text, 1, true), table.concat(tip, "\n"))
			-- His addon hears the King: both paid 5 gold or more.
			AsTreasurer()
			Word(KING, 50000, w.clock - WEEK, 100000)
			fs = D.SummaryMessages(D.Ledger())
			AsKing()
			for _, m in ipairs(fs) do D.HandleSummary("WHISPER", TREASURER, m) end
			text, lines = Page()
			eq(Row(lines, "<Olympus II>").right, ns.L.DUES_GUILD_ROW:format("300", "2", T.GoldText(150000), "1%"))
			assert(not text:find(ns.L.DUES_TABLE_DIFFERS:sub(1, 30), 1, true), text)
		end)
	end)

	test("1.1 dues, the review of Konig's fixes: the Treasurer's copy for Discord ranks the donors as his addon sends them, without what may be each giver's dues; his screen stays whole", function()
		WithLows(function()
			AsTreasurer()
			ns.db.keeperShares = { [TREASURER_KEY] = true }
			local function Give(name, copper, note) T.Record(name, copper, "mail", nil, { quiet = true, note = note }) end
			Give("Payer", 10000)                                     -- (the 1 gold in force: dues, or not)
			Give("Noted", 30000, D.Note(D.Week(), "Olympus II"))     -- (sent with the dues' note: all of it)
			Give("Patron", 35000)                                    -- (1 gold of it may be dues)
			local copy = T.DiscordText()
			assert(copy:find("1. Patron - 2g 50s", 1, true), "what went over the amount: " .. copy)
			assert(not copy:find("Payer", 1, true), "a payer of the amount is never in the copy: " .. copy)
			assert(not copy:find("Noted", 1, true), "nor what went with the dues' note: " .. copy)
			-- The ranking that leaves his client, place by place.
			for i, g in ipairs(T.PublicRanking(T.Book())) do assert(copy:find(("%d. %s - "):format(i, g.name), 1, true), g.name .. ": " .. copy) end
			-- His own screen: whole, as ever.
			local mine = {}
			for _, g in ipairs(T.Totals().ranking) do mine[g.name] = g.money end
			eq(mine.Payer, 10000); eq(mine.Noted, 30000); eq(mine.Patron, 35000)
			-- Another character of his account (his mail character) copies his book as it leaves too.
			ns.db.myCharacters = { [TREASURER_KEY] = true, [ANDARAI_KEY] = true }
			ns.me = ANDARAI
			copy = T.DiscordText()
			assert(copy:find("Patron - 2g 50s", 1, true), copy)
			assert(not copy:find("Payer", 1, true) and not copy:find("Noted", 1, true), copy)
		end)
	end)

	test("1.1 dues, the review of Konig's fixes: the new lines in English and pt-BR (the same values; es/fr/de show the English); the README and the CurseForge page say what the page goes by and what the Discord copy leaves out", function()
		local pt = { L = setmetatable({}, { __index = ns.L }) }
		local savedLocale = GetLocale
		GetLocale = function() return "ptBR" end
		local ok, err = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
		GetLocale = savedLocale
		if not ok then error(err, 0) end
		local function Slots(x) return (x:gsub("%%%%", ""):gsub("[^%%]", ""):len()) end
		for _, key in ipairs({ "DUES_AMOUNT_DIFFERS", "DUES_TABLE_DIFFERS", "DUES_REMOVE_AMOUNT_WAIT", "DUES_REMOVE_AMOUNT" }) do
			local en, p = rawget(ns.L, key), rawget(pt.L, key)
			assert(en and p and p ~= en, key)
			eq(Slots(p), Slots(en), key)
			for _, bad in ipairs({ "owe", "debt", "lose" }) do assert(not en:lower():find(bad, 1, true), key .. ": " .. bad) end
			for _, bad in ipairs({ "deve", "dívida", "perde" }) do assert(not p:lower():find(bad, 1, true), key .. ": " .. bad) end
		end
		-- A guild's "paid": a count, or "?", in both languages.
		assert(ns.L.DUES_GUILD_ROW:format("300", "?", "1g", "?"):find("300 · ? · 1g · ?", 1, true))
		assert(ns.L.DUES_GUILD_TIP:format("300", "?", "5g", "15g", 2):find("? paid 5g", 1, true))
		assert(rawget(pt.L, "DUES_GUILD_TIP"):format("300", "?", "5g", "15g", 2):find("? pagaram 5g", 1, true))
		for _, file in ipairs({ "esES", "frFR", "deDE" }) do
			local s = assert(ReadFile(ADDON_DIR .. "Locales/" .. file .. ".lua"))
			assert(not s:find("DUES_", 1, true), file .. ": the English dues lines show there")
		end
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
			for _, must in ipairs({ "never by the amount the Treasurer's list came with",
				"the King's table shows its \"paid\" as \"?\", and that list removes nobody",
				"counted by the King's amount; with an older one, or one counted by another amount",
				"his screen alone is whole", "and in the Discord copy of the Treasury tab, his own too" }) do
				assert(doc:find(must, 1, true), path .. ": " .. must)
			end
			assert(not doc:find("the Discord copy he makes there, are whole", 1, true), path .. ": the copy is no longer whole")
		end
	end)
end
---------------------------------------------------------------------------
-- 1.1 (a review of Konig's key rotation fixes, #45): with the gamepad UI the King's click on the
-- Throne's /who line searches a guild picked plainly, as the census's Refresh does there; an
-- acknowledgement counts under the guild his client whispered its sender for; the rotate
-- question says what a Lord who logs in during the grace gets.
---------------------------------------------------------------------------
do
	local KY = ns.Keys
	local function Page(lines)
		local out = {}
		for _, l in ipairs(lines) do out[#out + 1] = tostring(l.text) end
		return table.concat(out, "\n")
	end
	local function LineWith(lines, text)
		for _, l in ipairs(lines) do if tostring(l.text):find(text, 1, true) then return l end end
		return nil
	end
	local function Whispered(w)
		local out = {}
		for _, x in ipairs(w.whispered) do if x.msg:sub(1, 3) == "K3~" then out[#out + 1] = x.to end end
		table.sort(out)
		return table.concat(out, ",")
	end
	local function Targets()
		local out = {}
		for _, t in ipairs(KY.Targets()) do out[#out + 1] = t.name end
		table.sort(out)
		return table.concat(out, ",")
	end
	-- Locales.lua as the game in `code` loads it, then that language's file under Locales/ (if
	-- any): the lines in use, and the ones that file gives.
	local function Loaded(code, file)
		local lns, given = {}, nil
		local savedLocale = GetLocale
		GetLocale = function() return code end
		local ok, err = pcall(function()
			assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", lns)
			if file then
				local real = lns.Locale
				lns.Locale = function(codes, strings) given = strings; return real(codes, strings) end
				assert(loadfile(ADDON_DIR .. "Locales/" .. file .. ".lua"))("Olympus", lns)
				lns.Locale = real
			end
		end)
		GetLocale = savedLocale
		if not ok then error(err, 0) end
		return lns.L, given
	end
	-- The King's client with a stand-in of the game's /who (WithWho: GetTime is its clock) and the
	-- Throne (WithThrone). The census: <Olympus Zeus> (its Lord Zed and Captain Zeus Cap online)
	-- and <Olympus Nyx> (Nyx and Nyx Cap), each vouched by two senders and checked (his /who saw
	-- a guild of each name). A whisper leaves at once (done(true)).
	local function WithKing(fn)
		WithWho(function(server)
			WithThrone(function(w, K)
				local saved = { key = ns.rdb.realmKey, epoch = ns.rdb.keyEpoch, rot = ns.rdb.keyRotation, retired = ns.rdb.keyRetired,
					join = ns.Comm.JoinChannel, log = ns.db.log }
				local ok, err = pcall(function()
					ns.rdb.realmKey, ns.rdb.keyEpoch, ns.rdb.keyRotation, ns.rdb.keyRetired = nil, nil, nil, nil
					ns.db.log = {}
					KY.Reset()
					ns.Comm.JoinChannel = function() end
					local record = ns.Comm.Whisper
					ns.Comm.Whisper = function(to, msg, key, urgent, logged, done)
						record(to, msg, key, urgent)
						if done then done(true) end
					end
					local G = ns.rdb.guilds
					G["Olympus II"] = nil
					G["Olympus Zeus"] = Vouched({ total = 100, online = 9, zones = {}, t = w.clock, leader = "Zed", leaderOnline = true, realm = "Realm",
						officers = { { name = "Zeus Cap", online = true, days = 0 } } }, "W3-Realm", "W4-Realm")
					G["Olympus Nyx"] = Vouched({ total = 200, online = 12, zones = {}, t = w.clock, leader = "Nyx", leaderOnline = true, realm = "Realm",
						officers = { { name = "Nyx Cap", online = true, days = 0 } } }, "W7-Realm", "W8-Realm")
					ns.rdb.seen = { ["Olympus Zeus"] = { online = 9, t = w.clock }, ["Olympus Nyx"] = { online = 12, t = w.clock } }
					AsKing()
					fn(w, K, server)
				end)
				ns.rdb.realmKey, ns.rdb.keyEpoch, ns.rdb.keyRotation, ns.rdb.keyRetired = saved.key, saved.epoch, saved.rot, saved.retired
				ns.Comm.JoinChannel, ns.db.log = saved.join, saved.log
				KY.Reset()
				if not ok then error(err, 0) end
			end)
		end)
	end

	test("1.1 key rotation review, with the gamepad UI: the King's click on the Throne's /who line searches a guild picked plainly (the answer in the game's Who list, nothing silenced) and its Lords and Captains get the key; never quietly, never a name, never from a click on a guild", function()
		-- What the server lists for each guild's search (Nyx Cap logs in later).
		local listed = {
			["Olympus Zeus"] = { { "Zed", "Olympus Zeus", 60, "WARRIOR" }, { "Zeus Cap", "Olympus Zeus", 60, "MAGE" }, { "Zeus Soldier", "Olympus Zeus", 20, "PRIEST" } },
			["Olympus Nyx"] = { { "Nyx", "Olympus Nyx", 60, "PALADIN" }, { "Nyx Soldier", "Olympus Nyx", 30, "HUNTER" } },
		}
		WithUI(function()
			LoadUI()
			WithGamepadUI(true, function(game)
				WithKing(function(w, K, server)
					LFGWhoListFrame = ListenerFrame("LFGWhoListFrame", true)
					local sendWho = C_FriendList.SendWho
					eq(KY.Rotate(), true)
					K.Show("home")
					eq(#KY.Targets(), 0, "nobody his /who saw in his guild yet")
					-- A click on a guild's row only checks it there: the game's list opening would take the
					-- gamepad's focus.
					LineWith(K.Build(), "<Olympus Zeus>").onClick()
					LineWith(K.Build(), "<Olympus Zeus>").onClick()
					assert(tostring(LineWith(K.Build(), "<Olympus Zeus>").text):find("ReadyCheck-Ready", 1, true), "checked again")
					eq(#server.sent, 0, "no /who from a click on a guild")
					-- His click on the /who line: a plain /who of a guild picked, as the census's Refresh there.
					local toUi -- (where the answer went while it came: after it, results go back to chat)
					local function Click()
						local before = #server.sent
						LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:sub(1, 12)).onClick()
						if #server.sent == before then return nil end
						toUi = server.toUi[#server.toUi]
						local q = server.sent[#server.sent]
						local guild = q:match('^g%-"(.*)"$')
						assert(guild and listed[guild], "a guild's search: " .. q)
						server.Answer(listed[guild])
						server.Run(ns.Who.SETTLE)
						return guild
					end
					assert(LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:format(4)), Page((K.Build())))
					local first = Click()
					assert(first, "his click on the /who line searches")
					eq(toUi, true, "its answer to the game's Who list, as a /who with it open")
					eq(#LFGWhoListFrame.calls, 0, "the game's Who list never silenced")
					eq(C_FriendList.SendWho, sendWho, "Blizzard's SendWho left as it is")
					-- Within the cooldown: nothing, and he is told when (as Refresh tells him).
					eq(Click(), nil)
					assert(Printed(w, ns.L.WHO_WAIT:match("^(.-)%%")), "the wait said")
					server.clock = server.clock + ns.Who.COOLDOWN + 1
					local second = Click()
					local both = { first, tostring(second) }
					table.sort(both)
					eq(table.concat(both, ","), "Olympus Nyx,Olympus Zeus", "the next click the other guild")
					eq(Targets(), "Nyx-Realm,Zed-Realm,Zeus Cap-Realm", "the Lords and Captains his /who listed in their guild")
					-- Nyx Cap is not in his guild's answer: never searched by name there; his guild again a
					-- minute after its last search (he may have logged in since).
					w.printed = {}
					server.clock = server.clock + ns.Who.COOLDOWN + 1
					eq(Click(), nil, "every guild still waiting searched within the minute")
					assert(Printed(w, ns.L.KEY_WHO_GAMEPAD), "and he is told why")
					for _, q in ipairs(server.sent) do assert(not q:find("^n%-"), "never a name: " .. q) end
					eq(ns.Who.GUILD_AGAIN, 60, "(the words say a minute)")
					server.clock = server.clock + ns.Who.GUILD_AGAIN
					listed["Olympus Nyx"][3] = { "Nyx Cap", "Olympus Nyx", 60, "DRUID" }
					eq(Click(), "Olympus Nyx")
					eq(Targets(), "Nyx Cap-Realm,Nyx-Realm,Zed-Realm,Zeus Cap-Realm")
					eq(LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:sub(1, 12)), nil, "nobody left to look for")
					eq(KY.Start(), true)
					eq(Whispered(w), "Nyx Cap-Realm,Nyx-Realm,Zed-Realm,Zeus Cap-Realm")
					-- Still no quiet search there, and none by name: the Realm tab's search of a guild,
					-- Auto's, Olympus Link's.
					server.clock = server.clock + ns.Who.COOLDOWN + 1
					local sent = #server.sent
					eq(ns.Who.SearchGuild("Olympus Other"), false, "the Realm tab's quiet search of a guild")
					eq(ns.Who.Search(true, "Olympus Other"), false)
					eq(ns.Who.Search(false, nil, "Zed"), false, "a name")
					eq(ns.Who.Auto(), false)
					eq(#server.sent, sent)
					eq(#LFGWhoListFrame.calls, 0)
					eq(#game.shown, 0); eq(#w.popups, 0)
				end)
			end)
		end)
	end)

	test("1.1 key rotation review, with the gamepad UI: its line says what his /who does there (English and pt-BR; Spanish, French and German show the English); the README and the CurseForge page too", function()
		local en, pt = ns.L, Loaded("ptBR")
		assert(type(pt.KEY_WHO_GAMEPAD) == "string" and pt.KEY_WHO_GAMEPAD ~= en.KEY_WHO_GAMEPAD, "pt-BR")
		assert(en.KEY_WHO_GAMEPAD:find("your /who searches each guild picked (one a click, never a name), and a guild again a minute after its last search", 1, true), en.KEY_WHO_GAMEPAD)
		assert(pt.KEY_WHO_GAMEPAD:find("o seu /who busca cada guilda escolhida (uma por clique, nunca um nome), e uma guilda de novo um minuto depois da última busca dela", 1, true), pt.KEY_WHO_GAMEPAD)
		for _, s in ipairs({ en.KEY_WHO_GAMEPAD, pt.KEY_WHO_GAMEPAD }) do
			assert(not s:find("Refresh", 1, true) and not s:find("Atualizar", 1, true), "no longer the census's Refresh alone: " .. s)
		end
		for code, file in pairs({ esES = "esES", frFR = "frFR", deDE = "deDE" }) do
			local shown, given = Loaded(code, file)
			assert(type(given) == "table" and next(given), file .. ": its lines")
			eq(given.KEY_WHO_GAMEPAD, nil, file .. ": no line of its own")
			eq(shown.KEY_WHO_GAMEPAD, en.KEY_WHO_GAMEPAD, file .. ": the English shows")
		end
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
			for _, must in ipairs({ "with the gamepad UI his click on the /who line searches each guild picked plainly, its answer in the game's Who list, never a name, and a guild again a minute after its last search; a click on a guild only checks it there",
				"so does the King's click on his Throne's /who line for his key rotation, 1.1: the answer shows in the game's Who list" }) do
				assert(doc:find(must, 1, true), path .. ": " .. must)
			end
		end
	end)

	test("1.1 key rotation review, with the gamepad UI: a guild the /who refuses now (searched lately another way) is passed over for the next waiting one, never a click that does nothing", function()
		WithUI(function()
			LoadUI()
			WithGamepadUI(true, function(game)
				WithKing(function(w, K, server)
					LFGWhoListFrame = ListenerFrame("LFGWhoListFrame", true)
					eq(KY.Rotate(), true)
					K.Show("home")
					local real, calls, refused = ns.Who.SearchGuild, {}, nil
					ns.Who.SearchGuild = function(g, plain)
						calls[#calls + 1] = g
						if not refused then refused = g return false end -- (searched lately, as Who's own timer says)
						return real(g, plain)
					end
					local ok, err = pcall(function()
						local before = #server.sent
						LineWith(K.Build(), ns.L.KEY_WHO_CONFIRM:sub(1, 12)).onClick()
						eq(#calls, 2, "the refused guild, then the next")
						assert(calls[2] ~= calls[1], "another guild")
						eq(#server.sent, before + 1, "one /who sent")
						assert(server.sent[#server.sent]:find(calls[2], 1, true), server.sent[#server.sent])
					end)
					ns.Who.SearchGuild = real
					if not ok then error(err, 0) end
				end)
			end)
		end)
	end)

	test("1.1 key rotation review: the Throne counts an acknowledgement (K4) under the guild the King's client whispered its sender for, never the guild the K4 names", function()
		WithKing(function(w, K, server)
			eq(ns.Who.Search(true), true)
			server.Answer({ { "Zed", "Olympus Zeus", 60, "WARRIOR" }, { "Zeus Cap", "Olympus Zeus", 60, "MAGE" } })
			server.Run(ns.Who.SETTLE)
			eq(KY.Rotate(), true)
			eq(KY.Start(), true)
			eq(Whispered(w), "Zed-Realm,Zeus Cap-Realm", "Olympus Nyx picked, nobody of it whispered")
			local rot = KY.Rotation()
			K.Show("home")
			-- Zed names Olympus Nyx (picked, never whispered), Zeus Cap a guild nobody heard of: both
			-- have it, and one guild does, his.
			KY.HandleAck("WHISPER", "Zed-Realm", ("K4~%d~Olympus Nyx"):format(rot.at))
			KY.HandleAck("WHISPER", "Zeus Cap-Realm", ("K4~%d~Olympus Made Up"):format(rot.at))
			eq(KY.Stats().acks, 2)
			assert(Page((K.Build())):find(ns.L.KEY_ROTATING:format(2, 2, 1), 1, true), Page((K.Build())))
			-- Nyx, whispered for Olympus Nyx once his /who saw him there, names no guild (he left it
			-- since): counted under Olympus Nyx.
			server.clock = server.clock + ns.Who.COOLDOWN + 1
			eq(ns.Who.Search(true, nil, "Nyx"), true)
			server.Answer({ { "Nyx", "Olympus Nyx", 60, "PALADIN" } })
			server.Run(ns.Who.SETTLE)
			w.clock = w.clock + 60
			KY.Tick()
			eq(Whispered(w), "Nyx-Realm,Zed-Realm,Zeus Cap-Realm")
			KY.HandleAck("WHISPER", "Nyx-Realm", ("K4~%d~"):format(rot.at))
			assert(Page((K.Build())):find(ns.L.KEY_ROTATING:format(3, 3, 2), 1, true), Page((K.Build())))
			-- The record is the rotation's (saved): after he moves, the same count.
			eq(KY.Move(), true)
			assert(Page((K.Build())):find(ns.L.KEY_ROTATED_AGO:format(ns.Ago(rot.movedAt), 3, 2), 1, true), Page((K.Build())))
		end)
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
			assert(doc:find("and of how many guilds (each counted for the guild his addon whispered him for, never the one his answer names)", 1, true), path)
		end
	end)

	test("1.1 key rotation review: the rotate question says a Lord or Captain who logs in during the grace gets nothing until the King's /who sees him in his guild (English and pt-BR; Spanish, French and German show the English)", function()
		local en, pt = ns.L, Loaded("ptBR")
		assert(type(pt.KEY_ROTATE_CONFIRM) == "string" and pt.KEY_ROTATE_CONFIRM ~= en.KEY_ROTATE_CONFIRM, "pt-BR")
		eq(select(2, pt.KEY_ROTATE_CONFIRM:gsub("%%[sd]", "")), 1, "pt-BR: the minutes")
		eq(select(2, en.KEY_ROTATE_CONFIRM:gsub("%%[sd]", "")), 1, "English: the minutes")
		assert(en.KEY_ROTATE_CONFIRM:find("A Lord or Captain who logs in meanwhile gets nothing until your /who sees him in his guild", 1, true), en.KEY_ROTATE_CONFIRM)
		assert(not en.KEY_ROTATE_CONFIRM:find("get it too", 1, true), "no longer that those who log in meanwhile get it")
		assert(pt.KEY_ROTATE_CONFIRM:find("Um Lorde ou Capitão que entrar nesse meio-tempo não recebe nada até o seu /who vê-lo na guilda dele", 1, true), pt.KEY_ROTATE_CONFIRM)
		assert(not pt.KEY_ROTATE_CONFIRM:find("também receberem", 1, true), pt.KEY_ROTATE_CONFIRM)
		for code, file in pairs({ esES = "esES", frFR = "frFR", deDE = "deDE" }) do
			local shown, given = Loaded(code, file)
			assert(type(given) == "table" and next(given), file .. ": its lines")
			eq(given.KEY_ROTATE_CONFIRM, nil, file .. ": no line of its own")
			eq(shown.KEY_ROTATE_CONFIRM, en.KEY_ROTATE_CONFIRM, file .. ": the English shows")
		end
		-- The pages said it already.
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
			assert(doc:find("For 10 minutes his addon keeps handing it to Lords and Captains who log in (once his /who saw them in their guild)", 1, true), path)
		end
	end)
end

---------------------------------------------------------------------------
-- 1.1.1: the Olympus chats in the Olympus window's Chat tab (ChatWindow.lua, drawn in UI.lua's
-- window) and its ways in (/ol alone, /oly talk, the minimap button's Shift-click, the Realm tab's
-- link to the chats: its page of them is gone since, the Chat tab replacing it), and the marks by a
-- name (Borders.MarkOfName). The first 1.1.1 build had the chats
-- in a window of their own; these tests were written for it and moved to the tab (what changed on
-- purpose is said where it is asserted: the Olympus window instead of a window of its own, no Send
-- button, no place or size of its own, the search box).
---------------------------------------------------------------------------
do
	local L = ns.L
	local CW_LINE = 14
	local T0 = os.time({ year = 2026, month = 9, day = 30, hour = 12, min = 0, sec = 0 })
	local MOONCLOTH_LINK = "item:14342::::::::60:::::"
	local MOONCLOTH_TEXT = "|cff1eff00|H" .. MOONCLOTH_LINK .. "|h[Mooncloth]|h|r"

	-- What the client gives that the widget toolkit does not, installed for these tests alone and
	-- taken off after each (the older tests keep the toolkit they were written for: Dialog.lua's
	-- height fallback expects no GetStringHeight there). A FontString's height: its lines at 14
	-- each, a line per width of text where it wraps (the client wraps at word breaks, so a real
	-- height can be a line more: the tests assert growth and nothing cut, not pixels). An EditBox's
	-- focus as the client keeps it (HasFocus, ClearFocus), Insert at the end (where the cursor is
	-- after SetText), SetFocus and SetAutoFocus recorded, StartSizing recorded, and each named
	-- frame's Show logged (the order of the box's SetAutoFocus(false) and the window's first Show).
	local function Mocks(orig, w)
		return {
			GetStringHeight = function(self)
				local width = self.w or 0
				local lines = 1
				if self.wrap ~= false and width > 0 then lines = math.max(1, math.ceil(self:GetUnboundedStringWidth() / width)) end
				return lines * CW_LINE
			end,
			HasFocus = function(self) return self.focused == true end,
			Insert = function(self, text) self:SetText((self:GetText() or "") .. text) end,
			-- (1.1.1, the "Open chat" key: SetFocus gives the box the keyboard, as the client does;
			-- until then the tests only asked that nothing called it.)
			SetFocus = function(self) w.focus[#w.focus + 1] = self.name or "?"; self.focused = true end,
			ClearFocus = function(self) self.focused = false; self.cleared = (self.cleared or 0) + 1 end,
			SetAutoFocus = function(self, on) self.autoFocus = on; w.log[#w.log + 1] = "autofocus " .. tostring(on) end,
			StartSizing = function(self, point) self.sizing = point end,
			Show = function(self)
				if self.name then w.log[#w.log + 1] = "show " .. self.name end
				return orig.Show(self)
			end,
			-- (Review of 1.1.1) What the window's asks rest on, recorded where the toolkit made them
			-- no-ops (each could be deleted with every test green): a bubble's links and clicks, a long
			-- word's wrap, the resize bounds, the window kept on the screen, the box's byte cap.
			SetHyperlinksEnabled = function(self, on) self.hyperlinks = on and true or false end,
			SetNonSpaceWrap = function(self, on) self.nonSpaceWrap = on and true or false end,
			EnableMouse = function(self, on) self.mouse = on and true or false end,
			SetResizeBounds = function(self, ...) self.resizeBounds = { ... } end,
			SetClampedToScreen = function(self, on) self.clamped = on and true or false end,
			SetMaxBytes = function(self, n) self.maxBytes = n end,
			-- As the client: a frame's links answer the mouse only with its hyperlinks on
			-- (SetHyperlinksEnabled) and the mouse on (the client's own link frames that are not
			-- chat frames set enableMouse with hyperlinksEnabled, Blizzard_CatalogShop), and its
			-- OnMouseDown/OnMouseUp only with the mouse on. A Button or an EditBox has the mouse on
			-- from the start, a plain Frame not (EnableMouse).
			Fire = function(self, kind, ...)
				local mouse = self.mouse
				if mouse == nil then mouse = self.kind == "Button" or self.kind == "CheckButton" or self.kind == "EditBox" end
				if type(kind) == "string" and kind:find("^OnHyperlink") and not (self.hyperlinks and mouse) then return end
				if (kind == "OnMouseDown" or kind == "OnMouseUp") and not mouse then return end
				return orig.Fire(self, kind, ...)
			end,
		}
	end

	-- The Olympus window (UI.lua, fresh) and its Chat tab on the widget toolkit, as a soldier of
	-- Olympus II with an empty history: ChatWindow.lua loaded fresh in a namespace of its own, its
	-- ns.On listeners kept so a test fires them (w.fire) and its game events too (w.event), and put
	-- where UI, Views and the commands reach it (ns.ChatWindow). w.UI: the window's UI.lua.
	local function WithWindow(fn)
		WithUI(function()
			local w = { printed = {}, focus = {}, log = {}, on = {}, events = {} }
			local orig = {}
			local mocks = Mocks(orig, w)
			for k in pairs(mocks) do orig[k] = rawget(Widget, k) end
			for k, f in pairs(mocks) do Widget[k] = f end
			local C = ns.Channels
			local saved = { chat = ns.rdb.chat, me = ns.me, print = ns.Print, win = ns.db.chatWin, cw = ns.ChatWindow, send = C.Send,
				shift = IsShiftKeyDown, addonChat = ns.db.addonChat, mute = ns.db.chatMute, dialog = ns.ShowDialog, hides = ns.Filter.Hides,
				pin = C.Pin, canDown = C.CanTakeDown, consent = ns.Consent.Show, borders = ns.Borders, council = ns.rdb.council,
				history = C.History, getTime = GetTime, selfOff = ns.Moderation.SelfOff, youText = ns.Moderation.YouText,
				setup = rawget(C, "SetupTab"), tabState = rawget(C, "TabState"), findTab = rawget(C, "FindTab") }
			local ok, err = pcall(function()
				ns.Print = function(m) w.printed[#w.printed + 1] = tostring(m) end
				ns.rdb.chat = {}
				ns.db.chatWin = nil
				ns.Views.ClearFilters()
				AsSoldier()
				local cns = setmetatable({}, { __index = ns })
				cns.On = function(name, f) w.on[name] = w.on[name] or {}; table.insert(w.on[name], f) end
				cns.RegisterEvent = function(name, f) w.events[name] = w.events[name] or {}; table.insert(w.events[name], f) end
				assert(loadfile(ADDON_DIR .. "ChatWindow.lua"))("Olympus", cns)
				w.CW = cns.ChatWindow
				ns.ChatWindow = w.CW
				w.UI = LoadUI()
				w.fire = function(name, ...) for _, f in ipairs(w.on[name] or {}) do f(...) end end
				w.event = function(name, ...) for _, f in ipairs(w.events[name] or {}) do f(...) end end
				fn(w)
			end)
			for k in pairs(mocks) do Widget[k] = orig[k] end
			ns.rdb.chat, ns.me, ns.Print, ns.db.chatWin, ns.ChatWindow, C.Send = saved.chat, saved.me, saved.print, saved.win, saved.cw, saved.send
			IsShiftKeyDown, ns.db.addonChat, ns.db.chatMute, ns.ShowDialog, ns.Filter.Hides = saved.shift, saved.addonChat, saved.mute, saved.dialog, saved.hides
			C.Pin, C.CanTakeDown, ns.Consent.Show, ns.Borders, ns.rdb.council = saved.pin, saved.canDown, saved.consent, saved.borders, saved.council
			C.History, GetTime, ns.Moderation.SelfOff, ns.Moderation.YouText = saved.history, saved.getTime, saved.selfOff, saved.youText
			C.SetupTab, C.TabState, C.FindTab = saved.setup, saved.tabState, saved.findTab
			ns.Views.ClearFilters()
			if not ok then error(err, 0) end
		end)
	end

	local function Line(t, sender, text, extra)
		local e = { t = t, sender = sender, guild = "Olympus II", text = text }
		for k, v in pairs(extra or {}) do e[k] = v end
		return e
	end
	local function Visible(list)
		local out = {}
		for _, x in ipairs(list) do if x:IsShown() then out[#out + 1] = x end end
		return out
	end
	local function Said(w, text)
		for _, p in ipairs(w.printed) do if p:find(text, 1, true) then return true end end
		return false
	end
	local function RowWith(f, text)
		for _, r in ipairs(Visible(f.rows)) do if (r.text:GetText() or ""):find(text, 1, true) then return r end end
	end
	local function BubbleWith(f, text)
		for _, b in ipairs(Visible(f.bubbles)) do if (b.body:GetText() or ""):find(text, 1, true) then return b end end
	end
	-- A bubble's place from the top of the box's content.
	local function Top(b)
		local a = b:Anchor("TOPLEFT") or b:Anchor("TOPRIGHT")
		return -a[5]
	end
	local function TipLines()
		local out = {}
		for _, l in ipairs(GameTooltip.lines or {}) do out[#out + 1] = tostring(l) end
		return out
	end
	-- (The review of the Chat tab's layout: the channel pills' row is gone.) A channel picked with
	-- the switch on the top row: its list, then the channel's line there.
	local function PickChannel(f, t)
		assert(f.switch:IsShown(), "the channels' switch")
		f.switch:Click()
		assert(f.menu:IsShown(), "its list")
		f.menu.rows[t]:Click()
	end
	-- A line of the settings (the gear) shown, whose text holds `text`.
	local function Setting(f, text)
		for _, r in ipairs(Visible(f.setRows)) do if (r.text:GetText() or ""):find(text, 1, true) then return r end end
	end
	-- Channels' send gap (lastSend, Channels.Send's own) fresh for fn, and as it was after: the
	-- earlier tests' clocks never refuse fn's lines, and fn's clock never refuses a later test's.
	-- (Moved here from the review's block below: the settings' tests send a line too.)
	local function KeepSendGap(fn)
		local send, at, was = ns.Channels.Send, nil, nil
		for i = 1, 200 do
			local n, v = debug.getupvalue(send, i)
			if n == nil then break end
			if n == "lastSend" then at, was = i, v break end
		end
		assert(at, "(Channels.Send's lastSend)")
		debug.setupvalue(send, at, -math.huge)
		local ok, err = pcall(fn)
		debug.setupvalue(send, at, was)
		if not ok then error(err, 0) end
	end

	test("1.1.1 marks by a name (Borders.MarkOfName): the King gold; the High Council, Lords and Captains silver; Raiders and Veterans of our guild bronze; members the star; nobody for net-off or outside Olympus", function()
		WithBorders(function(w)
			local B = w.B
			local saved = { byName = ns.Roster.byName, rankName = GuildControlGetRankName, hides = ns.Moderation.Hides }
			local ok, err = pcall(function()
				-- Our guild (Olympus II): its ranks from our roster, their names from the game's list.
				ns.Roster.byName = { ["Guildie Master-Realm"] = 0, ["Guildie Officer-Realm"] = 1, ["Raider Guy-Realm"] = 2,
					["Vet Guy-Realm"] = 3, ["Plain Guy-Realm"] = 4 }
				GuildControlGetRankName = function(i) return ({ "Master", "Officer", "Raider", "Veteran", "Member" })[i] end
				eq(B.MarkOfName("Asmongold Asmongler-Realm", "OLYMPUS"), "gold", "the King by his pinned name in his guild")
				-- (Review of 1.1.1: a name our roster lacks is not proven one of ours, so no star; it was
				-- "member" before, from the guild the line names alone. REVIEW star below.)
				eq(B.MarkOfName("Asmongold Asmongler-Realm", "Olympus II"), nil, "his name in another guild is not him, nor proven one of ours")
				local mark, facts = B.MarkOfName("Sage Owl", "Olympus II")
				eq(mark, "silver", "a High Councillor"); eq(facts.council, true); eq(facts.who, "Sage Owl-Realm", "the name made whole")
				eq(B.MarkOfName("Guildie Master-Realm", "Olympus II"), "silver", "our guild master")
				eq(B.MarkOfName("Guildie Officer-Realm", "Olympus II"), "silver", "our officer")
				eq(B.MarkOfName("Raider Guy-Realm", "Olympus II"), "bronze", "our Raider")
				eq(B.MarkOfName("Vet Guy-Realm", "Olympus II"), "bronze", "our Veteran")
				eq(B.MarkOfName("Plain Guy-Realm", "Olympus II"), "member", "our Member")
				eq(B.MarkOfName("Stranger-Realm", "Olympus II"), nil, "not in our roster: nothing proves him one of ours (it was the star before the review)")
				-- Another guild: the census, two senders naming him.
				eq(B.MarkOfName("Zeusy-Realm", "Olympus Zeus"), "silver", "another guild's Lord, two senders")
				eq(B.MarkOfName("Capt-Realm", "Olympus Zeus"), "silver", "another guild's Captain, two senders")
				ns.rdb.guilds["Olympus Lone"] = Vouched({ guild = "Olympus Lone", leader = "Loner", officers = { { name = "Lone Capt" } }, realm = "Realm",
					t = ns.Now() }, "W1-Realm")
				-- (Review of 1.1.1: it was the star before. A guild master one sender names has no rank from
				-- the census (the Crown needs two), so Channels does not verify him either: no mark.)
				eq(ns.Data.KnownRank("Loner-Realm", "Olympus Lone"), nil, "(the census gives the master one sender names no rank)")
				eq(B.MarkOfName("Loner-Realm", "Olympus Lone"), nil, "one sender names him master: not proven, no mark")
				eq(ns.Data.KnownRank("Lone Capt-Realm", "Olympus Lone"), 1, "(the census's rank for a Captain one sender names)")
				eq(B.MarkOfName("Lone Capt-Realm", "Olympus Lone"), "member", "a Captain one sender names: a member, as the borders ask two")
				-- Nobody outside Olympus; nobody the moderators took off.
				eq(B.MarkOfName("Joe-Realm", "Wanderers"), nil)
				eq(B.MarkOfName("Joe-Realm", nil), nil)
				eq(B.MarkOfName(nil, "Olympus II"), nil)
				ns.Moderation.Hides = function(who) if who == "Zeusy-Realm" then return { kind = "c" } end end
				eq(B.MarkOfName("Zeusy-Realm", "Olympus Zeus"), nil, "net-off")
				ns.Moderation.Hides = saved.hides
				-- Independent of /oly borders off (the chat's marks are the chat's).
				ns.db.borders = false
				eq(B.MarkOfName("Raider Guy-Realm", "Olympus II"), "bronze")
				-- MarkOf and the borders unchanged: the unit functions still decide theirs.
				w.target(BorderUnit("Raider Guy", "Olympus II", "Raider", 2))
				eq(B.MarkOf("target"), "bronze")
			end)
			ns.Roster.byName, GuildControlGetRankName, ns.Moderation.Hides = saved.byName, saved.rankName, saved.hides
			if not ok then error(err, 0) end
		end)
	end)

	-- (Changed on purpose, the author's ask: the chats open in the Olympus window, on its Chat tab,
	-- not in a window of their own; toggled again, that window closes. Escape closes the Olympus
	-- window as ever, the tab with it; the gamepad UI keeps it off the Escape list.)
	test("1.1.1 Chat tab: it opens the Olympus window on its Chat tab for a member, on a channel the rank reads, never taking the keyboard; toggled, the window closes; Escape closes it with mouse and keyboard, the X with the gamepad UI", function()
		WithWindow(function(w)
			GetGuildInfo = function() return "Wanderers", "Member", 3 end
			eq(w.CW.Open(), nil)
			assert(Said(w, L.MEMBERS_ONLY), "told"); eq(rawget(_G, "OlympusFrame"), nil, "nothing made"); eq(w.CW.IsShown(), false)
			AsSoldier()
			w.printed = {}
			eq(w.CW.Open("C"), nil)
			eq(w.printed[1], L.CHAN_ONLY_CAPTAINS:format(L.CHAN_CAPTAINS), "a soldier asking for [Captains]"); eq(w.CW.IsShown(), false)
			local f = w.CW.Open()
			assert(f and f:IsShown(), "open"); eq(w.CW.Frame(), f); eq(w.CW.Tier(), "A")
			local main = OlympusFrame
			assert(main and main:IsShown(), "the Olympus window"); eq(main.tab, "chat", "on its Chat tab")
			eq(w.CW.Window(), main); eq(f:GetParent(), main, "the tab is in the window"); eq(f, OlympusFrameChat)
			eq(rawget(_G, "OlympusChatWindow"), nil, "no window of its own (the first 1.1.1 build's)")
			local eb = OlympusFrameChatInput
			eq(eb, f.input); eq(eb.autoFocus, false, "the box never takes the keyboard by itself"); eq(eb.olympusBox, true)
			eq(f.search.autoFocus, false, "nor the search box"); eq(f.search.olympusBox, true)
			local af, sh
			for i, e in ipairs(w.log) do
				if e == "autofocus false" and not af then af = i end
				if e == "show OlympusFrameChat" and not sh then sh = i end
			end
			assert(af and sh and af < sh, "autofocus off before the tab first shows: " .. table.concat(w.log, ", "))
			eq(#w.focus, 0, "no SetFocus")
			local listed = 0
			for _, n in ipairs(UISpecialFrames) do if n == "OlympusFrame" then listed = listed + 1 end end
			eq(listed, 1, "Escape closes the Olympus window, the tab with it, with mouse and keyboard")
			-- (Changed on purpose, the author's ask: no row of channel pills; one channel, no switch.)
			eq(f.pills, nil, "no pills"); eq(f.switch:IsShown(), false, "a soldier reads [Olympus] alone: no switch")
			eq(f.gear:IsShown(), true, "the settings' gear")
			w.CW.Toggle(); eq(w.CW.IsShown(), false, "toggled closed"); eq(main:IsShown(), false, "the Olympus window closed")
			eq(f:IsShown(), false, "the tab gone with it")
			w.CW.Toggle("A"); eq(w.CW.IsShown(), true); eq(main.tab, "chat")
			w.CW.Toggle("A"); eq(w.CW.IsShown(), false, "the same channel: closed")
			w.CW.Toggle(); eq(w.CW.IsShown(), true)
			w.CW.Toggle("C"); eq(w.CW.IsShown(), true, "a channel the rank does not read: stays"); eq(w.CW.Tier(), "A")
			w.CW.Close(); eq(w.CW.IsShown(), false); eq(main:IsShown(), false)
			-- Its X hides it itself, in combat too, as the first build's window did (the template's
			-- button would call HideUIPanel, which does nothing in combat; review of the Chat tab).
			local combat = rawget(_G, "InCombatLockdown")
			InCombatLockdown = function() return true end
			w.CW.Open()
			main.CloseButton:Click()
			InCombatLockdown = combat
			eq(main:IsShown(), false, "the X closes the window in combat"); eq(w.CW.IsShown(), false); eq(f:IsShown(), false)
			eq(main.onCloseCallback(), false, "(it says no to HideUIPanel)")
			-- The window open on another tab: the Chat tab is not shown, and a toggle turns to it.
			w.UI.SelectTab("census")
			eq(main:IsShown(), true); eq(f:IsShown(), false); eq(w.CW.IsShown(), false)
			w.CW.Toggle()
			eq(main.tab, "chat"); eq(w.CW.IsShown(), true, "the window kept open, on its Chat tab")
			-- The tab itself, clicked: the same (the channel it last showed).
			w.UI.SelectTab("realm"); eq(w.CW.IsShown(), false)
			w.UI.SelectTab("chat"); eq(w.CW.IsShown(), true); eq(w.CW.Tier(), "A")
			-- A rank that reads nothing any more: at the tab's next drawing, the window turns to the Census.
			GetGuildInfo = function() return "Wanderers", "Member", 3 end
			f:Fire("OnUpdate", 0.3)
			eq(f:IsShown(), false, "out of Olympus: the tab hidden"); eq(main.tab, "census"); eq(w.CW.IsShown(), false)
			-- The gamepad UI: nothing on the escape list, no game popup, no focus.
			AsSoldier()
			main:Hide()
			w.CW.Reset()
			for i = #UISpecialFrames, 1, -1 do UISpecialFrames[i] = nil end
			WithGamepadUI(true, function(game)
				local g = w.CW.Open()
				assert(g and g:IsShown(), "opens with the gamepad UI")
				eq(#UISpecialFrames, 0, "nothing on the escape list"); eq(#game.shown, 0); eq(#w.focus, 0)
				eq(g.input.autoFocus, false)
				main:Hide(); w.CW.Open()
				eq(#UISpecialFrames, 0, "nor when it shows again")
				-- The X, the way out there (with /oly): it closes the window, no HideUIPanel.
				main.CloseButton:Click()
				eq(main:IsShown(), false, "the X with the gamepad UI"); eq(w.CW.IsShown(), false); eq(#game.shown, 0)
			end)
		end)
	end)

	test("1.1.1 Chat tab: a bubble per line, others' on the left and ours on the right, a header where a writer starts, a long line wrapped whole; a resize wraps again and the bubbles are reused", function()
		WithWindow(function(w)
			local long = ("word "):rep(120)
			ns.rdb.chat = { A = {
				Line(T0 - 86400, "Old Timer-Realm", "yesterday"),
				Line(T0, "Aa-Realm", "hello there"),
				Line(T0 + 30, "Aa-Realm", "second from Aa"),
				Line(T0 + 60, "Soldier-Realm", "mine", { mine = true }),
				Line(T0 + 90, "Bb-Realm", long, { guild = "Olympus Zeus" }),
				Line(T0 + 500, "Bb-Realm", "after a pause", { guild = "Olympus Zeus" }),
			} }
			local f = w.CW.Open("A")
			local bs = Visible(f.bubbles)
			eq(#bs, 6, "one bubble a line")
			local rows = Visible(f.rows)
			eq(rows[1].text:GetText(), "|cff9d9d9d" .. L.CHATWIN_KEPT:format(100) .. "|r", "the kept lines, on top")
			assert(RowWith(f, date("%Y-%m-%d", T0 - 86400)) and RowWith(f, date("%Y-%m-%d", T0)), "a row at each day")
			-- Sides.
			assert(bs[2]:Anchor("TOPLEFT") and not bs[2]:Anchor("TOPRIGHT"), "someone else's: left")
			assert(bs[4]:Anchor("TOPRIGHT") and not bs[4]:Anchor("TOPLEFT"), "ours: right")
			eq(bs[4]:Anchor("TOPRIGHT")[2], f.content)
			-- Headers where a writer starts: a new day, a new writer, ours, a pause over 5 minutes.
			eq(bs[1].header:IsShown(), true); eq(bs[2].header:IsShown(), true)
			eq(bs[3].header:IsShown(), false, "the same writer within 300 s")
			eq(bs[4].header:IsShown(), true); eq(bs[4].who:GetText(), L.CHATWIN_YOU)
			eq(bs[5].header:IsShown(), true); eq(bs[6].header:IsShown(), true, "400 s later")
			assert(bs[2].who:GetText():find("Aa", 1, true) and bs[2].who:GetText():find("<Olympus II>", 1, true), bs[2].who:GetText())
			assert(bs[2].time:GetText():find(date("%H:%M", T0), 1, true), "its time")
			-- Gaps: 3 within a writer's lines, 10 between writers; top to bottom in order.
			eq(Top(bs[3]) - (Top(bs[2]) + bs[2]:GetHeight()), 3)
			eq(Top(bs[4]) - (Top(bs[3]) + bs[3]:GetHeight()), 10)
			for i = 2, #bs do assert(Top(bs[i]) > Top(bs[i - 1]), "in order") end
			-- The long line: whole, wrapped, taller than a one-line bubble, within 82 % of the box.
			local b = bs[5]
			eq(b.body:GetText(), ns.Codec.SanitizeChat(long), "never cut")
			assert(b.body.wrap ~= false, "wraps"); eq(b.body:IsTruncated(), false)
			assert(b:GetHeight() > bs[2]:GetHeight() + CW_LINE * 3, "taller")
			local width = f.content:GetWidth()
			assert(b:GetWidth() <= width * 0.82, ("%d wide in %d"):format(b:GetWidth(), width))
			assert(bs[2]:GetWidth() < b:GetWidth(), "a short line, a narrow bubble")
			-- A wider window (the Olympus window, docked to a wider guild window): the long line wraps
			-- again, on fewer lines; the same bubbles.
			local tall, wide = b:GetHeight(), b:GetWidth()
			w.CW.Window():SetSize(800, 600)
			w.CW.Render()
			assert(b:GetWidth() > wide and b:GetHeight() < tall, "wrapped again")
			assert(b:GetWidth() <= f.content:GetWidth() * 0.82)
			eq(#f.bubbles, 6); w.CW.Render(); eq(#f.bubbles, 6, "reused")
			-- (The review of the page's removal: the Realm tab's chats page asserted this, and no Chat
			-- tab test did.) A colour code typed in a line shows as typed: escaped (SanitizeChat), its
			-- bar doubled, never a colour.
			ns.rdb.chat.A = { Line(T0, "Bb-Realm", "second |cffff0000red") }
			w.CW.Render()
			local coded = BubbleWith(f, "red")
			assert(coded and coded.body:GetText():find("second ||cffff0000red", 1, true), coded and coded.body:GetText() or "no bubble")
			eq(coded.body:GetText():find("second |cffff0000red", 1, true), nil, "no bare colour code")
			-- A channel with fewer lines: the others hidden, not dropped.
			ns.rdb.chat.A = { Line(T0, "Aa-Realm", "alone") }
			w.CW.Render()
			eq(#Visible(f.bubbles), 1); eq(#f.bubbles, 6)
			-- Nothing said yet.
			ns.rdb.chat.A = {}
			w.CW.Render()
			eq(#Visible(f.bubbles), 0); assert(RowWith(f, L.CHATWIN_EMPTY:format(L.CHAN_ALL)), "the empty channel says so")
			eq(#ns.rdb.chat.A, 0)
		end)
	end)

	test("1.1.1 Chat tab: the marks in a header: the King's crown, the High Council's mark and colour, silver, bronze, the star, the Treasurer's coin, Steward and Hand", function()
		WithWindow(function(w)
			local saved = { byName = ns.Roster.byName, rankName = GuildControlGetRankName, loginAt = ns.Comm.loginAt, steward = ns.King.IsStewardName,
				hand = ns.King.IsHandName, tex = C_Texture, masked = ns.CouncilMasked }
			local ok, err = pcall(function()
				local bns = setmetatable({ On = function() end, RegisterEvent = function() end }, { __index = ns })
				assert(loadfile(ADDON_DIR .. "Borders.lua"))("Olympus", bns)
				ns.Borders = bns.Borders
				ns.rdb.council = { names = { ["sage owl"] = true } } -- (made-up names only)
				ns.Roster.byName = { ["Raider Guy-Realm"] = 2, ["Vet Guy-Realm"] = 3, ["Plain Guy-Realm"] = 4 }
				GuildControlGetRankName = function(i) return ({ "Master", "Officer", "Raider", "Veteran", "Member" })[i] end
				ns.Comm.loginAt = ns.Now() - ns.Data.CROWN_AFTER - 1
				ns.rdb.guilds["Olympus Zeus"] = Vouched({ guild = "Olympus Zeus", leader = "Zeusy", officers = {}, realm = "Realm", t = ns.Now() }, "W1-Realm", "W2-Realm")
				ns.King.IsStewardName = function(n) return n == "Stew Ard-Realm" end
				ns.King.IsHandName = function(n) return n == "Hand Some-Realm" end
				C_Texture = nil
				ns.rdb.chat = { A = {
					Line(T0, "Asmongold Asmongler-Realm", "the king speaks", { guild = "Olympus" }),
					Line(T0 + 1000, "Sage Owl-Realm", "a councillor speaks"),
					Line(T0 + 2000, "Zeusy-Realm", "a lord speaks", { guild = "Olympus Zeus" }),
					Line(T0 + 3000, "Raider Guy-Realm", "a raider speaks"),
					Line(T0 + 4000, "Vet Guy-Realm", "a veteran speaks"),
					Line(T0 + 5000, "Plain Guy-Realm", "a member speaks"),
					Line(T0 + 6000, "Pyralis Ashandar-Realm", "the treasurer speaks", { guild = "Olympus" }),
					Line(T0 + 7000, "Stew Ard-Realm", "a steward speaks", { guild = "Olympus" }),
					Line(T0 + 8000, "Hand Some-Realm", "a hand speaks", { guild = "Olympus" }),
					Line(T0 + 9000, "Stew Ard-Realm", "not his guild's rule", { guild = "Olympus II" }),
				} }
				local f = w.CW.Open()
				local function Header(text)
					local b = BubbleWith(f, text)
					assert(b, text)
					return b.who:GetText()
				end
				local SILVER = "|A:nameplates-icon-elite-silver:14:14|a"
				local BRONZE = "|A:nameplates-icon-elite-gold:14:14:0:0:158:118:86|a"
				local STAR = "|TInterface\\AddOns\\Olympus\\media\\borders\\star:14:14|t"
				local h = Header("the king speaks")
				eq(h:sub(1, #("|T" .. ns.CROWN_ICON .. ":14:14|t")), "|T" .. ns.CROWN_ICON .. ":14:14|t", "the King's crown first: " .. h)
				h = Header("a councillor speaks")
				assert(h:find(ns.HIGH_COUNCIL_MARK, 1, true) and h:find("|c" .. ns.HIGH_COUNCIL_COLOR .. "Sage Owl|r", 1, true), h)
				assert(not h:find(SILVER, 1, true), "the skull, not the silver mark")
				assert(Header("a lord speaks"):find(SILVER, 1, true), "a Lord: silver")
				assert(Header("a raider speaks"):find(BRONZE, 1, true), "a Raider: bronze")
				assert(Header("a veteran speaks"):find(BRONZE, 1, true), "a Veteran: bronze")
				assert(Header("a member speaks"):find(STAR, 1, true), "a member: the star")
				assert(Header("the treasurer speaks"):find("UI-GoldIcon:0|t", 1, true), "the Treasurer's coin")
				assert(Header("a steward speaks"):find("|cffffd200" .. L.CHATWIN_TAG_STEWARD .. "|r", 1, true), "Steward")
				assert(Header("a hand speaks"):find("|cffffd200" .. L.CHATWIN_TAG_HAND .. "|r", 1, true), "Hand")
				assert(not Header("not his guild's rule"):find(L.CHATWIN_TAG_STEWARD, 1, true), "the tags by the King's guild's rule only")
				-- An atlas the client does not know: the star.
				C_Texture = { GetAtlasInfo = function() return nil end }
				w.CW.Render()
				h = Header("a lord speaks")
				assert(h:find(STAR, 1, true) and not h:find(SILVER, 1, true), h)
				C_Texture = { GetAtlasInfo = function() return { width = 14, height = 14 } end }
				w.CW.Render()
				assert(Header("a lord speaks"):find(SILVER, 1, true))
				-- The King's screen while the councillors' names are hidden (his stream): no skull.
				ns.CouncilMasked = function() return true end
				w.fire("COUNCIL_MASK_CHANGED"); w.CW.Render()
				h = Header("a councillor speaks")
				ns.CouncilMasked = saved.masked
				assert(not h:find(ns.HIGH_COUNCIL_MARK, 1, true) and not h:find(ns.HIGH_COUNCIL_COLOR, 1, true), h)
				-- Without Borders.lua (a client updated without a restart): no mark, the rest as ever.
				ns.Borders = setmetatable({ missing = true }, { __index = function() return function() end end })
				w.CW.Render()
				h = Header("a lord speaks")
				assert(h:find("Zeusy", 1, true) and not h:find("|A:", 1, true), h)
			end)
			ns.Roster.byName, GuildControlGetRankName, ns.Comm.loginAt = saved.byName, saved.rankName, saved.loginAt
			ns.King.IsStewardName, ns.King.IsHandName, C_Texture, ns.CouncilMasked = saved.steward, saved.hand, saved.tex, saved.masked
			if not ok then error(err, 0) end
		end)
	end)

	-- 1.1.2 (the owner, from a screenshot: the silver mark in the Chat tab, none on the same line in the
	-- game's Olympus chat tab): the game's chat windows show the Chat tab's marks.
	test("1.1.2 the game's chat windows: each Olympus line carries the mark its Chat tab header shows (crown, High Council, silver, bronze, star, none)", function()
		WithWindow(function(w)
			local saved = { byName = ns.Roster.byName, rankName = GuildControlGetRankName, loginAt = ns.Comm.loginAt, tex = C_Texture,
				masked = ns.CouncilMasked, borders = ns.Borders }
			local ok, err = pcall(function()
				local bns = setmetatable({ On = function() end, RegisterEvent = function() end }, { __index = ns })
				assert(loadfile(ADDON_DIR .. "Borders.lua"))("Olympus", bns)
				ns.Borders = bns.Borders
				ns.rdb.council = { names = { ["sage owl"] = true } } -- (made-up names only)
				ns.Roster.byName = { ["Raider Guy-Realm"] = 2, ["Vet Guy-Realm"] = 3, ["Plain Guy-Realm"] = 4 }
				GuildControlGetRankName = function(i) return ({ "Master", "Officer", "Raider", "Veteran", "Member" })[i] end
				ns.Comm.loginAt = ns.Now() - ns.Data.CROWN_AFTER - 1
				ns.rdb.guilds["Olympus Zeus"] = Vouched({ guild = "Olympus Zeus", leader = "Zeusy", officers = {}, realm = "Realm", t = ns.Now() }, "W1-Realm", "W2-Realm")
				C_Texture = nil
				local CROWN = "|T" .. ns.CROWN_ICON .. ":14:14|t"
				local SILVER = "|A:nameplates-icon-elite-silver:14:14|a"
				local BRONZE = "|A:nameplates-icon-elite-gold:14:14:0:0:158:118:86|a"
				local STAR = "|TInterface\\AddOns\\Olympus\\media\\borders\\star:14:14|t"
				local cases = {
					{ "Asmongold Asmongler-Realm", "Olympus", CROWN, "the King's crown" },
					{ "Sage Owl-Realm", "Olympus II", ns.HIGH_COUNCIL_MARK, "the High Council's mark" },
					{ "Zeusy-Realm", "Olympus Zeus", SILVER, "a Lord: silver" },
					{ "Raider Guy-Realm", "Olympus II", BRONZE, "a Raider: bronze" },
					{ "Vet Guy-Realm", "Olympus II", BRONZE, "a Veteran: bronze" },
					{ "Plain Guy-Realm", "Olympus II", STAR, "a member: the star" },
				}
				for _, c in ipairs(cases) do
					local who, guild, mark, what = c[1], c[2], c[3], c[4]
					local line = ns.Channels.FormatLine("A", who, guild, "PA", "hello")
					local bare = ns.Channels.FormatLine("A", who, guild, "PA", "hello", true)
					assert(line:find("|h[" .. mark, 1, true), what .. ", right before the name: " .. line)
					assert(bare:find("|h[" .. mark, 1, true), what .. " in the Olympus tab: " .. bare)
					eq(ns.Borders.ChatMark(who, guild), line:match("|h%[(.-)|c") or line:match("|h%[(.-)" .. ns.DisplayName(who)), what .. ": the Chat tab's mark")
				end
				assert(not ns.Channels.FormatLine("A", "Sage Owl-Realm", "Olympus II", nil, "hi"):find(SILVER, 1, true), "the council's mark, not silver")
				-- Nobody our roster or a census proves: no mark, as in the Chat tab.
				local line = ns.Channels.FormatLine("A", "Stranger-Realm", "Olympus II", "PA", "hello")
				assert(not line:find("|A:", 1, true) and not line:find(STAR, 1, true) and not line:find(ns.CROWN_ICON, 1, true), "no mark: " .. line)
				-- An atlas the client does not know: the star, as the Chat tab.
				C_Texture = { GetAtlasInfo = function() return nil end }
				assert(ns.Channels.FormatLine("A", "Zeusy-Realm", "Olympus Zeus", nil, "x"):find("|h[" .. STAR, 1, true))
				C_Texture = nil
				-- The King's screen while the councillors' names are hidden: no council mark or colour.
				ns.CouncilMasked = function() return true end
				line = ns.Channels.FormatLine("A", "Sage Owl-Realm", "Olympus II", nil, "hi")
				assert(not line:find(ns.HIGH_COUNCIL_MARK, 1, true) and not line:find(ns.HIGH_COUNCIL_COLOR, 1, true), line)
				ns.CouncilMasked = saved.masked
				-- Without Borders.lua (a client updated without a restart): the council's mark alone, as before.
				ns.Borders = nil
				assert(ns.Channels.FormatLine("A", "Sage Owl-Realm", "Olympus II", nil, "hi"):find("|h[" .. ns.HIGH_COUNCIL_MARK .. "|c", 1, true))
				assert(not ns.Channels.FormatLine("A", "Zeusy-Realm", "Olympus Zeus", nil, "x"):find("|A:", 1, true))
			end)
			ns.Roster.byName, GuildControlGetRankName, ns.Comm.loginAt, C_Texture = saved.byName, saved.rankName, saved.loginAt, saved.tex
			ns.CouncilMasked, ns.Borders = saved.masked, saved.borders
			if not ok then error(err, 0) end
		end)
	end)

	-- (Changed on purpose, the owner's ask after trying the tab: "Enter and keep typing, Enter and keep
	-- typing, without going back to the game's controls". With mouse and keyboard a line sent, a
	-- refused one and a command kept leave the cursor in the box; an empty Enter, Escape and the
	-- privacy warning still let it go. It was: every Enter let the keyboard go, as the Communities
	-- box does, which the gamepad UI keeps: the key's tests below.)
	test("1.1.1 Chat tab: its own box: Enter sends through Channels.Send and the cursor stays for the next line; a refusal keeps the text and the cursor, the privacy warning empties it and lets go; no slash command; an empty Enter or Escape lets go; Tab changes channel", function()
		WithWindow(function(w)
			AsCaptain()
			local sent, answers = {}, {}
			ns.Channels.Send = function(t, text)
				sent[#sent + 1] = t .. " " .. text
				local a = table.remove(answers, 1) or { true, "ok" }
				return a[1], a[2]
			end
			local f = w.CW.Open("A")
			local eb = f.input
			eq(eb.hint:IsShown(), true, "a grey hint while empty")
			eq(eb.hint:GetText(), L.CHATWIN_PLACEHOLDER:format(L.CHAN_ALL) .. L.CHATWIN_PUBLIC, "the channel is public here")
			assert(eb.label:GetText():find("[" .. L.CHAN_ALL .. "]:", 1, true), "the channel's label")
			eb.focused = true
			eb:Fire("OnEditFocusGained")
			eq(eb.hint:IsShown(), false, "no hint while typing")
			eb:SetText("  hi  ")
			eb:Fire("OnEnterPressed")
			eq(sent[1], "A hi"); eq(eb:GetText(), ""); eq(eb.focused, true, "sent: the cursor stays for the next line")
			eq(eb.hint:IsShown(), false, "no hint while it is there")
			answers = { { false, "fast" } }
			eb:SetText("again")
			eb:Fire("OnEnterPressed")
			eq(sent[2], "A again"); eq(eb:GetText(), "again", "refused: the text stays"); eq(eb.focused, true, "and the cursor")
			answers = { { false, "confirm" } }
			eb:Fire("OnEnterPressed")
			eq(sent[3], "A again"); eq(eb:GetText(), "", "held by the privacy warning: the box empties")
			eq(eb.focused, false, "and lets go: the warning's Send or Cancel is next")
			eb.focused = true
			eb:SetText("/cast Fireball")
			eb:Fire("OnEnterPressed")
			eq(#sent, 3, "no command sent, none run"); eq(eb:GetText(), "/cast Fireball", "kept"); eq(eb.focused, true)
			assert(Said(w, L.CHATWIN_NO_SLASH:format(L.CHAN_ALL)), "told where commands go")
			eb:SetText("   ")
			eb:Fire("OnEnterPressed")
			eq(#sent, 3, "nothing to send"); eq(eb.focused, false, "an empty Enter lets go"); eq(eb:GetText(), "")
			-- (Changed on purpose, the author's ask: no Send button, so the box is not cramped: Enter sends.)
			eq(f.send, nil, "no Send button")
			eb:SetText("by enter")
			eb.focused = true
			eb:Fire("OnEnterPressed")
			eq(sent[4], "A by enter"); eq(eb:GetText(), ""); eq(eb.focused, true, "sent, and the cursor still there")
			eb.focused = true
			eb:Fire("OnEscapePressed")
			eq(eb.focused, false, "Escape lets go")
			eb:Fire("OnTabPressed")
			eq(w.CW.Tier(), "C", "Tab: the next channel"); assert(eb.label:GetText():find("[" .. L.CHAN_CAPTAINS .. "]:", 1, true))
			eb:SetText("for captains")
			eb:Fire("OnEnterPressed")
			eq(sent[5], "C for captains")
			eb:Fire("OnTabPressed")
			eq(w.CW.Tier(), "A", "and round")
			-- Taken off by the moderators: their word in the hint (Send refuses, as ever).
			ns.Moderation.SelfOff = function() return { kind = "c" } end
			ns.Moderation.YouText = function() return "YOU ARE OFF" end
			w.CW.Render()
			eq(eb.hint:GetText(), "YOU ARE OFF")
			-- The box hidden with the window: the keyboard let go.
			eb.focused = true
			w.CW.Window():Hide()
			eq(eb.focused, false)
			-- And with another tab picked.
			w.CW.Open()
			eb.focused = true
			w.UI.SelectTab("census")
			eq(eb.focused, false)
			eq(#w.focus, 0, "never SetFocus")
		end)
	end)

	-- (Changed on purpose, the author's ask: the pills' row is gone; another channel's lines count on
	-- the switch of the top row, "+N", and on that channel's line in its list, as they did on its pill.)
	test("1.1.1 Chat tab: new lines show at the bottom while it follows; scrolled up, an \"N new\" pill; another channel's lines count on the channels' switch; nothing drawn while hidden, then at most every 0.2 s", function()
		WithWindow(function(w)
			AsCaptain()
			local list = {}
			for i = 1, 30 do list[i] = Line(T0 + i * 10, "Aa-Realm", "line " .. i) end
			ns.rdb.chat = { A = list, C = {} }
			local f = w.CW.Open("A")
			local s = f.scroll
			s:Settle()
			assert(s:GetVerticalScrollRange() > 0, "more lines than the view")
			eq(s:GetVerticalScroll(), s:GetVerticalScrollRange(), "opened at the newest line")
			local function Arrive(t, text)
				local l = ns.rdb.chat[t]
				l[#l + 1] = Line(T0 + 1000 + #l, "Bb-Realm", text)
				w.fire("CHAT_CHANGED", t)
				w.fire("CHAT_LINE", t, "Bb-Realm", text)
			end
			Arrive("A", "fresh one")
			w.CW.Render(); s:Settle()
			assert(BubbleWith(f, "fresh one"), "drawn")
			eq(s:GetVerticalScroll(), s:GetVerticalScrollRange(), "still at the newest line")
			eq(f.newPill:IsShown(), false)
			-- The player scrolls up: the view stays; new lines count on the pill.
			s:SetVerticalScroll(0)
			Arrive("A", "while up")
			w.CW.Render(); s:Settle()
			eq(s:GetVerticalScroll(), 0, "where he put it")
			eq(f.newPill:IsShown(), true); eq(f.newPill:GetText(), L.CHATWIN_NEW_LINES:format(1))
			Arrive("A", "and another")
			w.CW.Render(); s:Settle()
			eq(f.newPill:GetText(), L.CHATWIN_NEW_LINES:format(2)); eq(s:GetVerticalScroll(), 0)
			f.newPill:Click()
			s:Settle()
			eq(s:GetVerticalScroll(), s:GetVerticalScrollRange(), "the pill: down to them"); eq(f.newPill:IsShown(), false)
			-- Scrolled back down by hand: it follows again.
			s:SetVerticalScroll(0)
			s:SetVerticalScroll(s:GetVerticalScrollRange())
			Arrive("A", "followed")
			w.CW.Render(); s:Settle()
			eq(s:GetVerticalScroll(), s:GetVerticalScrollRange()); eq(f.newPill:IsShown(), false)
			-- Our own line: to the bottom.
			ns.Channels.Send = function() return true, "ok" end
			s:SetVerticalScroll(0)
			f.input:SetText("mine")
			f.input:Fire("OnEnterPressed")
			local l = ns.rdb.chat.A
			l[#l + 1] = Line(T0 + 2000, "Cap-Realm", "mine", { mine = true })
			w.fire("CHAT_CHANGED", "A")
			w.CW.Render(); s:Settle()
			eq(s:GetVerticalScroll(), s:GetVerticalScrollRange(), "after our own line")
			-- Another channel: counted on the switch and on its line in the switch's list, until picked.
			Arrive("C", "for captains")
			Arrive("C", "again for captains")
			w.CW.Render()
			eq(f.switch:IsShown(), true, "a Captain reads two channels: the switch")
			eq(f.switch.text:GetText(), L.CHAN_ALL, "the channel shown"); eq(f.switch.count:GetText(), "+2")
			f.switch:Fire("OnEnter")
			local tip = table.concat(TipLines(), "\n")
			assert(tip:find(L.CHATWIN_NEW_IN:format(L.CHAN_CAPTAINS, 2), 1, true), tip)
			f.switch:Fire("OnLeave")
			f.switch:Click()
			eq(f.menu:IsShown(), true, "its list")
			eq(f.menu.rows.C.text:GetText(), L.CHAN_CAPTAINS .. " (2)"); eq(f.menu.rows.A.text:GetText(), L.CHAN_ALL)
			eq(f.menu.rows.L:IsShown(), false, "not a Lord's")
			eq(f.menu.rows.A.mark:IsShown(), true, "the one shown marked"); eq(f.menu.rows.C.mark:IsShown(), false)
			f.menu.rows.C:Click()
			eq(w.CW.Tier(), "C"); eq(f.menu:IsShown(), false, "picked: the list closes")
			eq(f.switch.text:GetText(), L.CHAN_CAPTAINS); eq(f.switch.count:IsShown(), false)
			assert(BubbleWith(f, "again for captains"))
			-- Muted in chat: its line in the list says the tab still shows it.
			ns.db.chatMute = { C = true }
			f.switch:Click()
			f.menu.rows.C:Fire("OnEnter")
			tip = table.concat(TipLines(), "\n")
			assert(tip:find(L.CHATWIN_MUTED_TIP, 1, true), tip)
			f.menu.rows.C:Fire("OnLeave")
			f.catcher:Click()
			eq(f.menu:IsShown(), false, "a click elsewhere closes the list"); eq(w.CW.Tier(), "C")
			-- Hidden: the listeners draw nothing. Shown: once, after 0.2 s.
			local calls = 0
			local real = ns.Channels.History
			ns.Channels.History = function(...) calls = calls + 1; return real(...) end
			f:Hide()
			Arrive("C", "while hidden")
			w.fire("DATA_CHANGED"); w.fire("PIN_CHANGED"); w.fire("FILTER_CHANGED"); w.fire("NETOFF_CHANGED", {}); w.fire("CONSENT_CHANGED", "chat", true)
			eq(calls, 0, "nothing drawn while hidden")
			f:Show()
			f:Fire("OnUpdate", 0.1)
			eq(calls, 0, "not before 0.2 s")
			f:Fire("OnUpdate", 0.15)
			eq(calls, 1, "drawn once")
			f:Fire("OnUpdate", 0.3)
			eq(calls, 1, "nothing new: not again")
			-- The census: at most once every 5 seconds.
			local clock = 100
			GetTime = function() return clock end
			w.fire("DATA_CHANGED")
			f:Fire("OnUpdate", 0.3)
			eq(calls, 2, "the census's first change")
			w.fire("DATA_CHANGED")
			clock = 102
			f:Fire("OnUpdate", 0.3)
			eq(calls, 2, "not within 5 s")
			clock = 105
			f:Fire("OnUpdate", 0.3)
			eq(calls, 3, "then once")
			-- Unread counts start again when it opens.
			PickChannel(f, "A")
			Arrive("C", "one more for captains")
			w.CW.Render()
			eq(f.switch.count:GetText(), "+1")
			f:Hide()
			w.CW.Open("A")
			eq(f.switch.count:IsShown(), false, "none since it opened")
		end)
	end)

	test("1.1.1 Chat tab: a line the block terms hide is a short grey bubble, shown by a click; ours never hidden; the history untouched", function()
		WithWindow(function(w)
			ns.Filter.Hides = function(text) return text:find("badword", 1, true) ~= nil end
			ns.rdb.chat = { A = { Line(T0, "Aa-Realm", "a badword here"), Line(T0 + 10, "Soldier-Realm", "my badword", { mine = true }),
				Line(T0 + 20, "Bb-Realm", "clean words") } }
			local f = w.CW.Open()
			local b = BubbleWith(f, L.CHATWIN_HIDDEN)
			assert(b and b.hidden, "a grey bubble")
			eq(BubbleWith(f, "a badword here"), nil, "its words not shown")
			assert(BubbleWith(f, "my badword"), "ours never hidden")
			assert(BubbleWith(f, "clean words"))
			assert(b.header:IsShown(), "who wrote it still shows")
			b:Fire("OnMouseUp", "LeftButton")
			assert(BubbleWith(f, "a badword here"), "shown by a click")
			eq(BubbleWith(f, L.CHATWIN_HIDDEN), nil)
			eq(ns.rdb.chat.A[1].revealed, nil, "the history untouched"); eq(ns.rdb.chat.A[1].text, "a badword here")
			-- Another window (a new session of it): hidden again.
			w.CW.Reset()
			f = w.CW.Open()
			assert(BubbleWith(f, L.CHATWIN_HIDDEN))
		end)
	end)

	test("1.1.1 Chat tab: the pinned line on top, as the Realm tab shows it: veiled words shown by a click, taken down through ns.ShowDialog; none, no strip", function()
		WithWindow(function(w)
			local p = { sender = "Kingly Man-Realm", guild = "Olympus", text = "raid at the gates at nine", setAt = ns.Now(), expires = ns.Now() + 3600, rank = 5 }
			ns.Channels.Pin = function() return p end
			ns.Channels.CanTakeDown = function() return true end
			local dialogs = {}
			ns.ShowDialog = function(which) dialogs[#dialogs + 1] = which end
			local f = w.CW.Open()
			eq(f.pin:IsShown(), true)
			local text = f.pin.text:GetText()
			assert(text:find(L.CHATWIN_PINNED, 1, true) and text:find("raid at the gates at nine", 1, true) and text:find("Kingly Man", 1, true), text)
			local withPin = f.box:Anchor("TOPLEFT")[5]
			f.pin:Fire("OnEnter")
			local tip = table.concat(TipLines(), "\n")
			assert(tip:find(L.PIN_DOWN_TIP, 1, true), tip)
			f.pin:Click()
			eq(dialogs[1], "OLYMPUS_PIN_DOWN", "taken down after the question")
			-- Veiled by the block terms: a click shows the words, nothing taken down.
			ns.Filter.Hides = function(t) return t:find("raid", 1, true) ~= nil end
			w.fire("FILTER_CHANGED"); w.CW.Render()
			text = f.pin.text:GetText()
			assert(text:find(L.FILTER_WORDS_HIDDEN, 1, true) and not text:find("raid at", 1, true), text)
			f.pin:Click()
			eq(p.revealed, true); eq(#dialogs, 1)
			assert(f.pin.text:GetText():find("raid at the gates", 1, true))
			-- None: no strip, the lines higher.
			ns.Channels.Pin = function() return nil end
			w.fire("PIN_CHANGED"); w.CW.Render()
			eq(f.pin:IsShown(), false)
			assert(f.box:Anchor("TOPLEFT")[5] > withPin, "the box moves up")
			eq(#w.focus, 0)
		end)
	end)

	test("1.1.1 Chat tab: the chats off on this client: the window says so and offers the choice, no box; on again, the lines and the box", function()
		WithWindow(function(w)
			ns.db.addonChat = false
			local asked = 0
			ns.Consent.Show = function() asked = asked + 1 end
			ns.rdb.chat = { A = { Line(T0, "Aa-Realm", "kept while on") } }
			local f = w.CW.Open()
			eq(w.CW.Window().tab, "chat", "the tab shows for a member with the chats off too")
			-- (The Chat tab says what the Realm tab's chats line says when they are off: the choice and
			-- what it means, CONSENT_CHAT_TEXT, with /oly chat on|off; the window said CHATWIN_OFF alone.)
			eq(f.off:IsShown(), true); eq(f.off.text:GetText(), L.CHATWIN_OFF .. "\n\n" .. L.CONSENT_CHAT_TEXT)
			eq(f.off.button:GetText(), L.CHATWIN_OFF_BUTTON)
			eq(f.input:IsShown(), false, "no box"); eq(f.scroll:IsShown(), false); eq(f.search:IsShown(), false, "no search")
			eq(f.guide:IsShown(), false, "no Olympus tab line")
			-- (The Olympus window asks its first-open page when it opens, whatever the tab: counted apart.)
			local before = asked
			f.off.button:Click()
			eq(asked, before + 1, "the first-open page, Olympus's own")
			ns.db.addonChat = true
			w.fire("CHAT_CHANGED")
			f:Fire("OnUpdate", 0.3)
			eq(f.off:IsShown(), false); eq(f.input:IsShown(), true); eq(f.search:IsShown(), true)
			assert(BubbleWith(f, "kept while on"))
		end)
	end)

	test("1.1.1 Chat tab: a name's click whispers through Olympus's whisper window; nothing opens or writes the game's chat box, with mouse and keyboard or the gamepad UI", function()
		WithWindow(function(w)
			local calls, saved = {}, {}
			local traps = { "ChatFrame_SendTell", "ChatFrame_OpenChat", "SetItemRef", "ChatEdit_InsertLink", "HandleModifiedItemClick",
				"ChatEdit_ActivateChat", "ChatFrame_ActivateChat", "ChatEdit_FocusActiveWindow", "ChatFrameUtil" }
			for _, name in ipairs(traps) do saved[name] = rawget(_G, name) end
			local ok, err = pcall(function()
				for _, name in ipairs(traps) do _G[name] = function() calls[#calls + 1] = name end end
				ChatFrameUtil = setmetatable({}, { __index = function(_, k) return function() calls[#calls + 1] = "ChatFrameUtil." .. k end end })
				local told = {}
				ns.UI.WhisperWindow = function(n) told[#told + 1] = n end
				ns.Channels.Send = function() return true, "ok" end
				ns.rdb.chat = { A = { Line(T0, "Aa Bb-Realm", "hello from Aa"), Line(T0 + 10, "Soldier-Realm", "mine", { mine = true }),
					Line(T0 + 20, "Cc-Realm", "look " .. MOONCLOTH_TEXT) } }
				for _, pad in ipairs({ false, true }) do
					WithGamepadUI(pad, function(game)
						w.CW.Reset()
						local f = w.CW.Open()
						assert(f, "open")
						local b = BubbleWith(f, "hello from Aa")
						b.header:Fire("OnEnter")
						local tip = table.concat(TipLines(), "\n")
						assert(tip:find(L.CHATWIN_WHISPER_TIP:format("Aa Bb"), 1, true), tip)
						b.header:Click()
						eq(told[#told], "Aa Bb", "the name the server finds")
						local n = #told
						BubbleWith(f, "mine").header:Click()
						eq(#told, n, "our own name: nothing")
						local lb = BubbleWith(f, "[Mooncloth]")
						IsShiftKeyDown = function() return true end
						lb:Fire("OnHyperlinkEnter", MOONCLOTH_LINK, MOONCLOTH_TEXT)
						lb:Fire("OnHyperlinkClick", MOONCLOTH_LINK, MOONCLOTH_TEXT, "LeftButton")
						lb:Fire("OnHyperlinkLeave")
						f.input:Fire("OnEnterPressed")
						w.CW.Toggle()
						eq(#game.shown, 0, "no game popup")
					end)
				end
				eq(#told, 2)
				eq(#calls, 0, "the game's chat untouched: " .. table.concat(calls, " "))
				eq(#w.focus, 0)
			end)
			for _, name in ipairs(traps) do _G[name] = saved[name] end
			if not ok then error(err, 0) end
		end)
	end)

	test("1.1.1 Chat tab: a link in a line shows its tooltip on hover, and a Shift-click puts it in the window's own box", function()
		WithWindow(function(w)
			ns.rdb.chat = { A = { Line(T0, "Aa-Realm", "look " .. MOONCLOTH_TEXT .. " cheap") } }
			local f = w.CW.Open()
			local b = BubbleWith(f, "[Mooncloth]")
			assert(b, "the link kept in the line")
			local shown
			GameTooltip.SetHyperlink = function(_, link) shown = link end
			GameTooltip:Hide()
			b:Fire("OnHyperlinkEnter", MOONCLOTH_LINK, MOONCLOTH_TEXT)
			eq(shown, MOONCLOTH_LINK); eq(GameTooltip.owner, b); eq(GameTooltip:IsShown(), true)
			b:Fire("OnHyperlinkLeave")
			eq(GameTooltip:IsShown(), false)
			shown = nil
			b:Fire("OnHyperlinkEnter", "player:Someone", "[Someone]")
			eq(shown, nil, "only the links a line may carry")
			-- A tooltip that fails: hidden, no error.
			GameTooltip.SetHyperlink = function() error("bad link") end
			b:Fire("OnHyperlinkEnter", MOONCLOTH_LINK, MOONCLOTH_TEXT)
			eq(GameTooltip:IsShown(), false)
			-- Shift-click: into our box, where it was; without Shift, nothing.
			f.input:SetText("wts ")
			IsShiftKeyDown = function() return false end
			b:Fire("OnHyperlinkClick", MOONCLOTH_LINK, MOONCLOTH_TEXT, "LeftButton")
			eq(f.input:GetText(), "wts ")
			IsShiftKeyDown = function() return true end
			b:Fire("OnHyperlinkClick", MOONCLOTH_LINK, MOONCLOTH_TEXT, "LeftButton")
			eq(f.input:GetText(), "wts " .. MOONCLOTH_TEXT)
			eq(#w.focus, 0, "the keyboard stays where it was")
			-- And it goes out as typed.
			local sent
			ns.Channels.Send = function(_, text) sent = text return true, "ok" end
			f.input:Fire("OnEnterPressed")
			eq(sent, "wts " .. MOONCLOTH_TEXT)
			-- The window closed: its tooltip goes with it.
			b:Fire("OnHyperlinkEnter", MOONCLOTH_LINK, MOONCLOTH_TEXT)
			GameTooltip.SetHyperlink = function(_, link) shown = link end
			b:Fire("OnHyperlinkEnter", MOONCLOTH_LINK, MOONCLOTH_TEXT)
			eq(GameTooltip:IsShown(), true)
			f:Hide()
			eq(GameTooltip:IsShown(), false)
		end)
	end)

	test("1.1.1 Chat tab: a line of ours that did not leave (CHAT_SEND_FAILED) is a note in its channel, and a click puts it back in the box", function()
		WithWindow(function(w)
			AsCaptain()
			ns.rdb.chat = { A = { Line(T0, "Aa-Realm", "hi") }, C = {} }
			local f = w.CW.Open("A")
			w.fire("CHAT_SEND_FAILED", "A", "moved", "my lost line", 0)
			w.CW.Render()
			local moved = L.CHATWIN_NOT_SENT:format(L.CHATWIN_WHY_MOVED)
			local r = RowWith(f, moved)
			assert(r, "the note")
			assert(r.text:GetText():find(L.CHATWIN_PUT_BACK, 1, true))
			r:Click()
			eq(f.input:GetText(), "my lost line", "back in the box"); eq(#w.focus, 0, "not focused")
			eq(RowWith(f, moved), nil, "the note gone")
			for why, key in pairs({ late = "CHATWIN_WHY_LATE", failed = "CHATWIN_WHY_FAILED", left = "CHATWIN_WHY_LEFT", odd = "CHATWIN_WHY_FAILED" }) do
				w.fire("CHAT_SEND_FAILED", "A", why, "line " .. why)
				w.CW.Render()
				assert(RowWith(f, L.CHATWIN_NOT_SENT:format(L[key])), why)
			end
			-- Another channel's: in that channel.
			w.fire("CHAT_SEND_FAILED", "C", "moved", "for captains")
			w.CW.Render()
			eq(#Visible(f.rows) - 2, 4, "four notes here (the kept row and a day row besides)")
			PickChannel(f, "C")
			assert(RowWith(f, moved), "the Captains' note")
			-- Nonsense: nothing.
			w.fire("CHAT_SEND_FAILED", "X", "moved", "x"); w.fire("CHAT_SEND_FAILED", "A", "moved", nil); w.fire("CHAT_SEND_FAILED", "A", "moved", "")
			PickChannel(f, "A")
			eq(#Visible(f.rows) - 2, 4)
			-- A line sent: the notes of that channel go.
			ns.Channels.Send = function() return true, "ok" end
			f.input:SetText("new line")
			f.input:Fire("OnEnterPressed")
			w.CW.Render()
			eq(RowWith(f, L.CHATWIN_PUT_BACK), nil)
			PickChannel(f, "C")
			assert(RowWith(f, moved), "the other channel's stays")
		end)
	end)

	-- (Changed on purpose: the chats are a tab of the Olympus window now, which has its own place and
	-- size; ns.db.chatWin keeps the channel last shown alone, and the first build's place and size
	-- are dropped at load. The window's dragging and docking have their own tests above.)
	test("1.1.1 Chat tab: the channel last shown is kept and opened again; nothing of a place or size of its own, and the first build's are dropped at load", function()
		WithWindow(function(w)
			AsCaptain()
			local f = w.CW.Open()
			local main = w.CW.Window()
			eq(f.grip, nil, "no resize grip"); eq(f.resizeBounds, nil)
			assert(f:Anchor("TOPLEFT") and f:Anchor("BOTTOMRIGHT"), "the tab fills its window")
			eq(f:Anchor("TOPLEFT")[2], main); eq(f:Anchor("BOTTOMRIGHT")[2], main)
			PickChannel(f, "C")
			eq(ns.db.chatWin.tier, "C", "the channel"); eq(ns.db.chatWin.x, nil); eq(ns.db.chatWin.w, nil)
			main:Hide()
			w.CW.Reset()
			f = w.CW.Open()
			eq(w.CW.Tier(), "C", "the channel it was on")
			-- A soldier now: the channel he reads.
			main:Hide()
			w.CW.Reset()
			AsSoldier()
			assert(w.CW.Open(), "open")
			eq(w.CW.Tier(), "A")
			-- Loaded: a channel's letter alone is kept.
			ns.db.chatWin = "junk"
			w.fire("INIT"); eq(ns.db.chatWin, nil)
			ns.db.chatWin = { x = "a", y = 1, w = 400, h = 400, tier = "Z" }
			w.fire("INIT"); eq(ns.db.chatWin, nil)
			ns.db.chatWin = { x = 1, y = 2, w = 400, h = 400, tier = "C", extra = 1 }
			w.fire("INIT")
			eq(ns.db.chatWin.tier, "C"); eq(ns.db.chatWin.x, nil, "the first build's place dropped"); eq(ns.db.chatWin.h, nil); eq(ns.db.chatWin.extra, nil)
			ns.db.chatWin = { x = 1 / 0, y = 2, w = 400, h = 400 }
			w.fire("INIT"); eq(ns.db.chatWin, nil, "nothing left to keep")
			-- (The review of the Chat tab: the Olympus tab's line put away with its x is kept too, as
			-- true alone.)
			ns.db.chatWin = { tier = "C", noTabLine = true, x = 1 }
			w.fire("INIT")
			eq(ns.db.chatWin.tier, "C"); eq(ns.db.chatWin.noTabLine, true); eq(ns.db.chatWin.x, nil)
			ns.db.chatWin = { tier = "Z", noTabLine = true }
			w.fire("INIT"); eq(ns.db.chatWin.tier, nil); eq(ns.db.chatWin.noTabLine, true, "alone")
			ns.db.chatWin = { tier = "A", noTabLine = "yes" }
			w.fire("INIT"); eq(ns.db.chatWin.tier, "A"); eq(ns.db.chatWin.noTabLine, nil)
			ns.db.chatWin = { noTabLine = 1 }
			w.fire("INIT"); eq(ns.db.chatWin, nil)
		end)
	end)

	-- (Changed on purpose: every way in opens the Olympus window on its Chat tab, on the channel
	-- asked for, where the first build opened a window of its own; toggled, the window closes. And,
	-- the author's call, the Realm tab's chats page is gone: the Realm's link to the chats is the way
	-- in from there, where the page's "Open the Chat tab" and "Write in" lines were; the page's
	-- Olympus tab line is in the Chat tab's settings, their own test.)
	test("1.1.4 Chat tab's ways in: /oly talk, Shift-click and the top-level tab open it; Realm has no duplicate shortcut", function()
		WithWindow(function(w)
			local saved = { open = rawget(_G, "ChatFrame_OpenChat"), map = ns.Map.SetEnabled,
				setup = ns.Channels.SetupTab, state = ns.Channels.TabState }
			local ok, err = pcall(function()
				local function OnTab(tier, why)
					local main = w.CW.Window()
					eq(w.CW.IsShown(), true, why); eq(main and main:IsShown(), true, why); eq(main.tab, "chat", why)
					if tier then eq(w.CW.Tier(), tier, why) end
				end
				-- /oly talk
				SlashCmdList.OLYMPUS("talk")
				OnTab("A", "/oly talk")
				SlashCmdList.OLYMPUS("talk")
				eq(w.CW.IsShown(), false); eq(OlympusFrame:IsShown(), false, "again: the window closes")
				AsLord()
				SlashCmdList.OLYMPUS("talk lords")
				OnTab("L", "/oly talk lords")
				SlashCmdList.OLYMPUS("falar capitães")
				OnTab("C", "another channel: that one")
				SlashCmdList.OLYMPUS("talk captains")
				eq(w.CW.IsShown(), false)
				AsSoldier()
				w.printed = {}
				SlashCmdList.OLYMPUS("talk lords")
				eq(w.CW.IsShown(), false); eq(w.printed[1], L.CHAN_ONLY_LORDS:format(L.CHAN_LORDS))
				-- The minimap button.
				local UI = w.UI
				Minimap = NewWidget("Frame", "Minimap", UIParent)
				Minimap.w, Minimap.h = 140, 140
				UI.UpdateMinimapButton()
				local b = OlympusMinimapButton
				local toggled, mapped = 0, 0
				local realToggle = UI.Toggle
				UI.Toggle = function() toggled = toggled + 1 end
				ns.Map.SetEnabled = function() mapped = mapped + 1 end
				IsShiftKeyDown = function() return true end
				b:Fire("OnClick", "LeftButton")
				OnTab("A", "Shift-click: the Chat tab"); eq(toggled, 0)
				b:Fire("OnClick", "LeftButton")
				eq(w.CW.IsShown(), false); eq(OlympusFrame:IsShown(), false)
				IsShiftKeyDown = function() return false end
				b:Fire("OnClick", "LeftButton")
				eq(toggled, 1, "a plain click: the Olympus window"); eq(w.CW.IsShown(), false)
				IsShiftKeyDown = nil
				b:Fire("OnClick", "LeftButton")
				eq(toggled, 2)
				b:Fire("OnClick", "RightButton")
				eq(mapped, 1, "right-click: the map, as ever")
				UI.Toggle = realToggle
				b:Fire("OnEnter")
				local lines = TipLines()
				local left, shift
				for i, l in ipairs(lines) do
					if l == L.MINIMAP_LEFT then left = i end
					if l == L.MINIMAP_SHIFT then shift = i end
				end
				assert(left and shift == left + 1, "the Shift-click line after the click's: " .. table.concat(lines, " / "))
				-- Chat remains directly selectable in either input mode, but the Realm has no redundant
				-- shortcut row. Selecting it never opens the game's chat box or a game popup.
				local opened = 0
				ChatFrame_OpenChat = function() opened = opened + 1 end
				local function At(ls, text)
					for i, l in ipairs(ls) do if (l.text or ""):find(text, 1, true) then return l, i end end
				end
				for _, pad in ipairs({ false, true }) do
					WithGamepadUI(pad, function(game)
						w.UI.SelectTab("realm")
						eq(OlympusFrame.tab, "realm")
						eq(At(ns.Views.RealmLines(), L.CHATS_LINK), nil, "no Realm chat shortcut")
						w.UI.SelectTab("chat")
						OnTab("A", "the top-level Chat tab")
						eq(opened, 0, "never the game's chat box"); eq(#game.shown, 0, "no game popup"); eq(#w.focus, 0, "no keyboard taken")
						w.CW.Close()
					end)
				end
				-- A Captain whose Chat tab last showed [Captains]: there again.
				AsCaptain()
				w.CW.Open("C"); w.CW.Close()
				w.UI.SelectTab("realm")
				eq(At(ns.Views.RealmLines(), L.CHATS_LINK), nil)
				w.UI.SelectTab("chat")
				OnTab("C", "the channel last shown")
				-- The page and its ways are gone: nothing on the Realm tab to open or write from.
				eq(ns.Views.ShowChat, nil); eq(ns.Views.ChatShown, nil); eq(ns.UI.ChatWindow, nil)
				w.CW.Close()
				AsSoldier()
			end)
			ChatFrame_OpenChat, ns.Map.SetEnabled = saved.open, saved.map
			ns.Channels.SetupTab, ns.Channels.TabState = saved.setup, saved.state
			ns.Views.ClearFilters()
			if not ok then error(err, 0) end
		end)
	end)

	-- The two halves of 1.1.1 together (checked after the merge, as the design asked): /ol alone
	-- opens the real window on its channel, and the Olympus tab's line runs the real SetupTab.
	-- (Changed on purpose: that line was the Realm tab's chats page's, gone; it is the Chat tab's
	-- settings' now.)
	test("1.1.1 merged: /ol, /olc and /oll alone open the real Olympus window on its Chat tab, on their channel; the Chat tab's settings' Olympus tab line sets up the real Olympus tab", function()
		WithWindow(function(w)
			local saved = { windows = ns.db.chatWindows, intro = ns.db.chatTabIntro, info = GetChatWindowInfo, num = NUM_CHAT_WINDOWS,
				frame2 = rawget(_G, "ChatFrame2") }
			local ok, err = pcall(function()
				AsCaptain()
				SlashCmdList.OLYMPUSALL("")
				eq(w.CW.IsShown(), true, "/ol alone opens it"); eq(w.CW.Tier(), "A")
				eq(OlympusFrame:IsShown(), true, "the Olympus window"); eq(OlympusFrame.tab, "chat", "on its Chat tab")
				SlashCmdList.OLYMPUSCAPTAINS("  ")
				eq(w.CW.IsShown(), true); eq(w.CW.Tier(), "C", "/olc alone: the Captains' channel")
				eq(OlympusFrame.tab, "chat")
				SlashCmdList.OLYMPUSCAPTAINS("")
				eq(w.CW.IsShown(), false, "again: it closes"); eq(OlympusFrame:IsShown(), false, "the window with it")
				-- The window on another tab: /oll alone turns it to the Chat tab, on [Lords].
				AsLord()
				w.UI.SelectTab("decrees")
				SlashCmdList.OLYMPUSLORDS("")
				eq(OlympusFrame.tab, "chat"); eq(w.CW.Tier(), "L"); eq(w.CW.IsShown(), true)
				w.CW.Close()
				AsCaptain()
				-- The tab line with the real Channels.SetupTab: no tab made yet, so the Chat tab shows
				-- how (its line's steps; the pointer with mouse and keyboard, none with the gamepad UI),
				-- and the real SetupTab runs when the player has made it. (Changed on purpose, the review
				-- of the Chat tab: the line ran SetupTab at once, which printed the steps and waited.)
				ns.db.addonChat = true
				for _, pad in ipairs({ false, true }) do
					WithGamepadUI(pad, function(game)
						w.CW.Close()
						w.CW.Reset()
						ns.db.chatWindows, ns.db.chatTabIntro = nil, nil
						NUM_CHAT_WINDOWS = 2
						local olympus = nil
						ChatFrame2 = { name = "", AddMessage = function(self, text) self.said = (self.said or 0) + 1 end }
						GetChatWindowInfo = function(i)
							if i == 1 then return "General", 14, 0, 0, 0, 1, true, false, nil, false end
							return olympus or "", 14, 0, 0, 0, 1, olympus ~= nil, false, nil, false
						end
						local f = w.CW.Open("A")
						f.gear:Click()
						eq(w.CW.SettingsShown(), true)
						local tab = Setting(f, L.CHATS_TAB_ADD)
						assert(tab, "the tab line in the settings, from the real TabState")
						w.printed = {}
						tab:Click()
						eq(ns.Channels.TabState(), "none", "nothing chosen before the tab exists")
						eq(w.CW.Watching(), true); eq(OlympusFrame.tab, "chat")
						assert(Setting(f, L.CHATS_TAB_STEPS:match("^(.-)%%s")), "the steps, in the settings")
						f.gear:Click()
						eq(w.CW.SettingsShown(), false, "back to the lines")
						local guide = f.guide
						eq(guide:IsShown(), true)
						assert(guide.text:GetText():find(L.CHATS_TAB_STEPS:match("^(.-)%%s"), 1, true), guide.text:GetText())
						local p = w.CW.Pointer()
						if pad then
							eq(p, nil, "no pointer with the gamepad UI"); eq(#game.shown, 0, "no game popup")
						else
							assert(p and p:IsShown(), "the pointer")
						end
						-- The player names a new window Olympus: the chats go there, said once.
						olympus = "Olympus"
						w.event("UPDATE_FLOATING_CHAT_WINDOWS")
						eq(ns.Channels.TabState(), "open", "the real SetupTab ran"); eq(w.CW.Watching(), false)
						local set = 0
						for _, m in ipairs(w.printed) do if m:find(L.CHATTAB_SET:match("^(.-)%%s"), 1, true) then set = set + 1 end end
						eq(set, 1, "said once: " .. table.concat(w.printed, " / "))
						eq(ChatFrame2.said, 1, "and in the tab"); eq(#w.focus, 0)
					end)
				end
			end)
			ChatFrame2 = saved.frame2
			ns.db.chatWindows, ns.db.chatTabIntro, GetChatWindowInfo, NUM_CHAT_WINDOWS = saved.windows, saved.intro, saved.info, saved.num
			if not ok then error(err, 0) end
		end)
	end)

	test("1.1.1 Chat tab: a client updated without a restart (no ChatWindow.lua yet): /oly talk says to restart the game, and the login names the file", function()
		eq(ns.ChatWindow.missing, true, "Core.lua's stand-in")
		local printed, logged = {}, {}
		local saved = { print = ns.Print, log = ns.Log, faction = ns.CheckFaction, me = ns.me }
		local ok, err = pcall(function()
			ns.Print = function(m) printed[#printed + 1] = tostring(m) end
			SlashCmdList.OLYMPUS("talk")
			eq(printed[1], L.RESTART_NEEDED)
			ns.ChatWindow.Open("A"); ns.ChatWindow.Toggle()
			eq(printed[3], L.RESTART_NEEDED)
			ns.ChatWindow.Close() -- (the rest do nothing)
			eq(#printed, 3)
			ns.Log = function(fmt, ...) logged[#logged + 1] = select("#", ...) > 0 and fmt:format(...) or fmt end
			ns.CheckFaction = function() end
			for _, fn in ipairs(EVENT_SCRIPTS) do fn(nil, "PLAYER_LOGIN") end
		end)
		ns.Print, ns.Log, ns.CheckFaction, ns.me = saved.print, saved.log, saved.faction, saved.me
		if not ok then error(err, 0) end
		local found
		for _, l in ipairs(logged) do if l:find("not loaded until the game restarts", 1, true) and l:find("ChatWindow.lua", 1, true) then found = l end end
		assert(found, "the login's list: " .. table.concat(logged, " / "))
	end)

	-- (Changed on purpose: no title of its own, CHATWIN_TITLE gone (the author: no Olympus name on top
	-- of the chat, it is in our tab); the tab's label, the Olympus tab's button and pointer added; the
	-- pages' section is the Chat tab's. And the Realm tab's chats page gone (the author's call): its
	-- "Open the Chat tab" and "Make an Olympus tab" lines, its Write lines and its gamepad Write
	-- window gone with it; the settings' words (the gear) and the channels' switch's added.)
	test("1.1.1 Chat tab: its words in English and pt-BR, the same codes in both; the help and the pages say how to open it", function()
		local pt = {}
		local savedLocale = GetLocale
		GetLocale = function() return "ptBR" end
		local okPt, errPt = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
		GetLocale = savedLocale
		if not okPt then error(errPt, 0) end
		-- The format and escape codes of a line, in order.
		local function Codes(str)
			str = tostring(str):gsub("%%%%", "")
			local specs = {}
			for spec in str:gmatch("%%[%-%d%.]*%a") do specs[#specs + 1] = spec end
			return table.concat(specs, " ") .. " / " .. select(2, str:gsub("|", ""))
		end
		for _, k in ipairs({ "CHATWIN_PLACEHOLDER", "CHATWIN_PUBLIC", "CHATWIN_YOU", "CHATWIN_TAG_STEWARD", "CHATWIN_TAG_HAND",
			"CHATWIN_KEPT", "CHATWIN_EMPTY", "CHATWIN_NEW_LINES", "CHATWIN_HIDDEN", "CHATWIN_NO_SLASH", "CHATWIN_NOT_SENT", "CHATWIN_WHY_MOVED",
			"CHATWIN_WHY_LATE", "CHATWIN_WHY_FAILED", "CHATWIN_WHY_LEFT", "CHATWIN_PUT_BACK", "CHATWIN_WHISPER_TIP", "CHATWIN_OFF",
			"CHATWIN_OFF_BUTTON", "CHATWIN_MUTED_TIP", "CHATWIN_PINNED", "CHATS_OPEN_WINDOW_TIP",
			"CHATS_TAB_WAITING", "CHATS_TAB_ON", "CHATS_TAB_TIP", "HELP_TALK", "MINIMAP_SHIFT", "HELP_TAB_CHAT", "CHATS_TAB_ADD",
			"CHATS_TAB_ADD_TIP", "CHATS_TAB_STEPS", "CHATTAB_POINTER_TITLE", "CHATTAB_POINTER", "CHATS_TAB_AWAY", "CHATS_TAB_AWAY_TIP",
			"CHATWIN_NEW_IN", "CHATSET_TITLE", "CHATSET_TIP", "CHATSET_SWITCH_TIP", "CHATSET_BACK", "CHATSET_CHATS_ON", "CHATSET_CHATS_OFF",
			"CHATSET_SHOWN", "CHATSET_MUTED", "CHATSET_MUTE_TIP", "CHATSET_WHERE", "CHATSET_WHERE_NEXT", "CHATSET_WHERE_TIP", "CHATSET_TAB" }) do
			assert(type(rawget(ns.L, k)) == "string" and rawget(ns.L, k) ~= "", "English: " .. k)
			assert(type(rawget(pt.L, k)) == "string" and rawget(pt.L, k) ~= rawget(ns.L, k), "pt-BR: " .. k)
			eq(Codes(rawget(pt.L, k)), Codes(rawget(ns.L, k)), "codes: " .. k)
		end
		-- The Realm tab's chats page's own words, gone with it (the languages' files hold no line
		-- English lacks: their test); the words that still name it name the Chat tab.
		for _, k in ipairs({ "CHATS_OPEN_WINDOW", "CHATS_TAB_MAKE", "CHATS_WRITE", "CHATS_WRITE_TO", "CHATS_EMPTY", "CHATS_LINE_TIP" }) do
			eq(rawget(ns.L, k), nil, "English: " .. k); eq(rawget(pt.L, k), nil, "pt-BR: " .. k)
		end
		for _, k in ipairs({ "CHATS_TAB_AWAY_TIP", "CHAN_FLOOD_NOTICE", "HELP_CHATS" }) do
			assert(not ns.L[k]:find("Realm", 1, true) and not pt.L[k]:find("Reino", 1, true), "no Realm page in " .. k)
			assert(ns.L[k]:find(ns.L.TAB_CHAT, 1, true) and pt.L[k]:find(pt.L.TAB_CHAT, 1, true), "the Chat tab in " .. k)
		end
		eq(ns.L.CHATWIN_NEW, "Create New Window", "the game's menu name /oly chatwindow falls back to: untouched")
		eq(pt.L.CHATWIN_NEW, "Nova janela")
		eq(rawget(ns.L, "CHATWIN_TITLE"), nil, "no title of its own"); eq(rawget(pt.L, "CHATWIN_TITLE"), nil)
		eq(pt.L.CHATWIN_NEW_LINES, "%d novas")
		-- The tab's label: the same word in every language Olympus carries, but French.
		eq(ns.L.TAB_CHAT, "Chat"); eq(pt.L.TAB_CHAT, "Chat")
		for code, word in pairs({ deDE = "Chat", esES = "Chat", frFR = "Discussion" }) do
			local src = assert(ReadFile(ADDON_DIR .. "Locales/" .. code .. ".lua"))
			assert(src:find('\tTAB_CHAT = "' .. word .. '",', 1, true), code)
		end
		-- (The review of the Chat tab: the help page's line for each tab, the Chat tab's too, in each
		-- language that has the others: it read in English among German, Spanish or French lines.)
		local helpTabs = {}
		for tab, help in ReadFile(ADDON_DIR .. "UI.lua"):gmatch('L%.TAB_(%u+) %.%. ": " %.%. L%.HELP_TAB_(%u+)') do
			eq(help, tab, "the help page's line for the " .. tab .. " tab")
			helpTabs[#helpTabs + 1] = tab
		end
		assert(#helpTabs >= 5, "the help page's tab lines: " .. table.concat(helpTabs, " "))
		-- Locales.lua, then the language's own file, as a game in that language loads them.
		local function Lang(code, file)
			local lns = {}
			local saved = GetLocale
			GetLocale = function() return code end
			local okLang, errLang = pcall(function()
				assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", lns)
				if file then assert(loadfile(ADDON_DIR .. "Locales/" .. file .. ".lua"))("Olympus", lns) end
			end)
			GetLocale = saved
			if not okLang then error(errLang, 0) end
			return lns.L
		end
		local english = Lang("enUS")
		for code, file in pairs({ deDE = "deDE", esES = "esES", esMX = "esES", frFR = "frFR" }) do
			local lang = Lang(code, file)
			for _, tab in ipairs(helpTabs) do
				local k = "HELP_TAB_" .. tab
				assert(lang[k] ~= english[k], code .. " translates " .. k)
			end
			for _, chan in ipairs({ "CHAN_ALL", "CHAN_CAPTAINS", "CHAN_LORDS" }) do
				assert(lang.HELP_TAB_CHAT:find("[" .. lang[chan] .. "]", 1, true), code .. ": the channel's name as the language has it, " .. lang[chan])
			end
		end
		-- Chat and Crafters are first-class tabs: Realm help does not advertise either as a link.
		for _, code in ipairs({ "enUS", "ptBR", "deDE", "esES", "esMX", "frFR" }) do
			local file = ({ deDE = "deDE", esES = "esES", esMX = "esES", frFR = "frFR" })[code]
			local lang = Lang(code, file)
			assert(not lang.HELP_TAB_REALM:find(lang.TAB_CHAT, 1, true), code .. ": no Chat link in Realm help")
			assert(type(lang.TAB_CRAFTERS) == "string" and type(lang.HELP_TAB_CRAFTERS) == "string", code .. ": Crafters help")
		end
		eq(select(2, ns.L.CHATS_TAB_STEPS:gsub("%%s", "")), 2, "the main tab, Create New Window")
		eq(select(2, ns.L.CHATTAB_POINTER:gsub("%%s", "")), 1, "Create New Window")
		-- The help's page (UI.ShowHelp): the Chat tab's line after the Realm's.
		assert(ReadFile(ADDON_DIR .. "UI.lua"):find('"  " .. L.TAB_REALM .. ": " .. L.HELP_TAB_REALM,\n\t\t"  " .. L.TAB_CHAT .. ": " .. L.HELP_TAB_CHAT,', 1, true),
			"the help page's line")
		-- /oly help: the line after /oly chatwindow's.
		local printed = {}
		local savedPrint, savedNsPrint = print, ns.Print
		print = function(s) printed[#printed + 1] = tostring(s) end
		ns.Print = function(s) printed[#printed + 1] = tostring(s) end
		local ok, err = pcall(SlashCmdList.OLYMPUS, "no-such-command")
		print, ns.Print = savedPrint, savedNsPrint
		if not ok then error(err, 0) end
		local at
		for i, p in ipairs(printed) do if p == L.HELP_CHATWIN then at = i end end
		assert(at, "the help"); eq(printed[at + 1], L.HELP_TALK)
		-- README and the CurseForge page: the section before the Board's, the command's row after /oly chat's, the Shift-click.
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			local doc = assert(ReadFile(ROOT .. path))
			local section, board = doc:find("\n### The Chat tab (1.1.1)\n", 1, true), doc:find("\n### The Board: who is looking for a group", 1, true)
			assert(section and board and section < board, path .. ": the section, before the Board's")
			local chat = doc:find("\n| `/oly chat on\\|off` |", 1, true)
			assert(chat, path .. ": /oly chat's row")
			local nextRow = doc:find("\n", chat + 1, true)
			assert(doc:sub(nextRow, nextRow + 20):find("| `/oly talk", 1, true), path .. ": /oly talk's row right after it")
			assert(doc:find("Shift-click the minimap button for the Chat tab", 1, true), path .. ": the Shift-click")
			assert(not doc:find("### The chat window (1.1.1)", 1, true), path .. ": no chat window section any more")
			-- What the tab is now, in the same words on both pages.
			local flat = doc:gsub("%s+", " ")
			for _, phrase in ipairs({ "The Olympus chats in a tab of the Olympus window, **Chat**, right after the Realm",
				"each opens the Olympus window on its Chat tab, on that channel", "the same command again closes the window",
				"The Realm does not repeat a chat shortcut or status row", "the top-level **Crafters** tab",
				"On top, where the other tabs show the army's counts, the search box",
				-- (Changed on purpose, the author's ask: the pills' row where the other tabs have their
				-- column titles is gone; the switch and the gear on the search's row, the settings, the
				-- Realm tab's link where its page's lines were.)
				"On the same row, right of it: for a rank that reads more than one channel, a small switch with the channel shown, in its colour, and **+N**",
				"There is no row of channels: most players read [Olympus] alone, and the lines take that room",
				"The pinned line shows over the lines, as on the Realm tab, and takes no room while nothing is pinned",
				-- (Changed on purpose, the review of the page's removal: the pages no longer mention the
				-- Realm tab's page of the chats, not even as gone (the brief: they do not mention it); the
				-- count of the hidden lines is a strip over the lines, taking no room without one.)
				"Over the lines, like the pinned line, how many your filter hides in the channel (no room while it hides none), and a click there shows them all (another hides them again)",
				"**Settings**: the gear at the end of the top row shows them in place of the lines",
				"a click mutes it there or shows it again, as `/oly mute`",
				"a click moves it to the next chat window open in your game, then back to the main one, as `/oly chatwindow`",
				"Each choice is the one its command makes, kept where it always was, so nothing chosen before 1.1.1 is lost",
				"its **x** puts it away for good, on every character: the settings and `/oly chatwindow tab` still make the tab",
				"(this tab has no detail box)", "**The box** runs across the bottom, where the other tabs have their buttons, with no Send button: Enter sends",
				"**Add an Olympus tab to the game chat**", "a small Olympus pointer by your main chat tab says right-click it, Create New Window, and name it Olympus",
				"It only reads the game's chat windows to see the new one appear", "With the gamepad UI there is no pointer",
				-- (The review of the Chat tab: the line's x and the window of one's own; the Realm page's click.)
				"The line stays away while you send a channel to a chat window of your own (`/oly chatwindow`), and its **x** puts it away for good, on every character",
				"The click shows you where on the Chat tab, as its **Add an Olympus tab to the game chat** line does",
				"its canonical tail continues from the bottom of the window's left edge upward",
				"Reading the right top-to-bottom and then the left bottom-to-top always gives the same tab order",
				"| `/oly talk [olympus\\|captains\\|lords]` | open or close the Olympus window on its Chat tab, on that channel" }) do
				assert(flat:find(phrase, 1, true), path .. ": " .. phrase)
			end
			for _, gone in ipairs({ "340 x 300 to 900 x 1000", "Olympus chat window", "the Treasury and then the author's Workshop",
				"where the other tabs have their column titles", "Realm tab's chats page", "**Open the Chat tab**", "**Write in [Olympus]**",
				"a line under the channels", "Realm tab's Olympus chats", "Realm tab's chats say", "on the chats page",
				"members seen online, the Olympus chats' lines", "newest first, even what was said",
				"page of the chats", "Realm tab's page", "gone since 1.1.1", "offers everything it did",
				"click **the Olympus chats** on the Realm tab", "his Treasury moves to the window's left edge",
				"the crafters' board on the Realm tab" }) do
				assert(not flat:find(gone, 1, true), path .. ": no more " .. gone)
			end
		end
		local sections = {}
		for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
			sections[#sections + 1] = assert(ReadFile(ROOT .. path)):match("\n### The Chat tab %(1%.1%.1%)\n(.-)\n### The Board")
		end
		assert(sections[1] and sections[1] == sections[2], "the same section on both pages")
	end)

	---------------------------------------------------------------------------
	-- The review of the 1.1.1 chat window: the view held by the line read at a channel's 100 lines,
	-- no member star for a guild a line only claims, the mute kept by a line written in the window,
	-- an alt's lines under his name, a note never replacing a draft, and the widget calls the
	-- window's asks rest on.
	---------------------------------------------------------------------------
	do
		local STAR = "|TInterface\\AddOns\\Olympus\\media\\borders\\star:14:14|t"
		local function BubbleOf(f, e)
			for _, b in ipairs(Visible(f.bubbles)) do if b.entry == e then return b end end
		end
		-- The bubble at the view's top, and how far its top sits from the view's.
		local function AtTop(f)
			local at = f.scroll:GetVerticalScroll()
			for _, b in ipairs(Visible(f.bubbles)) do
				if Top(b) + b:GetHeight() > at then return b.entry, Top(b) - at end
			end
		end
		-- A line from the channel through Channels.Receive, whose history keeps 100 (the oldest goes);
		-- the channel muted in chat, so the line only goes to the history (no chat frame, no flood
		-- guard: nothing left for a later test). Then the window's own redraw, and the client
		-- measuring the new range.
		local arrivals = 0
		local function Arrive(w, f, text)
			arrivals = arrivals + 1
			local sender = "Newcomer" .. arrivals .. "-Realm"
			local _, why = ns.Channels.Receive("CHANNEL", sender, ns.Codec.EncodeChat("A", "Olympus Zeus", 700 + arrivals, "", text), 9000 + arrivals)
			eq(why, "muted", "kept")
			w.fire("CHAT_CHANGED", "A"); w.fire("CHAT_LINE", "A", sender, text)
			f:Fire("OnUpdate", 0.3)
			f.scroll:Settle()
		end
		test("1.1.1 review: scrolled up in a channel at its 100 lines, the line being read stays in its place while new lines drop the oldest (the next one's place when it goes); a resize keeps it too", function()
			WithWindow(function(w)
				ns.db.addonChat = true
				ns.db.chatMute = { A = true }
				local list = {}
				for i = 1, 100 do
					list[i] = Line(T0 + i * 400, (i % 2 == 0) and "Aa-Realm" or "Bb-Realm", "line number " .. i .. " " .. ("words "):rep(i % 7 * 5))
				end
				ns.rdb.chat = { A = list }
				local f = w.CW.Open("A")
				local s = f.scroll
				s:Settle()
				s:SetVerticalScroll(math.floor(s:GetVerticalScrollRange() / 2))
				local read, off = AtTop(f)
				assert(read and read ~= list[1], "a line in the middle")
				for k = 1, 3 do Arrive(w, f, "new " .. k) end
				eq(#ns.rdb.chat.A, 100, "Channels keeps 100")
				assert(BubbleWith(f, "new 3"), "the new lines drawn")
				eq(BubbleWith(f, "line number 1 "), nil, "the oldest gone")
				local now, nowOff = AtTop(f)
				eq(now, read, "the same line at the view's top")
				eq(nowOff, off, "in the same place")
				eq(f.newPill:IsShown(), true); eq(f.newPill:GetText(), L.CHATWIN_NEW_LINES:format(3))
				-- The line read taken off the view (the moderators took its writer off: net-off): the next
				-- line under it stays where it was.
				local saved = { any = ns.Moderation.Any, hides = ns.Moderation.Hides }
				local ok, err = pcall(function()
					local gone = read.sender
					local after
					for _, b in ipairs(Visible(f.bubbles)) do
						if Top(b) > Top(BubbleOf(f, read)) and b.entry.sender ~= gone then after = b.entry break end
					end
					local afterOff = Top(BubbleOf(f, after)) - s:GetVerticalScroll()
					ns.Moderation.Any = function() return true end
					ns.Moderation.Hides = function(who) if who == gone then return { kind = "c" } end end
					w.fire("NETOFF_CHANGED", {})
					f:Fire("OnUpdate", 0.3)
					s:Settle()
					eq(BubbleOf(f, read), nil, "(off the view)")
					eq(Top(BubbleOf(f, after)) - s:GetVerticalScroll(), afterOff, "the next line where it was")
				end)
				ns.Moderation.Any, ns.Moderation.Hides = saved.any, saved.hides
				if not ok then error(err, 0) end
				w.fire("NETOFF_CHANGED", {})
				f:Fire("OnUpdate", 0.3)
				s:Settle()
				-- Reading the oldest kept, at the top of the history: when it goes, the view stays at the
				-- top, the next line whole in it.
				local oldest, second = ns.rdb.chat.A[1], ns.rdb.chat.A[2]
				s:SetVerticalScroll(Top(BubbleOf(f, oldest)) + 4)
				eq((AtTop(f)), oldest)
				Arrive(w, f, "new 4")
				eq(BubbleOf(f, oldest), nil, "dropped")
				eq(s:GetVerticalScroll(), 0, "at the top")
				eq((AtTop(f)), second); assert(Top(BubbleOf(f, second)) - s:GetVerticalScroll() >= 0, "whole in the view")
				-- A narrower window (the Olympus window the tab is in): every line above wraps on more
				-- lines; once the client measured the longer range, the line read is back in its place.
				s:SetVerticalScroll(s:GetVerticalScrollRange() - 40)
				read, off = AtTop(f)
				local before = f.content:GetHeight()
				w.CW.Window():SetSize(300, 424)
				f:Fire("OnUpdate", 0.3)
				s:Settle()
				assert(f.content:GetHeight() > before, "(taller)")
				now, nowOff = AtTop(f)
				eq(now, read); eq(nowOff, off)
				-- Followed again at the bottom: the newest line, as ever.
				s:SetVerticalScroll(s:GetVerticalScrollRange())
				Arrive(w, f, "new 5")
				eq(s:GetVerticalScroll(), s:GetVerticalScrollRange())
				eq(f.newPill:IsShown(), false)
			end)
		end)

		test("1.1.1 review: no member star for a guild a line only claims (an unknown name in a made-up Olympus guild, a stranger in our guild's name); our roster, a census and the King's names still give theirs; a redraw records no guild claim", function()
			WithWindow(function(w)
				local saved = { byName = ns.Roster.byName, steward = ns.King.IsStewardName, loginAt = ns.Comm.loginAt }
				local ok, err = pcall(function()
					local bns = setmetatable({ On = function() end, RegisterEvent = function() end }, { __index = ns })
					assert(loadfile(ADDON_DIR .. "Borders.lua"))("Olympus", bns)
					ns.Borders = bns.Borders
					ns.db.addonChat = true
					ns.db.chatMute = { A = true }
					ns.Roster.byName = { ["Plain Guy-Realm"] = 4, ["Soldier-Realm"] = 3 }
					ns.King.IsStewardName = function(n) return n == "Stew Ard-Realm" end
					ns.rdb.guilds["Olympus Lone"] = Vouched({ guild = "Olympus Lone", leader = "Loner", officers = { { name = "Lone Capt" }, { name = "Plain Guy" } }, realm = "Realm",
						t = ns.Now() }, "W1-Realm")
					ns.rdb.chat = { A = {
						Line(T0, "Plain Guy-Realm", "a guildmate speaks"),
						Line(T0 + 100, "Stranger-Realm", "a stranger in our guild's name"),
						Line(T0 + 200, "Lone Capt-Realm", "a captain his census names", { guild = "Olympus Lone" }),
						Line(T0 + 300, "Stew Ard-Realm", "the king's steward", { guild = "Olympus" }),
						Line(T0 + 400, "Drifter-Realm", "a drifter's claim", { guild = "Olympus Nowhere" }),
					} }
					-- Anyone on the channel: Channels keeps his [Olympus] line, unverified.
					eq(ns.IsFederation("Olympus Nowhere"), true, "(a name the Olympus rule takes)")
					local have, verified = ns.Channels.VerifiedLevel("Outsider-Realm", "Olympus Nowhere")
					eq(have, 1); eq(verified, false)
					local _, why = ns.Channels.Receive("CHANNEL", "Outsider-Realm", ns.Codec.EncodeChat("A", "Olympus Nowhere", 42, "", "hello from outside"), 1000)
					eq(why, "muted", "kept")
					local f = w.CW.Open("A")
					local function Header(text)
						local b = BubbleWith(f, text)
						assert(b, text)
						return b.who:GetText()
					end
					local h = Header("hello from outside")
					assert(not h:find(STAR, 1, true) and not h:find("|A:", 1, true), "no mark: " .. h)
					assert(h:find("Outsider", 1, true) and h:find("<Olympus Nowhere>", 1, true), "his name and the guild his line names still show: " .. h)
					h = Header("a stranger in our guild's name")
					assert(not h:find(STAR, 1, true), "our guild's name, not in our roster: " .. h)
					assert(Header("a guildmate speaks"):find(STAR, 1, true), "in our roster: the star")
					assert(Header("a captain his census names"):find(STAR, 1, true), "named in his guild's census: the star")
					assert(Header("the king's steward"):find(STAR, 1, true), "the King's Steward, by the name Channels verifies him by: the star")
					-- Our guild's name spelled another way, by a name our census names but our roster lacks:
					-- not one of ours (Channels says 0), no mark from the census either.
					ns.rdb.guilds["Olympus II"] = Vouched({ guild = "Olympus II", leader = "Old Boss", officers = {}, realm = "Realm", t = ns.Now() },
						"W1-Realm", "W2-Realm")
					ns.Comm.loginAt = ns.Now() - ns.Data.CROWN_AFTER - 1
					eq(ns.Channels.VerifiedLevel("Old Boss-Realm", "OLYMPUS II"), 0, "(not one of ours)")
					eq(ns.Borders.MarkOfName("Old Boss-Realm", "OLYMPUS II"), nil, "no mark")
					-- A guildmate of ours speaking for another guild, even one whose census names him: no mark
					-- (Channels says 0 for him there).
					eq(ns.Data.KnownRank("Plain Guy-Realm", "Olympus Lone"), 1, "(its census names him)")
					eq(ns.Channels.VerifiedLevel("Plain Guy-Realm", "Olympus Lone"), 0, "(not his guild)")
					eq(ns.Borders.MarkOfName("Plain Guy-Realm", "Olympus Lone"), nil, "no mark")
					eq(ns.Borders.MarkOfName("Plain Guy-Realm", "Olympus II"), "member", "his own guild: the star")
					-- Drawn again: the window left no guild claim (Channels.VerifiedLevel's Data.ClaimGuild
					-- would have, and his next line for his real guild would be refused as forged).
					w.CW.Render()
					eq(ns.Data.ClaimGuild("Drifter-Realm", "Olympus Zeus"), true, "no claim left by the window")
				end)
				ns.Roster.byName, ns.King.IsStewardName, ns.Comm.loginAt = saved.byName, saved.steward, saved.loginAt
				if not ok then error(err, 0) end
			end)
		end)

		test("1.1.1 review: a line written in the window keeps its channel muted in chat, the privacy warning's Send too; /ol typed in chat still unmutes it", function()
			WithWindow(function(w)
				local saved = { room = ns.Comm.ChatRoom, warned = ns.db.chatWarned }
				local ok, err = pcall(KeepSendGap, function()
					WithLane(function(sent)
						ns.db.addonChat = true
						ns.db.chatMute = { A = true }
						ns.db.chatWarned = { A = true }
						ns.Comm.ChatRoom = function() return 3 end
						local clock = 1e7
						GetTime = function() return clock end
						local f = w.CW.Open("A")
						f.input:SetText("from the window")
						f.input:Fire("OnEnterPressed")
						eq(#sent, 1, "sent: " .. table.concat(w.printed, " / ")); assert(sent[1]:find("from the window", 1, true), sent[1])
						eq(ns.db.chatMute.A, true, "still muted in chat")
						assert(not Said(w, L.CHAN_UNMUTED:format(L.CHAN_ALL)), "no word of unmuting")
						f:Fire("OnUpdate", 0.3)
						local b = BubbleWith(f, "from the window")
						assert(b and b.mine, "in the window, ours")
						-- The first line in a channel, held by the privacy warning: its Send keeps the mute too.
						ns.db.chatWarned = {}
						local dialogs = {}
						ns.ShowDialog = function(which, _, _, data) dialogs[#dialogs + 1] = { which = which, data = data } end
						clock = clock + 10
						f.input:SetText("a first line")
						f.input:Fire("OnEnterPressed")
						eq(dialogs[1].which, "OLYMPUS_CHAT_PRIVACY"); eq(#sent, 1, "held")
						clock = clock + 10
						ns.Channels.Confirm(dialogs[1].data, true)
						eq(#sent, 2, "sent on the OK"); eq(ns.db.chatMute.A, true, "still muted")
						-- /ol typed in chat: unmuted, as ever.
						clock = clock + 10
						ns.Channels.Send("A", "typed in chat")
						eq(#sent, 3); eq(ns.db.chatMute.A, nil, "unmuted")
						assert(Said(w, L.CHAN_UNMUTED:format(L.CHAN_ALL)), "and told")
					end)
				end)
				ns.Comm.ChatRoom, ns.db.chatWarned = saved.room, saved.warned
				if not ok then error(err, 0) end
			end)
		end)

		test("1.1.1 review: a line another character of the account wrote shows under his name, on the left, with a whisper; this character's own as You on the right", function()
			WithWindow(function(w)
				ns.rdb.chat = { A = {
					Line(T0, "Altchar-Realm", "written by my alt", { mine = true, guild = "Olympus Zeus" }),
					Line(T0 + 10, "Soldier-Realm", "written by me", { mine = true }),
				} }
				local f = w.CW.Open("A")
				local alt, me = BubbleWith(f, "written by my alt"), BubbleWith(f, "written by me")
				eq(alt.mine, false)
				assert(alt:Anchor("TOPLEFT") and not alt:Anchor("TOPRIGHT"), "the alt's: left")
				local h = alt.who:GetText()
				assert(h:find("Altchar", 1, true) and h:find("<Olympus Zeus>", 1, true) and not h:find(L.CHATWIN_YOU, 1, true), h)
				eq(alt.header.whisper, "Altchar", "a click whispers him")
				eq(me.mine, true); eq(me.who:GetText(), L.CHATWIN_YOU)
				assert(me:Anchor("TOPRIGHT") and not me:Anchor("TOPLEFT"), "ours: right")
				-- The same history, played from the alt.
				AsSoldier("Altchar")
				w.CW.Render()
				eq(BubbleWith(f, "written by my alt").who:GetText(), L.CHATWIN_YOU)
				assert(BubbleWith(f, "written by me").who:GetText():find("Soldier", 1, true))
			end)
		end)

		test("1.1.1 review: a note's click never replaces what the player is writing (the draft and the note stay, and he is told); into an empty box it goes", function()
			WithWindow(function(w)
				local f = w.CW.Open("A")
				w.fire("CHAT_SEND_FAILED", "A", "moved", "my lost line", 0)
				w.CW.Render()
				local moved = L.CHATWIN_NOT_SENT:format(L.CHATWIN_WHY_MOVED)
				f.input:SetText("a new draft I am typing")
				RowWith(f, moved):Click()
				eq(f.input:GetText(), "a new draft I am typing", "the draft stays")
				assert(RowWith(f, moved), "the note stays")
				assert(Said(w, L.CHATWIN_PUT_BACK_BUSY), "told")
				f.input:SetText("   ")
				RowWith(f, moved):Click()
				eq(f.input:GetText(), "my lost line", "an empty box: back in it")
				eq(RowWith(f, moved), nil, "the note gone")
				eq(#w.focus, 0, "never focused")
			end)
		end)

		-- (Changed on purpose: no resize bounds of its own, the tab takes its window's size; the
		-- Olympus window is the one kept on the screen.)
		test("1.1.1 review: what the Chat tab's asks rest on is set: a bubble's links and clicks, a long word's wrap, the window kept on the screen, the box's byte cap", function()
			WithWindow(function(w)
				ns.rdb.chat = { A = { Line(T0, "Aa-Realm", "look " .. MOONCLOTH_TEXT), Line(T0 + 10, "Soldier-Realm", "mine", { mine = true }) } }
				local f = w.CW.Open("A")
				local bs = Visible(f.bubbles)
				eq(#bs, 2)
				for _, b in ipairs(bs) do
					eq(b.hyperlinks, true, "its links answer the mouse (tooltip, Shift-click)")
					eq(b.mouse, true, "the mouse on: its links, and the click that shows a hidden line")
					eq(b.body.nonSpaceWrap, true, "a long word or link wraps inside the bubble")
					eq(b.body.wrap, true)
				end
				eq(f.resizeBounds, nil, "no size of its own: its window's")
				eq(w.CW.Window().clamped, true, "the Olympus window kept on the screen")
				eq(f.input.maxBytes, ns.Codec.CHAT_PARTS * 210 + 1, "the box holds what Channels.Send can send")
				-- (The toolkit here answers links and mouse clicks only where they are on, as the client.)
				local plain = NewWidget("Frame", nil, UIParent)
				local fired = 0
				plain:SetScript("OnHyperlinkEnter", function() fired = fired + 1 end)
				plain:SetScript("OnMouseUp", function() fired = fired + 1 end)
				plain:Fire("OnHyperlinkEnter", MOONCLOTH_LINK); plain:Fire("OnMouseUp", "LeftButton")
				eq(fired, 0, "a plain frame: neither")
				plain:SetHyperlinksEnabled(true)
				plain:Fire("OnHyperlinkEnter", MOONCLOTH_LINK)
				eq(fired, 0, "links on, the mouse off: nothing")
				plain:EnableMouse(true)
				plain:Fire("OnHyperlinkEnter", MOONCLOTH_LINK); plain:Fire("OnMouseUp", "LeftButton")
				eq(fired, 2)
			end)
		end)

		test("1.1.1 review: the new words in English and pt-BR, and the pages say what changed", function()
			local pt = {}
			local savedLocale = GetLocale
			GetLocale = function() return "ptBR" end
			local okPt, errPt = pcall(function() assert(loadfile(ADDON_DIR .. "Locales.lua"))("Olympus", pt) end)
			GetLocale = savedLocale
			if not okPt then error(errPt, 0) end
			for _, k in ipairs({ "CHATWIN_PUT_BACK_BUSY", "CHATWIN_MUTED_TIP" }) do
				assert(type(rawget(ns.L, k)) == "string" and rawget(ns.L, k) ~= "", "English: " .. k)
				assert(type(rawget(pt.L, k)) == "string" and rawget(pt.L, k) ~= rawget(ns.L, k), "pt-BR: " .. k)
				eq(rawget(pt.L, k):find("%", 1, true), nil, "no format code: " .. k)
			end
			assert(ns.L.CHATWIN_MUTED_TIP:find("keeps it muted", 1, true), ns.L.CHATWIN_MUTED_TIP)
			for _, path in ipairs({ "README.md", "docs/CURSEFORGE.md" }) do
				local doc = assert(ReadFile(ROOT .. path)):gsub("%s+", " ")
				assert(doc:find("a line you write here keeps it muted in chat", 1, true), path .. ": the mute")
				assert(doc:find("the line you are reading stays in its place while new lines come in and the oldest go", 1, true), path .. ": the scroll")
				assert(doc:find("and only where the guild a line names is proven", 1, true), path .. ": the marks")
				assert(doc:find("A name whose Olympus guild cannot be checked", 1, true), path .. ": no mark then")
				assert(not doc:find("from the same facts as the borders and the nameplate marks", 1, true), path .. ": no longer the same facts")
				assert(doc:find("a click puts it back in the box when the box is empty", 1, true), path .. ": the note")
				assert(doc:find("a line another of your characters wrote shows under that character's name, on the left", 1, true), path .. ": an alt's line")
			end
		end)
	end

	---------------------------------------------------------------------------
	-- 1.1.1, the chats inside the Olympus window (the author's ask after trying the window of their
	-- own): the Chat tab's place in each look, its search, its ways in, and the way to the Olympus
	-- tab of the game's chat (Olympus's pointer, the game's chat windows only read).
	---------------------------------------------------------------------------
	do
		local function Grey(s) return "|cff9d9d9d" .. s .. "|r" end
		local function Shown(frame) return frame ~= nil and frame:IsShown() end

		-- (Changed on purpose, the author's ask: "remove this Olympus with the underline, taking space
		-- and shrinking the conversations". The channel pills' row on the column titles' row is gone:
		-- the lines start where the list's box starts without column titles (old look -56, was -80
		-- under the pills; HD -60, was -85), the pinned line 3 under that (-59, was -83). On the top
		-- row the gear takes the search box's end (it ends 24 further left, -50, was -26), and a rank
		-- that reads more than one channel has the switch left of the gear, never a row of its own.)
		test("1.1.1 Chat tab: no soldiers' counts, no detail box, no column titles or buttons; the search where the counts were, the channels' switch and the gear at its end, no row of pills, the lines over the list and the detail box, the box across the buttons' row, in both looks", function()
			WithWindow(function(w)
				ns.Channels.TabState = function() return "open" end -- (no Olympus tab line: the places alone)
				ns.Channels.Pin = function() return nil end
				ns.rdb.chat = { A = { Line(T0, "Aa-Realm", "hello") } }
				local f = w.CW.Open()
				local main = OlympusFrame
				eq(main.style, "old")
				for _, key in ipairs({ "total", "sub", "headerHover", "listBox", "scroll", "detail", "colHeader" }) do
					eq(Shown(main[key]), false, "the Chat tab has no " .. key)
				end
				for _, b in ipairs(main.buttons) do eq(b:IsShown(), false, "no buttons") end
				for _, b in ipairs(main.detailButtons) do eq(b:IsShown(), false) end
				-- The search where the counts were (right of the portrait), the gear at that row's end
				-- (HEADER_RIGHT 26 from the window's right), no pills and, for a soldier's one channel,
				-- no switch; the lines from the list box's top (GEOMETRY.old.box: -56) down to the buttons'
				-- row (8 + 22 + 4), the box across that row (its buttons' x 8, margin 16).
				local s = f.search:Anchor("TOPLEFT")
				eq(s[2], f); eq(s[5], -30); assert(s[4] > main.headerX, "right of the portrait")
				eq(f.gear:Anchor("TOPRIGHT")[4], -26); eq(f.gear:Anchor("TOPRIGHT")[5], -30); eq(f.gear:IsShown(), true)
				-- (Changed on purpose, 1.1.2: the tab's "?" sits left of the gear, 20 wide and 4 apart,
